    let maStlUserFloorWallAxisLineMat = null;

    function maStlApplyUserFloorLineMaterialResolutionIfRenderer(mat) {
        if (!mat || !renderer || !renderer.domElement) return;
        maStlApplyUserFloorLineMaterialResolution(
            mat,
            renderer.domElement.clientWidth,
            renderer.domElement.clientHeight
        );
    }

    function maStlEnsureUserFloorLineMat() {
        if (!maStlUserFloorLineMat) {
            maStlUserFloorLineMat = maStlMakeUserFloorLineMaterial();
            maStlApplyUserFloorLineMaterialResolutionIfRenderer(maStlUserFloorLineMat);
        } else if (maStlUserFloorLineMat.linewidth !== MA_STL_USER_FLOOR_LINE_SCREEN_PX_WIDTH) {
            maStlUserFloorLineMat.color.setHex(0xff6600);
            maStlUserFloorLineMat.linewidth = MA_STL_USER_FLOOR_LINE_SCREEN_PX_WIDTH;
            maStlUserFloorLineMat.transparent = false;
            maStlUserFloorLineMat.opacity = 1;
            maStlApplyUserFloorLineMaterialResolutionIfRenderer(maStlUserFloorLineMat);
        }
        return maStlUserFloorLineMat;
    }

    function maStlEnsureUserFloorWallAxisLineMat() {
        if (!maStlUserFloorWallAxisLineMat) {
            maStlUserFloorWallAxisLineMat = maStlMakeUserFloorWallAxisLineMaterial();
            maStlApplyUserFloorLineMaterialResolutionIfRenderer(maStlUserFloorWallAxisLineMat);
        } else {
            maStlApplyUserFloorWallAxisLineStyleToMaterial(maStlUserFloorWallAxisLineMat);
            maStlApplyUserFloorLineMaterialResolutionIfRenderer(maStlUserFloorWallAxisLineMat);
        }
        return maStlUserFloorWallAxisLineMat;
    }

    function maStlCloneUserFloorWallAxisLineMaterial() {
        const axisUm = maStlEnsureUserFloorWallAxisLineMat();
        const mat = axisUm.clone ? axisUm.clone() : maStlMakeUserFloorWallAxisLineMaterial();
        maStlApplyUserFloorWallAxisLineStyleToMaterial(mat);
        maStlApplyUserFloorLineMaterialResolutionIfRenderer(mat);
        return mat;
    }

    /** Fuerza negro discontinuo en todos los ejes de muro 2D ya dibujados. */
    function maStlReapplyAllUserFloorWallAxisLineStyles() {
        if (!maStlUserLinesGroup) return;
        maStlEnsureUserFloorWallAxisLineMat();
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const ln = ch[i];
            if (!maStlIsUserFloorPlanLineObject(ln)) continue;
            const ud = ln.userData && ln.userData.maStlUserPlanLine;
            if (!ud || ud.wallRole !== 'axis') continue;
            if (
                !ln.material ||
                !ln.material.isLineMaterial ||
                ln.material === maStlUserFloorLineMat ||
                ln.material === maStlUserFloorWallAxisLineMat ||
                !ln.material.dashed
            ) {
                ln.material = maStlCloneUserFloorWallAxisLineMaterial();
            } else {
                maStlApplyUserFloorWallAxisLineStyleToMaterial(ln.material);
                maStlApplyUserFloorLineMaterialResolutionIfRenderer(ln.material);
            }
            maStlUserFloorLineSyncAxisDashDistances(ln);
        }
    }

    function maStlDesing2ClonePlanPointMm(p) {
        return { x: p.x, y: p.y, z: p.z };
    }

    const MA_STL_WALL_LINE_ATTR_KEYS = [
        '_idObject',
        '_TypeMesh',
        '_Datalong',
        '_DataWith',
        '_DataHeight',
        '_XRotation',
        '_YrRtation',
        '_ZRotation',
        '_IsFormwork',
        '_IsUniversalPanel',
        '_XCoordinate',
        '_YCoordinate',
        '_ZCoordinate',
        '_Tape_1',
        '_Tape_2',
        '_Idconnection_1',
        '_Idconnection_2',
        '_CHeckBracketInside',
        '_CHeckBracketOutside',
        '_CHeckRijiInside',
        '_CHeckRijiOutside',
        '_CHeckPropInside',
        '_CHeckPropOutside',
        '_CHeckPropInsideInf',
        '_CHeckPropOutsideInf',
    ];

    function maStlWallLineCopyAttrs(fromObj, toObj) {
        if (!fromObj || !toObj) return;
        for (let i = 0; i < MA_STL_WALL_LINE_ATTR_KEYS.length; i++) {
            const key = MA_STL_WALL_LINE_ATTR_KEYS[i];
            if (Object.prototype.hasOwnProperty.call(fromObj, key)) {
                toObj[key] = fromObj[key];
            }
        }
    }

    function maStlRoundMeters3(valueM) {
        return Math.round((Number(valueM) || 0) * 1000) / 1000;
    }

    function maStlWallLineResolveWidthMm(ud) {
        if (!ud) return MA_STL_DESING2_WALL_WIDTH_DEFAULT_MM;
        if (ud.wallRole === 'axis') {
            return maStlWall2dToolAxisHalfThicknessFromAxisUd(ud) * 2;
        }
        if (ud.numberOffsetMm != null && Number.isFinite(ud.numberOffsetMm)) {
            return Math.abs(ud.numberOffsetMm) * 2;
        }
        return MA_STL_DESING2_WALL_WIDTH_DEFAULT_MM;
    }

    function maStlWallLineEnsureAttrs(ud) {
        if (!ud || !ud.p1Mm || !ud.p2Mm) return;
        const wallId = ud.id != null ? ud.id : (ud.wallId != null ? ud.wallId : ud.wallGroupId);
        const lenMm = maStlUserFloorLineLengthMm(ud);
        const widthMm = maStlWallLineResolveWidthMm(ud);
        const dirX = ud.p2Mm.x - ud.p1Mm.x;
        const dirZ = ud.p2Mm.z - ud.p1Mm.z;
        const yRotDeg = Math.atan2(dirZ, dirX) * (180 / Math.PI);
        const midX = (ud.p1Mm.x + ud.p2Mm.x) * 0.5;
        const midY = (ud.p1Mm.y + ud.p2Mm.y) * 0.5;
        const midZ = (ud.p1Mm.z + ud.p2Mm.z) * 0.5;

        ud._idObject = wallId;
        ud._TypeMesh = 'Wall';
        ud._Datalong = maStlRoundMeters3(lenMm / 1000);
        ud._DataWith = maStlRoundMeters3(widthMm / 1000);
        ud._DataHeight = maStlRoundMeters3(MA_STL_WALL3D_DEFAULT_HEIGHT_MM / 1000);
        ud._XRotation = 0;
        ud._YrRtation = Math.round(yRotDeg * 1000) / 1000;
        ud._ZRotation = 0;
        if (ud._IsFormwork == null) ud._IsFormwork = true;
        if (ud._IsUniversalPanel == null) ud._IsUniversalPanel = true;
        ud._XCoordinate = midX;
        ud._YCoordinate = midY;
        ud._ZCoordinate = midZ;
        if (ud._Tape_1 == null) ud._Tape_1 = 'Tipo 1';
        if (ud._Tape_2 == null) ud._Tape_2 = 'Tipo 1';
        if (ud._Idconnection_1 === undefined) ud._Idconnection_1 = null;
        if (ud._Idconnection_2 === undefined) ud._Idconnection_2 = null;
        if (ud._CHeckBracketInside == null) ud._CHeckBracketInside = true;
        if (ud._CHeckBracketOutside == null) ud._CHeckBracketOutside = true;
        if (ud._CHeckRijiInside == null) ud._CHeckRijiInside = true;
        if (ud._CHeckRijiOutside == null) ud._CHeckRijiOutside = true;
        if (ud._CHeckPropInside == null) ud._CHeckPropInside = true;
        if (ud._CHeckPropOutside == null) ud._CHeckPropOutside = true;
        if (ud._CHeckPropInsideInf == null) ud._CHeckPropInsideInf = true;
        if (ud._CHeckPropOutsideInf == null) ud._CHeckPropOutsideInf = true;
    }

    /** Serializa líneas usuario (p1Mm/p2Mm) + anclaje reglas + uuids mallas STL visibles para undo/redo. */
    function maStlDesing2SerializeEditSnapshot() {
        const lines = [];
        if (maStlUserLinesGroup) {
            const ch = maStlUserLinesGroup.children;
            for (let i = 0; i < ch.length; i++) {
                const ln = ch[i];
                if (!maStlIsUserFloorPlanLineObject(ln)) continue;
                const ud = ln.userData && ln.userData.maStlUserPlanLine;
                if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
                maStlWallLineEnsureAttrs(ud);
                const row = {
                    id: ud.id,
                    p1Mm: maStlDesing2ClonePlanPointMm(ud.p1Mm),
                    p2Mm: maStlDesing2ClonePlanPointMm(ud.p2Mm),
                };
                if (ud.polylineGroupId != null) {
                    row.polylineGroupId = ud.polylineGroupId;
                }
                if (ud.wallGroupId != null) {
                    row.wallGroupId = ud.wallGroupId;
                }
                if (ud.wallId != null) {
                    row.wallId = ud.wallId;
                } else if (ud.wallGroupId != null) {
                    row.wallId = ud.wallGroupId;
                }
                if (ud.wallRole) {
                    row.wallRole = ud.wallRole;
                }
                if (ud.linkOffsetFromLineId != null) {
                    row.linkOffsetFromLineId = ud.linkOffsetFromLineId;
                }
                if (ud.numberOffsetMm != null) {
                    row.numberOffsetMm = ud.numberOffsetMm;
                }
                if (ud.numberWallFaceSideSign != null) {
                    row.numberWallFaceSideSign = ud.numberWallFaceSideSign;
                }
                maStlWallLineCopyAttrs(ud, row);
                lines.push(row);
            }
        }
        const stlMeshUuids = [];
        for (let si = 0; si < clipStlMeshes.length; si++) {
            const sm = clipStlMeshes[si];
            if (sm && sm.uuid) stlMeshUuids.push(sm.uuid);
        }
        return {
            lines: lines,
            nextSegId: maStlUserFloorLineNextSegId,
            nextPolylineGroupId: maStlUserFloorLineNextPolylineGroupId,
            nextWallGroupId: maStlUserFloorLineNextWallGroupId,
            rulerAnchor: {
                x: maStlRulerAnchorMm.x,
                y: maStlRulerAnchorMm.y,
                z: maStlRulerAnchorMm.z,
            },
            stlMeshUuids: stlMeshUuids,
        };
    }

    let maStlWallConnectionsLastStableJson = '';

    function maStlDesing2WallConnectionsApiUrl() {
        return viewerShell ? viewerShell.getAttribute('data-ma-stl-wall-connections-api-url') || '' : '';
    }

    function maStlDesing2WallDiagnosticsApiUrl() {
        return viewerShell ? viewerShell.getAttribute('data-ma-stl-wall-diagnostics-api-url') || '' : '';
    }

    function maStlWallConnectionsPointDtoMm(p) {
        return {
            xMm: p && Number.isFinite(p.x) ? p.x : 0,
            yMm: p && Number.isFinite(p.y) ? p.y : 0,
            zMm: p && Number.isFinite(p.z) ? p.z : 0,
            xM: p && Number.isFinite(p.x) ? p.x / 1000 : 0,
            yM: p && Number.isFinite(p.y) ? p.y / 1000 : 0,
            zM: p && Number.isFinite(p.z) ? p.z / 1000 : 0,
        };
    }

    function maStlWallConnectionsSegmentKind(row) {
        if (row && row.wallRole === 'axis') return 'wallAxis';
        if (row && row.wallRole === 'face') return 'wallFace';
        if (row && row.polylineGroupId != null) return 'polylineSegment';
        return 'userLine';
    }

    function maStlWallConnectionsFindNode(nodes, pt, eps) {
        for (let i = 0; i < nodes.length; i++) {
            const n = nodes[i];
            if (maStlUserFloorPlanPointNearXzMm(n.pointMm, pt, eps)) return n;
        }
        return null;
    }

    function maStlWallConnectionsNodeForPoint(nodes, pt, eps) {
        let node = maStlWallConnectionsFindNode(nodes, pt, eps);
        if (node) return node;
        node = {
            id: 'N' + (nodes.length + 1),
            pointMm: { x: pt.x, y: pt.y, z: pt.z },
            point: maStlWallConnectionsPointDtoMm(pt),
            incidentEndpoints: [],
            junctionType: 'Free',
        };
        nodes.push(node);
        return node;
    }

    function maStlWallConnectionsDirectionFromNode(row, endpointKey) {
        const from = endpointKey === 'p2' ? row.p2Mm : row.p1Mm;
        const to = endpointKey === 'p2' ? row.p1Mm : row.p2Mm;
        const dx = to.x - from.x;
        const dz = to.z - from.z;
        const len = Math.hypot(dx, dz);
        if (!(len > 0)) return null;
        return { x: dx / len, z: dz / len };
    }

    function maStlWallConnectionsUniqueDirectionCount(dirs) {
        const unique = [];
        for (let i = 0; i < dirs.length; i++) {
            const d = dirs[i];
            if (!d) continue;
            let exists = false;
            for (let j = 0; j < unique.length; j++) {
                const u = unique[j];
                if (Math.abs(d.x * u.x + d.z * u.z) > 0.985) {
                    exists = true;
                    break;
                }
            }
            if (!exists) unique.push(d);
        }
        return unique.length;
    }

    function maStlWallConnectionsClassifyNode(node, rowsById) {
        const endpoints = node.incidentEndpoints || [];
        const axisDirs = [];
        for (let i = 0; i < endpoints.length; i++) {
            const ep = endpoints[i];
            const row = rowsById[ep.lineId];
            if (!row || row.wallRole !== 'axis') continue;
            axisDirs.push(maStlWallConnectionsDirectionFromNode(row, ep.endpoint));
        }
        const axisCount = axisDirs.length;
        const uniqueDirCount = maStlWallConnectionsUniqueDirectionCount(axisDirs);
        if (axisCount <= 1) return endpoints.length > 1 ? 'Connection' : 'Free';
        if (axisCount === 2) return uniqueDirCount <= 1 ? 'Collinear' : 'L';
        if (axisCount === 3) return 'T';
        if (axisCount === 4) return 'Cross';
        return 'Multi';
    }

    function maStlWallConnectionsEndpointOnSegmentBody(endpointPt, row, eps) {
        if (!endpointPt || !row || !row.p1Mm || !row.p2Mm) return null;
        if (
            maStlUserFloorPlanPointNearXzMm(endpointPt, row.p1Mm, eps) ||
            maStlUserFloorPlanPointNearXzMm(endpointPt, row.p2Mm, eps)
        ) {
            return null;
        }
        const proj = maStlProjectPointOntoUserFloorSegmentBodyXzMm(
            endpointPt,
            row.p1Mm,
            row.p2Mm,
            _maStlUserFloorSegmentBodyProj
        );
        if (!proj || proj.distXZ > eps) return null;
        return {
            point: maStlWallConnectionsPointDtoMm(_maStlUserFloorSegmentBodyProj),
            t: proj.t,
            distXZMm: proj.distXZ,
        };
    }

    function maStlWallConnectionsEndpointKeyNearNode(row, nodePt, eps) {
        if (!row || !nodePt || !row.p1Mm || !row.p2Mm) return null;
        const d1 = maStlUserFloorPlanPointDistSqXzMm(row.p1Mm, nodePt);
        const d2 = maStlUserFloorPlanPointDistSqXzMm(row.p2Mm, nodePt);
        const e2 = eps * eps;
        if (d1 <= e2 && d2 <= e2) return d1 <= d2 ? 'p1' : 'p2';
        if (d1 <= e2) return 'p1';
        if (d2 <= e2) return 'p2';
        return null;
    }

    function maStlWallConnectionsBuildJunctionDiagnostics(nodes, rowsById, rows) {
        const out = [];
        const eps =
            typeof maStlWall2dToolJunctionClusterEpsMm === 'function'
                ? maStlWall2dToolJunctionClusterEpsMm()
                : maStlUserFloorLineMergeEndpointEpsMm();
        for (let ni = 0; ni < nodes.length; ni++) {
            const node = nodes[ni];
            if (!node || !node.pointMm) continue;
            const axisRefs = [];
            const faceRefs = [];
            const endpoints = node.incidentEndpoints || [];
            for (let ei = 0; ei < endpoints.length; ei++) {
                const ep = endpoints[ei];
                const row = rowsById[ep.lineId];
                if (!row || row.wallRole !== 'axis') continue;
                const dir = maStlWallConnectionsDirectionFromNode(row, ep.endpoint);
                axisRefs.push({
                    lineId: row.id,
                    wallGroupId: row.wallGroupId,
                    endpoint: ep.endpoint,
                    directionFromNode: dir,
                });
            }
            for (let ri = 0; ri < rows.length; ri++) {
                const row = rows[ri];
                if (!row || row.wallRole !== 'face') continue;
                const endpoint = maStlWallConnectionsEndpointKeyNearNode(row, node.pointMm, eps);
                if (!endpoint) continue;
                faceRefs.push({
                    lineId: row.id,
                    wallGroupId: row.wallGroupId,
                    linkOffsetFromLineId: row.linkOffsetFromLineId,
                    numberWallFaceSideSign: row.numberWallFaceSideSign,
                    endpoint: endpoint,
                    point: maStlWallConnectionsPointDtoMm(endpoint === 'p2' ? row.p2Mm : row.p1Mm),
                });
            }

            const tCandidates = [];
            if (axisRefs.length >= 3) {
                for (let ai = 0; ai < axisRefs.length; ai++) {
                    for (let aj = ai + 1; aj < axisRefs.length; aj++) {
                        const a = rowsById[axisRefs[ai].lineId];
                        const b = rowsById[axisRefs[aj].lineId];
                        const da = axisRefs[ai].directionFromNode;
                        const db = axisRefs[aj].directionFromNode;
                        if (!a || !b || !da || !db) continue;
                        const opposite = da.x * db.x + da.z * db.z < -0.85;
                        if (!opposite || !maStlUserFloorPlanLinesCollinearParallelXz(a, b)) continue;
                        for (let bk = 0; bk < axisRefs.length; bk++) {
                            if (bk === ai || bk === aj) continue;
                            const branch = rowsById[axisRefs[bk].lineId];
                            if (!branch || maStlUserFloorPlanLinesCollinearParallelXz(branch, a)) continue;
                            tCandidates.push({
                                throughAxisSegmentIds: [a.id, b.id],
                                branchAxisSegmentId: branch.id,
                                throughWallGroupIds: [a.wallGroupId, b.wallGroupId],
                                branchWallGroupId: branch.wallGroupId,
                            });
                        }
                    }
                }
            }

            if (axisRefs.length || faceRefs.length || tCandidates.length) {
                out.push({
                    nodeId: node.id,
                    point: node.point,
                    junctionType: node.junctionType,
                    axisEndpoints: axisRefs,
                    faceEndpointsNearNode: faceRefs,
                    tCandidates: tCandidates,
                });
            }
        }
        return out;
    }

    function maStlBuildWallConnectionsPayload() {
        const snapshot = maStlDesing2SerializeEditSnapshot();
        const rows = (snapshot.lines || []).slice().sort(function (a, b) {
            return (a.id || 0) - (b.id || 0);
        });
        const eps = maStlUserFloorLineMergeEndpointEpsMm();
        const nodes = [];
        const rowsById = Object.create(null);
        const lineDtos = [];
        const polylines = Object.create(null);
        const walls = Object.create(null);

        for (let i = 0; i < rows.length; i++) {
            const row = rows[i];
            if (!row || !row.p1Mm || !row.p2Mm || row.id == null) continue;
            rowsById[row.id] = row;
            const n1 = maStlWallConnectionsNodeForPoint(nodes, row.p1Mm, eps);
            const n2 = maStlWallConnectionsNodeForPoint(nodes, row.p2Mm, eps);
            n1.incidentEndpoints.push({ lineId: row.id, endpoint: 'p1' });
            n2.incidentEndpoints.push({ lineId: row.id, endpoint: 'p2' });
            const lineDto = {
                id: row.id,
                kind: maStlWallConnectionsSegmentKind(row),
                p1NodeId: n1.id,
                p2NodeId: n2.id,
                p1: maStlWallConnectionsPointDtoMm(row.p1Mm),
                p2: maStlWallConnectionsPointDtoMm(row.p2Mm),
                lengthMm: maStlUserFloorLineLengthMm(row),
            };
            if (row.polylineGroupId != null) lineDto.polylineGroupId = row.polylineGroupId;
            if (row.wallGroupId != null) lineDto.wallGroupId = row.wallGroupId;
            if (row.wallId != null) lineDto.wallId = row.wallId;
            else if (row.wallGroupId != null) lineDto.wallId = row.wallGroupId;
            if (row.wallRole) lineDto.wallRole = row.wallRole;
            if (row.linkOffsetFromLineId != null) lineDto.linkOffsetFromLineId = row.linkOffsetFromLineId;
            if (row.numberOffsetMm != null) lineDto.numberOffsetMm = row.numberOffsetMm;
            if (row.numberWallFaceSideSign != null) lineDto.numberWallFaceSideSign = row.numberWallFaceSideSign;
            maStlWallLineCopyAttrs(row, lineDto);
            lineDtos.push(lineDto);

            if (row.polylineGroupId != null) {
                const pgKey = String(row.polylineGroupId);
                if (!polylines[pgKey]) polylines[pgKey] = { id: row.polylineGroupId, segmentIds: [] };
                polylines[pgKey].segmentIds.push(row.id);
            }
            if (row.wallGroupId != null) {
                const wgKey = String(row.wallGroupId);
                if (!walls[wgKey]) walls[wgKey] = { id: row.wallGroupId, axisSegmentIds: [], faceSegmentIds: [] };
                if (row.wallId != null) walls[wgKey].wallId = row.wallId;
                else if (row.wallGroupId != null && walls[wgKey].wallId == null) {
                    walls[wgKey].wallId = row.wallGroupId;
                }
                if (row.wallRole === 'axis') walls[wgKey].axisSegmentIds.push(row.id);
                else if (row.wallRole === 'face') walls[wgKey].faceSegmentIds.push(row.id);
            }
        }

        const nodeConnections = [];
        for (let ni = 0; ni < nodes.length; ni++) {
            const node = nodes[ni];
            node.junctionType = maStlWallConnectionsClassifyNode(node, rowsById);
            if (node.incidentEndpoints.length >= 2) {
                nodeConnections.push({
                    kind: 'endpoint-node',
                    nodeId: node.id,
                    junctionType: node.junctionType,
                    endpoints: node.incidentEndpoints.slice(),
                    point: node.point,
                });
            }
        }

        const junctionDiagnostics = maStlWallConnectionsBuildJunctionDiagnostics(nodes, rowsById, rows);

        for (let ni = 0; ni < nodes.length; ni++) {
            delete nodes[ni].pointMm;
        }

        const bodyConnections = [];
        for (let ai = 0; ai < rows.length; ai++) {
            const a = rows[ai];
            if (!a || a.id == null) continue;
            const endpoints = [
                { key: 'p1', pt: a.p1Mm },
                { key: 'p2', pt: a.p2Mm },
            ];
            for (let ei = 0; ei < endpoints.length; ei++) {
                const ep = endpoints[ei];
                for (let bi = 0; bi < rows.length; bi++) {
                    const b = rows[bi];
                    if (!b || b.id == null || b.id === a.id) continue;
                    const hit = maStlWallConnectionsEndpointOnSegmentBody(ep.pt, b, eps);
                    if (!hit) continue;
                    bodyConnections.push({
                        kind: 'endpoint-segment',
                        sourceLineId: a.id,
                        sourceEndpoint: ep.key,
                        targetLineId: b.id,
                        targetKind: maStlWallConnectionsSegmentKind(b),
                        point: hit.point,
                        t: hit.t,
                        distXZMm: hit.distXZMm,
                    });
                }
            }
        }

        const stable = {
            schema: 'WallConnections.v1',
            source: 'Desing_2',
            units: {
                scene: 'mm',
                display: 'm',
                plane: 'XZ',
            },
            tolerances: {
                endpointMergeMm: eps,
            },
            rulerAnchor: maStlWallConnectionsPointDtoMm(snapshot.rulerAnchor || maStlRulerAnchorMm),
            counts: {
                lines: lineDtos.length,
                nodes: nodes.length,
                endpointConnections: nodeConnections.length,
                bodyConnections: bodyConnections.length,
                polylines: Object.keys(polylines).length,
                walls: Object.keys(walls).length,
                wallJunctionDiagnostics: junctionDiagnostics.length,
            },
            lines: lineDtos,
            polylines: Object.keys(polylines)
                .sort(function (a, b) { return Number(a) - Number(b); })
                .map(function (key) { return polylines[key]; }),
            walls: Object.keys(walls)
                .sort(function (a, b) { return Number(a) - Number(b); })
                .map(function (key) { return walls[key]; }),
            nodes: nodes,
            connections: nodeConnections.concat(bodyConnections),
            wallJunctionDiagnostics: junctionDiagnostics,
            generatedWallModel: maStlDesing2LastWallModelDetection,
        };
        return {
            stableJson: JSON.stringify(stable),
            payload: Object.assign(
                {
                    generatedAtUtc: new Date().toISOString(),
                    pageUrl: window.location.href,
                },
                stable
            ),
        };
    }

    function maStlBuildStraightWallsForFormwork() {
        const built = maStlBuildWallConnectionsPayload();
        if (!built || !built.payload || !Array.isArray(built.payload.lines)) return [];

        const seen = Object.create(null);
        return built.payload.lines
            .filter(function (line) {
                if (!line || line.id == null) return false;

                // Enfoque tipo legacy: coger todos los tramos rectos de muro candidatos
                // y descartar caras offset para no duplicar por cada lado.
                const isAxis = line.wallRole === 'axis' || line.kind === 'wallAxis';
                const isStraightCandidate = line.kind === 'polylineSegment' || line.kind === 'userLine';
                const isFace = line.wallRole === 'face' || line.kind === 'wallFace';
                if (isFace) return false;
                if (!isAxis && !isStraightCandidate) return false;

                const key = String(line.id);
                if (seen[key]) return false;
                seen[key] = true;
                return true;
            })
            .map(function (line) {
                const attrs = Object.assign({}, line);
                const wall = Object.assign({}, line, {
                    Id: line.wallId != null ? line.wallId : (line.wallGroupId != null ? line.wallGroupId : line.id),
                    LineId: line.id,
                    WallGroupId: line.wallGroupId != null ? line.wallGroupId : null,
                    Attributes: attrs,
                });

                return wall;
            });
    }

    function maStlBuildStraightWallsFromScene() {
        if (!scene) return [];

        const out = [];
        const seen = Object.create(null);

        scene.traverse(function (obj) {
            if (!obj) return;

            const ud = obj.userData && obj.userData.maStlUserPlanLine;
            const name = String(obj.name || '');

            const isStraightWallByUd = !!(
                ud &&
                ud.p1Mm &&
                ud.p2Mm &&
                (ud.wallRole === 'axis' || ud.wallRole == null)
            );
            const isStraightWallByName = name.indexOf('Wall_R000') === 0 || name.indexOf('Wall_R900') === 0;

            if (!isStraightWallByUd && !isStraightWallByName) return;

            const src = ud || obj;
            const lineId = src.id != null ? src.id : obj.id;
            const wallGroupId = src.wallGroupId != null ? src.wallGroupId : null;
            const wallId = src.wallId != null ? src.wallId : (wallGroupId != null ? wallGroupId : lineId);
            const dedupeKey = String(lineId != null ? lineId : wallId);
            if (seen[dedupeKey]) return;
            seen[dedupeKey] = true;

            if (ud) {
                maStlWallLineEnsureAttrs(ud);
            }

            const attrs = {};
            if (ud) {
                for (let i = 0; i < MA_STL_WALL_LINE_ATTR_KEYS.length; i++) {
                    const key = MA_STL_WALL_LINE_ATTR_KEYS[i];
                    if (Object.prototype.hasOwnProperty.call(ud, key)) {
                        attrs[key] = ud[key];
                    }
                }
            }

            const wall = {
                Id: wallId,
                LineId: lineId,
                WallGroupId: wallGroupId,
                WallRole: ud && ud.wallRole ? ud.wallRole : 'axis',
                Attributes: attrs,
            };

            if (ud && ud.p1Mm && ud.p2Mm) {
                wall.P1 = maStlWallConnectionsPointDtoMm(ud.p1Mm);
                wall.P2 = maStlWallConnectionsPointDtoMm(ud.p2Mm);
            }

            out.push(wall);
        });

        out.sort(function (a, b) {
            return Number(a.LineId || 0) - Number(b.LineId || 0);
        });
        return out;
    }

    function maStlBuildStraightWallsFromWallModelSource() {
        // Prioridad: sólidos/mallas de muro dibujados en 3D (fuente real para encofrado).
        const solidWalls = [];
        const seen = Object.create(null);

        function normalizeYawToRad(rawYaw) {
            const y = Number(rawYaw);
            if (!Number.isFinite(y)) return 0;
            return Math.abs(y) > (Math.PI * 2 + 1e-6) ? (y * Math.PI / 180) : y;
        }

        if (scene) {
            scene.traverse(function (obj) {
                if (!obj || !obj.userData || typeof obj.userData !== 'object') return;
                const attrs = obj.userData;
                const typeMesh = String(attrs._TypeMesh || attrs.TypeMesh || '').toLowerCase();
                if (typeMesh !== 'wall') return;

                const idWallRaw = attrs._idObject != null ? attrs._idObject : (attrs.Id != null ? attrs.Id : obj.id);
                const idWall = String(idWallRaw);
                if (!idWall || seen[idWall]) return;

                const lengthMmRaw = maStlDesing2MaybeMetersToSceneMm(Number(attrs._Datalong));
                const centerXRaw = maStlDesing2MaybeMetersToSceneMm(Number(attrs._XCoordinate));
                const centerYRaw = maStlDesing2MaybeMetersToSceneMm(Number(attrs._YCoordinate));
                const centerZRaw = maStlDesing2MaybeMetersToSceneMm(Number(attrs._ZCoordinate));

                if (!Number.isFinite(lengthMmRaw) || !Number.isFinite(centerXRaw) || !Number.isFinite(centerZRaw)) {
                    return;
                }

                const yaw = normalizeYawToRad(attrs._YrRtation);
                const half = Math.max(lengthMmRaw, 0) * 0.5;
                const ux = Math.cos(yaw);
                const uz = Math.sin(yaw);

                const startXmm = centerXRaw - ux * half;
                const startZmm = centerZRaw - uz * half;
                const endXmm = centerXRaw + ux * half;
                const endZmm = centerZRaw + uz * half;
                const yMm = Number.isFinite(centerYRaw) ? centerYRaw : 0;

                const enrichedAttrs = Object.assign({}, attrs, {
                    InicioX: startXmm,
                    InicioY: startZmm,
                    InicioZ: yMm,
                    FinX: endXmm,
                    FinY: endZmm,
                    FinZ: yMm,
                    __SourceSolid3D: true,
                });

                solidWalls.push({
                    Id: idWall,
                    LineId: idWall,
                    WallGroupId: attrs.wallGroupId != null ? String(attrs.wallGroupId) : null,
                    WallRole: 'axis',
                    P1: { xMm: startXmm, yMm: yMm, zMm: startZmm },
                    P2: { xMm: endXmm, yMm: yMm, zMm: endZmm },
                    Attributes: enrichedAttrs,
                });

                seen[idWall] = true;
            });
        }

        if (solidWalls.length) {
            return solidWalls;
        }

        // Fallback robusto: usar ejes de muros (maStlUserPlanLine) que alimentan
        // el inspector de atributos de muro 3D, evitando volver a Lineas 2D detectadas.
        const axisWalls = maStlBuildStraightWallsFromScene();
        for (let i = 0; i < axisWalls.length; i++) {
            const w = axisWalls[i];
            if (!w || !w.Attributes) continue;
            w.Attributes.__SourceSolid3D = false;
            w.Attributes.__SourceWallAxis3D = true;
        }
        return axisWalls;
    }

    const MA_STL_DESING2_ATK60_SAMPLE_GLB_URL = '/Content/DesignTools/Atk-60NewGeneration/GLB/27904209.glb';
    const MA_STL_DESING2_ATK60_SAMPLE_MARKER_RADIUS_MM = 85;
    const MA_STL_DESING2_ATK60_SAMPLE_MARKER_Y_OFFSET_MM = 20;
    const MA_STL_DESING2_ATK60_ANCHOR_POINT_RADIUS_MM = 65;
    const MA_STL_DESING2_ATK60_ANCHOR_POINT_COLOR_HEX = 0x11c1ff;
    const MA_STL_DESING2_ATK60_SAMPLE_DEFAULT_HEIGHT_MM = MA_STL_WALL3D_DEFAULT_HEIGHT_MM;
    const MA_STL_DESING2_ATK60_COLOR_FRAME_HEX = 0xcaa11b;
    const MA_STL_DESING2_ATK60_COLOR_PHENOLIC_HEX = 0x24211c;
    let maStlDesing2Atk60SampleTemplatePromise = null;
    const maStlDesing2Atk60ElementTemplatePromises = Object.create(null);
    let maStlDesing2Atk60SampleGroup = null;

    function maStlDesing2EnsureAtk60SampleGroup() {
        if (maStlDesing2Atk60SampleGroup) return maStlDesing2Atk60SampleGroup;
        maStlDesing2Atk60SampleGroup = new THREE.Group();
        maStlDesing2Atk60SampleGroup.name = 'maStlAtk60Samples';
        maStlDesing2Atk60SampleGroup.renderOrder = 140;
        scene.add(maStlDesing2Atk60SampleGroup);
        return maStlDesing2Atk60SampleGroup;
    }

    function maStlDesing2SyncAtk60SampleVisibility() {
        if (!maStlDesing2Atk60SampleGroup) return;
        maStlDesing2Atk60SampleGroup.visible = maStlDesing2ModelMode === 'wall3d';
    }

    function maStlDesing2MaybeMetersToSceneMm(v) {
        if (!Number.isFinite(v)) return null;
        const abs = Math.abs(v);
        if (abs <= 50) return v * MA_STL_SCENE_MM_PER_PHYSICAL_METER;
        return v;
    }

    function maStlDesing2Atk60WallPointToSceneMm(p) {
        if (!p || typeof p !== 'object') return null;
        const x = Number.isFinite(p.xMm) ? p.xMm : (Number.isFinite(p.x) ? p.x : null);
        const y = Number.isFinite(p.yMm) ? p.yMm : (Number.isFinite(p.y) ? p.y : null);
        const z = Number.isFinite(p.zMm) ? p.zMm : (Number.isFinite(p.z) ? p.z : null);
        if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(z)) return null;
        return { x: x, y: y, z: z };
    }

    function maStlDesing2Atk60ExtractWallEndpoints(wall) {
        if (!wall || typeof wall !== 'object') return null;
        const attrs = wall.Attributes && typeof wall.Attributes === 'object' ? wall.Attributes : null;
        const p1 = maStlDesing2Atk60WallPointToSceneMm(wall.P1 || (attrs ? attrs.p1 : null));
        const p2 = maStlDesing2Atk60WallPointToSceneMm(wall.P2 || (attrs ? attrs.p2 : null));
        if (p1 && p2) return { p1: p1, p2: p2 };
        return null;
    }

    function maStlDesing2Atk60PickLowerLeftVertexMm(p1, p2) {
        if (!p1 || !p2) return null;
        if (p1.z !== p2.z) return p1.z < p2.z ? p1 : p2;
        if (p1.x !== p2.x) return p1.x < p2.x ? p1 : p2;
        return p1;
    }

    function maStlDesing2Atk60ResolveWallThicknessMm(attrs) {
        if (!attrs || typeof attrs !== 'object') return MA_STL_DESING2_WALL_WIDTH_DEFAULT_MM;
        const fromDataWith = maStlDesing2MaybeMetersToSceneMm(Number(attrs._DataWith));
        if (Number.isFinite(fromDataWith) && fromDataWith > 1) return Math.abs(fromDataWith);
        const fromThickness = maStlDesing2MaybeMetersToSceneMm(Number(attrs.ThicknessMm));
        if (Number.isFinite(fromThickness) && fromThickness > 1) return Math.abs(fromThickness);
        const fromOffset = maStlDesing2MaybeMetersToSceneMm(Number(attrs.numberOffsetMm));
        if (Number.isFinite(fromOffset) && fromOffset > 0.5) return Math.abs(fromOffset) * 2;
        return MA_STL_DESING2_WALL_WIDTH_DEFAULT_MM;
    }

    function maStlDesing2Atk60ComputeWallsCentroidXz(walls) {
        if (!Array.isArray(walls) || walls.length === 0) return null;
        let sx = 0;
        let sz = 0;
        let c = 0;
        for (let i = 0; i < walls.length; i++) {
            const seg = maStlDesing2Atk60ExtractWallEndpoints(walls[i]);
            if (!seg) continue;
            sx += (seg.p1.x + seg.p2.x) * 0.5;
            sz += (seg.p1.z + seg.p2.z) * 0.5;
            c++;
        }
        if (!c) return null;
        return { x: sx / c, z: sz / c };
    }

    function maStlDesing2Atk60BuildPlacementFromWall(wall) {
        const seg = maStlDesing2Atk60ExtractWallEndpoints(wall);
        if (!seg) return null;
        const p1 = seg.p1;
        const p2 = seg.p2;
        const attrs = wall && wall.Attributes && typeof wall.Attributes === 'object' ? wall.Attributes : null;

        const inicioXRaw = attrs ? Number(attrs.InicioX) : NaN;
        const inicioYRaw = attrs ? Number(attrs.InicioY) : NaN;
        const inicioZRaw = attrs ? Number(attrs.InicioZ) : NaN;
        const inicioX = maStlDesing2MaybeMetersToSceneMm(inicioXRaw);
        const inicioY = maStlDesing2MaybeMetersToSceneMm(inicioYRaw);
        const inicioZ = maStlDesing2MaybeMetersToSceneMm(inicioZRaw);

        const axRaw = attrs ? Number(attrs._XCoordinate) : NaN;
        const ayRaw = attrs ? Number(attrs._YCoordinate) : NaN;
        const azRaw = attrs ? Number(attrs._ZCoordinate) : NaN;
        const ax = maStlDesing2MaybeMetersToSceneMm(axRaw);
        const ay = maStlDesing2MaybeMetersToSceneMm(ayRaw);
        const az = maStlDesing2MaybeMetersToSceneMm(azRaw);

        let anchor = null;

        // 1) Punto de inserción legacy del muro (inicio) si está disponible.
        if (Number.isFinite(inicioX) && Number.isFinite(inicioY) && Number.isFinite(inicioZ)) {
            anchor = { x: inicioX, y: inicioY, z: inicioZ };
        }

        // 2) Si no hay Inicio*, usar el vértice del tramo (extremo inferior-izquierdo).
        if (!anchor) {
            anchor = maStlDesing2Atk60PickLowerLeftVertexMm(p1, p2);
        }

        // 3) Último fallback: coordenada de muro genérica (suele ser centro).
        if (!anchor && Number.isFinite(ax) && Number.isFinite(ay) && Number.isFinite(az)) {
            anchor = { x: ax, y: ay, z: az };
        }

        if (!anchor) return null;
        const dx = p2.x - p1.x;
        const dz = p2.z - p1.z;
        const yaw = Math.atan2(dz, dx);
        const len = Math.sqrt(dx * dx + dz * dz);

        let targetHeightMm = MA_STL_DESING2_ATK60_SAMPLE_DEFAULT_HEIGHT_MM;
        const hRaw = attrs ? Number(attrs._DataHeight) : NaN;
        const hMm = maStlDesing2MaybeMetersToSceneMm(hRaw);
        if (Number.isFinite(hMm) && hMm > 1) {
            targetHeightMm = hMm;
        }

        const wallThicknessMm = maStlDesing2Atk60ResolveWallThicknessMm(attrs);
        const faceSignRaw = attrs ? Number(attrs.numberWallFaceSideSign) : NaN;

        return {
            position: anchor,
            yawRad: Number.isFinite(yaw) ? yaw : 0,
            targetHeightMm: targetHeightMm,
            wallThicknessMm: wallThicknessMm,
            faceSign: Number.isFinite(faceSignRaw) && faceSignRaw !== 0 ? (faceSignRaw > 0 ? 1 : -1) : 0,
            axisDx: dx,
            axisDz: dz,
            axisLen: len,
        };
    }

    function maStlDesing2EnsureAtk60SampleTemplate() {
        if (maStlDesing2Atk60SampleTemplatePromise) return maStlDesing2Atk60SampleTemplatePromise;
        maStlDesing2Atk60SampleTemplatePromise = new Promise(function (resolve, reject) {
            const loader = new GLTFLoader();
            loader.load(
                MA_STL_DESING2_ATK60_SAMPLE_GLB_URL,
                function (gltf) {
                    if (!gltf || !gltf.scene) {
                        reject(new Error('GLB sin escena válida.'));
                        return;
                    }
                    resolve(gltf.scene);
                },
                undefined,
                function (err) {
                    reject(err || new Error('No se pudo cargar el GLB ATK-60.'));
                }
            );
        });
        return maStlDesing2Atk60SampleTemplatePromise;
    }

    function maStlDesing2NormalizeAtk60ImportPath(importPath) {
        const raw = importPath != null ? String(importPath).trim() : '';
        if (!raw) return MA_STL_DESING2_ATK60_SAMPLE_GLB_URL;
        if (raw[0] === '/') return raw;
        const normalized = raw.replace(/\\/g, '/');
        const idx = normalized.toLowerCase().indexOf('/content/');
        if (idx >= 0) return normalized.substring(idx);
        return normalized;
    }

    function maStlDesing2EnsureAtk60ElementTemplate(importPath) {
        const resolvedPath = maStlDesing2NormalizeAtk60ImportPath(importPath);
        if (maStlDesing2Atk60ElementTemplatePromises[resolvedPath]) {
            return maStlDesing2Atk60ElementTemplatePromises[resolvedPath];
        }
        maStlDesing2Atk60ElementTemplatePromises[resolvedPath] = new Promise(function (resolve, reject) {
            const loader = new GLTFLoader();
            loader.load(
                resolvedPath,
                function (gltf) {
                    if (!gltf || !gltf.scene) {
                        reject(new Error('GLB sin escena válida.'));
                        return;
                    }
                    resolve(gltf.scene);
                },
                undefined,
                function (err) {
                    reject(err || new Error('No se pudo cargar el GLB ATK-60.'));
                }
            );
        });
        return maStlDesing2Atk60ElementTemplatePromises[resolvedPath];
    }

    function maStlDesing2CreateAtk60InsertionMarker(placement, wall) {
        const marker = new THREE.Mesh(
            new THREE.SphereGeometry(MA_STL_DESING2_ATK60_SAMPLE_MARKER_RADIUS_MM, 16, 12),
            new THREE.MeshBasicMaterial({ color: 0xff2d55 })
        );
        marker.position.set(
            placement.position.x,
            placement.position.y + MA_STL_DESING2_ATK60_SAMPLE_MARKER_Y_OFFSET_MM,
            placement.position.z
        );
        marker.userData = Object.assign({}, marker.userData || {}, {
            maStlAtk60SampleMarker: true,
            maStlAtk60SampleWallId: wall && wall.Id != null ? String(wall.Id) : null,
            maStlAtk60SampleLineId: wall && wall.LineId != null ? String(wall.LineId) : null,
        });
        return marker;
    }

    function maStlDesing2Atk60IsPhenolicMesh(mesh) {
        const nn = (mesh && mesh.name ? String(mesh.name) : '').toLowerCase();
        const mn = (mesh && mesh.material && mesh.material.name ? String(mesh.material.name) : '').toLowerCase();
        const tag = nn + ' ' + mn;
        if (!tag.trim()) return false;
        return (
            tag.indexOf('fenol') >= 0 ||
            tag.indexOf('phenol') >= 0 ||
            tag.indexOf('ply') >= 0 ||
            tag.indexOf('tablero') >= 0 ||
            tag.indexOf('madera') >= 0 ||
            tag.indexOf('infill') >= 0 ||
            tag.indexOf('fill') >= 0
        );
    }

    function maStlDesing2Atk60IsFrameMesh(mesh) {
        const nn = (mesh && mesh.name ? String(mesh.name) : '').toLowerCase();
        const mn = (mesh && mesh.material && mesh.material.name ? String(mesh.material.name) : '').toLowerCase();
        const tag = nn + ' ' + mn;
        if (!tag.trim()) return false;
        return (
            tag.indexOf('frame') >= 0 ||
            tag.indexOf('marco') >= 0 ||
            tag.indexOf('bastidor') >= 0 ||
            tag.indexOf('perfil') >= 0 ||
            tag.indexOf('edge') >= 0
        );
    }

    function maStlDesing2ApplyAtk60PanelColors(root) {
        if (!root) return;
        const meshes = [];
        root.traverse(function (obj) {
            if (obj && obj.isMesh && obj.material) meshes.push(obj);
        });
        if (!meshes.length) return;

        let taggedCount = 0;
        for (let i = 0; i < meshes.length; i++) {
            const mesh = meshes[i];
            let targetHex = null;
            if (maStlDesing2Atk60IsPhenolicMesh(mesh)) {
                targetHex = MA_STL_DESING2_ATK60_COLOR_PHENOLIC_HEX;
                taggedCount++;
            } else if (maStlDesing2Atk60IsFrameMesh(mesh)) {
                targetHex = MA_STL_DESING2_ATK60_COLOR_FRAME_HEX;
                taggedCount++;
            }
            if (targetHex == null) continue;

            const mat = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material;
            if (!mat) continue;
            mesh.material = mat.clone();
            if (mesh.material.color) {
                mesh.material.color.setHex(targetHex);
            }
            mesh.material.transparent = false;
            mesh.material.opacity = 1;
            if (mesh.material.alphaTest != null) mesh.material.alphaTest = 0;
            if (mesh.material.emissive) {
                mesh.material.emissive.setHex(0x000000);
                mesh.material.emissiveIntensity = 0;
            }
            mesh.material.needsUpdate = true;
        }

        if (taggedCount > 0) return;

        // Fallback estable: el mesh más grande se toma como marco; el resto como fenólico.
        let maxAreaIdx = 0;
        let maxArea = -1;
        for (let i = 0; i < meshes.length; i++) {
            const geom = meshes[i].geometry;
            if (!geom) continue;
            if (!geom.boundingBox) geom.computeBoundingBox();
            const bb = geom.boundingBox;
            if (!bb) continue;
            const sx = Math.max(bb.max.x - bb.min.x, 0);
            const sy = Math.max(bb.max.y - bb.min.y, 0);
            const sz = Math.max(bb.max.z - bb.min.z, 0);
            const areaProxy = sx * sy + sy * sz + sx * sz;
            if (areaProxy > maxArea) {
                maxArea = areaProxy;
                maxAreaIdx = i;
            }
        }

        for (let i = 0; i < meshes.length; i++) {
            const mesh = meshes[i];
            const targetHex = i === maxAreaIdx
                ? MA_STL_DESING2_ATK60_COLOR_FRAME_HEX
                : MA_STL_DESING2_ATK60_COLOR_PHENOLIC_HEX;
            const mat = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material;
            if (!mat) continue;
            mesh.material = mat.clone();
            if (mesh.material.color) {
                mesh.material.color.setHex(targetHex);
            }
            mesh.material.transparent = false;
            mesh.material.opacity = 1;
            if (mesh.material.alphaTest != null) mesh.material.alphaTest = 0;
            if (mesh.material.emissive) {
                mesh.material.emissive.setHex(0x000000);
                mesh.material.emissiveIntensity = 0;
            }
            mesh.material.needsUpdate = true;
        }
    }

    function maStlDesing2FitAtk60CloneScaleAndAnchor(clone, placement) {
        clone.position.set(0, 0, 0);
        clone.rotation.set(0, 0, 0);

        const preBox = new THREE.Box3().setFromObject(clone);
        const preSize = new THREE.Vector3();
        preBox.getSize(preSize);

        if (preSize.y > 1e-6 && Number.isFinite(placement.targetHeightMm) && placement.targetHeightMm > 1) {
            const s = placement.targetHeightMm / preSize.y;
            clone.scale.setScalar(s);
        }

        const localBox = new THREE.Box3().setFromObject(clone);
        clone.rotation.set(0, placement.yawRad, 0);
        clone.position.set(placement.position.x, placement.position.y, placement.position.z);
        clone.updateMatrixWorld(true);

        const bottomCornersLocal = [
            new THREE.Vector3(localBox.min.x, localBox.min.y, localBox.min.z),
            new THREE.Vector3(localBox.max.x, localBox.min.y, localBox.min.z),
            new THREE.Vector3(localBox.max.x, localBox.min.y, localBox.max.z),
            new THREE.Vector3(localBox.min.x, localBox.min.y, localBox.max.z),
        ];

        const axisLen = Number.isFinite(placement.axisLen) ? placement.axisLen : 0;
        const ux = axisLen > 1e-6 ? placement.axisDx / axisLen : Math.cos(placement.yawRad);
        const uz = axisLen > 1e-6 ? placement.axisDz / axisLen : Math.sin(placement.yawRad);

        let bestCornerWorld = null;
        let bestAxisComp = Infinity;
        let bestNormalAbs = Infinity;
        for (let i = 0; i < bottomCornersLocal.length; i++) {
            const worldCorner = clone.localToWorld(bottomCornersLocal[i].clone());
            const rx = worldCorner.x - placement.position.x;
            const rz = worldCorner.z - placement.position.z;
            const axisComp = rx * ux + rz * uz;
            const normalComp = -rx * uz + rz * ux;
            const normalAbs = Math.abs(normalComp);

            if (
                axisComp < bestAxisComp - 1e-6 ||
                (Math.abs(axisComp - bestAxisComp) <= 1e-6 && normalAbs < bestNormalAbs)
            ) {
                bestAxisComp = axisComp;
                bestNormalAbs = normalAbs;
                bestCornerWorld = worldCorner;
            }
        }

        if (bestCornerWorld) {
            clone.position.x += placement.position.x - bestCornerWorld.x;
            clone.position.y += placement.position.y - bestCornerWorld.y;
            clone.position.z += placement.position.z - bestCornerWorld.z;
        }
    }

    function maStlDesing2ToFiniteNumber(v) {
        const n = Number(v);
        return Number.isFinite(n) ? n : null;
    }

    function maStlDesing2NormalizeAngleToRad(v) {
        const n = maStlDesing2ToFiniteNumber(v);
        if (!Number.isFinite(n)) return 0;
        return Math.abs(n) > (Math.PI * 2 + 1e-6) ? (n * Math.PI / 180) : n;
    }

    function maStlDesing2RenderAtk60AnchorPoints(wallAnchors, opts) {
        if (!scene) throw new Error('Escena no disponible.');

        const sampleGroup = maStlDesing2EnsureAtk60SampleGroup();
        maStlDesing2SyncAtk60SampleVisibility();

        const sourceAnchors = Array.isArray(wallAnchors) ? wallAnchors : [];
        const options = opts && typeof opts === 'object' ? opts : {};
        const clearPrevious = options.clearPrevious !== false;

        if (clearPrevious) {
            for (let i = sampleGroup.children.length - 1; i >= 0; i--) {
                sampleGroup.remove(sampleGroup.children[i]);
            }
        }

        let inserted = 0;
        for (let i = 0; i < sourceAnchors.length; i++) {
            const anchor = sourceAnchors[i] || {};
            const x = maStlDesing2ToFiniteNumber(anchor.X);
            const y = maStlDesing2ToFiniteNumber(anchor.Y);
            const z = maStlDesing2ToFiniteNumber(anchor.Z);
            if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(z)) continue;

            const marker = new THREE.Mesh(
                new THREE.SphereGeometry(MA_STL_DESING2_ATK60_ANCHOR_POINT_RADIUS_MM, 16, 12),
                new THREE.MeshBasicMaterial({ color: MA_STL_DESING2_ATK60_ANCHOR_POINT_COLOR_HEX })
            );
            marker.position.set(x, y + MA_STL_DESING2_ATK60_SAMPLE_MARKER_Y_OFFSET_MM, z);
            marker.userData = Object.assign({}, marker.userData || {}, {
                maStlAtk60AnchorPoint: true,
                maStlAtk60SampleWallId: anchor.IdWall != null ? String(anchor.IdWall) : null,
            });
            sampleGroup.add(marker);
            inserted++;
        }

        return {
            inserted: inserted,
            requested: sourceAnchors.length,
        };
    }

    function maStlDesing2CreateAtk60ElementDebugProxy(item, x, y, z, rotY) {
        const widthMm = Math.max(50, maStlDesing2ToFiniteNumber(item.PieceWidthMm) || 900);
        const heightMm = Math.max(50, maStlDesing2ToFiniteNumber(item.PieceHeightMm) || 2700);
        const depthMm = Math.max(20, Math.min(120, (maStlDesing2ToFiniteNumber(item.WallThicknessMm) || 300) * 0.2));

        const orientation = item && item.Orientation != null ? String(item.Orientation).toLowerCase() : '';
        const color = orientation === 'tumbado' ? 0xff8f1f : 0x2ed573;

        const box = new THREE.Mesh(
            new THREE.BoxGeometry(widthMm, heightMm, depthMm),
            new THREE.MeshBasicMaterial({ color: color, transparent: true, opacity: 0.35 })
        );

        const ux = Math.cos(rotY || 0);
        const uz = Math.sin(rotY || 0);
        box.position.set(
            x + ux * (widthMm * 0.5),
            y + (heightMm * 0.5),
            z + uz * (widthMm * 0.5)
        );
        box.rotation.set(0, rotY || 0, 0);
        box.userData = Object.assign({}, box.userData || {}, {
            maStlAtk60ElementProxy: true,
            maStlAtk60ElementCode: item && item.ElementCode != null ? String(item.ElementCode) : '',
            maStlAtk60SampleWallId: item && item.IdWall != null ? String(item.IdWall) : null,
        });
        return box;
    }

    function maStlDesing2ClearAtk60Visuals() {
        if (!maStlDesing2Atk60SampleGroup) return;
        for (let i = maStlDesing2Atk60SampleGroup.children.length - 1; i >= 0; i--) {
            maStlDesing2Atk60SampleGroup.remove(maStlDesing2Atk60SampleGroup.children[i]);
        }
    }

    async function maStlDesing2RenderAtk60Elements(elementItems, opts) {
        if (!scene) throw new Error('Escena no disponible.');

        const sampleGroup = maStlDesing2EnsureAtk60SampleGroup();
        maStlDesing2SyncAtk60SampleVisibility();

        const sourceElements = Array.isArray(elementItems) ? elementItems : [];
        const options = opts && typeof opts === 'object' ? opts : {};
        const clearPrevious = options.clearPrevious === true;
        const drawDebugProxy = options.drawDebugProxy === true;

        if (clearPrevious) {
            for (let i = sampleGroup.children.length - 1; i >= 0; i--) {
                sampleGroup.remove(sampleGroup.children[i]);
            }
        }

        let inserted = 0;
        for (let i = 0; i < sourceElements.length; i++) {
            const item = sourceElements[i] || {};
            const x = maStlDesing2ToFiniteNumber(item.X);
            const y = maStlDesing2ToFiniteNumber(item.Y);
            const z = maStlDesing2ToFiniteNumber(item.Z);
            if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(z)) continue;

            const rotY = maStlDesing2NormalizeAngleToRad(item.RotY);

            if (drawDebugProxy) {
                const proxy = maStlDesing2CreateAtk60ElementDebugProxy(item, x, y, z, rotY);
                sampleGroup.add(proxy);
            }

            try {
                const template = await maStlDesing2EnsureAtk60ElementTemplate(item.ImportPath);
                const clone = template.clone(true);
                maStlDesing2ApplyAtk60PanelColors(clone);

                const pieceWidthMm = Math.max(10, maStlDesing2ToFiniteNumber(item.PieceWidthMm) || 900);
                const pieceHeightMm = Math.max(10, maStlDesing2ToFiniteNumber(item.PieceHeightMm) || 2700);

                // Insercion directa: escalar por altura de pieza y ubicar en ancla calculada por C#.
                clone.position.set(0, 0, 0);
                clone.rotation.set(0, 0, 0);
                const box = new THREE.Box3().setFromObject(clone);
                const size = new THREE.Vector3();
                box.getSize(size);
                if (size.y > 1e-6) {
                    const s = pieceHeightMm / size.y;
                    clone.scale.setScalar(s);
                }

                // Compensa GLB cuyo eje largo viene en Z local para que RotY siga el eje del muro.
                const yawAssetOffset = (size.z > (size.x * 1.25)) ? (-Math.PI * 0.5) : 0;
                const ux = Math.cos(rotY);
                const uz = Math.sin(rotY);
                const rotX = maStlDesing2NormalizeAngleToRad(item.RotX);
                const rotZ = maStlDesing2NormalizeAngleToRad(item.RotZ);

                let nx = maStlDesing2ToFiniteNumber(item.NormalX);
                let nz = maStlDesing2ToFiniteNumber(item.NormalZ);
                const faceSign = maStlDesing2ToFiniteNumber(item.FaceSign);
                if (!Number.isFinite(nx) || !Number.isFinite(nz)) {
                    const sign = (Number.isFinite(faceSign) && Math.abs(faceSign) > 1e-6)
                        ? (faceSign >= 0 ? 1 : -1)
                        : 1;
                    nx = -uz * sign;
                    nz = ux * sign;
                }
                const nn = Math.hypot(nx, nz);
                if (nn > 1e-9) {
                    nx /= nn;
                    nz /= nn;
                }

                const thicknessIsX = size.x <= size.z;
                const localOutSign = 1;
                const evaluateYawByOutwardNormal = function (yawCandidate) {
                    const localOut = thicknessIsX
                        ? new THREE.Vector3(localOutSign, 0, 0)
                        : new THREE.Vector3(0, 0, localOutSign);
                    localOut.applyEuler(new THREE.Euler(rotX, yawCandidate, rotZ, 'XYZ'));
                    return (localOut.x * nx) + (localOut.z * nz);
                };

                const yawCandidateA = rotY + yawAssetOffset;
                const yawCandidateB = yawCandidateA + Math.PI;
                const outAlignA = evaluateYawByOutwardNormal(yawCandidateA);
                const outAlignB = evaluateYawByOutwardNormal(yawCandidateB);
                const finalYaw = outAlignB > outAlignA ? yawCandidateB : yawCandidateA;

                clone.rotation.set(rotX, finalYaw, rotZ);
                clone.position.set(x, y, z);
                clone.updateMatrixWorld(true);

                // 1) Anclaje robusto de arranque en eje del muro (evita desplazamientos +0,90 esporadicos).
                const bottomCornersLocal = [
                    new THREE.Vector3(box.min.x, box.min.y, box.min.z),
                    new THREE.Vector3(box.max.x, box.min.y, box.min.z),
                    new THREE.Vector3(box.max.x, box.min.y, box.max.z),
                    new THREE.Vector3(box.min.x, box.min.y, box.max.z),
                ];

                let minAlong = Infinity;
                for (let ci = 0; ci < bottomCornersLocal.length; ci++) {
                    const wc = clone.localToWorld(bottomCornersLocal[ci].clone());
                    const rx = wc.x - x;
                    const rz = wc.z - z;
                    const along = (rx * ux) + (rz * uz);
                    if (along < minAlong) {
                        minAlong = along;
                    }
                }
                if (Number.isFinite(minAlong)) {
                    clone.position.x += (-minAlong * ux);
                    clone.position.z += (-minAlong * uz);
                    clone.updateMatrixWorld(true);
                }

                // 2) Ajuste estable solo en la normal exterior:
                // evita meter paneles en cara interior sin alterar la progresion sobre el eje del muro.
                let maxOut = -Infinity;
                for (let ci = 0; ci < bottomCornersLocal.length; ci++) {
                    const wc = clone.localToWorld(bottomCornersLocal[ci].clone());
                    const rx = wc.x - x;
                    const rz = wc.z - z;
                    const out = (rx * nx) + (rz * nz);
                    if (out > maxOut) {
                        maxOut = out;
                    }
                }

                if (Number.isFinite(maxOut)) {
                    clone.position.x += (-maxOut * nx);
                    clone.position.z += (-maxOut * nz);
                }

                // Regla de negocio solicitada:
                // - Todos los muros: separar 0,12 m hacia exterior.
                clone.position.x += nx * 120;
                clone.position.z += nz * 120;
                clone.userData = Object.assign({}, clone.userData || {}, {
                    maStlAtk60SamplePlaced: true,
                    maStlAtk60Element: true,
                    maStlAtk60ElementCode: item.ElementCode != null ? String(item.ElementCode) : '',
                    maStlAtk60ElementType: item.ElementType != null ? String(item.ElementType) : '',
                    maStlAtk60ElementOrientation: item.Orientation != null ? String(item.Orientation) : '',
                    maStlAtk60SampleWallId: item.IdWall != null ? String(item.IdWall) : null,
                    maStlAtk60FaceSign: Number.isFinite(faceSign) ? faceSign : null,
                });
                sampleGroup.add(clone);
                inserted++;
            } catch (err) {
                const msg = err && err.message ? err.message : String(err || 'Error GLB');
                console.error('ATK-60 no pudo pintar elemento:', item, msg);
            }
        }

        return {
            inserted: inserted,
            requested: sourceElements.length,
        };
    }

    async function maStlDesing2InsertAtk60SampleOnWalls(walls, opts) {
        if (!scene) throw new Error('Escena no disponible.');
        const sampleGroup = maStlDesing2EnsureAtk60SampleGroup();
        maStlDesing2SyncAtk60SampleVisibility();
        const sourceWalls = Array.isArray(walls) ? walls : [];
        const centroidXz = maStlDesing2Atk60ComputeWallsCentroidXz(sourceWalls);
        const options = opts && typeof opts === 'object' ? opts : {};
        const clearPrevious = options.clearPrevious !== false;

        if (clearPrevious) {
            for (let i = sampleGroup.children.length - 1; i >= 0; i--) {
                sampleGroup.remove(sampleGroup.children[i]);
            }
        }

        const template = await maStlDesing2EnsureAtk60SampleTemplate();
        let inserted = 0;

        for (let i = 0; i < sourceWalls.length; i++) {
            const wall = sourceWalls[i];
            const placement = maStlDesing2Atk60BuildPlacementFromWall(wall);
            if (!placement) continue;

            if (placement.axisLen > 1e-6) {
                const nx = -placement.axisDz / placement.axisLen;
                const nz = placement.axisDx / placement.axisLen;
                let sign = placement.faceSign;
                if (!sign) {
                    if (centroidXz) {
                        const vx = placement.position.x - centroidXz.x;
                        const vz = placement.position.z - centroidXz.z;
                        sign = (vx * nx + vz * nz) >= 0 ? 1 : -1;
                    } else {
                        sign = 1;
                    }
                }
                const halfWall = Math.max(placement.wallThicknessMm || MA_STL_DESING2_WALL_WIDTH_DEFAULT_MM, 1) * 0.5;
                placement.position.x += nx * sign * halfWall;
                placement.position.z += nz * sign * halfWall;
            }

            const marker = maStlDesing2CreateAtk60InsertionMarker(placement, wall);
            sampleGroup.add(marker);

            const clone = template.clone(true);
            maStlDesing2ApplyAtk60PanelColors(clone);
            maStlDesing2FitAtk60CloneScaleAndAnchor(clone, placement);
            clone.userData = Object.assign({}, clone.userData || {}, {
                maStlAtk60SamplePlaced: true,
                maStlAtk60SampleWallId: wall && wall.Id != null ? String(wall.Id) : null,
                maStlAtk60SampleLineId: wall && wall.LineId != null ? String(wall.LineId) : null,
            });
            sampleGroup.add(clone);
            inserted++;
        }

        return {
            inserted: inserted,
            requested: sourceWalls.length,
            glbUrl: MA_STL_DESING2_ATK60_SAMPLE_GLB_URL,
        };
    }

    if (typeof window !== 'undefined') {
        window.maStlDesing2GetStraightWallsForFormwork = maStlBuildStraightWallsForFormwork;
        window.maStlDesing2GetStraightWallsFromScene = maStlBuildStraightWallsFromScene;
        window.maStlDesing2GetStraightWallsFromWallModelSource = maStlBuildStraightWallsFromWallModelSource;
        window.maStlDesing2BuildWallConnectionsPayload = maStlBuildWallConnectionsPayload;
        window.maStlDesing2RenderAtk60AnchorPoints = maStlDesing2RenderAtk60AnchorPoints;
        window.maStlDesing2RenderAtk60Elements = maStlDesing2RenderAtk60Elements;
    }

    function maStlBuildWallDiagnosticsPayload(reason) {
        const built = maStlBuildWallConnectionsPayload();
        if (!built || !built.payload) return null;
        const payload = Object.assign({}, built.payload);
        payload.schema = 'WallDiagnostics.v1';
        payload.reason = reason || 'wall-dim-tool';
        payload.outputPath = 'C:\\temp\\WallDiagnostics.json';
        payload.wallAxisSegments = (payload.lines || []).filter(function (line) {
            return line && line.wallRole === 'axis';
        });
        payload.wallFaceSegments = (payload.lines || []).filter(function (line) {
            return line && line.wallRole === 'face';
        });
        return payload;
    }

    function maStlSaveWallDiagnosticsNow(reason) {
        if (!maStlDesingV2Viewer) return;
        const apiUrl = maStlDesing2WallDiagnosticsApiUrl();
        if (!apiUrl) return;
        const payload = maStlBuildWallDiagnosticsPayload(reason);
        if (!payload) return;
        try {
            fetch(apiUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'same-origin',
                body: JSON.stringify(payload),
            })
                .then(function (r) {
                    return r
                        .json()
                        .catch(function () {
                            return null;
                        });
                })
                .then(function (resp) {
                    if (!resp || resp.Exito !== true) {
                        throw new Error((resp && resp.Mensaje) || 'No se pudo guardar WallDiagnostics.json');
                    }
                })
                .catch(function (err) {
                    if (maStlStlViewerIsLocalDevHost() && window.console && console.warn) {
                        console.warn('[Desing_2] WallDiagnostics.json no guardado', err);
                    }
                });
        } catch (err) {
            if (maStlStlViewerIsLocalDevHost() && window.console && console.warn) {
                console.warn('[Desing_2] WallDiagnostics.json no guardado', err);
            }
        }
    }

    function maStlSaveWallConnectionsNow(options) {
        if (!maStlDesingV2Viewer) return;
        const apiUrl = maStlDesing2WallConnectionsApiUrl();
        if (!apiUrl) return;
        const force = !!(options && options.force);
        const built = maStlBuildWallConnectionsPayload();
        if (!built || (!force && built.stableJson === maStlWallConnectionsLastStableJson)) return;
        maStlWallConnectionsLastStableJson = built.stableJson;
        if (options && options.reason) {
            built.payload.saveReason = options.reason;
        }
        fetch(apiUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
            body: JSON.stringify(built.payload),
            credentials: 'same-origin',
        })
            .then(function (res) {
                if (!res.ok) throw new Error('HTTP ' + res.status);
                return res.json();
            })
            .then(function (resp) {
                if (!resp || !resp.Exito) {
                    throw new Error((resp && resp.Mensaje) || 'No se pudo guardar WallConnections.json');
                }
            })
            .catch(function (err) {
                maStlWallConnectionsLastStableJson = '';
                if (window.console && console.warn) {
                    console.warn('[Desing_2] WallConnections.json no guardado', err);
                }
            });
    }

    function maStlDesing2EditSnapshotsEqual(a, b) {
        if (!a || !b) return false;
        return JSON.stringify(a) === JSON.stringify(b);
    }

    /** Restaura líneas usuario y anclaje reglas desde snapshot (no afecta cámara/órbita). */
    function maStlDesing2ApplyEditSnapshot(snapshot) {
        if (!snapshot || !maStlUserLinesGroup) return;
        maStlDesing2UndoApplying = true;
        try {
            maStlDisposeUserFloorLineDimEdit(true);
            maStlClearUserFloorLineSelection();
            maStlClearUserFloorLineHover();
            maStlClearUserFloorEndpointDragSnapPreview();
            maStlClearLineToolVertexSnapHighlight();

            const toRemove = [];
            const chRem = maStlUserLinesGroup.children;
            for (let ri = 0; ri < chRem.length; ri++) {
                const ln = chRem[ri];
                if (maStlIsUserFloorPlanLineObject(ln)) toRemove.push(ln);
            }
            for (let rj = 0; rj < toRemove.length; rj++) {
                maStlUserLinesGroup.remove(toRemove[rj]);
                disposeObject3D(toRemove[rj]);
            }

            const rows = snapshot.lines || [];
            let maxId = 0;
            let maxPolylineGroupId = 0;
            let maxWallGroupId = 0;
            for (let li = 0; li < rows.length; li++) {
                const row = rows[li];
                if (!row || !row.p1Mm || !row.p2Mm) continue;
                const geo = maStlCreateUserFloorLineGeometryMm(row.p1Mm, row.p2Mm);
                let mat;
                if (row.wallRole === 'axis') {
                    mat = maStlCloneUserFloorWallAxisLineMaterial();
                } else {
                    const um = maStlEnsureUserFloorLineMat();
                    mat = um.clone ? um.clone() : um;
                }
                const line = new Line2(geo, mat);
                line.renderOrder = row.wallRole === 'axis' ? 170 : 168;
                const planUd = {
                    id: row.id,
                    p1Mm: maStlDesing2ClonePlanPointMm(row.p1Mm),
                    p2Mm: maStlDesing2ClonePlanPointMm(row.p2Mm),
                };
                if (row.polylineGroupId != null) {
                    planUd.polylineGroupId = row.polylineGroupId;
                    if (row.polylineGroupId > maxPolylineGroupId) {
                        maxPolylineGroupId = row.polylineGroupId;
                    }
                }
                if (row.wallGroupId != null) {
                    planUd.wallGroupId = row.wallGroupId;
                    if (row.wallGroupId > maxWallGroupId) {
                        maxWallGroupId = row.wallGroupId;
                    }
                }
                if (row.wallId != null) {
                    planUd.wallId = row.wallId;
                } else if (row.wallGroupId != null) {
                    planUd.wallId = row.wallGroupId;
                }
                if (row.wallRole) {
                    planUd.wallRole = row.wallRole;
                }
                if (row.linkOffsetFromLineId != null) {
                    planUd.linkOffsetFromLineId = row.linkOffsetFromLineId;
                }
                if (row.numberOffsetMm != null) {
                    planUd.numberOffsetMm = row.numberOffsetMm;
                }
                if (row.numberWallFaceSideSign != null) {
                    planUd.numberWallFaceSideSign = row.numberWallFaceSideSign;
                }
                maStlWallLineCopyAttrs(row, planUd);
                maStlWallLineEnsureAttrs(planUd);
                line.userData.maStlUserPlanLine = planUd;
                maStlDisableRaycastOnOverlay(line);
                maStlUserLinesGroup.add(line);
                maStlUserFloorLineSyncAxisDashDistances(line);
                if (row.id > maxId) maxId = row.id;
            }
            maStlUserFloorLineNextSegId = Math.max(snapshot.nextSegId || 1, maxId + 1);
            maStlUserFloorLineNextPolylineGroupId = Math.max(
                snapshot.nextPolylineGroupId || 1,
                maxPolylineGroupId + 1
            );
            maStlUserFloorLineNextWallGroupId = Math.max(
                snapshot.nextWallGroupId || 1,
                maxWallGroupId + 1
            );

            const ra = snapshot.rulerAnchor;
            if (ra) {
                maStlRulerAnchorMm.set(ra.x, ra.y, ra.z);
            }
            if (Object.prototype.hasOwnProperty.call(snapshot, 'stlMeshUuids')) {
                maStlDesing2ApplyStlMeshSnapshotFromUuids(snapshot.stlMeshUuids || []);
            }
            maStlInvalidateUserFloorDimGuideGeomCache();
            rebuildMaStlUcsOverlayDecor(lastMaxDim);
            maStlReapplyAllUserFloorWallAxisLineStyles();
            maStlHideUserFloorLineDimHud(true);
            maStlSyncRulerAnchorCoordsHud();
        } finally {
            maStlDesing2UndoApplying = false;
            maStlDesing2SyncUndoRedoToolbarUi();
        }
    }

    /**
     * Registra acción undo/redo genérica. API pública para comandos futuros Desing_2.
     * @param {{ label?: string, undo: function(): void, redo: function(): void }} action
     */
    function maStlDesing2PushUndoAction(action) {
        if (maStlDesing2UndoApplying || !maStlDesingV2Viewer) return;
        if (!action || typeof action.undo !== 'function' || typeof action.redo !== 'function') return;
        maStlDesing2UndoStack.push({
            label: action.label || '',
            undo: action.undo,
            redo: action.redo,
        });
        maStlDesing2RedoStack.length = 0;
        maStlDesing2SyncUndoRedoToolbarUi();
    }

    function maStlDesing2PushEditSnapshotUndo(label, beforeSnap, afterSnap) {
        if (maStlDesing2EditSnapshotsEqual(beforeSnap, afterSnap)) return;
        maStlDesing2PushUndoAction({
            label: label || '',
            undo: function () {
                maStlDesing2ApplyEditSnapshot(beforeSnap);
            },
            redo: function () {
                maStlDesing2ApplyEditSnapshot(afterSnap);
            },
        });
    }

    function maStlDesing2SyncUndoRedoToolbarUi() {
        if (maStlDesing2UndoBtn) {
            const canUndo = maStlDesing2UndoStack.length > 0;
            maStlDesing2UndoBtn.disabled = !canUndo;
            maStlDesing2UndoBtn.setAttribute('aria-disabled', canUndo ? 'false' : 'true');
        }
        if (maStlDesing2RedoBtn) {
            const canRedo = maStlDesing2RedoStack.length > 0;
            maStlDesing2RedoBtn.disabled = !canRedo;
            maStlDesing2RedoBtn.setAttribute('aria-disabled', canRedo ? 'false' : 'true');
        }
    }

    function maStlDesing2Undo() {
        if (!maStlDesingV2Viewer || maStlDesing2UndoStack.length === 0) return false;
        const action = maStlDesing2UndoStack.pop();
        maStlDesing2UndoApplying = true;
        try {
            action.undo();
            maStlWall2dToolRefreshResumeStateFromScene();
        } finally {
            maStlDesing2UndoApplying = false;
        }
        maStlDesing2RedoStack.push(action);
        maStlDesing2SyncUndoRedoToolbarUi();
        return true;
    }

    function maStlDesing2Redo() {
        if (!maStlDesingV2Viewer || maStlDesing2RedoStack.length === 0) return false;
        const action = maStlDesing2RedoStack.pop();
        maStlDesing2UndoApplying = true;
        try {
            action.redo();
            maStlWall2dToolMaybeAutoResumeAfterRedo();
        } finally {
            maStlDesing2UndoApplying = false;
        }
        maStlDesing2UndoStack.push(action);
        maStlDesing2SyncUndoRedoToolbarUi();
        return true;
    }

    function maStlDesing2TryFinalizeDragUndo(label) {
        if (!_maStlDesing2DragUndoBeforeSnapshot) return;
        const before = _maStlDesing2DragUndoBeforeSnapshot;
        _maStlDesing2DragUndoBeforeSnapshot = null;
        const after = maStlDesing2SerializeEditSnapshot();
        maStlDesing2PushEditSnapshotUndo(label, before, after);
    }

    function maStlSyncAllUserFloorLineMaterialResolutions(widthPx, heightPx) {
        maStlApplyUserFloorLineMaterialResolution(maStlUserFloorLineMat, widthPx, heightPx);
        if (maStlUserFloorWallAxisLineMat) {
            maStlApplyUserFloorLineMaterialResolution(maStlUserFloorWallAxisLineMat, widthPx, heightPx);
        }
        if (maStlUserLinesGroup) {
            for (let uli = 0; uli < maStlUserLinesGroup.children.length; uli++) {
                const o = maStlUserLinesGroup.children[uli];
                if (o.material) {
                    maStlApplyUserFloorLineMaterialResolution(o.material, widthPx, heightPx);
                }
            }
        }
        if (maStlLineToolRubberBandLine && maStlLineToolRubberBandLine.material) {
            maStlApplyUserFloorLineMaterialResolution(
                maStlLineToolRubberBandLine.material,
                widthPx,
                heightPx
            );
        }
        if (maStlWall2dToolRubberBandFacePlus && maStlWall2dToolRubberBandFacePlus.material) {
            maStlApplyUserFloorLineMaterialResolution(
                maStlWall2dToolRubberBandFacePlus.material,
                widthPx,
                heightPx
            );
        }
        if (maStlWall2dToolRubberBandFaceMinus && maStlWall2dToolRubberBandFaceMinus.material) {
            maStlApplyUserFloorLineMaterialResolution(
                maStlWall2dToolRubberBandFaceMinus.material,
                widthPx,
                heightPx
            );
        }
        if (maStlOffsetToolPreviewLine && maStlOffsetToolPreviewLine.material) {
            maStlApplyUserFloorLineMaterialResolution(
                maStlOffsetToolPreviewLine.material,
                widthPx,
                heightPx
            );
        }
        for (let opi = 0; opi < maStlOffsetToolPreviewLines.length; opi++) {
            const opl = maStlOffsetToolPreviewLines[opi];
            if (opl && opl.material) {
                maStlApplyUserFloorLineMaterialResolution(opl.material, widthPx, heightPx);
            }
        }
        for (let cpi = 0; cpi < maStlCopyToolPreviewLines.length; cpi++) {
            const cpl = maStlCopyToolPreviewLines[cpi];
            if (cpl && cpl.material) {
                maStlApplyUserFloorLineMaterialResolution(cpl.material, widthPx, heightPx);
            }
        }
    }
    /** Hijo opcional del grupo anclaje: cruz cyan, visible solo cuando reglas están en pantalla. */
    let maStlRulerAnchorCrossObject = null;
    /** Esfera roja del anclaje; permanece cuando se ocultan reglas (#ma-stl-ucs-rulers-toggle). */
    let maStlRulerAnchorBallMesh = null;

    function maStlStripOverlayMeshes(group) {
        if (!group) return;
        while (group.children.length > 0) {
            const ch = group.children[0];
            const disposedMats = new WeakSet();
            ch.traverse(function (c) {
                if (c.geometry) {
                    c.geometry.dispose();
                }
                const mats = Array.isArray(c.material) ? c.material : c.material ? [c.material] : [];
                mats.forEach(function (m) {
                    if (!m || disposedMats.has(m)) return;
                    disposedMats.add(m);
                    if (m.map) m.map.dispose();
                    if (m.dispose) m.dispose();
                });
            });
            group.remove(ch);
        }
    }

    function maStlDesing2SetSourceLinesVisible(visible) {
        if (maStlUserLinesGroup) maStlUserLinesGroup.visible = !!visible;
        if (maStlUserFloorLineDimHudGroup) maStlUserFloorLineDimHudGroup.visible = !!visible;
        maStlWall2dToolHideFaceRubberBands();
        maStlLineToolHidePreviewDimHud();
        maStlHideUserFloorLineDimHud(true);
    }

    function maStlWall2dModelClearGenerated() {
        maStlStripOverlayMeshes(maStlWall2dModelMeshesGroup);
    }

    function maStlWall3dModelClearGenerated() {
        maStlWall3dInspectClearHoverMesh();
        if (!maStlWall3dMeshesGroup) return;
        const generated = [];
        maStlWall3dMeshesGroup.traverse(function (obj) {
            if (obj && obj.isMesh && obj.userData && obj.userData.maStlWall3dGenerated) {
                generated.push(obj);
            }
        });
        for (let i = 0; i < generated.length; i++) {
            const mesh = generated[i];
            const idx = clipStlMeshes.indexOf(mesh);
            if (idx >= 0) clipStlMeshes.splice(idx, 1);
        }
        maStlStripOverlayMeshes(maStlWall3dMeshesGroup);
        maStlWall3dConcreteMapActive = false;
        maStlSyncWall3dMapBtnUi();
        updateClipPlanes();
        syncGroundShadowToggleUi();
    }

    function maStlDesing2ClearGeneratedWallModels() {
        maStlWall2dModelClearGenerated();
        maStlWall3dModelClearGenerated();
    }

    function maStlDesing2SetWallModelRenderingVisible(visible) {
        if (!maStlWallModelRenderOverlay) return;
        maStlWallModelRenderOverlay.classList.toggle('d-none', !visible);
        maStlWallModelRenderOverlay.setAttribute('aria-hidden', visible ? 'false' : 'true');
    }

    function maStlDesing2CollectWallModelSourceLines() {
        const faces = [];
        const plain = [];
        if (!maStlUserLinesGroup) return plain;
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const line = ch[i];
            if (!maStlIsUserFloorPlanLineObject(line)) continue;
            const ud = line.userData && line.userData.maStlUserPlanLine;
            if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
            if (ud.wallRole === 'axis') continue;
            if (ud.wallRole === 'face') faces.push(line);
            else plain.push(line);
        }
        return faces.length ? faces : plain;
    }

    function maStlDesing2BuildWallModelDetectionPayload() {
        const sourceLines = maStlDesing2CollectWallModelSourceLines();
        const lineas = [];
        for (let i = 0; i < sourceLines.length; i++) {
            const dto = maStlWall3dUserLineToDto(sourceLines[i]);
            if (dto) lineas.push(dto);
        }
        return {
            payload: {
                Lineas: lineas,
                TotalSeleccionados: lineas.length,
                TotalLineas: lineas.length,
                TotalPolilineas: 0,
                FechaSeleccion: new Date().toISOString(),
                Usuario: 'Desing_2',
                AlturaMuroMm: MA_STL_WALL3D_DEFAULT_HEIGHT_MM,
            },
            sourceCount: sourceLines.length,
        };
    }

    function maStlDesing2SummarizeWallModelDetection(mode, payload, datos, generatedCount) {
        return {
            mode: mode,
            system: 'Atk-60',
            generatedAtUtc: new Date().toISOString(),
            source: {
                totalLineas: payload && payload.Lineas ? payload.Lineas.length : 0,
                lineas: payload && payload.Lineas ? payload.Lineas : [],
            },
            result: datos || null,
            counts: {
                generatedMeshes: generatedCount || 0,
                polilineas: datos && datos.PolilineasADibujar ? datos.PolilineasADibujar.length : 0,
                murosRectos: datos && datos.TotalMurosRectos != null ? datos.TotalMurosRectos : 0,
                esquinas: datos && datos.TotalEsquinasDetectadas != null ? datos.TotalEsquinasDetectadas : 0,
            },
        };
    }

    function maStlDesing2RequestWallModelDetection(mode, onSuccess, onError) {
        const apiUrl = maStlWall3dGetApiUrl();
        if (!apiUrl) {
            const err = new Error('API muros no configurada');
            maStlDesing2SetWallModelRenderingVisible(false);
            if (onError) onError(err);
            return;
        }
        const built = maStlDesing2BuildWallModelDetectionPayload();
        if (!built.payload.Lineas.length) {
            const noLines = new Error('No hay líneas fuente para generar el modelo');
            maStlDesing2SetWallModelRenderingVisible(false);
            if (onError) onError(noLines);
            return;
        }
        maStlDesing2WallModelBusy = true;
        maStlDesing2SetWallModelRenderingVisible(true);
        fetch(apiUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
            body: JSON.stringify(built.payload),
            credentials: 'same-origin',
        })
            .then(function (res) {
                if (!res.ok) throw new Error('HTTP ' + res.status);
                return res.json();
            })
            .then(function (resp) {
                maStlDesing2WallModelBusy = false;
                if (!resp || !resp.Exito || !resp.Datos) {
                    throw new Error((resp && resp.Mensaje) || 'Error desconocido');
                }
                if (onSuccess) onSuccess(resp.Datos, built.payload);
                maStlDesing2SetWallModelRenderingVisible(false);
            })
            .catch(function (err) {
                maStlDesing2WallModelBusy = false;
                maStlDesing2SetWallModelRenderingVisible(false);
                if (onError) onError(err);
            });
    }

    function maStlWall2dModelMaterial(colorHex, opacity) {
        return new THREE.MeshBasicMaterial({
            color: colorHex,
            opacity: opacity,
            transparent: opacity < 1,
            side: THREE.DoubleSide,
            depthWrite: false,
        });
    }

    function maStlWall2dModelSignedAreaXz(points) {
        if (!points || points.length < 3) return 0;
        let sum = 0;
        for (let i = 0; i < points.length; i++) {
            const a = points[i];
            const b = points[(i + 1) % points.length];
            sum += a.x * b.z - b.x * a.z;
        }
        return sum * 0.5;
    }

    function maStlWall2dModelOrderClockwiseXz(points) {
        if (!points || points.length < 3) return points || [];
        const out = points.map(function (p) {
            return { x: p.x, z: p.z };
        });
        if (maStlWall2dModelSignedAreaXz(out) > 0) out.reverse();
        return out;
    }

    function maStlWall2dModelAddRectVertexRefs(points, baseY) {
        if (!points || points.length !== 4 || !maStlWall2dModelMeshesGroup) return false;
        const ordered = maStlWall2dModelOrderClockwiseXz(points);
        const root = new THREE.Group();
        root.userData.maStlWall2dModelGenerated = true;
        root.userData.maStlWall2dRectRefs = true;
        root.renderOrder = 130;
        let cx = 0;
        let cz = 0;
        for (let ci = 0; ci < ordered.length; ci++) {
            cx += ordered[ci].x;
            cz += ordered[ci].z;
        }
        cx /= ordered.length;
        cz /= ordered.length;
        const markHalf = 42;
        const markThickness = 10;
        const labelScale = 112;
        const labelOffset = 150;
        const labels = ['R-1', 'R-2', 'R-3', 'R-4'];
        for (let i = 0; i < ordered.length; i++) {
            const pt = ordered[i];
            const markMat = new THREE.MeshBasicMaterial({
                color: 0xff2d2d,
                depthTest: false,
                depthWrite: false,
            });
            const armA = new THREE.Mesh(
                new THREE.BoxGeometry(markHalf * 2, 2, markThickness),
                markMat
            );
            armA.position.set(pt.x, baseY + 2, pt.z);
            armA.rotation.y = Math.PI / 4;
            armA.renderOrder = 130;
            root.add(armA);
            const armB = new THREE.Mesh(
                new THREE.BoxGeometry(markHalf * 2, 2, markThickness),
                markMat
            );
            armB.position.set(pt.x, baseY + 2, pt.z);
            armB.rotation.y = -Math.PI / 4;
            armB.renderOrder = 130;
            root.add(armB);

            const prev = ordered[(i + ordered.length - 1) % ordered.length];
            const next = ordered[(i + 1) % ordered.length];
            let prevX = prev.x - pt.x;
            let prevZ = prev.z - pt.z;
            let nextX = next.x - pt.x;
            let nextZ = next.z - pt.z;
            const prevLen = Math.hypot(prevX, prevZ);
            const nextLen = Math.hypot(nextX, nextZ);
            if (prevLen > 1e-6) {
                prevX /= prevLen;
                prevZ /= prevLen;
            }
            if (nextLen > 1e-6) {
                nextX /= nextLen;
                nextZ /= nextLen;
            }
            let dirX = prevX + nextX;
            let dirZ = prevZ + nextZ;
            let dirLen = Math.hypot(dirX, dirZ);
            if (dirLen <= 1e-6) {
                dirX = cx - pt.x;
                dirZ = cz - pt.z;
                dirLen = Math.hypot(dirX, dirZ);
            }
            if (dirLen > 1e-6) {
                dirX /= dirLen;
                dirZ /= dirLen;
            } else {
                dirX = 1;
                dirZ = 0;
            }

            const sp = maStlMakeTextSprite(labels[i], labelScale, {
                thinFillOnly: true,
                fillColor: '#ff2d2d',
                fontPx: 16,
                fontWeight: 600,
                canvasPad: 2,
                thinPillFill: null,
                thinPillStroke: null,
                strokeRatio: 0,
            });
            if (sp) {
                sp.position.set(pt.x + dirX * labelOffset, baseY + labelScale * 0.25, pt.z + dirZ * labelOffset);
                sp.renderOrder = 131;
                root.add(sp);
            }
        }
        maStlDisableRaycastOnOverlay(root);
        maStlWall2dModelMeshesGroup.add(root);
        return true;
    }

    function maStlWall2dModelAddPolygon(points, colorHex, opacity, kind) {
        if (!points || points.length < 3 || !maStlWall2dModelMeshesGroup) return null;
        const isCornerKind = kind === 'cornerL' || kind === 'cornerT' || kind === 'cornerX';
        const y = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM + (isCornerKind ? 3 : 2);
        const shape = new THREE.Shape();
        shape.moveTo(points[0].x, -points[0].z);
        for (let i = 1; i < points.length; i++) {
            shape.lineTo(points[i].x, -points[i].z);
        }
        shape.closePath();
        const geo = new THREE.ShapeGeometry(shape);
        geo.rotateX(-Math.PI / 2);
        geo.translate(0, y, 0);
        geo.computeBoundingSphere();
        const mesh = new THREE.Mesh(geo, maStlWall2dModelMaterial(colorHex, opacity));
        mesh.renderOrder = isCornerKind ? 120 : 119;
        mesh.userData.maStlWall2dModelGenerated = true;
        mesh.userData.maStlWall2dModelKind = kind || 'wall';
        maStlDisableRaycastOnOverlay(mesh);
        maStlWall2dModelMeshesGroup.add(mesh);
        if ((kind || 'wall') === 'straight' && points.length === 4) {
            maStlWall2dModelAddRectVertexRefs(points, y);
        }
        return mesh;
    }

    function maStlWall2dModelAddFlatPolylineDto(poly) {
        if (!poly || poly.Capa !== 'ModelDesing' || !(poly.AlturaExtrusion > 0)) return null;
        const verts = poly.Vertices;
        if (!verts || verts.length < 3) return null;
        if (verts.length >= 6) return null;
        const kind = maStlWall3dClassifyPolyline(poly);
        const points = [];
        for (let i = 0; i < verts.length; i++) {
            if (!verts[i]) continue;
            points.push({ x: verts[i].X, z: verts[i].Y });
        }
        return maStlWall2dModelAddPolygon(
            points,
            kind === 'corner' ? MA_STL_WALL_MODEL_COLOR_CORNER : MA_STL_WALL_MODEL_COLOR_WALL,
            1,
            kind === 'corner' ? 'cornerL' : 'straight'
        );
    }

    function maStlWall2dModelAddFlatPolylinesFromDetection(datos) {
        if (!datos || !datos.PolilineasADibujar) return 0;
        let n = 0;
        for (let i = 0; i < datos.PolilineasADibujar.length; i++) {
            if (maStlWall2dModelAddFlatPolylineDto(datos.PolilineasADibujar[i])) n++;
        }
        maStlWall2dModelMeshesGroup.visible = true;
        return n;
    }

    function maStlWall2dModelCollectSourceSegments() {
        const out = [];
        if (!maStlUserLinesGroup) return out;
        const minLen = maStlUserFloorSegmentMinMm();
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const line = ch[i];
            if (!maStlIsUserFloorPlanLineObject(line)) continue;
            const ud = line.userData && line.userData.maStlUserPlanLine;
            if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
            if (ud.wallRole && ud.wallRole !== 'axis') continue;
            const len = maStlUserFloorLineLengthMm(ud);
            if (!(len >= minLen)) continue;
            out.push({
                id: ud.id != null ? ud.id : i + 1,
                p1Mm: maStlDesing2ClonePlanPointMm(ud.p1Mm),
                p2Mm: maStlDesing2ClonePlanPointMm(ud.p2Mm),
                ud: ud,
            });
        }
        return out;
    }

    function maStlWall2dModelCollectWallFaceStrips() {
        const stripsByAxisId = new Map();
        if (!maStlUserLinesGroup) return [];
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const line = ch[i];
            if (!maStlIsUserFloorPlanLineObject(line)) continue;
            const ud = line.userData && line.userData.maStlUserPlanLine;
            if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
            if (ud.wallRole === 'axis' && ud.id != null) {
                const key = Number(ud.id);
                const row = stripsByAxisId.get(key) || { axis: null, facePos: null, faceNeg: null };
                row.axis = ud;
                stripsByAxisId.set(key, row);
                continue;
            }
            if (ud.wallRole === 'face' && ud.linkOffsetFromLineId != null) {
                const key = Number(ud.linkOffsetFromLineId);
                const row = stripsByAxisId.get(key) || { axis: null, facePos: null, faceNeg: null };
                if (ud.numberWallFaceSideSign === -1) row.faceNeg = ud;
                else row.facePos = ud;
                stripsByAxisId.set(key, row);
            }
        }
        const out = [];
        const minLen = maStlUserFloorSegmentMinMm();
        stripsByAxisId.forEach(function (row) {
            if (!row || !row.axis || !row.facePos || !row.faceNeg) return;
            if (!row.facePos.p1Mm || !row.facePos.p2Mm || !row.faceNeg.p1Mm || !row.faceNeg.p2Mm) return;
            if (!(maStlUserFloorLineLengthMm(row.axis) >= minLen)) return;
            out.push(row);
        });
        out.sort(function (a, b) {
            return (a.axis.id || 0) - (b.axis.id || 0);
        });
        return out;
    }

    function maStlWall2dModelFaceEndpointTowardAxis(facePtA, facePtB, axisPt) {
        const da = maStlUserFloorPlanPointDistSqXzMm(facePtA, axisPt);
        const db = maStlUserFloorPlanPointDistSqXzMm(facePtB, axisPt);
        return da <= db ? facePtA : facePtB;
    }

    /**
     * Tapa cuadrada (⊥ al eje) en un extremo del eje — ignora ingletes oblicuos en caras fuente.
     * @param {'p1'|'p2'} endpointKey
     * @param {number} trimAlongAxisMm recorte hacia el interior del tramo desde el vértice del eje
     */
    function maStlWall2dModelStripSquareCapAtAxisMm(axisUd, facePosUd, faceNegUd, endpointKey, trimAlongAxisMm) {
        const u = maStlUserFloorPlanLineDirUnitXz(axisUd);
        if (!u || !axisUd.p1Mm || !axisUd.p2Mm) return null;
        const axisPt = endpointKey === 'p2' ? axisUd.p2Mm : axisUd.p1Mm;
        const t = Math.max(0, trimAlongAxisMm || 0);
        const cutOnAxis = {
            x: endpointKey === 'p1' ? axisPt.x + u.ux * t : axisPt.x - u.ux * t,
            y: axisPt.y,
            z: endpointKey === 'p1' ? axisPt.z + u.uz * t : axisPt.z - u.uz * t,
        };
        const posSign = facePosUd.numberWallFaceSideSign != null ? facePosUd.numberWallFaceSideSign : 1;
        const negSign = faceNegUd.numberWallFaceSideSign != null ? faceNegUd.numberWallFaceSideSign : -1;
        const posHalf = Math.abs(
            facePosUd.numberOffsetMm != null && Number.isFinite(facePosUd.numberOffsetMm)
                ? facePosUd.numberOffsetMm
                : maStlWall2dToolAxisHalfThicknessFromAxisUd(axisUd)
        );
        const negHalf = Math.abs(
            faceNegUd.numberOffsetMm != null && Number.isFinite(faceNegUd.numberOffsetMm)
                ? faceNegUd.numberOffsetMm
                : posHalf
        );
        const pos = maStlWall2dToolFaceOffsetPointAtAxisPointMm(axisUd, cutOnAxis, posHalf, posSign);
        const neg = maStlWall2dToolFaceOffsetPointAtAxisPointMm(axisUd, cutOnAxis, negHalf, negSign);
        if (!pos || !neg) return null;
        return {
            pos: { x: pos.x, z: pos.z },
            neg: { x: neg.x, z: neg.z },
        };
    }

    function maStlWall2dModelBuildStripQuadXzMm(strip, axisEndpointTrimMap) {
        if (!strip || !strip.axis || !strip.facePos || !strip.faceNeg) return null;
        const axis = strip.axis;
        const pos = strip.facePos;
        const neg = strip.faceNeg;
        const trimP1 =
            axisEndpointTrimMap && axis.id != null ? axisEndpointTrimMap.get(axis.id + '|p1') || 0 : 0;
        const trimP2 =
            axisEndpointTrimMap && axis.id != null ? axisEndpointTrimMap.get(axis.id + '|p2') || 0 : 0;

        let posStart;
        let negStart;
        let posEnd;
        let negEnd;

        if (trimP1 > 0) {
            const cap = maStlWall2dModelStripSquareCapAtAxisMm(axis, pos, neg, 'p1', trimP1);
            if (!cap) return null;
            posStart = cap.pos;
            negStart = cap.neg;
        } else {
            posStart = maStlWall2dModelFaceEndpointTowardAxis(pos.p1Mm, pos.p2Mm, axis.p1Mm);
            negStart = maStlWall2dModelFaceEndpointTowardAxis(neg.p1Mm, neg.p2Mm, axis.p1Mm);
        }

        if (trimP2 > 0) {
            const cap = maStlWall2dModelStripSquareCapAtAxisMm(axis, pos, neg, 'p2', trimP2);
            if (!cap) return null;
            posEnd = cap.pos;
            negEnd = cap.neg;
        } else {
            posEnd = maStlWall2dModelFaceEndpointTowardAxis(pos.p1Mm, pos.p2Mm, axis.p2Mm);
            negEnd = maStlWall2dModelFaceEndpointTowardAxis(neg.p1Mm, neg.p2Mm, axis.p2Mm);
        }

        if (
            maStlUserFloorPlanPointNearXzMm(posStart, posEnd, 1e-6) ||
            maStlUserFloorPlanPointNearXzMm(negStart, negEnd, 1e-6)
        ) {
            return null;
        }
        return [
            { x: posStart.x, z: posStart.z },
            { x: posEnd.x, z: posEnd.z },
            { x: negEnd.x, z: negEnd.z },
            { x: negStart.x, z: negStart.z },
        ];
    }

    function maStlWall2dModelAddStripFromWallFaces(strip, axisEndpointTrimMap) {
        const quad = maStlWall2dModelBuildStripQuadXzMm(strip, axisEndpointTrimMap);
        if (!quad) return false;
        maStlWall2dModelAddPolygon(quad, MA_STL_WALL_MODEL_COLOR_WALL, 1, 'straight');
        return true;
    }

    function maStlAtk60RayPolygonFirstHitMm(vertexMm, dirUnit, points) {
        if (!vertexMm || !dirUnit || !points || points.length < 3) return null;
        const eps = 1e-6;
        let bestT = Infinity;
        const rx = dirUnit.ux;
        const rz = dirUnit.uz;
        if (!(Math.hypot(rx, rz) > eps)) return null;
        for (let i = 0; i < points.length; i++) {
            const a = points[i];
            const b = points[(i + 1) % points.length];
            if (!a || !b) continue;
            const sx = b.x - a.x;
            const sz = b.z - a.z;
            const denom = rx * sz - rz * sx;
            if (Math.abs(denom) < eps) continue;
            const qpx = a.x - vertexMm.x;
            const qpz = a.z - vertexMm.z;
            const t = (qpx * sz - qpz * sx) / denom;
            const u = (qpx * rz - qpz * rx) / denom;
            if (!(t > 0.5)) continue;
            if (u < -eps || u > 1 + eps) continue;
            if (t < bestT) bestT = t;
        }
        return Number.isFinite(bestT) ? bestT : null;
    }

    function maStlAtk60CanonicalThroughDirFromTJunction(intoA, intoB, branchInto) {
        if (!intoA || !intoB || !branchInto) return null;
        let ux = intoA.ux;
        let uz = intoA.uz;
        const dotOpp = ux * intoB.ux + uz * intoB.uz;
        if (dotOpp > 0) {
            ux = -ux;
            uz = -uz;
        }
        const cross = ux * branchInto.uz - uz * branchInto.ux;
        if (cross < 0) {
            ux = -ux;
            uz = -uz;
        }
        const len = Math.hypot(ux, uz);
        if (!(len > 1e-9)) return null;
        return { x: ux / len, z: uz / len };
    }

    function maStlAtk60TryBuildCrossFootprintAtJunction(vertex, axisUds) {
        if (!vertex || !axisUds || axisUds.length < 4) return null;
        const entries = [];
        for (let i = 0; i < axisUds.length; i++) {
            const axisUd = axisUds[i];
            const endKey = maStlWall2dToolAxisEndpointKeyNearVertexMm(axisUd, vertex);
            const into = maStlWall2dToolDirFromVertexIntoAxisMm(axisUd, endKey);
            if (!axisUd || !endKey || !into) continue;
            entries.push({
                axisUd: axisUd,
                endKey: endKey,
                into: into,
                thicknessMm: maStlWall2dModelAxisThicknessMm(axisUd),
            });
        }
        if (entries.length < 4) return null;

        for (let i = 0; i < entries.length; i++) {
            for (let j = i + 1; j < entries.length; j++) {
                const a = entries[i];
                const b = entries[j];
                if (!maStlUserFloorPlanLinesCollinearParallelXz(a.axisUd, b.axisUd)) continue;
                if (a.into.ux * b.into.ux + a.into.uz * b.into.uz > -0.85) continue;

                for (let k = 0; k < entries.length; k++) {
                    if (k === i || k === j) continue;
                    for (let l = k + 1; l < entries.length; l++) {
                        if (l === i || l === j) continue;
                        const c = entries[k];
                        const d = entries[l];
                        if (!maStlUserFloorPlanLinesCollinearParallelXz(c.axisUd, d.axisUd)) continue;
                        if (c.into.ux * d.into.ux + c.into.uz * d.into.uz > -0.85) continue;
                        if (maStlUserFloorPlanLinesCollinearParallelXz(a.axisUd, c.axisUd)) continue;

                        const eU = (a.thicknessMm + b.thicknessMm) * 0.5;
                        const eV = (c.thicknessMm + d.thicknessMm) * 0.5;
                        const fp = maAtk60BuildCrossFootprintMm(
                            vertex,
                            { x: a.into.ux, z: a.into.uz },
                            { x: c.into.ux, z: c.into.uz },
                            eU,
                            eV,
                            { x: a.into.ux, z: a.into.uz }
                        );
                        if (!fp) continue;
                        return {
                            footprint: fp,
                            entries: [a, b, c, d],
                        };
                    }
                }
            }
        }
        return null;
    }

    function maStlAtk60BuildAxisEndpointTrimMap() {
        const trimMap = new Map();
        const bucket = maStlAtk60BuildJunctionBucket();
        const keys = Object.keys(bucket);
        for (let bi = 0; bi < keys.length; bi++) {
            const junction = bucket[keys[bi]];
            if (!junction || !junction.axes || junction.axes.length < 2) continue;
            const vertex = junction.vertexMm;
            const axisUds = junction.axes.map(function (e) {
                return e && e.axisUd;
            }).filter(Boolean);
            if (axisUds.length === 2) {
                const dA = maStlWall2dModelDirIntoAxisFromVertexMm(axisUds[0], vertex);
                const dB = maStlWall2dModelDirIntoAxisFromVertexMm(axisUds[1], vertex);
                if (!dA || !dB || maStlWall2dModelDirsCollinear(dA, dB)) continue;
                const eA = maStlWall2dModelAxisThicknessMm(axisUds[0]);
                const eB = maStlWall2dModelAxisThicknessMm(axisUds[1]);
                const trims = maAtk60GetLJunctionAxisTrimMm(dA, dB, eA, eB);
                const endA = maStlWall2dToolAxisEndpointKeyNearVertexMm(axisUds[0], vertex);
                const endB = maStlWall2dToolAxisEndpointKeyNearVertexMm(axisUds[1], vertex);
                if (endA && axisUds[0].id != null) {
                    trimMap.set(axisUds[0].id + '|' + endA, trims.leg1AxisTrimMm);
                }
                if (endB && axisUds[1].id != null) {
                    trimMap.set(axisUds[1].id + '|' + endB, trims.leg2AxisTrimMm);
                }
                continue;
            }
            if (axisUds.length < 3) continue;
            const cross = maStlAtk60TryBuildCrossFootprintAtJunction(vertex, axisUds);
            if (cross && cross.footprint && cross.entries && cross.entries.length) {
                for (let ci = 0; ci < cross.entries.length; ci++) {
                    const entry = cross.entries[ci];
                    if (!entry || !entry.axisUd || entry.axisUd.id == null || !entry.endKey || !entry.into) continue;
                    const trimFromShape = maStlAtk60RayPolygonFirstHitMm(
                        vertex,
                        entry.into,
                        cross.footprint.points
                    );
                    if (trimFromShape != null) {
                        trimMap.set(entry.axisUd.id + '|' + entry.endKey, trimFromShape);
                    }
                }
                continue;
            }
            for (let i = 0; i < axisUds.length; i++) {
                for (let j = i + 1; j < axisUds.length; j++) {
                    const a = axisUds[i];
                    const b = axisUds[j];
                    if (!maStlUserFloorPlanLinesCollinearParallelXz(a, b)) continue;
                    const intoA = maStlWall2dToolDirFromVertexIntoAxisMm(
                        a,
                        maStlWall2dToolAxisEndpointKeyNearVertexMm(a, vertex)
                    );
                    const intoB = maStlWall2dToolDirFromVertexIntoAxisMm(
                        b,
                        maStlWall2dToolAxisEndpointKeyNearVertexMm(b, vertex)
                    );
                    if (!intoA || !intoB || intoA.ux * intoB.ux + intoA.uz * intoB.uz > -0.85) continue;
                    for (let k = 0; k < axisUds.length; k++) {
                        if (k === i || k === j) continue;
                        const branch = axisUds[k];
                        if (maStlUserFloorPlanLinesCollinearParallelXz(branch, a)) continue;
                        const endA = maStlWall2dToolAxisEndpointKeyNearVertexMm(a, vertex);
                        const endB = maStlWall2dToolAxisEndpointKeyNearVertexMm(b, vertex);
                        const endBr = maStlWall2dToolAxisEndpointKeyNearVertexMm(branch, vertex);
                        const intoBr = maStlWall2dToolDirFromVertexIntoAxisMm(branch, endBr);
                        const throughDir = maStlAtk60CanonicalThroughDirFromTJunction(intoA, intoB, intoBr);
                        if (!throughDir) continue;
                        const throughThicknessMm = maStlWall2dModelAxisThicknessMm(a);
                        const branchThicknessMm = maStlWall2dModelAxisThicknessMm(branch);
                        const fp = maAtk60BuildTFootprintMm(
                            vertex,
                            intoA,
                            intoBr,
                            throughThicknessMm,
                            branchThicknessMm,
                            throughDir
                        );
                        const trims = maAtk60GetTJunctionTrimMm(throughThicknessMm, branchThicknessMm);
                        const trimAFromShape = fp && fp.points ? maStlAtk60RayPolygonFirstHitMm(vertex, intoA, fp.points) : null;
                        const trimBFromShape = fp && fp.points ? maStlAtk60RayPolygonFirstHitMm(vertex, intoB, fp.points) : null;
                        const trimBrFromShape =
                            fp && fp.points && intoBr
                                ? maStlAtk60RayPolygonFirstHitMm(vertex, intoBr, fp.points)
                                : null;
                        if (a.id != null && endA) {
                            trimMap.set(
                                a.id + '|' + endA,
                                trimAFromShape != null ? trimAFromShape : trims.throughHalfMm
                            );
                        }
                        if (b.id != null && endB) {
                            trimMap.set(
                                b.id + '|' + endB,
                                trimBFromShape != null ? trimBFromShape : trims.throughHalfMm
                            );
                        }
                        if (branch.id != null && endBr) {
                            const baseBranchTrim =
                                trimBrFromShape != null ? trimBrFromShape : trims.branchStemMm;
                            // Crecer solo el muro rama hasta conectar mejor con la esquina T,
                            // sin modificar la geometría de la esquina encofrado.
                            const grownBranchTrim = Math.max(0, baseBranchTrim - throughThicknessMm * 0.5);
                            trimMap.set(
                                branch.id + '|' + endBr,
                                grownBranchTrim
                            );
                        }
                        break;
                    }
                }
            }
        }
        return trimMap;
    }

    /**
     * Genera muro 2D/3D desde caras fuente (WallConnections / líneas usuario).
     * Prioridad sobre LCornerDetector: respeta T/L del JSON y el brazo horizontal.
     * En uniones T recorta cada pata del atravesado (mitad panel atravesado) y la rama (vástago).
     * @returns {{ stripCount: number, junctionCount: number, fromFaceStrips: boolean }}
     */
    function maStlDesing2BuildWallModelFromFaceStrips(mode) {
        const faceStrips = maStlWall2dModelCollectWallFaceStrips();
        if (!faceStrips.length) {
            return { stripCount: 0, junctionCount: 0, fromFaceStrips: false };
        }
        const axisEndpointTrimMap = maStlAtk60BuildAxisEndpointTrimMap();
        let stripCount = 0;
        if (mode === 'wall3d') {
            stripCount = maStlWall3dAddMeshesFromFaceStrips(faceStrips, axisEndpointTrimMap);
        } else {
            for (let fi = 0; fi < faceStrips.length; fi++) {
                if (maStlWall2dModelAddStripFromWallFaces(faceStrips[fi], axisEndpointTrimMap)) stripCount++;
            }
            if (stripCount > 0) maStlWall2dModelMeshesGroup.visible = true;
        }
        const junctionCount =
            mode === 'wall3d'
                ? maStlAtk60RenderJunctionFootprints3d()
                : maStlAtk60RenderJunctionFootprints2d();
        return { stripCount: stripCount, junctionCount: junctionCount, fromFaceStrips: stripCount > 0 };
    }

    function maStlWall2dModelNodeForPoint(nodes, pt, eps) {
        for (let i = 0; i < nodes.length; i++) {
            if (maStlUserFloorPlanPointNearXzMm(nodes[i].pointMm, pt, eps)) return nodes[i];
        }
        const node = { pointMm: maStlDesing2ClonePlanPointMm(pt), incident: [] };
        nodes.push(node);
        return node;
    }

    function maStlWall2dModelBuildGraph(segments) {
        const eps = Math.max(maStlUserFloorLineMergeEndpointEpsMm(), maStlWall2dToolJunctionClusterEpsMm());
        const nodes = [];
        for (let si = 0; si < segments.length; si++) {
            const seg = segments[si];
            const n1 = maStlWall2dModelNodeForPoint(nodes, seg.p1Mm, eps);
            const n2 = maStlWall2dModelNodeForPoint(nodes, seg.p2Mm, eps);
            n1.incident.push({ segment: seg, endpoint: 'p1' });
            n2.incident.push({ segment: seg, endpoint: 'p2' });
        }
        return nodes;
    }

    function maStlWall2dModelDirFromNode(incident) {
        const seg = incident && incident.segment;
        if (!seg) return null;
        const from = incident.endpoint === 'p2' ? seg.p2Mm : seg.p1Mm;
        const to = incident.endpoint === 'p2' ? seg.p1Mm : seg.p2Mm;
        const dx = to.x - from.x;
        const dz = to.z - from.z;
        const len = Math.hypot(dx, dz);
        if (!(len > 1e-9)) return null;
        return { x: dx / len, z: dz / len };
    }

    function maStlWall2dModelDirsCollinear(a, b) {
        return !!(a && b && Math.abs(a.x * b.x + a.z * b.z) > 0.985);
    }

    function maStlWall2dModelLineIntersectionXz(p1, d1, p2, d2) {
        const det = d1.x * d2.z - d1.z * d2.x;
        if (Math.abs(det) < 1e-9) return null;
        const dx = p2.x - p1.x;
        const dz = p2.z - p1.z;
        const t = (dx * d2.z - dz * d2.x) / det;
        return { x: p1.x + d1.x * t, z: p1.z + d1.z * t };
    }

    function maStlWall2dModelAddStraightSegment(seg, halfT) {
        const dx = seg.p2Mm.x - seg.p1Mm.x;
        const dz = seg.p2Mm.z - seg.p1Mm.z;
        const len = Math.hypot(dx, dz);
        if (!(len > 1e-9)) return;
        const ux = dx / len;
        const uz = dz / len;
        const nx = -uz * halfT;
        const nz = ux * halfT;
        maStlWall2dModelAddPolygon(
            [
                { x: seg.p1Mm.x + nx, z: seg.p1Mm.z + nz },
                { x: seg.p2Mm.x + nx, z: seg.p2Mm.z + nz },
                { x: seg.p2Mm.x - nx, z: seg.p2Mm.z - nz },
                { x: seg.p1Mm.x - nx, z: seg.p1Mm.z - nz },
            ],
            MA_STL_WALL_MODEL_COLOR_WALL,
            1,
            'straight'
        );
    }

    function maStlWall2dModelAxisThicknessMm(axisUd) {
        return maStlWall2dToolAxisHalfThicknessFromAxisUd(axisUd) * 2;
    }

    function maStlWall2dModelDirIntoAxisFromVertexMm(axisUd, vertexMm) {
        if (!axisUd || !axisUd.p1Mm || !axisUd.p2Mm || !vertexMm) return null;
        const d1 = maStlUserFloorPlanPointDistSqXzMm(axisUd.p1Mm, vertexMm);
        const d2 = maStlUserFloorPlanPointDistSqXzMm(axisUd.p2Mm, vertexMm);
        const from = d1 <= d2 ? axisUd.p1Mm : axisUd.p2Mm;
        const to = d1 <= d2 ? axisUd.p2Mm : axisUd.p1Mm;
        return maAtk60UnitXz(from, to);
    }

    function maStlWall2dModelAddAtk60Footprint2d(footprint) {
        if (!footprint || !footprint.points || footprint.points.length < 3) return false;
        const kind = (footprint.meta && footprint.meta.kind) || maAtk60ClassifyFootprintKind(footprint.points.length);
        const color =
            kind === 'cornerL' || kind === 'cornerT' || kind === 'cornerX'
                ? MA_STL_WALL_MODEL_COLOR_CORNER
                : MA_STL_WALL_MODEL_COLOR_WALL;
        const flat = footprint.points.map(function (pt) {
            return { x: pt.x, z: pt.z };
        });
        const mesh = maStlWall2dModelAddPolygon(flat, color, 1, kind);
        if (mesh && footprint.meta) {
            mesh.userData.maStlAtk60FormworkMeta = footprint.meta;
        }
        return !!mesh;
    }

    function maStlWall3dAddMeshFromAtk60Footprint(footprint) {
        if (!footprint || !footprint.points || footprint.points.length < 3 || !maStlWall3dMeshesGroup) return null;
        const kind = (footprint.meta && footprint.meta.kind) || maAtk60ClassifyFootprintKind(footprint.points.length);
        const shape = new THREE.Shape();
        shape.moveTo(footprint.points[0].x, -footprint.points[0].z);
        for (let i = 1; i < footprint.points.length; i++) {
            shape.lineTo(footprint.points[i].x, -footprint.points[i].z);
        }
        shape.closePath();
        const geo = new THREE.ExtrudeGeometry(shape, {
            depth: MA_STL_WALL3D_DEFAULT_HEIGHT_MM,
            bevelEnabled: false,
        });
        geo.rotateX(-Math.PI / 2);
        geo.computeVertexNormals();
        const pieceKind = kind === 'cornerT' || kind === 'cornerL' || kind === 'cornerX' ? 'corner' : 'wall';
        const baseMat = maStlWall3dEnsureSharedMaterial(pieceKind);
        const mat = baseMat.clone ? baseMat.clone() : baseMat;
        const mesh = new THREE.Mesh(geo, mat);
        mesh.userData.maStlWall3dGenerated = true;
        mesh.userData.maStlWall3dKind = pieceKind;
        mesh.userData.maStlWall3dAtk60Kind = kind;
        mesh.userData.maStlAtk60FormworkMeta = footprint.meta || null;
        mesh.userData.maStlWall3dMapped = false;
        mesh.renderOrder = pieceKind === 'corner' ? 121 : 120;
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        if (maStlWall3dConcreteMapActive && maStlWall3dConcreteTexture) {
            maStlWall3dApplyConcreteToMesh(mesh);
        }
        maStlWall3dMeshesGroup.add(mesh);
        if (clipStlMeshes.indexOf(mesh) < 0) {
            clipStlMeshes.push(mesh);
        }
        maStlWall3dExpandClipBoundsForMesh(mesh);
        return mesh;
    }

    /** T: contorno P-1…P-8 validado; en Muro 3D se extruye desde P-1. */
    const MA_STL_ATK60_T_EXTRUDE_3D = true;

    function maStlAtk60AddTFootprintPointGuide(footprint, useWall3dGroup) {
        if (!footprint || !footprint.points || footprint.points.length < 3) return false;
        const pts = footprint.points;
        const labels =
            (footprint.meta && footprint.meta.pointLabels) ||
            pts.map(function (_p, i) {
                return 'P-' + (i + 1);
            });
        const floorY = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM + 12;
        const root = new THREE.Group();
        root.userData.maStlWall3dGenerated = true;
        root.userData.maStlAtk60TFootprintGuide = true;
        root.renderOrder = 200;

        let cx = 0;
        let cz = 0;
        for (let pi = 0; pi < pts.length; pi++) {
            cx += pts[pi].x;
            cz += pts[pi].z;
        }
        cx /= pts.length;
        cz /= pts.length;

        const markHalf = 42;
        const markThickness = 10;
        const labelScale = 112;
        const labelOffsetDefault = 150;
        const labelOffsetFarOutside = 210;
        const labelOffsetInside = 120;

        for (let li = 0; li < pts.length; li++) {
            const pt = pts[li];
            const markMat = new THREE.MeshBasicMaterial({
                color: 0x111111,
                depthTest: false,
                depthWrite: false,
            });
            const armA = new THREE.Mesh(
                new THREE.BoxGeometry(markHalf * 2, 2, markThickness),
                markMat
            );
            armA.position.set(pt.x, floorY, pt.z);
            armA.rotation.y = Math.PI / 4;
            armA.renderOrder = 200;
            root.add(armA);
            const armB = new THREE.Mesh(
                new THREE.BoxGeometry(markHalf * 2, 2, markThickness),
                markMat
            );
            armB.position.set(pt.x, floorY, pt.z);
            armB.rotation.y = -Math.PI / 4;
            armB.renderOrder = 200;
            root.add(armB);

            const rawLabel = labels[li] || 'P-' + (li + 1);
            const labelNumMatch = /([0-9]+)/.exec(String(rawLabel));
            const labelNum = labelNumMatch ? Number(labelNumMatch[1]) : li + 1;

            let dirX = pt.x - cx;
            let dirZ = pt.z - cz;
            let dirLen = Math.hypot(dirX, dirZ);
            if (dirLen <= 1e-6) {
                dirX = 1;
                dirZ = 0;
                dirLen = 1;
            }
            dirX /= dirLen;
            dirZ /= dirLen;

            let labelDirSign = 1;
            let labelOffset = labelOffsetDefault;
            if (labelNum === 3 || labelNum === 8) {
                labelDirSign = -1;
                labelOffset = labelOffsetInside;
            } else if (labelNum === 1 || labelNum === 2 || labelNum === 4 || labelNum === 7) {
                labelDirSign = 1;
                labelOffset = labelOffsetFarOutside;
            }

            const displayLabel = 'T-' + labelNum;
            const sp = maStlMakeTextSprite(displayLabel, labelScale, {
                thinFillOnly: true,
                fillColor: '#111111',
                fontPx: 16,
                fontWeight: 600,
                canvasPad: 2,
                thinPillFill: null,
                thinPillStroke: null,
                strokeRatio: 0,
            });
            if (sp) {
                sp.position.set(
                    pt.x + dirX * labelOffset * labelDirSign,
                    floorY + labelScale * 0.25,
                    pt.z + dirZ * labelOffset * labelDirSign
                );
                sp.renderOrder = 201;
                root.add(sp);
            }
        }

        maStlDisableRaycastOnOverlay(root);
        if (useWall3dGroup && maStlWall3dMeshesGroup) {
            maStlWall3dMeshesGroup.add(root);
        } else if (maStlWall2dModelMeshesGroup) {
            maStlWall2dModelMeshesGroup.add(root);
            maStlWall2dModelMeshesGroup.visible = true;
        } else {
            return false;
        }
        return true;
    }

    function maStlAtk60AddXFootprintPointGuide(footprint, useWall3dGroup) {
        if (!footprint || !footprint.points || footprint.points.length < 3) return false;
        const pts = footprint.points;
        const labels =
            (footprint.meta && footprint.meta.pointLabels) ||
            pts.map(function (_p, i) {
                return 'X-' + (i + 1);
            });
        const floorY = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM + 12;
        const root = new THREE.Group();
        root.userData.maStlWall3dGenerated = true;
        root.userData.maStlAtk60XFootprintGuide = true;
        root.renderOrder = 200;

        let cx = 0;
        let cz = 0;
        for (let pi = 0; pi < pts.length; pi++) {
            cx += pts[pi].x;
            cz += pts[pi].z;
        }
        cx /= pts.length;
        cz /= pts.length;

        const markHalf = 42;
        const markThickness = 10;
        const labelScale = 112;
        const labelOffset = 165;

        for (let li = 0; li < pts.length; li++) {
            const pt = pts[li];
            const markMat = new THREE.MeshBasicMaterial({
                color: 0x111111,
                depthTest: false,
                depthWrite: false,
            });
            const armA = new THREE.Mesh(
                new THREE.BoxGeometry(markHalf * 2, 2, markThickness),
                markMat
            );
            armA.position.set(pt.x, floorY, pt.z);
            armA.rotation.y = Math.PI / 4;
            armA.renderOrder = 200;
            root.add(armA);
            const armB = new THREE.Mesh(
                new THREE.BoxGeometry(markHalf * 2, 2, markThickness),
                markMat
            );
            armB.position.set(pt.x, floorY, pt.z);
            armB.rotation.y = -Math.PI / 4;
            armB.renderOrder = 200;
            root.add(armB);

            let dirX = pt.x - cx;
            let dirZ = pt.z - cz;
            let dirLen = Math.hypot(dirX, dirZ);
            if (dirLen <= 1e-6) {
                dirX = 1;
                dirZ = 0;
                dirLen = 1;
            }
            dirX /= dirLen;
            dirZ /= dirLen;

            const displayLabel = labels[li] || 'X-' + (li + 1);
            const sp = maStlMakeTextSprite(displayLabel, labelScale, {
                thinFillOnly: true,
                fillColor: '#111111',
                fontPx: 16,
                fontWeight: 600,
                canvasPad: 2,
                thinPillFill: null,
                thinPillStroke: null,
                strokeRatio: 0,
            });
            if (sp) {
                sp.position.set(
                    pt.x + dirX * labelOffset,
                    floorY + labelScale * 0.25,
                    pt.z + dirZ * labelOffset
                );
                sp.renderOrder = 201;
                root.add(sp);
            }
        }

        maStlDisableRaycastOnOverlay(root);
        if (useWall3dGroup && maStlWall3dMeshesGroup) {
            maStlWall3dMeshesGroup.add(root);
        } else if (maStlWall2dModelMeshesGroup) {
            maStlWall2dModelMeshesGroup.add(root);
            maStlWall2dModelMeshesGroup.visible = true;
        } else {
            return false;
        }
        return true;
    }

    /** Encofrado T: guía activa; extrusión opcional. */
    const MA_STL_ATK60_RENDER_T_JUNCTION = true;

    function maStlAtk60TryRenderJunctionAtBucket(junction, render2d) {
        if (!junction || !junction.axes || junction.axes.length < 2) return 0;
        const vertex = junction.vertexMm;
        const axisUds = junction.axes.map(function (e) {
            return e && e.axisUd;
        }).filter(Boolean);
        if (axisUds.length === 2) {
            const dA = maStlWall2dModelDirIntoAxisFromVertexMm(axisUds[0], vertex);
            const dB = maStlWall2dModelDirIntoAxisFromVertexMm(axisUds[1], vertex);
            if (!dA || !dB || maStlWall2dModelDirsCollinear(dA, dB)) return 0;
            const fp = maAtk60BuildLFootprintMm(
                vertex,
                dA,
                dB,
                maStlWall2dModelAxisThicknessMm(axisUds[0]),
                maStlWall2dModelAxisThicknessMm(axisUds[1])
            );
            if (!fp) return 0;
            if (render2d) return maStlWall2dModelAddAtk60Footprint2d(fp) ? 1 : 0;
            return maStlWall3dAddMeshFromAtk60Footprint(fp) ? 1 : 0;
        }
        if (axisUds.length < 3) return 0;
        if (axisUds.length >= 4) {
            const cross = maStlAtk60TryBuildCrossFootprintAtJunction(vertex, axisUds);
            if (cross && cross.footprint) {
                if (render2d) {
                    maStlAtk60AddXFootprintPointGuide(cross.footprint, false);
                    return maStlWall2dModelAddAtk60Footprint2d(cross.footprint) ? 1 : 0;
                }
                return maStlWall3dAddMeshFromAtk60Footprint(cross.footprint) ? 1 : 0;
            }
        }
        for (let i = 0; i < axisUds.length; i++) {
            for (let j = i + 1; j < axisUds.length; j++) {
                const a = axisUds[i];
                const b = axisUds[j];
                if (!maStlUserFloorPlanLinesCollinearParallelXz(a, b)) continue;
                const intoA = maStlWall2dToolDirFromVertexIntoAxisMm(
                    a,
                    maStlWall2dToolAxisEndpointKeyNearVertexMm(a, vertex)
                );
                const intoB = maStlWall2dToolDirFromVertexIntoAxisMm(
                    b,
                    maStlWall2dToolAxisEndpointKeyNearVertexMm(b, vertex)
                );
                if (!intoA || !intoB || intoA.ux * intoB.ux + intoA.uz * intoB.uz > -0.85) continue;
                for (let k = 0; k < axisUds.length; k++) {
                    if (k === i || k === j) continue;
                    const branch = axisUds[k];
                    if (maStlUserFloorPlanLinesCollinearParallelXz(branch, a)) continue;
                    const branchInto = maStlWall2dToolDirFromVertexIntoAxisMm(
                        branch,
                        maStlWall2dToolAxisEndpointKeyNearVertexMm(branch, vertex)
                    );
                    if (!branchInto) continue;
                    const uThrough = maStlAtk60CanonicalThroughDirFromTJunction(intoA, intoB, branchInto);
                    if (!uThrough) continue;
                    const fp = maAtk60BuildTFootprintMm(
                        vertex,
                        { x: intoA.ux, z: intoA.uz },
                        { x: branchInto.ux, z: branchInto.uz },
                        maStlWall2dModelAxisThicknessMm(a),
                        maStlWall2dModelAxisThicknessMm(branch),
                        { x: uThrough.x, z: uThrough.z }
                    );
                    if (!fp) return 0;
                    if (render2d) maStlAtk60AddTFootprintPointGuide(fp, false);
                    if (!MA_STL_ATK60_T_EXTRUDE_3D) return 1;
                    if (render2d) return maStlWall2dModelAddAtk60Footprint2d(fp) ? 1 : 0;
                    return maStlWall3dAddMeshFromAtk60Footprint(fp) ? 1 : 0;
                }
            }
        }
        return 0;
    }

    function maStlAtk60BuildJunctionBucket() {
        const bucketEps = maStlWall2dToolJunctionClusterEpsMm();
        const bucket = Object.create(null);
        const axes = maStlWall2dToolCollectAllAxisLines();
        for (let ai = 0; ai < axes.length; ai++) {
            const axisUd = axes[ai].userData && axes[ai].userData.maStlUserPlanLine;
            if (!axisUd || !axisUd.p1Mm || !axisUd.p2Mm) continue;
            if (!(maStlUserFloorLineLengthMm(axisUd) >= maStlUserFloorSegmentMinMm())) continue;
            ['p1', 'p2'].forEach(function (end) {
                const vertexMm = end === 'p1' ? axisUd.p1Mm : axisUd.p2Mm;
                const key = Math.round(vertexMm.x / bucketEps) + '|' + Math.round(vertexMm.z / bucketEps);
                if (!bucket[key]) bucket[key] = { vertexMm: vertexMm, axes: [] };
                bucket[key].axes.push({ axisUd: axisUd });
            });
        }
        return bucket;
    }

    function maStlAtk60CollectJunctionDimPlacements() {
        const floorY =
            MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM + MA_STL_USER_FLOOR_LINE_DIM_DRAW_Y_EPS_MM + 0.35;
        const bucket = maStlAtk60BuildJunctionBucket();
        const out = [];
        for (const bkey in bucket) {
            const junction = bucket[bkey];
            if (!junction || !junction.axes || junction.axes.length < 2) continue;
            const vertex = junction.vertexMm;
            const axisUds = junction.axes
                .map(function (e) {
                    return e && e.axisUd;
                })
                .filter(Boolean);
            let footprint = null;
            if (axisUds.length === 2) {
                const dA = maStlWall2dModelDirIntoAxisFromVertexMm(axisUds[0], vertex);
                const dB = maStlWall2dModelDirIntoAxisFromVertexMm(axisUds[1], vertex);
                if (!dA || !dB || maStlWall2dModelDirsCollinear(dA, dB)) continue;
                footprint = maAtk60BuildLFootprintMm(
                    vertex,
                    dA,
                    dB,
                    maStlWall2dModelAxisThicknessMm(axisUds[0]),
                    maStlWall2dModelAxisThicknessMm(axisUds[1])
                );
            } else if (axisUds.length >= 3) {
                if (axisUds.length >= 4) {
                    const cross = maStlAtk60TryBuildCrossFootprintAtJunction(vertex, axisUds);
                    if (cross && cross.footprint) {
                        footprint = cross.footprint;
                    }
                }
                for (let i = 0; i < axisUds.length && !footprint; i++) {
                    for (let j = i + 1; j < axisUds.length && !footprint; j++) {
                        const a = axisUds[i];
                        const b = axisUds[j];
                        if (!maStlUserFloorPlanLinesCollinearParallelXz(a, b)) continue;
                        const intoA = maStlWall2dToolDirFromVertexIntoAxisMm(
                            a,
                            maStlWall2dToolAxisEndpointKeyNearVertexMm(a, vertex)
                        );
                        const intoB = maStlWall2dToolDirFromVertexIntoAxisMm(
                            b,
                            maStlWall2dToolAxisEndpointKeyNearVertexMm(b, vertex)
                        );
                        if (!intoA || !intoB || intoA.ux * intoB.ux + intoA.uz * intoB.uz > -0.85) continue;
                        for (let k = 0; k < axisUds.length; k++) {
                            if (k === i || k === j) continue;
                            const branch = axisUds[k];
                            if (maStlUserFloorPlanLinesCollinearParallelXz(branch, a)) continue;
                            const branchInto = maStlWall2dToolDirFromVertexIntoAxisMm(
                                branch,
                                maStlWall2dToolAxisEndpointKeyNearVertexMm(branch, vertex)
                            );
                            if (!branchInto) continue;
                            const uThrough = maStlAtk60CanonicalThroughDirFromTJunction(intoA, intoB, branchInto);
                            if (!uThrough) continue;
                            footprint = maAtk60BuildTFootprintMm(
                                vertex,
                                { x: intoA.ux, z: intoA.uz },
                                { x: branchInto.ux, z: branchInto.uz },
                                maStlWall2dModelAxisThicknessMm(a),
                                maStlWall2dModelAxisThicknessMm(branch),
                                { x: uThrough.x, z: uThrough.z }
                            );
                            break;
                        }
                    }
                }
            }
            if (!footprint) continue;
            const dims = maAtk60BuildFootprintDimPlacements(footprint, floorY);
            if (dims.length) out.push.apply(out, dims);
        }
        return out;
    }

    /** Huellas AT-60 (forma blanca) en nodos L/T — líneas fuente persisten; sólidos se regeneran al cambiar modo. */
    function maStlAtk60RenderJunctionFootprints2d() {
        const bucket = maStlAtk60BuildJunctionBucket();
        let n = 0;
        for (const bkey in bucket) {
            n += maStlAtk60TryRenderJunctionAtBucket(bucket[bkey], true);
        }
        return n;
    }

    function maStlAtk60RenderJunctionFootprints3d() {
        const bucket = maStlAtk60BuildJunctionBucket();
        let n = 0;
        for (const bkey in bucket) {
            n += maStlAtk60TryRenderJunctionAtBucket(bucket[bkey], false);
        }
        if (n > 0) {
            updateClipPlanes();
            syncGroundShadowToggleUi();
        }
        return n;
    }

    function maStlWall2dModelAddLCorner(node, halfT) {
        void halfT;
        if (!node || !node.incident || node.incident.length !== 2) return;
        const axisUds = [];
        for (let i = 0; i < node.incident.length; i++) {
            const seg = node.incident[i].segment;
            if (seg && seg.ud) axisUds.push(seg.ud);
        }
        if (axisUds.length !== 2) return;
        const dA = maStlWall2dModelDirIntoAxisFromVertexMm(axisUds[0], node.pointMm);
        const dB = maStlWall2dModelDirIntoAxisFromVertexMm(axisUds[1], node.pointMm);
        if (!dA || !dB) return;
        maStlWall2dModelAddAtk60Footprint2d(
            maAtk60BuildLFootprintMm(
                node.pointMm,
                dA,
                dB,
                maStlWall2dModelAxisThicknessMm(axisUds[0]),
                maStlWall2dModelAxisThicknessMm(axisUds[1])
            )
        );
    }

    function maStlWall2dModelRegenerateFromSourceLines() {
        maStlWall2dModelClearGenerated();
        const built = maStlDesing2BuildWallModelFromFaceStrips('wall2d');
        if (built.fromFaceStrips) return true;

        const segments = maStlWall2dModelCollectSourceSegments();
        const halfT = maStlWall2dToolThicknessHalfMm();
        for (let si = 0; si < segments.length; si++) {
            maStlWall2dModelAddStraightSegment(segments[si], halfT);
        }
        maStlAtk60RenderJunctionFootprints2d();
        maStlWall2dModelMeshesGroup.visible = true;
        return segments.length > 0;
    }

    function maStlDesing2SetModelModeLines() {
        maStlDesing2ModelMode = 'lines';
        maStlDesing2SyncAtk60SampleVisibility();
        maStlDesing2SetWallModelRenderingVisible(false);
        if (maStlIsWall3dToolActive()) maStlStopWall3dToolModesToolbar(false);
        if (maStlIsLineToolPlacementActive()) maStlStopLineToolModesToolbar(false);
        if (maStlIsOffsetToolActive()) maStlStopOffsetToolModesToolbar(false);
        if (maStlIsDeleteToolActive()) maStlStopDeleteToolModesToolbar(false);
        if (maStlIsDupMoveToolActive()) maStlStopCopyToolModesToolbar(false);
        maStlDesing2ClearGeneratedWallModels();
        maStlDesing2LastWallModelDetection = null;
        if (maStlWall2dModelMeshesGroup) maStlWall2dModelMeshesGroup.visible = false;
        if (maStlWall3dMeshesGroup) maStlWall3dMeshesGroup.visible = true;
        maStlDesing2SetSourceLinesVisible(true);
        maStlSyncDesing2ModeToolbarUi();
        maStlSaveWallConnectionsNow({
            force: true,
            reason: 'wall-model-mode-lines',
        });
    }

    function maStlDesing2ApplyWall2dModelMode() {
        if (maStlDesing2WallModelBusy) return;
        maStlDesing2ModelMode = 'wall2d';
        maStlDesing2SyncAtk60SampleVisibility();
        if (maStlIsWall3dToolActive()) maStlStopWall3dToolModesToolbar(false);
        if (maStlIsLineToolPlacementActive()) maStlStopLineToolModesToolbar(false);
        if (maStlIsOffsetToolActive()) maStlStopOffsetToolModesToolbar(false);
        if (maStlIsDeleteToolActive()) maStlStopDeleteToolModesToolbar(false);
        if (maStlIsDupMoveToolActive()) maStlStopCopyToolModesToolbar(false);
        if (maStlIsInsertCornerToolActive()) maStlStopInsertCornerToolModesToolbar(false);
        if (maStlIsInsertEnclosureToolActive()) maStlStopInsertEnclosureToolModesToolbar(false);
        maStlDisposeUserFloorLineDimEdit(false);
        maStlClearUserFloorLineSelection();
        maStlDesing2ClearGeneratedWallModels();
        maStlDesing2LastWallModelDetection = null;
        maStlDesing2SetSourceLinesVisible(false);
        maStlSyncDesing2ModeToolbarUi();
        maStlDesing2RequestWallModelDetection('wall2d', function (datos, payload) {
            if (maStlDesing2ModelMode !== 'wall2d') return;
            const fromFaces = maStlDesing2BuildWallModelFromFaceStrips('wall2d');
            let count = fromFaces.stripCount + fromFaces.junctionCount;
            if (!fromFaces.fromFaceStrips) {
                count =
                    maStlWall2dModelAddFlatPolylinesFromDetection(datos) +
                    maStlAtk60RenderJunctionFootprints2d();
            }
            maStlDesing2LastWallModelDetection = maStlDesing2SummarizeWallModelDetection(
                'wall2d',
                payload,
                datos,
                count
            );
            maStlSaveWallConnectionsNow({
                force: true,
                reason: 'wall2d-model-mode-regenerate',
            });
        }, function (err) {
            maStlDesing2SetSourceLinesVisible(true);
            maStlDesing2ModelMode = 'lines';
            maStlSyncDesing2ModeToolbarUi();
            maStlDesing2ShowSaveViewToast(err && err.message ? err.message : String(err || 'Error modelo muro'));
        });
    }

    function maStlDesing2ApplyWall3dModelMode() {
        if (maStlDesing2WallModelBusy) return;
        maStlDesing2ClearAtk60Visuals();
        maStlDesing2ModelMode = 'wall3d';
        maStlDesing2SyncAtk60SampleVisibility();
        if (maStlIsWall3dToolActive()) maStlStopWall3dToolModesToolbar(false);
        if (maStlIsLineToolPlacementActive()) maStlStopLineToolModesToolbar(false);
        if (maStlIsOffsetToolActive()) maStlStopOffsetToolModesToolbar(false);
        if (maStlIsDeleteToolActive()) maStlStopDeleteToolModesToolbar(false);
        if (maStlIsDupMoveToolActive()) maStlStopCopyToolModesToolbar(false);
        if (maStlIsInsertCornerToolActive()) maStlStopInsertCornerToolModesToolbar(false);
        if (maStlIsInsertEnclosureToolActive()) maStlStopInsertEnclosureToolModesToolbar(false);
        maStlDisposeUserFloorLineDimEdit(false);
        maStlClearUserFloorLineSelection();
        maStlDesing2ClearGeneratedWallModels();
        maStlDesing2LastWallModelDetection = null;
        maStlDesing2SetSourceLinesVisible(false);
        maStlSyncDesing2ModeToolbarUi();
        maStlDesing2RequestWallModelDetection('wall3d', function (datos, payload) {
            if (maStlDesing2ModelMode !== 'wall3d') return;
            const fromFaces = maStlDesing2BuildWallModelFromFaceStrips('wall3d');
            let count = fromFaces.stripCount + fromFaces.junctionCount;
            if (!fromFaces.fromFaceStrips) {
                count =
                    maStlWall3dAddMeshesFromDetection(datos) + maStlAtk60RenderJunctionFootprints3d();
            }
            maStlDesing2LastWallModelDetection = maStlDesing2SummarizeWallModelDetection(
                'wall3d',
                payload,
                datos,
                count
            );
            maStlSaveWallConnectionsNow({
                force: true,
                reason: 'wall3d-model-mode-regenerate',
            });
        }, function (err) {
            maStlDesing2SetSourceLinesVisible(true);
            maStlDesing2ModelMode = 'lines';
            maStlSyncDesing2ModeToolbarUi();
            maStlDesing2ShowSaveViewToast(err && err.message ? err.message : String(err || 'Error modelo 3D'));
        });
    }

    function syncMaStlUcsOverlayVisibility() {
        if (maStlRulersGate) {
            maStlRulersGroup.visible = maStlUcsRulersManualOn;
            /* Grupo padre sigue visible: esfera de anclaje no depende del toggle de reglas. */
            maStlRulerAnchorMarkerGroup.visible = true;
            if (maStlRulerAnchorCrossObject) {
                maStlRulerAnchorCrossObject.visible = maStlUcsRulersManualOn;
            }
            if (maStlRulerAnchorBallMesh) {
                maStlRulerAnchorBallMesh.visible = true;
            }
            maStlXyzAxesGroup.visible = maStlXyzAxesGate ? maStlXyzAxesManualOn : false;
            maStlUcsAxesGroup.visible = false;
        } else {
            maStlUcsAxesGroup.visible = true;
            maStlXyzAxesGroup.visible = false;
            maStlRulersGroup.visible = false;
            maStlRulerAnchorMarkerGroup.visible = false;
        }
    }

    function maStlSyncEdgeRulersOverlayVisibility() {
        if (!maStlEdgeRulersOverlay || !maStlRulersGate) return;
        const show = maStlEdgeRulersManualOn;
        maStlEdgeRulersOverlay.classList.toggle('d-none', !show);
        maStlEdgeRulersOverlay.setAttribute('aria-hidden', show ? 'false' : 'true');
        if (!show) {
            _maStlEdgeRulerSyncStateKey = '';
        }
    }

    function maStlEdgeRulerComputeSyncStateKey(overlayRect, cam) {
        if (!cam || !overlayRect) return '';
        const p = cam.position;
        const q = cam.quaternion;
        const t = maStlRulerAnchorMm;
        return [
            overlayRect.width.toFixed(1),
            overlayRect.height.toFixed(1),
            p.x,
            p.y,
            p.z,
            q.x,
            q.y,
            q.z,
            q.w,
            cam.zoom || 1,
            lastAspect,
            darkBgVisible ? 1 : 0,
            t.x,
            t.z,
            desing2EnvGridSnapMm,
            maStlRulerAnchorPickMode || ''
        ].join('|');
    }

    /** Reglas borde (top +X, right +Z): canvas DOM adaptativo a zoom/encuadre. */
    function maStlSyncEdgeRulersOverlay(forceRedraw) {
        if (
            !maStlRulersGate ||
            !maStlEdgeRulersManualOn ||
            !maStlEdgeRulersOverlay ||
            !maStlEdgeRulerTopCanvas ||
            !maStlEdgeRulerRightCanvas ||
            !renderer ||
            !renderer.domElement
        ) {
            return;
        }
        const glCanvas = renderer.domElement;
        const cam = activeCamera();
        if (!cam) return;
        const overlayRect = maStlEdgeRulersOverlay.getBoundingClientRect();
        const syncKey = maStlEdgeRulerComputeSyncStateKey(overlayRect, cam);
        if (!forceRedraw && syncKey === _maStlEdgeRulerSyncStateKey) {
            return;
        }
        _maStlEdgeRulerSyncStateKey = syncKey;
        const topCssW = Math.max(overlayRect.width - MA_STL_EDGE_RULER_THICKNESS_PX, 1);
        const topCssH = MA_STL_EDGE_RULER_THICKNESS_PX;
        const rightCssW = MA_STL_EDGE_RULER_THICKNESS_PX;
        const rightCssH = Math.max(overlayRect.height - MA_STL_EDGE_RULER_THICKNESS_PX, 1);
        if (
            !maStlEdgeRulerSampleViewportFloorExtents(
                glCanvas,
                cam,
                _maStlFloorPickNdc,
                _maStlEdgeRulerRaycaster,
                _maStlEdgeRulerExtents
            )
        ) {
            const topCtxClear = maStlEdgeRulerPrepareCanvas(maStlEdgeRulerTopCanvas, topCssW, topCssH);
            const rightCtxClear = maStlEdgeRulerPrepareCanvas(maStlEdgeRulerRightCanvas, rightCssW, rightCssH);
            if (topCtxClear) {
                topCtxClear.clearRect(0, 0, topCssW, topCssH);
            }
            if (rightCtxClear) {
                rightCtxClear.clearRect(0, 0, rightCssW, rightCssH);
            }
            _maStlEdgeRulerSyncStateKey = '';
            return;
        }
        const orbitPivot = controls ? controls.target : maStlRulerAnchorMm;
        const wpp = maStlWorldMmPerPixel(cam, renderer, orbitPivot);
        const lod = maStlDesing2GridLodCellSizesMm(wpp, desing2EnvGridSnapMm, desing2EnvGridMajorMm());
        const minorStepMm = lod.minorMm;
        const labelStepMm = maStlEdgeRulerNiceLabelStepMm(wpp);
        const theme = maStlEdgeRulerThemeColors(darkBgVisible);
        const floorY = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM;
        const tickOptsBase = {
            minorStepMm: minorStepMm,
            labelStepMm: labelStepMm,
            floorY: floorY,
            glCanvas: glCanvas,
            camera: cam,
            anchorX: maStlRulerAnchorMm.x,
            anchorZ: maStlRulerAnchorMm.z
        };
        const topTicks = maStlEdgeRulerBuildAxisTicks(
            'x',
            Object.assign({}, tickOptsBase, {
                minX: _maStlEdgeRulerExtents.minX,
                maxX: _maStlEdgeRulerExtents.maxX,
                refZ: _maStlEdgeRulerExtents.refZTop
            })
        );
        const rightTicks = maStlEdgeRulerBuildAxisTicks(
            'z',
            Object.assign({}, tickOptsBase, {
                minZ: _maStlEdgeRulerExtents.minZ,
                maxZ: _maStlEdgeRulerExtents.maxZ,
                refX: _maStlEdgeRulerExtents.refXRight,
                /* Canvas derecho empieza bajo la banda superior (inset 26 px). */
                posOffsetPx: MA_STL_EDGE_RULER_THICKNESS_PX
            })
        );
        const topCtx = maStlEdgeRulerPrepareCanvas(maStlEdgeRulerTopCanvas, topCssW, topCssH);
        if (topCtx) {
            maStlEdgeRulerDrawHorizontal(topCtx, topCssW, topCssH, theme, topTicks);
        }
        const rightCtx = maStlEdgeRulerPrepareCanvas(maStlEdgeRulerRightCanvas, rightCssW, rightCssH);
        if (rightCtx) {
            maStlEdgeRulerDrawVertical(rightCtx, rightCssW, rightCssH, theme, rightTicks);
        }
    }

