    /**
     * Desing_2: cancelar herramienta línea, modo pick rejilla/objeto y restos pick-lock/highlights visuales (p. ej. Escape).
     * @returns {boolean} true si había modo interactivo o pick-lock pendiente y se aplicó teardown
     */
    function maStlCancelAllViewerInteractionModes() {
        const hadEdit = maStlUserFloorDimDomHudEditing;
        maStlDisposeUserFloorLineDimEdit(false);
        const hadSelection = !!maStlUserFloorLineSelected;
        maStlClearUserFloorLineSelection();
        const hadLinePlacement = maStlIsLineToolPlacementActive();
        const hadOffsetTool = maStlIsOffsetToolActive();
        const hadDeleteTool = maStlIsDeleteToolActive();
        const hadCopyTool = maStlIsDupMoveToolActive();
        const hadWall3dTool = maStlIsWall3dToolActive();
        const hadImageSketchTool = maStlIsImageSketchToolActive();
        const hadInsertCornerTool = maStlIsInsertCornerToolActive();
        const hadInsertEnclosureTool = maStlIsInsertEnclosureToolActive();
        const hadWall2dTool = maStlIsWall2dToolActive();
        const hadWallDimTool = maStlIsWallDimToolActive();
        const hadPickMode = maStlIsRulerAnchorPickModeActive();
        let touched = !!(
            hadLinePlacement ||
            hadOffsetTool ||
            hadDeleteTool ||
            hadCopyTool ||
            hadWall3dTool ||
            hadImageSketchTool ||
            hadInsertCornerTool ||
            hadInsertEnclosureTool ||
            hadWall2dTool ||
            hadWallDimTool ||
            hadPickMode ||
            hadSelection ||
            hadEdit
        );
        if (hadLinePlacement) {
            maStlStopLineToolModesToolbar(false);
        }
        if (hadOffsetTool) {
            maStlStopOffsetToolModesToolbar(false);
        }
        if (hadDeleteTool) {
            maStlStopDeleteToolModesToolbar(false);
        }
        if (hadCopyTool) {
            maStlStopCopyToolModesToolbar(false);
        }
        if (hadWall3dTool) {
            maStlStopWall3dToolModesToolbar(false);
        }
        if (hadImageSketchTool) {
            maStlStopImageSketchToolModesToolbar(false);
        }
        if (hadInsertCornerTool) {
            maStlStopInsertCornerToolModesToolbar(false);
        }
        if (hadInsertEnclosureTool) {
            maStlStopInsertEnclosureToolModesToolbar(false);
        }
        if (hadWall2dTool) {
            maStlStopWall2dToolModesToolbar(false);
        }
        if (hadWallDimTool) {
            maStlStopWallDimToolModesToolbar();
        }
        if (hadPickMode) {
            maStlStopRulerAnchorPickModesToolbar();
        }
        if (maStlRulerAnchorPickOrbitLockSnapshot !== null || maStlDeferredRulerPickUnlockPointerEnded !== null) {
            maStlUnlockOrbitForRulerAnchorPick();
            touched = true;
        }
        if (!touched) {
            return false;
        }
        maStlTeardownPickHighlightsOnly();
        if (maStlLineToolRubberBandLine) {
            maStlLineToolRubberBandLine.visible = false;
        }
        maStlSyncLineToolHud();
        maStlSyncOffsetToolHud();
        maStlSyncDeleteToolHud();
        maStlCopyToolSyncHud();
        maStlSyncWall3dToolHud();
        maStlSyncImageSketchToolHud();
        maStlSyncInsertCornerToolHud();
        maStlSyncInsertEnclosureToolHud();
        syncMaStlRulerPickToolbarUi();
        maStlSyncLineToolToggleBtnUi();
        maStlLineToolPickCursorSync();
        syncMaStlRulerAnchorPickCursor();
        [maStlPolylineToolToggleBtn, maStlRulerAnchorPickToggleBtn, maStlRulerAnchorObjectPickToggleBtn].forEach(
            function (el) {
                if (!el) return;
                el.classList.remove('active', 'pressed');
            }
        );
        syncMaStlRulerPickToolbarUi();
        maStlSyncLineToolToggleBtnUi();
        return true;
    }

    function maStlClearStlPickHoverHighlight() {
        maStlPickHoverMaterialSnapshots.forEach(function (entry) {
            const mesh = entry.mesh;
            if (!mesh || !mesh.material) return;
            mesh.material.color.copy(entry.color);
            if (mesh.material.emissive) {
                mesh.material.emissive.copy(entry.emissive);
            }
            mesh.material.emissiveIntensity = entry.emissiveIntensity;
            mesh.material.needsUpdate = true;
        });
        maStlPickHoverMaterialSnapshots = [];
    }

    /**
     * Hover azul temporal sobre malla STL en modo objeto (solo temporal; revierte al mover/salir).
     * @param {THREE.Mesh|null} mesh
     */
    function maStlApplyStlPickHoverHighlight(mesh) {
        if (!mesh || !mesh.isMesh || !mesh.material) return;
        const already = maStlPickHoverMaterialSnapshots.some((entry) => entry.mesh === mesh);
        if (already) return;
        maStlPickHoverMaterialSnapshots.push({
            mesh: mesh,
            color: mesh.material.color.clone(),
            emissive: mesh.material.emissive ? mesh.material.emissive.clone() : new THREE.Color(0x000000),
            emissiveIntensity: mesh.material.emissiveIntensity != null ? mesh.material.emissiveIntensity : 0
        });
        mesh.material.emissive.setHex(MA_STL_PICK_HOVER_EMISSIVE_HEX);
        mesh.material.emissiveIntensity = MA_STL_PICK_HOVER_EMISSIVE_INTENSITY;
        mesh.material.color.lerp(_maStlPickHoverColor, MA_STL_PICK_HOVER_COLOR_LERP);
        mesh.material.needsUpdate = true;
    }

    function maStlClearInsertionPickHighlight() {
        maStlInsertionPickHighlightGroup.visible = false;
        maStlStripOverlayMeshes(maStlInsertionPickHighlightGroup);
    }

    function maStlSyncRulerAnchorCoordsHud() {
        if (!maStlRulerAnchorCoordsHud) return;
        const showLineSnap =
            maStlRulerAnchorPickMode === 'grid' &&
            maStlLineToolVertexSnapHighlightGroup &&
            maStlLineToolVertexSnapHighlightGroup.visible;
        const showGridSnap = maStlRulerAnchorPickMode === 'grid' && maStlGridIntersectionNearActive;
        const show = showLineSnap || showGridSnap;
        if (!show) {
            maStlRulerAnchorCoordsHud.classList.add('d-none');
            maStlRulerAnchorCoordsHud.textContent = '';
            return;
        }
        const tpl =
            maStlRulerAnchorCoordsHud.getAttribute('data-ma-stl-ruler-anchor-coords-template') || '';
        const snapX = showLineSnap ? _maStlLineToolVertexSnapMm.x : _maStlGridIntersectionSnapMm.x;
        const snapZ = showLineSnap ? _maStlLineToolVertexSnapMm.z : _maStlGridIntersectionSnapMm.z;
        maStlRulerAnchorCoordsHud.textContent = maStlFormatRulerAnchorGridIntersectionToast(
            tpl,
            snapX,
            snapZ
        );
        maStlRulerAnchorCoordsHud.classList.remove('d-none');
    }

    function maStlApplyGridPickHighlightMaterials(mode, onMajorGrid) {
        const root =
            mode === 'connected'
                ? maStlGridIntersectionPickMeshes.connected
                : maStlGridIntersectionPickMeshes.idle;
        if (!root) return;
        const colorHex = onMajorGrid
            ? MA_STL_GRID_MAJOR_LINE_SNAP_COLOR
            : mode === 'connected'
              ? MA_STL_GRID_INTERSECTION_PICK_HIGHLIGHT_COLOR
              : MA_STL_GRID_INTERSECTION_PICK_IDLE_COLOR;
        const opacity = onMajorGrid
            ? MA_STL_GRID_MAJOR_LINE_SNAP_OPACITY
            : mode === 'connected'
              ? MA_STL_GRID_INTERSECTION_PICK_HIGHLIGHT_OPACITY
              : MA_STL_GRID_INTERSECTION_PICK_IDLE_OPACITY;
        root.traverse(function (o) {
            if (!o.material) return;
            o.material.color.setHex(colorHex);
            o.material.opacity = opacity;
            o.material.needsUpdate = true;
        });
    }

    function maStlTouchGridPickHighlightMaterials(mode) {
        const root =
            mode === 'connected'
                ? maStlGridIntersectionPickMeshes.connected
                : maStlGridIntersectionPickMeshes.idle;
        if (!root) return;
        root.traverse(function (o) {
            if (o.material) {
                o.material.needsUpdate = true;
            }
        });
    }

    /**
     * Herramientas de pick (rejilla/objeto/regla/línea): zoom + pan (encuadrar punto); rotación desactivada para no interferir con colocación.
     * Capture en pointerdown sólo corta órbita con botón izquierdo (línea: clic tras up; rejilla/objeto: colocación en down).
     * Captura flags sólo la primera vez; en cada llamada re-fuerza rotación-off + pan/zoom-on (evita carrera si algo rehabilitó flags con snapshot vivo).
     */
    function maStlLockOrbitForRulerAnchorPick() {
        if (!controls) return;
        if (!maStlRulerAnchorPickOrbitLockSnapshot) {
            maStlRulerAnchorPickOrbitLockSnapshot = {
                enabled: controls.enabled,
                enableRotate: !!controls.enableRotate,
                enablePan: !!controls.enablePan,
                enableZoom: !!controls.enableZoom
            };
            maStlClearDesing2OrbitDeferRulerPivotPreserve();
            _maStlPickLockOrbitTargetBaseline.copy(controls.target);
            _maStlPickLockRulerAnchorStartMm.copy(maStlRulerAnchorMm);
        }
        controls.enabled = true;
        controls.enableRotate = false;
        controls.enablePan = true;
        controls.enableZoom = true;
    }

    /** Desing_2: bloquea totalmente órbita/pan durante selección ventana/cruce (copiar/mover/estirar/borrar). */
    function maStlLockOrbitFullyForToolSelection() {
        maStlLockOrbitForRulerAnchorPick();
        if (controls) {
            controls.enabled = false;
        }
    }

    /** Tras confirmar selección — pick-lock sin rotación (pan/zoom opcional en desplazamiento). */
    function maStlReenableOrbitForDupMovePlacementAfterSelection() {
        if (!controls || !maStlRulerAnchorPickOrbitLockSnapshot) return;
        controls.enabled = true;
        controls.enableRotate = false;
        controls.enablePan = true;
        controls.enableZoom = true;
    }

    function maStlClearDeferredRulerPickOrbitUnlock() {
        if (!maStlDeferredRulerPickUnlockPointerEnded) return;
        window.removeEventListener('pointerup', maStlDeferredRulerPickUnlockPointerEnded, true);
        window.removeEventListener('pointercancel', maStlDeferredRulerPickUnlockPointerEnded, true);
        maStlDeferredRulerPickUnlockPointerEnded = null;
    }

    function maStlClearDesing2OrbitDeferRulerPivotPreserve() {
        maStlDesing2OrbitDeferRulerPivotPreserveOnNextSync = false;
    }

    function maStlClearDesing2OrbitPreserveRulerPivotOnRotatePointerDown() {
        maStlDesing2OrbitPreserveRulerPivotOnRotatePointerDown = false;
    }

    function maStlMarkDesing2OrbitRulerAnchoredPreserveNeededOnRotate() {
        if (maStlDesingV2Viewer) {
            maStlDesing2OrbitPreserveRulerPivotOnRotatePointerDown = true;
        }
    }

    function maStlDisposeDesing2OrbitPickLockListener() {
        if (_maStlDesing2OrbitPickLockChangeHandler && controls) {
            controls.removeEventListener('change', _maStlDesing2OrbitPickLockChangeHandler);
        }
        _maStlDesing2OrbitPickLockChangeHandler = null;
    }

    /**
     * Registrar en cada instancia de OrbitControls. Desing_2: durante pick-lock, si `controls.target` se mueve
     * respecto al baseline (> {@link MA_STL_DESING2_PICK_ORBIT_PAN_DETECTION_EPS_MM}), hubo pan → no preservar vista
     * re-anclando al ruler en unlock ni en el primer rotate.
     */
    function maStlWireDesing2OrbitPickLockListener() {
        if (!maStlDesingV2Viewer || !controls) return;
        maStlDisposeDesing2OrbitPickLockListener();
        const epsMm = MA_STL_DESING2_PICK_ORBIT_PAN_DETECTION_EPS_MM;
        const epsSq = epsMm * epsMm;
        _maStlDesing2OrbitPickLockChangeHandler = function () {
            if (!maStlRulerAnchorPickOrbitLockSnapshot || !controls) return;
            if (controls.target.distanceToSquared(_maStlPickLockOrbitTargetBaseline) > epsSq) {
                maStlDesing2OrbitDeferRulerPivotPreserveOnNextSync = true;
            }
        };
        controls.addEventListener('change', _maStlDesing2OrbitPickLockChangeHandler);
    }

    /**
     * Rehabilitar órbita tras pick sin carrera con OrbitControls.
     * @param {boolean} deferUntilPointerEnd `true`: clic coloca en `pointerdown` → esperar `pointerup`/`pointercancel` + 2 RAF (reglas/objects).
     *   `false`: colocación tras `pointerup` (p. ej. evento `click` en herramienta línea) → sólo 2 RAF.
     * @param {boolean} [skipRulerAnchorPreserveViewOnUnlock] Desing_2: si es true (herramienta **línea**), no ejecutar
     *   {@link maStlApplyRulerAnchorOrbitPivotPreserveView} tras unlock: la línea no mueve `maStlRulerAnchorMm`;
     *   forzar pivote al ruler aquí reproduce el salto de “pan → snap” (orbit target desalineado a propósito).
     *   Si además `deferUntilPointerEnd` es false, se usa `queueMicrotask` + 2 RAF (el `click` de P2 corre tras `pointerup`).
     */
    function maStlSchedulePickOrbitUnlockAfterPlacement(
        deferUntilPointerEnd,
        skipRulerAnchorPreserveViewOnUnlock
    ) {
        if (!maStlRulerAnchorPickOrbitLockSnapshot) return;
        maStlClearDeferredRulerPickOrbitUnlock();
        const tryFinishDeferredUnlockFromPlacement = function () {
            if (!maStlRulerAnchorPickOrbitLockSnapshot || !controls) return;
            maStlUnlockOrbitForRulerAnchorPickInner();
            maStlSyncDesing2OrbitPivotAfterPickOrbitUnlock(!!skipRulerAnchorPreserveViewOnUnlock);
            if (typeof controls.saveState === 'function') {
                controls.saveState();
            }
        };
        if (deferUntilPointerEnd) {
            const onPointerEnded = function () {
                maStlClearDeferredRulerPickOrbitUnlock();
                requestAnimationFrame(function () {
                    requestAnimationFrame(tryFinishDeferredUnlockFromPlacement);
                });
            };
            maStlDeferredRulerPickUnlockPointerEnded = onPointerEnded;
            window.addEventListener('pointerup', onPointerEnded, true);
            window.addEventListener('pointercancel', onPointerEnded, true);
        } else if (skipRulerAnchorPreserveViewOnUnlock) {
            queueMicrotask(function () {
                requestAnimationFrame(function () {
                    requestAnimationFrame(tryFinishDeferredUnlockFromPlacement);
                });
            });
        } else {
            requestAnimationFrame(function () {
                requestAnimationFrame(tryFinishDeferredUnlockFromPlacement);
            });
        }
    }

    /** Tras modo pick — fin de gesto (`pointerup`/`pointercancel`) + 2 RAF antes de rehabilitar órbita (evita carrera con OrbitControls). */
    function maStlScheduleDeferRulerPickOrbitUnlockAfterPointerEnd() {
        maStlSchedulePickOrbitUnlockAfterPlacement(true);
    }

    function maStlUnlockOrbitForRulerAnchorPickInner() {
        if (!controls || !maStlRulerAnchorPickOrbitLockSnapshot) return;
        const snap = maStlRulerAnchorPickOrbitLockSnapshot;
        controls.enabled = snap.enabled;
        controls.enableRotate = snap.enableRotate;
        controls.enablePan = snap.enablePan;
        controls.enableZoom = snap.enableZoom;
        maStlRulerAnchorPickOrbitLockSnapshot = null;
    }

    /**
     * Desing_2: tras desbloquear órbita al salir pick de anclaje / regla (o línea con `skip`): alinear target con ruler via
     * {@link maStlApplyRulerAnchorOrbitPivotPreserveView()} salvo cuando el usuario **paneó** bajo pick-lock **y**
     * **`maStlRulerAnchorMm` no cambió** desde el inicio de esa sesión lock. Si durante lock sí se **colocó** nuevo anclaje
     * (rejilla/objeto), ejecutar preserveView y limpiar defer. **Herramienta línea** (`skip`): no preserve hacia ruler —
     * la línea no mueve `maStlRulerAnchorMm`.
     *
     * @see Desing/docs/desing-2-orbit-pivot.md ({@link MA_STL_DESING2_PICK_ORBIT_PAN_DETECTION_EPS_MM}, defer flag)
     * @param {boolean} [skipRulerAnchorPreserveViewOnUnlock] Herramienta línea / cierre sin colocación de anclaje:
     *   no alinear `controls.target` a `maStlRulerAnchorMm` aquí (el usuario puede haber paneado con target desfasado).
     */
    function maStlSyncDesing2OrbitPivotAfterPickOrbitUnlock(skipRulerAnchorPreserveViewOnUnlock) {
        if (!controls || !maStlUsesFixedOrbitPivotAtOrigin()) return;
        if (skipRulerAnchorPreserveViewOnUnlock) {
            maStlClearDesing2OrbitDeferRulerPivotPreserve();
            controls.update();
            return;
        }
        const epsMm = MA_STL_DESING2_PICK_ORBIT_PAN_DETECTION_EPS_MM;
        const anchorMoved =
            _maStlPickLockRulerAnchorStartMm.distanceToSquared(maStlRulerAnchorMm) > epsMm * epsMm;
        if (maStlDesing2OrbitDeferRulerPivotPreserveOnNextSync && !anchorMoved) {
            /* Pan bajo pick-lock sin mover anclaje (p. ej. herramienta línea): no re-encajar pivote al ruler. */
            return;
        }
        maStlApplyRulerAnchorOrbitPivotPreserveView();
        maStlClearDesing2OrbitDeferRulerPivotPreserve();
    }

    /** @param {boolean} [skipRulerAnchorPreserveViewOnUnlock] Ver {@link maStlSyncDesing2OrbitPivotAfterPickOrbitUnlock}. */
    function maStlUnlockOrbitForRulerAnchorPick(skipRulerAnchorPreserveViewOnUnlock) {
        maStlClearDeferredRulerPickOrbitUnlock();
        maStlUnlockOrbitForRulerAnchorPickInner();
        maStlSyncDesing2OrbitPivotAfterPickOrbitUnlock(skipRulerAnchorPreserveViewOnUnlock);
    }

    function maStlEnsureGridIntersectionPickHighlightMeshes() {
        if (maStlGridIntersectionPickMeshes.connected) {
            if (maStlDesingV2Viewer && maStlGridIntersectionPickHighlightGroup.parent !== scene) {
                scene.add(maStlGridIntersectionPickHighlightGroup);
            }
            return;
        }
        const half = desing2EnvGridSnapMm * 0.48;
        maStlGridIntersectionPickMeshes.idle = maStlBuildGridIntersectionPickHighlightOutline(
            half,
            MA_STL_GRID_INTERSECTION_PICK_IDLE_COLOR,
            MA_STL_GRID_INTERSECTION_PICK_IDLE_OPACITY
        );
        maStlGridIntersectionPickMeshes.connected = maStlBuildGridIntersectionPickHighlightFilled(
            half,
            MA_STL_GRID_INTERSECTION_PICK_HIGHLIGHT_COLOR,
            MA_STL_GRID_INTERSECTION_PICK_HIGHLIGHT_OPACITY
        );
        maStlGridIntersectionPickMeshes.idle.visible = false;
        maStlGridIntersectionPickMeshes.connected.visible = false;
        maStlGridIntersectionPickHighlightGroup.add(maStlGridIntersectionPickMeshes.idle);
        maStlGridIntersectionPickHighlightGroup.add(maStlGridIntersectionPickMeshes.connected);
    }

    function maStlClearGridIntersectionPickHighlight() {
        maStlGridIntersectionNearActive = false;
        maStlGridIntersectionPickHighlightGroup.visible = false;
        maStlGridIntersectionPickHighlightGroup.scale.setScalar(1);
        maStlSetOverlaySubtreeVisible(maStlGridIntersectionPickMeshes.idle, false);
        maStlSetOverlaySubtreeVisible(maStlGridIntersectionPickMeshes.connected, false);
        maStlSyncRulerAnchorCoordsHud();
        maStlSyncLineToolHud();
    }

    /**
     * @param {boolean} active
     * @param {THREE.Vector3|null} [worldPos]
     */
    function maStlSetInsertionPickHighlight(active, worldPos) {
        if (!active || !worldPos) {
            maStlClearInsertionPickHighlight();
            return;
        }
        maStlStripOverlayMeshes(maStlInsertionPickHighlightGroup);
        const half = THREE.MathUtils.clamp(lastMaxDim * 0.06, 180, 400);
        maStlInsertionPickHighlightGroup.position.set(
            worldPos.x,
            MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM,
            worldPos.z
        );
        maStlInsertionPickHighlightGroup.add(maStlBuildInsertionPickHighlightRect(half));
        maStlInsertionPickHighlightGroup.visible = true;
    }

    /**
     * @param {'idle'|'connected'} mode
     * @param {{ x: number, y: number, z: number }} snapSnap Punto snap rejilla (mm).
     * @param {boolean} [onMajorGridLine] Línea gruesa mayor rejilla → naranja ×2.
     */
    function maStlSetGridIntersectionPickHighlight(mode, snapSnap, onMajorGridLine) {
        if (!mode || !snapSnap) {
            maStlClearGridIntersectionPickHighlight();
            return;
        }
        maStlEnsureGridIntersectionPickHighlightMeshes();
        maStlGridIntersectionNearActive = mode === 'connected';
        _maStlGridIntersectionSnapMm.set(snapSnap.x, snapSnap.y, snapSnap.z);
        maStlGridIntersectionPickHighlightGroup.position.set(snapSnap.x, snapSnap.y, snapSnap.z);
        maStlGridIntersectionPickHighlightGroup.scale.setScalar(
            onMajorGridLine ? MA_STL_GRID_MAJOR_LINE_SNAP_SCALE : 1
        );
        maStlSetOverlaySubtreeVisible(maStlGridIntersectionPickMeshes.idle, mode === 'idle');
        maStlSetOverlaySubtreeVisible(maStlGridIntersectionPickMeshes.connected, mode === 'connected');
        maStlApplyGridPickHighlightMaterials('idle', !!onMajorGridLine);
        maStlApplyGridPickHighlightMaterials('connected', !!onMajorGridLine);
        maStlTouchGridPickHighlightMaterials('idle');
        maStlTouchGridPickHighlightMaterials('connected');
        maStlGridIntersectionPickHighlightGroup.visible = true;
        maStlSyncRulerAnchorCoordsHud();
        maStlSyncLineToolHud();
    }

    /** Solo click: anclaje + reglas; pivote = target con pan compensado (vista estable). */
    function maStlApplyRulerAnchorOrbitTargetOnly() {
        if (!controls) return;
        maStlApplyRulerAnchorOrbitPivotPreserveView();
    }

    function maStlSetRulerAnchorFromGridSnap(snap) {
        const undoBefore = maStlDesingV2Viewer ? maStlDesing2SerializeEditSnapshot() : null;
        maStlRulerAnchorMm.set(snap.x, snap.y, snap.z);
        maStlInvalidateUserFloorDimGuideGeomCache();
        maStlSyncUserFloorDimHudScreenOnly();
        rebuildMaStlUcsOverlayDecor(lastMaxDim);
        /* Desing_2 Viewer: no tocar cámara/target/controls en el clic de colocación; rejilla/brújula usan maStlRulerAnchorMm. */
        if (!maStlDesingV2Viewer) {
            maStlApplyRulerAnchorOrbitTargetOnly();
        } else {
            maStlMarkDesing2OrbitRulerAnchoredPreserveNeededOnRotate();
            if (undoBefore) {
                maStlDesing2PushEditSnapshotUndo(
                    'rulerAnchor',
                    undoBefore,
                    maStlDesing2SerializeEditSnapshot()
                );
            }
        }
    }

    function maStlSetRulerAnchorFromInsertionPoint(worldPos) {
        const undoBefore = maStlDesingV2Viewer ? maStlDesing2SerializeEditSnapshot() : null;
        maStlRulerAnchorMm.set(worldPos.x, MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM, worldPos.z);
        maStlInvalidateUserFloorDimGuideGeomCache();
        maStlSyncUserFloorDimHudScreenOnly();
        rebuildMaStlUcsOverlayDecor(lastMaxDim);
        if (!maStlDesingV2Viewer) {
            maStlApplyRulerAnchorOrbitTargetOnly();
        } else {
            maStlMarkDesing2OrbitRulerAnchoredPreserveNeededOnRotate();
            if (undoBefore) {
                maStlDesing2PushEditSnapshotUndo(
                    'rulerAnchor',
                    undoBefore,
                    maStlDesing2SerializeEditSnapshot()
                );
            }
        }
    }

    /** @deprecated usar maStlSetRulerAnchorFromInsertionPoint */
    function maStlSetRulerAnchorFromPickPoint(hitPoint) {
        maStlSetRulerAnchorFromInsertionPoint(hitPoint);
    }

    /** Salir del modo pick tras colocación por clic canvas (defer unlock órbita). */
    function maStlExitRulerAnchorPickAfterPlacement() {
        maStlRulerAnchorPickMode = null;
        /**
         * DESING_2 ruler pick — MUST NOT rehabilitar OrbitControls hasta que termine la gestión `pointer*` del clic.
         *
         * `queueMicrotask` fue insuficiente: el microtask siguen antes que `pointerup` y algunos navegadores/Orbit pueden
         * quedar fuera de fase (`enabled=true` antes de cerrar gesto → primer `controls.update()` “engancha”).
         * Se espera `pointerup`/`pointercancel` en window (captura), luego 2 RAF, y sólo entonces unlock + `saveState`.
         * @see Desing/docs/desing-2-orbit-pivot.md (ruler anchor pick)
         */
        maStlScheduleDeferRulerPickOrbitUnlockAfterPointerEnd();
        maStlClearInsertionPickHighlight();
        maStlClearGridIntersectionPickHighlight();
        maStlClearLineToolVertexSnapHighlight();
        maStlClearStlPickHoverHighlight();
        syncMaStlRulerPickToolbarUi();
        syncMaStlRulerAnchorPickCursor();
    }

    const _maStlInsertionFloorProbe = new THREE.Vector3();

    function maStlSyncLineToolHud() {
        if (!maStlLineToolHud || !maStlDesingV2Viewer) return;
        if (!maStlIsLineToolPlacementActive()) {
            maStlLineToolHud.classList.add('d-none');
            if (maStlLineToolHudInstruction) {
                maStlLineToolHudInstruction.textContent = '';
            }
            if (maStlLineToolHudCoords) {
                maStlLineToolHudCoords.textContent = '';
            }
            if (maStlLineToolHudDistanceRow) {
                maStlLineToolHudDistanceRow.classList.add('d-none');
            }
            if (maStlLineToolHudDistancePreview) {
                maStlLineToolHudDistancePreview.textContent = '';
            }
            return;
        }
        const insFirst =
            (maStlLineToolHud &&
                maStlLineToolHud.getAttribute(
                    maStlIsWall2dToolPlacementActive()
                        ? 'data-ma-stl-wall2d-tool-instruction-first'
                        : maStlIsPolylineToolPlacementActive()
                          ? 'data-ma-stl-polyline-tool-instruction-first'
                          : 'data-ma-stl-line-tool-instruction-first'
                )) ||
            '';
        const insSecond =
            (maStlLineToolHud &&
                maStlLineToolHud.getAttribute(
                    maStlIsWall2dToolPlacementActive()
                        ? 'data-ma-stl-wall2d-tool-instruction-second'
                        : maStlIsPolylineToolPlacementActive()
                          ? 'data-ma-stl-polyline-tool-instruction-second'
                          : 'data-ma-stl-line-tool-instruction-second'
                )) ||
            '';
        if (maStlLineToolHudInstruction) {
            maStlLineToolHudInstruction.textContent =
                maStlLineToolState === 'picking1' ? insFirst : insSecond;
        }
        const tpl =
            (maStlLineToolHudCoords &&
                maStlLineToolHudCoords.getAttribute('data-ma-stl-line-tool-coords-template')) ||
            '';
        const showCoords = !!(
            (maStlGridIntersectionPickHighlightGroup && maStlGridIntersectionPickHighlightGroup.visible) ||
            (maStlLineToolVertexSnapHighlightGroup && maStlLineToolVertexSnapHighlightGroup.visible)
        );
        if (maStlLineToolHudCoords) {
            const typedRaw = maStlLineToolRawDistanceTypingTrimmed();
            const typedPt = typedRaw
                ? maStlLineToolTryParseAbsoluteFloorCoordsMm(typedRaw, maStlLineToolState)
                : null;
            if (typedPt && tpl) {
                maStlLineToolHudCoords.textContent = maStlFormatRulerAnchorGridIntersectionToast(
                    tpl,
                    typedPt.x,
                    typedPt.z
                );
            } else if (showCoords && tpl) {
                const snapX = maStlLineToolVertexSnapHighlightGroup.visible
                    ? _maStlLineToolVertexSnapMm.x
                    : _maStlGridIntersectionSnapMm.x;
                const snapZ = maStlLineToolVertexSnapHighlightGroup.visible
                    ? _maStlLineToolVertexSnapMm.z
                    : _maStlGridIntersectionSnapMm.z;
                maStlLineToolHudCoords.textContent = maStlFormatRulerAnchorGridIntersectionToast(
                    tpl,
                    snapX,
                    snapZ
                );
            } else {
                maStlLineToolHudCoords.textContent = '';
            }
        }
        if (maStlLineToolHudDistanceRow) {
            maStlLineToolHudDistanceRow.classList.toggle('d-none', maStlLineToolState !== 'picking2');
        }
        maStlLineToolSyncTypingPreviewUi();
        maStlLineToolHud.classList.remove('d-none');
    }

    function maStlSyncLineToolToggleBtnUi() {
        if (maStlPolylineToolToggleBtn) {
            const onPoly = maStlIsPolylineToolPlacementActive();
            maStlPolylineToolToggleBtn.setAttribute('aria-pressed', onPoly ? 'true' : 'false');
            maStlPolylineToolToggleBtn.classList.toggle('active', onPoly);
        }
        if (maStlOffsetToolToggleBtn) {
            const onOffset = maStlIsOffsetToolActive();
            maStlOffsetToolToggleBtn.setAttribute('aria-pressed', onOffset ? 'true' : 'false');
            maStlOffsetToolToggleBtn.classList.toggle('active', onOffset);
        }
        if (maStlDeleteToolToggleBtn) {
            const onDelete = maStlIsDeleteToolActive();
            maStlDeleteToolToggleBtn.setAttribute('aria-pressed', onDelete ? 'true' : 'false');
            maStlDeleteToolToggleBtn.classList.toggle('active', onDelete);
        }
        if (maStlCopyToolToggleBtn) {
            const onCopy = maStlIsCopyToolActive();
            maStlCopyToolToggleBtn.setAttribute('aria-pressed', onCopy ? 'true' : 'false');
            maStlCopyToolToggleBtn.classList.toggle('active', onCopy);
        }
        if (maStlMoveToolToggleBtn) {
            const onMove = maStlIsMoveToolActive();
            maStlMoveToolToggleBtn.setAttribute('aria-pressed', onMove ? 'true' : 'false');
            maStlMoveToolToggleBtn.classList.toggle('active', onMove);
        }
        if (maStlStretchToolToggleBtn) {
            const onStretch = maStlIsStretchToolActive();
            maStlStretchToolToggleBtn.setAttribute('aria-pressed', onStretch ? 'true' : 'false');
            maStlStretchToolToggleBtn.classList.toggle('active', onStretch);
        }
        if (maStlInsertCornerToolToggleBtn) {
            const onInsertCorner = maStlIsInsertCornerToolActive();
            maStlInsertCornerToolToggleBtn.setAttribute('aria-pressed', onInsertCorner ? 'true' : 'false');
            maStlInsertCornerToolToggleBtn.classList.toggle('active', onInsertCorner);
        }
        if (maStlInsertEnclosureToolToggleBtn) {
            const onInsertEnclosure = maStlIsInsertEnclosureToolActive();
            maStlInsertEnclosureToolToggleBtn.setAttribute('aria-pressed', onInsertEnclosure ? 'true' : 'false');
            maStlInsertEnclosureToolToggleBtn.classList.toggle('active', onInsertEnclosure);
        }
        if (maStlWall2dToolToggleBtn) {
            const onWall2d = maStlIsWall2dToolActive();
            maStlWall2dToolToggleBtn.setAttribute('aria-pressed', onWall2d ? 'true' : 'false');
            maStlWall2dToolToggleBtn.classList.toggle('active', onWall2d);
        }
        maStlSyncDesing2ModeToolbarUi();
        maStlSyncWallDimToolToggleBtnUi();
    }

    function maStlSyncDesing2ModeToolbarUi() {
        const mode = maStlIsWall3dToolActive() ? 'wall3d' : maStlDesing2ModelMode || 'lines';
        const rows = [
            { btn: maStlModeLinesToggleBtn, mode: 'lines' },
            { btn: maStlModeWall2dToggleBtn, mode: 'wall2d' },
            { btn: maStlModeWall3dToggleBtn, mode: 'wall3d' },
        ];
        for (let i = 0; i < rows.length; i++) {
            const row = rows[i];
            if (!row.btn) continue;
            const on = row.mode === mode;
            row.btn.setAttribute('aria-pressed', on ? 'true' : 'false');
            row.btn.classList.toggle('active', on);
        }
    }

    function maStlActivateDesing2ModeToolbarMode(mode) {
        if (!maStlDesingV2Viewer) return false;
        switch (mode) {
            case 'lines':
                maStlDesing2SetModelModeLines();
                return true;
            case 'wall2d':
                maStlDesing2ApplyWall2dModelMode();
                return true;
            case 'wall3d':
                maStlDesing2ApplyWall3dModelMode();
                return true;
            default:
                return false;
        }
    }

    function maStlSyncLineToolOrtho15ToggleUi() {
        if (maStlLineToolOrtho15ToggleBtn) {
            maStlLineToolOrtho15ToggleBtn.setAttribute('aria-pressed', maStlLineToolOrtho15Enabled ? 'true' : 'false');
            maStlLineToolOrtho15ToggleBtn.classList.toggle('active', maStlLineToolOrtho15Enabled);
            const onTitle = maStlLineToolOrtho15ToggleBtn.getAttribute('data-ma-stl-ortho15-title-on') || '';
            const offTitle = maStlLineToolOrtho15ToggleBtn.getAttribute('data-ma-stl-ortho15-title-off') || '';
            const t = maStlLineToolOrtho15Enabled ? onTitle : offTitle;
            if (t) {
                maStlLineToolOrtho15ToggleBtn.setAttribute('title', t);
                maStlLineToolOrtho15ToggleBtn.setAttribute('aria-label', t);
            }
        }
        if (maStlLineToolOrthoStatusHud) {
            maStlLineToolOrthoStatusHud.textContent = maStlLineToolOrtho15Enabled
                ? '(F8) Act'
                : '(F8) Des';
            maStlLineToolOrthoStatusHud.setAttribute(
                'aria-label',
                maStlLineToolOrtho15Enabled ? 'Orto activado. Click para desactivar.' : 'Orto desactivado. Click para activar.'
            );
            maStlLineToolOrthoStatusHud.setAttribute(
                'title',
                maStlLineToolOrtho15Enabled ? 'Orto activado. Click para desactivar.' : 'Orto desactivado. Click para activar.'
            );
            maStlLineToolOrthoStatusHud.classList.remove('d-none', 'is-on', 'is-off');
            maStlLineToolOrthoStatusHud.classList.add(maStlLineToolOrtho15Enabled ? 'is-on' : 'is-off');
        }
    }

    function maStlToggleLineToolOrtho15FromUi() {
        maStlLineToolOrtho15Enabled = !maStlLineToolOrtho15Enabled;
        maStlSyncLineToolOrtho15ToggleUi();
        if (maStlLineToolState === 'picking2') {
            maStlLineToolRefreshPicking2RubberBand();
        }
        if (maStlCopyToolState === 'displacement') {
            maStlCopyToolRefreshDisplacementRubberBand();
        }
    }

    function maStlLineToolResolveWallAxisLineFromSnapLine(line) {
        if (!line || !line.userData) return null;
        const ud = line.userData.maStlUserPlanLine;
        if (!ud) return null;
        if (ud.wallRole === 'axis') return line;
        if (ud.wallRole === 'face' && ud.linkOffsetFromLineId != null) {
            return maStlWall2dToolFindLineByPlanId(ud.linkOffsetFromLineId);
        }
        return null;
    }

    function maStlLineToolNormalizeWallSnapCandidate(snap) {
        if (!snap || !maStlIsWall2dToolPlacementActive()) return snap;
        const axisLine = maStlLineToolResolveWallAxisLineFromSnapLine(snap.segLine);
        const axisUd = axisLine && axisLine.userData && axisLine.userData.maStlUserPlanLine;
        if (!axisUd || axisUd.wallRole !== 'axis' || !axisUd.p1Mm || !axisUd.p2Mm) return snap;

        const out = Object.assign({}, snap, {
            segLine: axisLine,
            segP1: axisUd.p1Mm,
            segP2: axisUd.p2Mm,
        });
        const yFloor = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM;
        if (snap.kind === 'p1') {
            out.x = axisUd.p1Mm.x;
            out.y = axisUd.p1Mm.y != null ? axisUd.p1Mm.y : yFloor;
            out.z = axisUd.p1Mm.z;
        } else if (snap.kind === 'p2') {
            out.x = axisUd.p2Mm.x;
            out.y = axisUd.p2Mm.y != null ? axisUd.p2Mm.y : yFloor;
            out.z = axisUd.p2Mm.z;
        } else if (snap.kind === 'mid') {
            out.x = (axisUd.p1Mm.x + axisUd.p2Mm.x) * 0.5;
            out.y = yFloor;
            out.z = (axisUd.p1Mm.z + axisUd.p2Mm.z) * 0.5;
        } else if (snap.kind === 'segment') {
            const proj = maStlProjectPointOntoUserFloorSegmentBodyXzMm(
                snap,
                axisUd.p1Mm,
                axisUd.p2Mm,
                _maStlUserFloorSegmentBodyProj
            );
            if (proj) {
                out.x = _maStlUserFloorSegmentBodyProj.x;
                out.y = yFloor;
                out.z = _maStlUserFloorSegmentBodyProj.z;
            }
        }
        return out;
    }

    function maStlLineToolPickCursorSync() {
        if (!renderer || !renderer.domElement) return;
        if (maStlIsDesing2FloorDrawToolActive()) {
            renderer.domElement.style.cursor = 'crosshair';
        } else if (!maStlIsRulerAnchorPickModeActive()) {
            renderer.domElement.style.cursor = '';
        }
    }

    function maStlResetLineToolDistanceTypingState() {
        maStlLineToolDistanceTypeBuffer = '';
        maStlLineToolAngleTypeBuffer = '';
        if (maStlLineToolHudDistanceInput) {
            maStlLineToolHudDistanceInput.value = '';
        }
        if (maStlLineToolHudAngleInput) {
            maStlLineToolHudAngleInput.value = '';
        }
        if (maStlLineToolHudDistancePreview) {
            maStlLineToolHudDistancePreview.textContent = '';
        }
    }

    /** Al iniciar `picking1` o tras cancelación: dirección+tamaño último puntero limpios. */
    function maStlResetLineToolPickingBaselineState() {
        maStlLineToolLastHoverDirUnitXz.set(1, 0);
        maStlLineToolLastPointerClientXY.set(Number.NaN, Number.NaN);
        maStlResetLineToolDistanceTypingState();
    }

    function maStlLineToolMaybeUpdateHoverDirFromP2Candidate(p) {
        if (!p || maStlLineToolState !== 'picking2') return;
        const dx = p.x - maStlLineToolPoint1Mm.x;
        const dz = p.z - maStlLineToolPoint1Mm.z;
        const r = maStlLineToolFloorDirLenFromDeltaMm(dx, dz, maStlLineToolOrtho15Enabled);
        if (r) {
            maStlLineToolLastHoverDirUnitXz.set(r.x, r.z);
        }
    }

    /**
     * Dirección en planta (XZ): P1→cursor en suelo; con orto 15° redondea el acimut a múltiplos de 15° (0° = +X, +90° = +Z vía atan2).
     * Si rayo inválido o longitud ~0, último hover no nulo ({@link maStlLineToolLastHoverDirUnitXz}); si vacío, +X.
     * @returns {{ x: number, z: number }} unitario XZ.
     */
    function maStlLineToolComputeFloorDirUnitXz() {
        const p1x = maStlLineToolPoint1Mm.x;
        const p1z = maStlLineToolPoint1Mm.z;
        if (Number.isFinite(maStlLineToolLastPointerClientXY.x) && renderer) {
            const pCur = maStlResolveLineToolFloorPointMm(
                maStlLineToolLastPointerClientXY.x,
                maStlLineToolLastPointerClientXY.y
            );
            if (pCur) {
                const dx = pCur.x - p1x;
                const dz = pCur.z - p1z;
                const r = maStlLineToolFloorDirLenFromDeltaMm(dx, dz, maStlLineToolOrtho15Enabled);
                if (r) {
                    return { x: r.x, z: r.z };
                }
            }
        }
        const ux = maStlLineToolLastHoverDirUnitXz.x;
        const uz = maStlLineToolLastHoverDirUnitXz.y;
        const hu = Math.hypot(ux, uz);
        if (hu >= 1e-9) {
            return { x: ux / hu, z: uz / hu };
        }
        return { x: 1, z: 0 };
    }

    function maStlLineToolTryOrthoTPerpendicularEndMm(snap, out) {
        if (
            !maStlLineToolOrtho15Enabled ||
            !maStlIsWall2dToolPlacementActive() ||
            !snap ||
            snap.kind !== 'segment' ||
            !snap.segLine ||
            !out
        ) {
            return false;
        }
        const targetLine = maStlLineToolResolveWallAxisLineFromSnapLine(snap.segLine);
        const targetUd = targetLine && targetLine.userData && targetLine.userData.maStlUserPlanLine;
        if (!targetUd || targetUd.wallRole !== 'axis' || !targetUd.p1Mm || !targetUd.p2Mm) return false;
        const proj = maStlProjectPointOntoUserFloorSegmentBodyXzMm(
            maStlLineToolPoint1Mm,
            targetUd.p1Mm,
            targetUd.p2Mm,
            _maStlUserFloorSegmentBodyProj
        );
        if (!proj) return false;
        const span = Math.hypot(targetUd.p2Mm.x - targetUd.p1Mm.x, targetUd.p2Mm.z - targetUd.p1Mm.z);
        const minSeg = maStlUserFloorSegmentMinMm();
        const minT = span > minSeg ? minSeg / span : 0.05;
        if (proj.t <= minT || proj.t >= 1 - minT) return false;
        const len = Math.hypot(
            _maStlUserFloorSegmentBodyProj.x - maStlLineToolPoint1Mm.x,
            _maStlUserFloorSegmentBodyProj.z - maStlLineToolPoint1Mm.z
        );
        if (len < minSeg - 1e-9) return false;
        out.x = _maStlUserFloorSegmentBodyProj.x;
        out.y = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM;
        out.z = _maStlUserFloorSegmentBodyProj.z;
        return true;
    }

    /** Texto de distancia: HUD y buffer global pueden desalinearse (Input vs keydown ventana); unificar antes de parseo. */
    function maStlLineToolRawDistanceTypingTrimmed() {
        const vi = maStlLineToolHudDistanceInput ? String(maStlLineToolHudDistanceInput.value || '').trim() : '';
        const vb = String(maStlLineToolDistanceTypeBuffer || '').trim();
        return vi || vb;
    }

    function maStlLineToolRawAngleTypingTrimmed() {
        const vi = maStlLineToolHudAngleInput ? String(maStlLineToolHudAngleInput.value || '').trim() : '';
        const vb = String(maStlLineToolAngleTypeBuffer || '').trim();
        return vi || vb;
    }

    function maStlParseAngleInputValueDeg(text) {
        if (text == null) return null;
        let s = String(text).trim().replace(/[\u00a0\u202f\u2009\u2028\u2029]/g, ' ');
        if (!s) return null;
        s = s.replace(/[^\d,.+\-]/g, '');
        if (!s) return null;
        const comma = s.lastIndexOf(',');
        const dot = s.lastIndexOf('.');
        let numTok = s;
        if (comma >= 0 && dot >= 0) {
            if (dot > comma) numTok = numTok.replace(/,/g, '');
            else numTok = numTok.replace(/\./g, '').replace(',', '.');
        } else if (comma >= 0) {
            numTok = numTok.replace(/,/g, '.');
        }
        const val = Number(numTok);
        return Number.isFinite(val) ? val : null;
    }

    function maStlLineToolParsePolarDistanceAngleMm(raw) {
        if (raw == null) return null;
        const s = String(raw).trim();
        if (!s) return null;
        const body = s.charAt(0) === '@' ? s.slice(1).trim() : s;
        const lt = body.indexOf('<');
        if (lt <= 0 || lt >= body.length - 1) return null;
        const lenMm = maStlParseLengthInputValueToMm(body.slice(0, lt));
        const angleDeg = maStlParseAngleInputValueDeg(body.slice(lt + 1));
        if (lenMm == null || !Number.isFinite(lenMm) || angleDeg == null || !Number.isFinite(angleDeg)) {
            return null;
        }
        const rad = THREE.MathUtils.degToRad(angleDeg);
        return {
            lenMm: lenMm,
            angleDeg: maStlNormalizeAzimuthDeg(angleDeg),
            ux: Math.cos(rad),
            /* En planta Desing_2, arriba en pantalla es -Z; los ángulos CAD positivos van antihorario en pantalla. */
            uz: -Math.sin(rad),
        };
    }

    function maStlLineToolParsedPreviewLenMm() {
        const raw = maStlLineToolRawDistanceTypingTrimmed();
        const polar = maStlLineToolParsePolarDistanceAngleMm(raw);
        if (polar) return polar.lenMm;
        return maStlParseLengthInputValueToMm(raw);
    }

    function maStlLineToolParsedAngleDeg() {
        const rawAngle = maStlLineToolRawAngleTypingTrimmed();
        if (rawAngle) {
            const deg = maStlParseAngleInputValueDeg(rawAngle);
            return deg == null || !Number.isFinite(deg) ? null : maStlNormalizeAzimuthDeg(deg);
        }
        const polar = maStlLineToolParsePolarDistanceAngleMm(maStlLineToolRawDistanceTypingTrimmed());
        return polar ? polar.angleDeg : null;
    }

    function maStlLineToolDirectionUnitXzForTypedInput() {
        const angleDeg = maStlLineToolParsedAngleDeg();
        if (angleDeg != null && Number.isFinite(angleDeg)) {
            const rad = THREE.MathUtils.degToRad(angleDeg);
            return { x: Math.cos(rad), z: -Math.sin(rad) };
        }
        const polar = maStlLineToolParsePolarDistanceAngleMm(maStlLineToolRawDistanceTypingTrimmed());
        if (polar) return { x: polar.ux, z: polar.uz };
        return maStlLineToolComputeFloorDirUnitXz();
    }

    function maStlLineToolSyncTypingPreviewUi() {
        if (
            maStlLineToolHudDistancePreview &&
            maStlLineToolState !== 'picking2'
        ) {
            maStlLineToolHudDistancePreview.textContent = '';
        }
        if (!maStlLineToolHudDistancePreview || maStlLineToolState !== 'picking2') {
            return;
        }
        const lenParsed = maStlLineToolParsedPreviewLenMm();
        if (lenParsed != null && lenParsed > 0) {
            const minMm = maStlUserFloorSegmentMinMm();
            const maxMm = Math.max(minMm, lastMaxDim * 25);
            const lenDisp = maStlDesing2LengthMmRoundedEditableFromMm(
                THREE.MathUtils.clamp(lenParsed, minMm, maxMm)
            );
            const d = maStlDesing2DimEditableMetersDisplayFromMm(lenDisp);
            const pfx =
                (maStlLineToolHud &&
                    maStlLineToolHud.getAttribute('data-ma-stl-line-tool-distance-preview-prefix')) ||
                '\u2248';
            const angleDeg = maStlLineToolParsedAngleDeg();
            maStlLineToolHudDistancePreview.textContent =
                String(pfx) +
                '\u00A0' +
                d +
                '\u00A0m' +
                (angleDeg != null ? '\u00A0<\u00A0' + maStlFormatFloorPlanAngleDegDisplay(angleDeg) : '');
        } else {
            maStlLineToolHudDistancePreview.textContent = '';
        }
    }

    function maStlLineToolTypingBufferedLenOkForRubberMm() {
        const len = maStlLineToolParsedPreviewLenMm();
        const minMm = maStlUserFloorSegmentMinMm();
        return maStlLineToolState === 'picking2' && len != null && Number.isFinite(len) && len >= minMm - 1e-9;
    }

    function maStlLineToolTypingBufferedCoordOkForRubberMm() {
        if (maStlLineToolState !== 'picking2') return false;
        const raw = maStlLineToolRawDistanceTypingTrimmed();
        const pt = raw ? maStlLineToolTryParseAbsoluteFloorCoordsMm(raw, 'picking2') : null;
        if (!pt) return false;
        const lenMm = Math.hypot(pt.x - maStlLineToolPoint1Mm.x, pt.z - maStlLineToolPoint1Mm.z);
        return lenMm >= maStlUserFloorSegmentMinMm() - 1e-9;
    }

    /**
     * Extremo P2 del caucho en `picking2` (cursor, snap vértice u longitud tecleada + orto 15°).
     * @param {{ x: number, y: number, z: number }} out
     * @returns {{ x: number, y: number, z: number }|null}
     */
    function maStlLineToolComputeRubberBandEndMm(out) {
        if (maStlLineToolState !== 'picking2') return null;
        if (maStlLineToolTypingBufferedCoordOkForRubberMm()) {
            const raw = maStlLineToolRawDistanceTypingTrimmed();
            const pt = maStlLineToolTryParseAbsoluteFloorCoordsMm(raw, 'picking2');
            if (pt) {
                out.x = pt.x;
                out.y = pt.y;
                out.z = pt.z;
                return out;
            }
        }
        if (maStlLineToolTypingBufferedLenOkForRubberMm()) {
            out.x = maStlLineToolTypedEndRubberMm.x;
            out.y = maStlLineToolTypedEndRubberMm.y;
            out.z = maStlLineToolTypedEndRubberMm.z;
            return out;
        }
        if (!Number.isFinite(maStlLineToolLastPointerClientXY.x) || !renderer) return null;
        const p = maStlResolveLineToolFloorPointMm(
            maStlLineToolLastPointerClientXY.x,
            maStlLineToolLastPointerClientXY.y
        );
        if (!p) return null;
        const yFl = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM;
        if (
            maStlLineToolVertexSnapHighlightGroup &&
            maStlLineToolVertexSnapHighlightGroup.visible &&
            maStlLineToolTryOrthoTPerpendicularEndMm(maStlLineToolVertexSnapActiveCandidate, out)
        ) {
            return out;
        }
        const dx = p.x - maStlLineToolPoint1Mm.x;
        const dz = p.z - maStlLineToolPoint1Mm.z;
        const r = maStlLineToolFloorDirLenFromDeltaMm(dx, dz, maStlLineToolOrtho15Enabled);
        if (r) {
            out.x = maStlLineToolPoint1Mm.x + r.x * r.len;
            out.y = yFl;
            out.z = maStlLineToolPoint1Mm.z + r.z * r.len;
            return out;
        }
        out.x = p.x;
        out.y = p.y;
        out.z = p.z;
        return out;
    }

    function maStlLineToolRefreshPicking2RubberBand() {
        if (maStlLineToolState !== 'picking2') {
            maStlLineToolHidePreviewDimHud();
            return;
        }
        if (maStlLineToolTypingBufferedLenOkForRubberMm()) {
            let lenMm = maStlLineToolParsedPreviewLenMm();
            const minMm = maStlUserFloorSegmentMinMm();
            const maxMm = Math.max(minMm, lastMaxDim * 25);
            lenMm = THREE.MathUtils.clamp(lenMm, minMm, maxMm);
            lenMm = maStlDesing2LengthMmRoundedEditableFromMm(lenMm);
            const u = maStlLineToolDirectionUnitXzForTypedInput();
            const y = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM;
            maStlLineToolTypedEndRubberMm.set(
                maStlLineToolPoint1Mm.x + u.x * lenMm,
                y,
                maStlLineToolPoint1Mm.z + u.z * lenMm
            );
        }
        const end = maStlLineToolComputeRubberBandEndMm(_maStlLineToolRubberEndMm);
        if (!end) {
            if (maStlLineToolRubberBandLine) {
                maStlLineToolRubberBandLine.visible = false;
            }
            maStlLineToolHidePreviewDimHud();
            return;
        }
        maStlEnsureLineToolRubberBand();
        maStlUpdateLineToolRubberBandMm(end.x, end.y, end.z);
        if (maStlIsWall2dToolPlacementActive()) {
            maStlWall2dToolRefreshFaceRubberBands(end);
        } else {
            maStlWall2dToolHideFaceRubberBands();
        }
        maStlLineToolUpdatePreviewDimHud();
        maStlRefreshLineSnapAngleHudIfVisible();
    }

    function maStlLineToolGloballyConsumeDistanceKeys() {
        const el = document.activeElement;
        if (maStlLineToolHudDistanceInput && el === maStlLineToolHudDistanceInput) return false;
        if (maStlLineToolHudAngleInput && el === maStlLineToolHudAngleInput) return false;
        if (maStlIsUserFloorLineDimEditOverlayActive()) return false;
        if (maStlDesingV2AvoidKeyboardShortcutSteal(el)) return false;
        /* picking1/2: el botón polilínea/muro suele mantener foco tras el clic — sin esto los dígitos no entran en buffer. */
        if (
            (maStlLineToolState === 'picking1' || maStlLineToolState === 'picking2') &&
            ((maStlPolylineToolToggleBtn && el === maStlPolylineToolToggleBtn) ||
                (maStlWall2dToolToggleBtn && el === maStlWall2dToolToggleBtn))
        ) {
            return true;
        }
        if (el && el.closest && el.closest('button, a[href], [role="button"], label')) return false;
        return true;
    }

    /** @returns {boolean} true si trató esta tecla (puede haber ejecutado {@link ev.preventDefault}). */
    function maStlLineToolApplyWindowKeydownToDistanceBuffer(ev) {
        if (!maStlIsLineToolPlacementActive() || !maStlDesingV2Viewer) return false;
        if (!maStlIsDesing2ViewerShellVisibleForKeyboardShortcuts()) return false;
        if (ev.defaultPrevented) return false;
        if (!maStlLineToolGloballyConsumeDistanceKeys(ev)) return false;
        if (ev.ctrlKey || ev.metaKey || ev.altKey) return false;
        if (ev.key === 'Escape' || ev.code === 'Escape') return false;
        if (ev.key === 'Enter' || ev.code === 'Enter' || ev.key === 'NumpadEnter') {
            if (maStlIsPolylineToolPlacementActive() || maStlIsWall2dToolPlacementActive()) {
                const raw = maStlLineToolRawDistanceTypingTrimmed();
                if (raw) {
                    if (/^c$/i.test(raw) && maStlIsWall2dToolPlacementActive()) {
                        ev.preventDefault();
                        return maStlWall2dToolTryCloseActiveGroupFromCommand();
                    }
                    const ok = maStlLineToolTryTypedCommitDistanceOrbitDefer();
                    if (ok) ev.preventDefault();
                    return ok;
                }
                maStlStopLineToolModesToolbar(false);
                ev.preventDefault();
                return true;
            }
            return false;
        }
        if (maStlLineToolState !== 'picking1' && maStlLineToolState !== 'picking2') return false;
        let next = maStlLineToolDistanceTypeBuffer;
        const k = ev.key;
        if (k === 'Backspace') {
            if (!next.length) return false;
            ev.preventDefault();
            next = next.slice(0, -1);
        } else if (k === 'Delete') {
            if (!next.length) return false;
            ev.preventDefault();
            next = '';
        } else if (k.length === 1 && /^[0-9.,;\sMm#@<>\-+°ºCc]$/.test(k)) {
            ev.preventDefault();
            next += k;
        } else {
            return false;
        }
        maStlLineToolDistanceTypeBuffer = next;
        if (maStlLineToolHudDistanceInput && document.activeElement !== maStlLineToolHudDistanceInput) {
            maStlLineToolHudDistanceInput.value = next;
        }
        maStlLineToolSyncTypingPreviewUi();
        maStlSyncLineToolHud();
        maStlLineToolRefreshPicking2RubberBand();
        return true;
    }

    /** @param {string} btnId id botón `#ma-stl-tool-*` (excluye orto 15°). */
    function maStlDesing2SetLastToolbarCommandId(btnId) {
        if (!btnId || btnId === 'ma-stl-tool-ortho-15') return;
        maStlDesing2LastToolbarCommandId = btnId;
    }

    /**
     * Activa un comando de barra superior (no alterna apagado). Placeholders: cancelan modos transitorios.
     * @param {string} btnId
     * @param {{ resume?: boolean }} [options]
     * @returns {boolean} true si aplicó activación
     */
    function maStlDesing2ActivateToolbarCommandById(btnId, options) {
        if (!btnId || !maStlDesingV2Viewer) return false;
        if (btnId === 'ma-stl-tool-line') btnId = 'ma-stl-tool-polyline';
        if (maStlDesing2ModelMode !== 'lines') {
            maStlDesing2SetModelModeLines();
        }
        switch (btnId) {
            case 'ma-stl-tool-polyline':
                if (maStlIsLineToolPlacementActive()) return false;
                maStlStartPolylineToolModesToolbar();
                return true;
            case 'ma-stl-tool-wall-2d':
                if (maStlIsWall2dToolActive()) return false;
                maStlStartWall2dToolModesToolbar({
                    resume: !!(options && options.resume && maStlWall2dToolResumeState != null),
                });
                return true;
            case 'ma-stl-tool-offset':
                if (maStlIsOffsetToolActive()) return false;
                maStlStartOffsetToolModesToolbar();
                return true;
            case 'ma-stl-tool-delete':
                if (maStlIsDeleteToolActive()) return false;
                maStlStartDeleteToolModesToolbar();
                return true;
            case 'ma-stl-tool-copy':
                if (maStlIsCopyToolActive()) return false;
                maStlStartCopyToolModesToolbar();
                return true;
            case 'ma-stl-tool-move':
                if (maStlIsMoveToolActive()) return false;
                maStlStartMoveToolModesToolbar();
                return true;
            case 'ma-stl-tool-stretch':
                if (maStlIsStretchToolActive()) return false;
                maStlStartStretchToolModesToolbar();
                return true;
            case 'ma-stl-tool-insert-corner':
                if (maStlIsInsertCornerToolActive()) return false;
                maStlStartInsertCornerToolModesToolbar();
                return true;
            case 'ma-stl-tool-insert-enclosure':
                if (maStlIsInsertEnclosureToolActive()) return false;
                maStlStartInsertEnclosureToolModesToolbar();
                return true;
            default:
                return false;
        }
    }

    /** @returns {boolean} true si Enter repitió el último comando de barra (sin robar foco de inputs). */
    function maStlDesing2ApplyWindowEnterToRepeatLastToolbarCommand(ev) {
        if (maStlIsDesing2FloorDrawToolActive() || !maStlDesingV2Viewer) return false;
        if (!maStlIsDesing2ViewerShellVisibleForKeyboardShortcuts()) return false;
        if (ev.defaultPrevented) return false;
        if (!(ev.key === 'Enter' || ev.code === 'Enter' || ev.key === 'NumpadEnter') || ev.shiftKey) return false;
        if (ev.ctrlKey || ev.metaKey || ev.altKey) return false;
        const ae = document.activeElement;
        if (maStlLineToolHudDistanceInput && ae === maStlLineToolHudDistanceInput) return false;
        if (maStlLineToolHudAngleInput && ae === maStlLineToolHudAngleInput) return false;
        if (maStlOffsetToolHudDistanceInput && ae === maStlOffsetToolHudDistanceInput) return false;
        if (maStlIsUserFloorLineDimEditOverlayActive()) return false;
        if (maStlDesingV2AvoidKeyboardShortcutSteal(ae)) return false;
        if (ae && ae.closest && ae.closest('button, a[href], [role="button"], label')) return false;
        const ok = maStlDesing2ActivateToolbarCommandById(maStlDesing2LastToolbarCommandId, {
            resume: maStlDesing2LastToolbarCommandId === 'ma-stl-tool-wall-2d',
        });
        if (ok) ev.preventDefault();
        return ok;
    }

    /** @returns {boolean} alias {@link maStlDesing2ApplyWindowEnterToRepeatLastToolbarCommand} */
    function maStlLineToolApplyWindowEnterToActivate(ev) {
        return maStlDesing2ApplyWindowEnterToRepeatLastToolbarCommand(ev);
    }

    function maStlLineToolAdvancePicking1ToPicking2Mm(pSnap) {
        maStlQuantizeUserFloorPlanPointToGridMm(pSnap);
        maStlLineToolPoint1Mm.set(pSnap.x, pSnap.y, pSnap.z);
        maStlLineToolState = 'picking2';
        maStlResetLineToolDistanceTypingState();
        maStlLineToolRefreshPicking2RubberBand();
        maStlSyncLineToolHud();
        queueMicrotask(function () {
            if (maStlLineToolState !== 'picking2' || !maStlLineToolHudDistanceInput) return;
            try {
                maStlLineToolHudDistanceInput.focus({ preventScroll: true });
            } catch (_e) {
                maStlLineToolHudDistanceInput.focus();
            }
        });
    }

    /** @returns {boolean} true si colocó vértice por coordenadas absolutas X,Z. */
    function maStlLineToolTryTypedCommitAbsoluteCoordOrbitDefer() {
        const raw = maStlLineToolRawDistanceTypingTrimmed();
        maStlLineToolDistanceTypeBuffer = raw;
        const pt = maStlLineToolTryParseAbsoluteFloorCoordsMm(raw, maStlLineToolState);
        if (!pt) return false;
        if (maStlLineToolState === 'picking1') {
            maStlLineToolAdvancePicking1ToPicking2Mm(pt);
            return true;
        }
        if (maStlLineToolState === 'picking2') {
            const end = {
                x: pt.x,
                y: pt.y,
                z: pt.z,
            };
            maStlQuantizeUserFloorPlanPointToGridMm(end);
            const lenMm = Math.hypot(
                end.x - maStlLineToolPoint1Mm.x,
                end.z - maStlLineToolPoint1Mm.z
            );
            if (lenMm < maStlUserFloorSegmentMinMm() - 1e-9) {
                const toastTpl =
                    maStlLineToolHud &&
                    maStlLineToolHud.getAttribute('data-ma-stl-line-tool-distance-invalid-toast');
                if (toastTpl) maStlDesing2ShowSaveViewToast(toastTpl);
                return false;
            }
            if (maStlIsWall2dToolPlacementActive()) {
                maStlWall2dToolCommitWallSegmentMm(maStlLineToolPoint1Mm, end);
                maStlWall2dToolAdvanceAfterSegmentMm(end);
            } else {
                maStlCommitUserPlanLineSegmentMm(maStlLineToolPoint1Mm, end);
                maStlPolylineToolAdvanceAfterSegmentMm(end);
            }
            return true;
        }
        return false;
    }

    /** @returns {boolean} true si aplicó segmento completo (`true` igual que segundo clic). */
    function maStlLineToolTryTypedCommitDistanceOrbitDefer() {
        const raw = maStlLineToolRawDistanceTypingTrimmed();
        maStlLineToolDistanceTypeBuffer = raw;
        maStlLineToolAngleTypeBuffer = maStlLineToolRawAngleTypingTrimmed();
        if (/^c$/i.test(raw) && maStlIsWall2dToolPlacementActive()) {
            return maStlWall2dToolTryCloseActiveGroupFromCommand();
        }
        if (maStlLineToolTryTypedCommitAbsoluteCoordOrbitDefer()) return true;
        const polar = maStlLineToolParsePolarDistanceAngleMm(raw);
        const lenMmRaw = polar ? polar.lenMm : maStlParseLengthInputValueToMm(raw);
        const minMm = maStlUserFloorSegmentMinMm();
        const maxMm = Math.max(minMm, lastMaxDim * 25);
        if (lenMmRaw == null || !Number.isFinite(lenMmRaw)) {
            const toastTpl =
                maStlLineToolHud &&
                maStlLineToolHud.getAttribute('data-ma-stl-line-tool-distance-invalid-toast');
            if (toastTpl) maStlDesing2ShowSaveViewToast(toastTpl);
            return false;
        }
        let lenMm = THREE.MathUtils.clamp(lenMmRaw, minMm, maxMm);
        lenMm = maStlDesing2LengthMmRoundedEditableFromMm(lenMm);
        const u = maStlLineToolDirectionUnitXzForTypedInput();
        const y = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM;
        const end = {
            x: maStlLineToolPoint1Mm.x + u.x * lenMm,
            y: y,
            z: maStlLineToolPoint1Mm.z + u.z * lenMm,
        };
        if (maStlIsWall2dToolPlacementActive()) {
            maStlWall2dToolCommitWallSegmentMm(maStlLineToolPoint1Mm, end);
            maStlWall2dToolAdvanceAfterSegmentMm(end);
        } else {
            maStlCommitUserPlanLineSegmentMm(maStlLineToolPoint1Mm, end);
            maStlPolylineToolAdvanceAfterSegmentMm(end);
        }
        return true;
    }

    /** Segundo vértice / clic en planta: extremo del segmento desde {@link maStlLineToolPoint1Mm}. */
    function maStlLineToolComputeSegmentEndMmFromFloorPointMm(pSnap) {
        const y = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM;
        const orthoTEnd = { x: 0, y: y, z: 0 };
        if (maStlLineToolTryOrthoTPerpendicularEndMm(pSnap, orthoTEnd)) {
            return orthoTEnd;
        }
        if (pSnap.maStlLineVertexSnap) {
            return { x: pSnap.x, y: pSnap.y, z: pSnap.z };
        }
        const dx = pSnap.x - maStlLineToolPoint1Mm.x;
        const dz = pSnap.z - maStlLineToolPoint1Mm.z;
        const r = maStlLineToolFloorDirLenFromDeltaMm(dx, dz, maStlLineToolOrtho15Enabled);
        return r
            ? {
                  x: maStlLineToolPoint1Mm.x + r.x * r.len,
                  y: y,
                  z: maStlLineToolPoint1Mm.z + r.z * r.len,
              }
            : { x: pSnap.x, y: pSnap.y, z: pSnap.z };
    }

    /** Polilínea: tras confirmar un tramo, encadenar desde el nuevo vértice (`picking2`). */
    function maStlPolylineToolAdvanceAfterSegmentMm(end) {
        maStlQuantizeUserFloorPlanPointToGridMm(end);
        maStlLineToolPoint1Mm.set(end.x, end.y, end.z);
        maStlLineToolState = 'picking2';
        maStlResetLineToolDistanceTypingState();
        maStlLineToolRefreshPicking2RubberBand();
        maStlSyncLineToolHud();
        queueMicrotask(function () {
            if (maStlLineToolState !== 'picking2' || !maStlLineToolHudDistanceInput) return;
            try {
                maStlLineToolHudDistanceInput.focus({ preventScroll: true });
            } catch (_e) {
                maStlLineToolHudDistanceInput.focus();
            }
        });
    }

    function maStlEnsureLineToolVertexSnapMarker() {
        if (maStlLineToolVertexSnapBallMesh) return;
        maStlLineToolVertexSnapBallMesh = maStlBuildLineToolVertexSnapBallMm(
            MA_STL_LINE_TOOL_VERTEX_SNAP_BALL_VISUAL_RADIUS_MM,
            MA_STL_LINE_TOOL_VERTEX_SNAP_COLOR,
            MA_STL_LINE_TOOL_VERTEX_SNAP_OPACITY_IDLE
        );
        maStlLineToolVertexSnapHighlightGroup.add(maStlLineToolVertexSnapBallMesh);
    }

    /**
     * Par ángulos HUD snap: original (trazo/caucho o eje línea estirada) vs. eje segmento destino.
     * @returns {{ origDeg: number|null, resultDeg: number }|null}
     */
    function maStlResolveLineSnapAnglePairDeg(snap) {
        if (!snap || !snap.segP1 || !snap.segP2) return null;
        const tgtDx = snap.segP2.x - snap.segP1.x;
        const tgtDz = snap.segP2.z - snap.segP1.z;
        if (Math.hypot(tgtDx, tgtDz) < MA_STL_LINE_TOOL_DIR_EPS_MM) return null;
        const resultDeg = maStlNormalizeAzimuthDeg(
            maStlFloorPlanAzimuthDegFromDeltaMm(tgtDx, tgtDz)
        );

        if (maStlIsLineToolPlacementActive() && maStlLineToolState === 'picking2') {
            const end = maStlLineToolComputeRubberBandEndMm(_maStlLineToolRubberEndMm);
            if (!end) return { origDeg: null, resultDeg: resultDeg };
            const odx = end.x - maStlLineToolPoint1Mm.x;
            const odz = end.z - maStlLineToolPoint1Mm.z;
            const r = maStlLineToolFloorDirLenFromDeltaMm(odx, odz, maStlLineToolOrtho15Enabled);
            if (!r) return { origDeg: null, resultDeg: resultDeg };
            const origDeg = maStlNormalizeAzimuthDeg(
                maStlFloorPlanAzimuthDegFromDeltaMm(r.x, r.z)
            );
            return { origDeg: origDeg, resultDeg: resultDeg };
        }

        if (maStlIsLineToolPlacementActive() && maStlLineToolState === 'picking1') {
            return { origDeg: null, resultDeg: resultDeg };
        }

        let srcLine = null;
        if (maStlUserFloorEndpointHandleDragActive()) {
            srcLine = maStlUserFloorLineHudTargetLine();
        }
        if (srcLine && srcLine.userData && srcLine.userData.maStlUserPlanLine) {
            const ud = srcLine.userData.maStlUserPlanLine;
            if (!ud.p1Mm || !ud.p2Mm) return { origDeg: null, resultDeg: resultDeg };
            const odx = ud.p2Mm.x - ud.p1Mm.x;
            const odz = ud.p2Mm.z - ud.p1Mm.z;
            if (Math.hypot(odx, odz) < MA_STL_LINE_TOOL_DIR_EPS_MM) {
                return { origDeg: null, resultDeg: resultDeg };
            }
            const origDeg = maStlNormalizeAzimuthDeg(
                maStlFloorPlanAzimuthDegFromDeltaMm(odx, odz)
            );
            return { origDeg: origDeg, resultDeg: resultDeg };
        }

        if (maStlRulerAnchorPickMode === 'grid') {
            return { origDeg: null, resultDeg: resultDeg };
        }

        return { origDeg: null, resultDeg: resultDeg };
    }

    function maStlFormatLineSnapAngleHudTextFromPair(pair) {
        if (!pair || !Number.isFinite(pair.resultDeg)) return '';
        const fmtR = maStlFormatFloorPlanAngleDegDisplay(pair.resultDeg);
        if (pair.origDeg == null || !Number.isFinite(pair.origDeg)) {
            return '\u2192 ' + fmtR;
        }
        const fmtO = maStlFormatFloorPlanAngleDegDisplay(pair.origDeg);
        const uO = maStlFloorPlanUndirectedLineAngleDegFromDeltaMm(
            Math.cos(THREE.MathUtils.degToRad(pair.origDeg)),
            Math.sin(THREE.MathUtils.degToRad(pair.origDeg))
        );
        const uR = maStlFloorPlanUndirectedLineAngleDegFromDeltaMm(
            Math.cos(THREE.MathUtils.degToRad(pair.resultDeg)),
            Math.sin(THREE.MathUtils.degToRad(pair.resultDeg))
        );
        if (
            maStlFloorPlanUndirectedAngleDiffDeg(uO, uR) <=
            MA_STL_LINE_TOOL_VERTEX_SNAP_ANGLE_COLINEAR_TOL_DEG
        ) {
            return fmtO + ' (colineal)';
        }
        return fmtO + ' \u2192 ' + fmtR;
    }

    function maStlClearLineSnapAngleHud() {
        maStlLineSnapAngleHudActiveSnap = null;
        if (!maStlLineSnapAngleHud) return;
        maStlLineSnapAngleHud.textContent = '';
        maStlLineSnapAngleHud.classList.add('d-none');
        maStlLineSnapAngleHud.removeAttribute('style');
    }

    function maStlPlaceLineSnapAngleHudNearSnapMm(snap) {
        if (!maStlLineSnapAngleHud || !snap || !maStlLineSnapAngleHudCanvasWrap) return;
        if (!maStlWorldMmToScreenPx(snap.x, snap.y, snap.z, _maStlLineSnapAngleHudScr)) return;
        const rWrap = maStlLineSnapAngleHudCanvasWrap.getBoundingClientRect();
        const ballR = MA_STL_LINE_TOOL_VERTEX_SNAP_BALL_VISUAL_RADIUS_MM;
        const lx = _maStlLineSnapAngleHudScr.x - rWrap.left + ballR * 0.35;
        const ly = _maStlLineSnapAngleHudScr.y - rWrap.top - ballR * 0.55 - 22;
        maStlLineSnapAngleHud.style.left = Math.max(4, lx) + 'px';
        maStlLineSnapAngleHud.style.top = Math.max(4, ly) + 'px';
    }

    function maStlSyncLineSnapAngleHud(snap) {
        if (
            !snap ||
            !maStlLineToolVertexSnapHighlightGroup ||
            !maStlLineToolVertexSnapHighlightGroup.visible
        ) {
            maStlClearLineSnapAngleHud();
            return;
        }
        maStlLineSnapAngleHudActiveSnap = snap;
        const pair = maStlResolveLineSnapAnglePairDeg(snap);
        const text = maStlFormatLineSnapAngleHudTextFromPair(pair);
        if (!text || !maStlLineSnapAngleHud) {
            maStlClearLineSnapAngleHud();
            return;
        }
        maStlLineSnapAngleHud.textContent = text;
        maStlPlaceLineSnapAngleHudNearSnapMm(snap);
        maStlLineSnapAngleHud.classList.remove('d-none');
    }

    /** Reposiciona / refresca texto HUD ángulo (cámara, caucho `picking2`, estirar). */
    function maStlRefreshLineSnapAngleHudIfVisible() {
        if (
            !maStlLineSnapAngleHudActiveSnap ||
            !maStlLineToolVertexSnapHighlightGroup ||
            !maStlLineToolVertexSnapHighlightGroup.visible
        ) {
            return;
        }
        maStlSyncLineSnapAngleHud(maStlLineSnapAngleHudActiveSnap);
    }

    function maStlClearLineToolVertexSnapHighlight() {
        maStlLineToolVertexSnapHighlightGroup.visible = false;
        _maStlLineToolVertexSnapKind = null;
        maStlLineToolVertexSnapActiveCandidate = null;
        if (maStlLineToolVertexSnapBallMesh) {
            maStlLineToolVertexSnapBallMesh.scale.setScalar(1);
        }
        maStlClearLineSnapAngleHud();
        maStlSyncLineToolHud();
        maStlSyncRulerAnchorCoordsHud();
    }

    /**
     * @param {{ x: number, y: number, z: number }} snapSnap
     * @param {boolean} active connected (verde) vs. idle (cian)
     * @param {boolean} [onMajorGridLine] Línea gruesa mayor rejilla → naranja ×2.
     */
    function maStlSetLineToolVertexSnapHighlight(snapSnap, active, onMajorGridLine) {
        if (!snapSnap) {
            maStlClearLineToolVertexSnapHighlight();
            return;
        }
        maStlEnsureLineToolVertexSnapMarker();
        _maStlLineToolVertexSnapMm.set(snapSnap.x, snapSnap.y, snapSnap.z);
        _maStlLineToolVertexSnapKind =
            snapSnap.kind === 'p1' ||
            snapSnap.kind === 'p2' ||
            snapSnap.kind === 'mid' ||
            snapSnap.kind === 'segment'
                ? snapSnap.kind
                : null;
        maStlLineToolVertexSnapActiveCandidate = snapSnap;
        maStlLineToolVertexSnapHighlightGroup.position.set(snapSnap.x, snapSnap.y, snapSnap.z);
        if (maStlLineToolVertexSnapBallMesh && maStlLineToolVertexSnapBallMesh.material) {
            const mat = maStlLineToolVertexSnapBallMesh.material;
            if (onMajorGridLine) {
                mat.color.setHex(MA_STL_GRID_MAJOR_LINE_SNAP_COLOR);
                mat.opacity = MA_STL_GRID_MAJOR_LINE_SNAP_OPACITY;
                maStlLineToolVertexSnapBallMesh.scale.setScalar(MA_STL_GRID_MAJOR_LINE_SNAP_SCALE);
            } else {
                mat.color.setHex(
                    active
                        ? MA_STL_LINE_TOOL_VERTEX_SNAP_COLOR_ACTIVE
                        : MA_STL_LINE_TOOL_VERTEX_SNAP_COLOR
                );
                mat.opacity = active
                    ? MA_STL_LINE_TOOL_VERTEX_SNAP_OPACITY_ACTIVE
                    : MA_STL_LINE_TOOL_VERTEX_SNAP_OPACITY_IDLE;
                maStlLineToolVertexSnapBallMesh.scale.setScalar(active ? 1.12 : 1);
            }
        }
        maStlLineToolVertexSnapHighlightGroup.visible = true;
        maStlSyncLineSnapAngleHud(snapSnap);
        maStlSyncLineToolHud();
        maStlSyncRulerAnchorCoordsHud();
    }

    const _maStlUserFloorSegmentBodyProj = { x: 0, y: 0, z: 0 };

    /**
     * Proyección ortogonal en XZ de `floorPt` sobre el tramo P1–P2 (solo cuerpo: t ∈ [0,1]).
     * @param {{ x: number, z: number }} floorPt
     * @param {{ x: number, y: number, z: number }} p1Mm
     * @param {{ x: number, y: number, z: number }} p2Mm
     * @param {{ x: number, y: number, z: number }} out
     * @returns {{ distXZ: number, t: number }|null}
     */
    function maStlProjectPointOntoUserFloorSegmentBodyXzMm(floorPt, p1Mm, p2Mm, out) {
        if (!floorPt || !p1Mm || !p2Mm || !out) return null;
        const abx = p2Mm.x - p1Mm.x;
        const abz = p2Mm.z - p1Mm.z;
        const ab2 = abx * abx + abz * abz;
        if (ab2 < 1e-12) return null;
        const apx = floorPt.x - p1Mm.x;
        const apz = floorPt.z - p1Mm.z;
        const t = (apx * abx + apz * abz) / ab2;
        if (t < 0 || t > 1) return null;
        const px = p1Mm.x + abx * t;
        const pz = p1Mm.z + abz * t;
        out.x = px;
        out.y = p1Mm.y + (p2Mm.y - p1Mm.y) * t;
        out.z = pz;
        return { distXZ: Math.hypot(floorPt.x - px, floorPt.z - pz), t: t };
    }

    /**
     * Snap unificado línea usuario: vértices P1/P2/mid y punto sobre el cuerpo del segmento (T).
     * Solo distancia XZ en planta ≤ `maxDistMm`; el candidato más cercano gana.
     * @param {{ x: number, z: number }} floorPt punto consulta en planta
     * @param {THREE.Line2|null} excludeLine línea a excluir (p. ej. la que se estira)
     * @param {number} [maxDistMm] tolerancia XZ mm escena (default {@link MA_STL_USER_FLOOR_LINE_VERTEX_SNAP_MM})
     * @param {{ excludeWallGroupId?: number|null, skipAxis?: boolean }} [options]
     * @returns {{ x: number, y: number, z: number, kind: 'p1'|'p2'|'mid'|'segment', active: boolean }|null}
     */
    function maStlFindNearestUserFloorLineSegmentSnapMm(floorPt, excludeLine, maxDistMm, options) {
        if (!maStlUserLinesGroup || !floorPt) return null;
        const opts = options || {};
        const threshMm =
            maxDistMm != null && Number.isFinite(maxDistMm)
                ? maxDistMm
                : MA_STL_USER_FLOOR_LINE_VERTEX_SNAP_MM;
        const yFloor = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM;
        let best = null;
        let bestDistXZ = Infinity;
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const line = ch[i];
            if (line === excludeLine) continue;
            if (!maStlIsUserFloorPlanLineObject(line)) continue;
            const ud = line.userData && line.userData.maStlUserPlanLine;
            if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
            if (opts.skipAxis && ud.wallRole === 'axis') continue;
            if (
                opts.excludeWallGroupId != null &&
                ud.wallGroupId != null &&
                ud.wallGroupId === opts.excludeWallGroupId
            ) {
                continue;
            }
            const p1 = ud.p1Mm;
            const p2 = ud.p2Mm;
            const vtxCandidates = [
                { kind: 'p1', x: p1.x, y: p1.y, z: p1.z },
                { kind: 'p2', x: p2.x, y: p2.y, z: p2.z },
                {
                    kind: 'mid',
                    x: (p1.x + p2.x) * 0.5,
                    y: yFloor,
                    z: (p1.z + p2.z) * 0.5
                }
            ];
            for (let ci = 0; ci < vtxCandidates.length; ci++) {
                const c = vtxCandidates[ci];
                const distXZ = Math.hypot(floorPt.x - c.x, floorPt.z - c.z);
                if (distXZ > threshMm) continue;
                if (distXZ < bestDistXZ) {
                    bestDistXZ = distXZ;
                    best = {
                        x: c.x,
                        y: c.y,
                        z: c.z,
                        kind: c.kind,
                        active: true,
                        segLine: line,
                        segP1: p1,
                        segP2: p2,
                    };
                }
            }
            const segProj = maStlProjectPointOntoUserFloorSegmentBodyXzMm(
                floorPt,
                p1,
                p2,
                _maStlUserFloorSegmentBodyProj
            );
            if (segProj && segProj.distXZ <= threshMm && segProj.distXZ < bestDistXZ) {
                bestDistXZ = segProj.distXZ;
                best = {
                    x: _maStlUserFloorSegmentBodyProj.x,
                    y: _maStlUserFloorSegmentBodyProj.y,
                    z: _maStlUserFloorSegmentBodyProj.z,
                    kind: 'segment',
                    active: true,
                    segLine: line,
                    segP1: p1,
                    segP2: p2,
                };
            }
        }
        return maStlLineToolNormalizeWallSnapCandidate(best);
    }

    /**
     * Ajusta vértice en planta al feature de rejilla más cercano si está a ≤ tolerancia (corrige deriva orto/float).
     */
    function maStlQuantizeUserFloorPlanPointToGridMm(pt) {
        if (!pt || !Number.isFinite(pt.x) || !Number.isFinite(pt.z)) return;
        const step =
            desing2EnvGridSnapMm != null && desing2EnvGridSnapMm > 0
                ? desing2EnvGridSnapMm
                : MA_STL_DESING2_GRID_MINOR_MM;
        const tol = Math.max(step * 0.06, MA_STL_WALL_DIM_LENGTH_VALUE_TOL_MM);
        const feat = maStlSnapFloorToGridFeatures({ x: pt.x, z: pt.z }, null, step);
        if (Math.abs(pt.x - feat.x) <= tol && Math.abs(pt.z - feat.z) <= tol) {
            pt.x = feat.x;
            pt.z = feat.z;
        }
    }

    function maStlLineToolVertexSnapClickScreenThresholdPx(camera) {
        return (
            maStlGridIntersectionPickScreenThresholdPx(camera) +
            MA_STL_LINE_TOOL_GRID_PICK_SCREEN_PX_BOOST +
            10
        );
    }

    /**
     * Snap línea usuario en planta (herramienta línea / pick anclaje).
     * Tolerancia mundo XZ + distancia en pantalla (coherente con hover rejilla).
     * Prioriza extremos P1/P2 sobre cuerpo del segmento.
     */
    function maStlFindLineToolVertexSnapCandidate(clientX, clientY, floorHit, proximity) {
        if (!floorHit || !maStlUserLinesGroup) return null;
        const threshMm = MA_STL_USER_FLOOR_LINE_VERTEX_SNAP_MM;
        const yFloor = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM;
        const hasScreen =
            proximity &&
            proximity.camera &&
            proximity.canvas &&
            Number.isFinite(clientX) &&
            Number.isFinite(clientY);
        const boostPx =
            proximity && proximity.pickScreenPxBoost != null && proximity.pickScreenPxBoost > 0
                ? proximity.pickScreenPxBoost
                : 0;
        const screenThreshPx = hasScreen
            ? maStlGridIntersectionPickScreenThresholdPx(proximity.camera) + boostPx
            : Infinity;
        let best = null;
        let bestRank = Infinity;
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const line = ch[i];
            if (!maStlIsUserFloorPlanLineObject(line)) continue;
            const ud = line.userData && line.userData.maStlUserPlanLine;
            if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
            const p1 = ud.p1Mm;
            const p2 = ud.p2Mm;
            const vtxCandidates = [
                { kind: 'p1', x: p1.x, y: p1.y, z: p1.z },
                { kind: 'p2', x: p2.x, y: p2.y, z: p2.z },
                {
                    kind: 'mid',
                    x: (p1.x + p2.x) * 0.5,
                    y: yFloor,
                    z: (p1.z + p2.z) * 0.5,
                },
            ];
            for (let ci = 0; ci < vtxCandidates.length; ci++) {
                const c = vtxCandidates[ci];
                const distXZ = Math.hypot(floorHit.x - c.x, floorHit.z - c.z);
                let screenPx = Infinity;
                if (hasScreen) {
                    _maStlLineToolVertexSnapWorldScratch.set(c.x, c.y, c.z);
                    screenPx = maStlInsertionPointScreenDistancePx(
                        _maStlLineToolVertexSnapWorldScratch,
                        clientX,
                        clientY,
                        proximity.camera,
                        proximity.canvas
                    );
                }
                const xzOk = distXZ <= threshMm;
                const scrOk = screenPx <= screenThreshPx;
                if (!xzOk && !scrOk) continue;
                const endpointBias = c.kind === 'p1' || c.kind === 'p2' ? 0.8 : c.kind === 'mid' ? 0.92 : 1;
                const rank =
                    Math.min(xzOk ? distXZ : Infinity, scrOk ? screenPx : Infinity) * endpointBias;
                if (rank < bestRank) {
                    bestRank = rank;
                    best = {
                        x: c.x,
                        y: c.y,
                        z: c.z,
                        kind: c.kind,
                        active: true,
                        segLine: line,
                        segP1: p1,
                        segP2: p2,
                    };
                }
            }
            const segProj = maStlProjectPointOntoUserFloorSegmentBodyXzMm(
                floorHit,
                p1,
                p2,
                _maStlUserFloorSegmentBodyProj
            );
            if (segProj && segProj.distXZ <= threshMm) {
                let screenPx = Infinity;
                if (hasScreen) {
                    _maStlLineToolVertexSnapWorldScratch.set(
                        _maStlUserFloorSegmentBodyProj.x,
                        _maStlUserFloorSegmentBodyProj.y,
                        _maStlUserFloorSegmentBodyProj.z
                    );
                    screenPx = maStlInsertionPointScreenDistancePx(
                        _maStlLineToolVertexSnapWorldScratch,
                        clientX,
                        clientY,
                        proximity.camera,
                        proximity.canvas
                    );
                }
                const scrOk = screenPx <= screenThreshPx;
                if (scrOk || segProj.distXZ <= threshMm) {
                    const rank =
                        Math.min(segProj.distXZ, scrOk ? screenPx : Infinity) * 1.08;
                    if (rank < bestRank) {
                        bestRank = rank;
                        best = {
                            x: _maStlUserFloorSegmentBodyProj.x,
                            y: _maStlUserFloorSegmentBodyProj.y,
                            z: _maStlUserFloorSegmentBodyProj.z,
                            kind: 'segment',
                            active: true,
                            segLine: line,
                            segP1: p1,
                            segP2: p2,
                        };
                    }
                }
            }
        }
        if (!best) return null;
        if (maStlLineToolState === 'picking2') {
            const minSegMm = maStlUserFloorSegmentMinMm();
            const dP1 = Math.hypot(best.x - maStlLineToolPoint1Mm.x, best.z - maStlLineToolPoint1Mm.z);
            if (dP1 < minSegMm) return null;
        }
        return maStlLineToolNormalizeWallSnapCandidate(best);
    }

    /**
     * Snap línea usuario en planta (herramienta línea y pick anclaje rejilla).
     * Solo tolerancia mundo XZ {@link MA_STL_USER_FLOOR_LINE_VERTEX_SNAP_MM} (100 mm); sin boost px.
     * @param {number} clientX
     * @param {number} clientY
     * @param {number} [pickScreenPxBoost] ignorado para snap línea (reservado API)
     * @returns {{ x: number, y: number, z: number, kind: 'p1'|'p2'|'mid'|'segment', active: boolean }|null}
     */
    function maStlFindFloorLineVertexSnapAtPointer(clientX, clientY, pickScreenPxBoost) {
        if (!renderer) return null;
        const canvas = renderer.domElement;
        const cam = activeCamera();
        if (
            !maStlClientRayToWorkspaceFloor(
                clientX,
                clientY,
                canvas,
                cam,
                orbitPivotNdc,
                orbitPivotRaycaster,
                _maStlInsertionFloorProbe
            )
        ) {
            return null;
        }
        const floorHitObj = { x: _maStlInsertionFloorProbe.x, z: _maStlInsertionFloorProbe.z };
        const proximity = {
            clientX: clientX,
            clientY: clientY,
            camera: cam,
            canvas: canvas,
            maxDim: lastMaxDim,
            pickScreenPxBoost:
                pickScreenPxBoost != null && pickScreenPxBoost > 0 ? pickScreenPxBoost : 0
        };
        const lineSnap = maStlFindLineToolVertexSnapCandidate(
            clientX,
            clientY,
            floorHitObj,
            proximity
        );
        return lineSnap && lineSnap.active ? lineSnap : null;
    }

    /**
     * Punto en planta: snap extendido (cruce / arista / centro) si está activo; si no, impacto libre en el suelo.
     * No aplica snap a vértices de línea (solo preview en hover y commit en clic).
     */
    function maStlResolveLineToolFloorPointMm(clientX, clientY) {
        if (!renderer) return null;
        const canvas = renderer.domElement;
        const cam = activeCamera();
        if (
            !maStlClientRayToWorkspaceFloor(
                clientX,
                clientY,
                canvas,
                cam,
                orbitPivotNdc,
                orbitPivotRaycaster,
                _maStlInsertionFloorProbe
            )
        ) {
            return null;
        }
        const rawX = _maStlInsertionFloorProbe.x;
        const rawZ = _maStlInsertionFloorProbe.z;
        const proximity = {
            clientX: clientX,
            clientY: clientY,
            camera: cam,
            canvas: canvas,
            maxDim: lastMaxDim,
            pickScreenPxBoost: MA_STL_LINE_TOOL_GRID_PICK_SCREEN_PX_BOOST
        };
        const gridSnap = maStlSnapFloorToGridFeatures({ x: rawX, z: rawZ }, proximity, desing2EnvGridSnapMm);
        if (gridSnap.active) {
            return { x: gridSnap.x, y: gridSnap.y, z: gridSnap.z };
        }
        return {
            x: rawX,
            y: MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM,
            z: rawZ
        };
    }

    /**
     * Snap vértice vecino en clic herramienta línea (mundo XZ + pantalla; reutiliza hover activo).
     * @param {{ x: number, y: number, z: number }} basePoint punto ya resuelto (rejilla / suelo libre)
     * @returns {{ x: number, y: number, z: number, maStlLineVertexSnap?: boolean }}
     */
    function maStlApplyLineToolVertexSnapOnClickMm(clientX, clientY, basePoint) {
        const vertexSnap = maStlFindFloorLineVertexSnapAtPointer(
            clientX,
            clientY,
            MA_STL_LINE_TOOL_GRID_PICK_SCREEN_PX_BOOST
        );
        if (vertexSnap) {
            return {
                x: vertexSnap.x,
                y: vertexSnap.y,
                z: vertexSnap.z,
                maStlLineVertexSnap: true,
                kind: vertexSnap.kind,
                segLine: vertexSnap.segLine || null,
                segP1: vertexSnap.segP1 || null,
                segP2: vertexSnap.segP2 || null,
            };
        }
        if (
            maStlLineToolVertexSnapHighlightGroup &&
            maStlLineToolVertexSnapHighlightGroup.visible &&
            renderer &&
            (_maStlLineToolVertexSnapKind === 'p1' ||
                _maStlLineToolVertexSnapKind === 'p2' ||
                _maStlLineToolVertexSnapKind === 'mid' ||
                _maStlLineToolVertexSnapKind === 'segment')
        ) {
            const cam = activeCamera();
            const canvas = renderer.domElement;
            _maStlLineToolVertexSnapWorldScratch.set(
                _maStlLineToolVertexSnapMm.x,
                _maStlLineToolVertexSnapMm.y,
                _maStlLineToolVertexSnapMm.z
            );
            const screenPx = maStlInsertionPointScreenDistancePx(
                _maStlLineToolVertexSnapWorldScratch,
                clientX,
                clientY,
                cam,
                canvas
            );
            if (screenPx <= maStlLineToolVertexSnapClickScreenThresholdPx(cam)) {
                return {
                    x: _maStlLineToolVertexSnapMm.x,
                    y: _maStlLineToolVertexSnapMm.y,
                    z: _maStlLineToolVertexSnapMm.z,
                    maStlLineVertexSnap: true,
                    kind: _maStlLineToolVertexSnapKind,
                    segLine: maStlLineToolVertexSnapActiveCandidate
                        ? maStlLineToolVertexSnapActiveCandidate.segLine
                        : null,
                    segP1: maStlLineToolVertexSnapActiveCandidate
                        ? maStlLineToolVertexSnapActiveCandidate.segP1
                        : null,
                    segP2: maStlLineToolVertexSnapActiveCandidate
                        ? maStlLineToolVertexSnapActiveCandidate.segP2
                        : null,
                };
            }
        }
        return basePoint;
    }

    function maStlUpdateLineToolFloorHover(clientX, clientY) {
        if (!maStlIsLineToolPlacementActive() || !maStlDesingV2Viewer || !renderer) {
            return false;
        }
        const canvas = renderer.domElement;
        const cam = activeCamera();
        const floorHit = maStlClientRayToWorkspaceFloor(
            clientX,
            clientY,
            canvas,
            cam,
            orbitPivotNdc,
            orbitPivotRaycaster,
            _maStlInsertionFloorProbe
        );
        if (!floorHit) {
            maStlClearGridIntersectionPickHighlight();
            maStlClearLineToolVertexSnapHighlight();
            maStlSyncLineToolHud();
            if (maStlLineToolState === 'picking2') {
                maStlLineToolRefreshPicking2RubberBand();
            }
            return false;
        }
        const floorHitObj = { x: _maStlInsertionFloorProbe.x, z: _maStlInsertionFloorProbe.z };
        const lineSnap = maStlFindFloorLineVertexSnapAtPointer(
            clientX,
            clientY,
            MA_STL_LINE_TOOL_GRID_PICK_SCREEN_PX_BOOST
        );
        if (lineSnap) {
            const onMajor = maStlIsOnDisplayedMajorGridLineAtMm(lineSnap.x, lineSnap.z);
            maStlSetLineToolVertexSnapHighlight(lineSnap, true, onMajor);
            maStlClearGridIntersectionPickHighlight();
            return true;
        }
        maStlClearLineToolVertexSnapHighlight();
        const proximity = {
            clientX: clientX,
            clientY: clientY,
            camera: cam,
            canvas: canvas,
            maxDim: lastMaxDim,
            pickScreenPxBoost: MA_STL_LINE_TOOL_GRID_PICK_SCREEN_PX_BOOST
        };
        const gridSnap = maStlSnapFloorToGridFeatures(floorHitObj, proximity, desing2EnvGridSnapMm);
        const onMajor = maStlIsOnDisplayedMajorGridLineAtMm(gridSnap.x, gridSnap.z);
        maStlSetGridIntersectionPickHighlight(
            gridSnap.active ? 'connected' : 'idle',
            gridSnap,
            onMajor
        );
        return true;
    }

    function maStlLineToolEnsureRubberBandMaterialIsolated() {
        maStlEnsureLineToolRubberBand();
        if (!maStlLineToolRubberBandLine || !maStlUserFloorLineMat) return;
        if (maStlLineToolRubberBandLine.material === maStlUserFloorLineMat) {
            const mat = maStlUserFloorLineMat.clone ? maStlUserFloorLineMat.clone() : maStlUserFloorLineMat;
            maStlApplyUserFloorLineMaterialResolutionIfRenderer(mat);
            maStlLineToolRubberBandLine.material = mat;
        }
    }

    function maStlEnsureLineToolRubberBand() {
        if (maStlLineToolRubberBandLine) return;
        const geo = new LineGeometry();
        geo.setPositions(new Float32Array(6));
        const um = maStlEnsureUserFloorLineMat();
        const mat = um.clone ? um.clone() : um;
        maStlApplyUserFloorLineMaterialResolutionIfRenderer(mat);
        maStlLineToolRubberBandLine = new Line2(geo, mat);
        maStlLineToolRubberBandLine.renderOrder = 169;
        maStlLineToolRubberBandLine.visible = false;
        maStlDisableRaycastOnOverlay(maStlLineToolRubberBandLine);
        scene.add(maStlLineToolRubberBandLine);
    }

    function maStlLineToolSyncRubberBandWall2dStyle() {
        if (!maStlLineToolRubberBandLine || !maStlLineToolRubberBandLine.material) return;
        const mat = maStlLineToolRubberBandLine.material;
        if (maStlIsWall2dToolPlacementActive()) {
            maStlApplyUserFloorWallAxisLineStyleToMaterial(mat);
            maStlApplyUserFloorLineMaterialResolutionIfRenderer(mat);
            maStlUserFloorLineSyncAxisDashDistances(maStlLineToolRubberBandLine);
        } else {
            maStlApplyUserFloorLineBaseMaterial(mat, null);
        }
    }

    function maStlUpdateLineToolRubberBandMm(p2x, p2y, p2z) {
        if (maStlLineToolState !== 'picking2') {
            if (maStlLineToolRubberBandLine) {
                maStlLineToolRubberBandLine.visible = false;
            }
            maStlWall2dToolHideFaceRubberBands();
            return;
        }
        maStlEnsureLineToolRubberBand();
        maStlSetUserFloorLineGeometryMm(maStlLineToolRubberBandLine, maStlLineToolPoint1Mm, {
            x: p2x,
            y: p2y,
            z: p2z
        });
        maStlLineToolSyncRubberBandWall2dStyle();
        maStlLineToolRubberBandLine.visible = true;
    }

    function maStlLineToolHidePreviewDimHud() {
        if (!maStlLineToolPreviewDimActive) return;
        maStlLineToolPreviewDimActive = false;
        maStlLineToolHideAngleArcHud();
        const h = maStlEnsureUserFloorDimDomHud();
        if (h && h.root) {
            h.root.classList.remove('desing2-stl-floor-dim-overlay--line-tool-preview');
        }
        maStlHideUserFloorLineDimHud(true);
    }

    function maStlLineToolEnsureAngleArcMesh() {
        if (maStlLineToolAngleArcMesh) return maStlLineToolAngleArcMesh;
        const geo = new THREE.BufferGeometry();
        const mat = new THREE.LineBasicMaterial({
            color: 0x8fb3ff,
            transparent: true,
            opacity: 0.95,
            depthTest: false,
            depthWrite: false,
        });
        const mesh = new THREE.Line(geo, mat);
        mesh.visible = false;
        mesh.renderOrder = 175;
        maStlDisableRaycastOnOverlay(mesh);
        maStlUserFloorLineDimHudGroup.add(mesh);
        maStlLineToolAngleArcMesh = mesh;
        return mesh;
    }

    function maStlLineToolEnsureAngleArcLabelEl() {
        if (maStlLineToolAngleArcLabelEl) return maStlLineToolAngleArcLabelEl;
        const h = maStlEnsureUserFloorDimDomHud();
        const wrap = h && h.canvasWrap;
        if (!wrap) return null;
        const el = document.createElement('div');
        el.className = 'ma-stl-line-snap-angle-hud d-none';
        el.setAttribute('aria-hidden', 'true');
        wrap.appendChild(el);
        maStlLineToolAngleArcLabelEl = el;
        return el;
    }

    function maStlLineToolHideAngleArcHud() {
        if (maStlLineToolAngleArcMesh) {
            maStlLineToolAngleArcMesh.visible = false;
        }
        if (maStlLineToolAngleArcLabelEl) {
            maStlLineToolAngleArcLabelEl.classList.add('d-none');
            maStlLineToolAngleArcLabelEl.setAttribute('aria-hidden', 'true');
            maStlLineToolAngleArcLabelEl.textContent = '';
        }
    }

    function maStlLineToolFindPreviousSegmentAtCurrentPointMm() {
        if (!maStlUserLinesGroup || maStlLineToolState !== 'picking2') return null;
        const eps = maStlUserFloorLineMergeEndpointEpsMm();
        const pt = maStlLineToolPoint1Mm;
        const ch = maStlUserLinesGroup.children;
        for (let i = ch.length - 1; i >= 0; i--) {
            const line = ch[i];
            if (!maStlIsUserFloorPlanLineObject(line)) continue;
            const ud = line.userData && line.userData.maStlUserPlanLine;
            if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
            if (maStlIsWall2dToolPlacementActive()) {
                if (ud.wallRole !== 'axis' || ud.wallGroupId !== maStlWall2dToolActiveGroupId) continue;
            } else if (maStlIsPolylineToolPlacementActive()) {
                if (ud.polylineGroupId !== maStlPolylineToolActiveGroupId) continue;
            } else {
                continue;
            }
            if (maStlUserFloorPlanPointNearXzMm(ud.p2Mm, pt, eps)) {
                return {
                    dx: ud.p2Mm.x - ud.p1Mm.x,
                    dz: ud.p2Mm.z - ud.p1Mm.z,
                    len: maStlUserFloorLineLengthMm(ud),
                };
            }
            if (maStlUserFloorPlanPointNearXzMm(ud.p1Mm, pt, eps)) {
                return {
                    dx: ud.p1Mm.x - ud.p2Mm.x,
                    dz: ud.p1Mm.z - ud.p2Mm.z,
                    len: maStlUserFloorLineLengthMm(ud),
                };
            }
        }
        return null;
    }

    function maStlLineToolPositiveIncludedAngleDeg(baseDx, baseDz, outDx, outDz) {
        const baseAng = maStlFloorPlanCadAngleDegFromDeltaMm(baseDx, baseDz);
        const outAng = maStlFloorPlanCadAngleDegFromDeltaMm(outDx, outDz);
        let d = maStlNormalizeAzimuthDeg(outAng - baseAng);
        if (d > 180) d = 360 - d;
        return d;
    }

    function maStlLineToolUpdateAngleArcHud(currentUd) {
        if (!currentUd || !currentUd.p1Mm || !currentUd.p2Mm) {
            maStlLineToolHideAngleArcHud();
            return false;
        }
        const prev = maStlLineToolFindPreviousSegmentAtCurrentPointMm();
        const outDx = currentUd.p2Mm.x - currentUd.p1Mm.x;
        const outDz = currentUd.p2Mm.z - currentUd.p1Mm.z;
        const outLen = Math.hypot(outDx, outDz);
        if (!prev || !(prev.len > 0) || !(outLen > maStlUserFloorSegmentMinMm())) {
            maStlLineToolHideAngleArcHud();
            return false;
        }
        const angleDeg = maStlLineToolPositiveIncludedAngleDeg(prev.dx, prev.dz, outDx, outDz);
        if (!Number.isFinite(angleDeg) || angleDeg < 0.5 || angleDeg > 179.5) {
            maStlLineToolHideAngleArcHud();
            return false;
        }

        const baseAng = maStlFloorPlanCadAngleDegFromDeltaMm(prev.dx, prev.dz);
        const outAng = maStlFloorPlanCadAngleDegFromDeltaMm(outDx, outDz);
        const ccw = maStlNormalizeAzimuthDeg(outAng - baseAng);
        const dir = ccw <= 180 ? 1 : -1;
        const sweep = ccw <= 180 ? ccw : 360 - ccw;
        const radius = THREE.MathUtils.clamp(
            Math.min(prev.len, outLen) * 0.38,
            Math.max(desing2EnvGridSnapMm * 0.85, 460),
            Math.min(3600, lastMaxDim * 0.35)
        );
        const floorYB = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM + MA_STL_USER_FLOOR_LINE_DIM_DRAW_Y_EPS_MM * 2.2;
        const segs = Math.max(16, Math.ceil(sweep / 5));
        const pts = [];
        for (let i = 0; i <= segs; i++) {
            const a = baseAng + dir * sweep * (i / segs);
            const rad = THREE.MathUtils.degToRad(a);
            pts.push(
                new THREE.Vector3(
                    currentUd.p1Mm.x + Math.cos(rad) * radius,
                    floorYB,
                    currentUd.p1Mm.z - Math.sin(rad) * radius
                )
            );
        }
        const mesh = maStlLineToolEnsureAngleArcMesh();
        mesh.geometry.dispose();
        mesh.geometry = new THREE.BufferGeometry().setFromPoints(pts);
        mesh.geometry.computeBoundingSphere();
        mesh.visible = true;

        const labelEl = maStlLineToolEnsureAngleArcLabelEl();
        const labelScr = { x: 0, y: 0, valid: false };
        const midAng = baseAng + dir * sweep * 0.5;
        const midRad = THREE.MathUtils.degToRad(midAng);
        const lx = currentUd.p1Mm.x + Math.cos(midRad) * radius * 1.08;
        const lz = currentUd.p1Mm.z - Math.sin(midRad) * radius * 1.08;
        if (!labelEl || !maStlWorldMmToScreenPx(lx, floorYB, lz, labelScr)) {
            if (labelEl) labelEl.classList.add('d-none');
            return true;
        }
        const h = maStlEnsureUserFloorDimDomHud();
        const wrap = h && h.canvasWrap;
        if (!wrap) return true;
        const rr = wrap.getBoundingClientRect();
        labelEl.textContent = maStlFormatFloorPlanAngleDegDisplay(angleDeg);
        labelEl.style.left = labelScr.x - rr.left + 'px';
        labelEl.style.top = labelScr.y - rr.top + 'px';
        labelEl.style.transform = 'translate(-50%, -50%)';
        labelEl.classList.remove('d-none');
        labelEl.setAttribute('aria-hidden', 'false');
        return true;
    }

    /** Cotas CAD + readouts DOM en vivo (`picking2`): sólo longitud P1→P2 (sin ΔX/ΔZ). */
    function maStlLineToolUpdatePreviewDimHud() {
        if (maStlLineToolState !== 'picking2' || !maStlDesingV2Viewer) {
            maStlLineToolHidePreviewDimHud();
            return;
        }
        const end = maStlLineToolComputeRubberBandEndMm(_maStlLineToolRubberEndMm);
        if (!end) {
            maStlLineToolHidePreviewDimHud();
            return;
        }
        const ud = maStlLineToolPreviewDimUd;
        ud.p1Mm.x = maStlLineToolPoint1Mm.x;
        ud.p1Mm.y = maStlLineToolPoint1Mm.y;
        ud.p1Mm.z = maStlLineToolPoint1Mm.z;
        ud.p2Mm.x = end.x;
        ud.p2Mm.y = end.y;
        ud.p2Mm.z = end.z;
        if (maStlUserFloorLineLengthMm(ud) < maStlUserFloorSegmentMinMm() - 1e-9) {
            maStlLineToolHidePreviewDimHud();
            return;
        }
        const mergedSpan = maStlFindUserFloorCollinearExtensionMergeSpanMm(ud);
        const dimUd = mergedSpan || ud;
        maStlLineToolPreviewDimActive = true;
        maStlRebuildUserFloorDimGuideGeometry(dimUd, true);
        if (!maStlUserFloorDimProjectHudReadoutScreens()) {
            maStlLineToolHidePreviewDimHud();
            return;
        }
        const hdom = maStlEnsureUserFloorDimDomHud();
        if (
            !hdom ||
            !hdom.root ||
            !hdom.readoutBtn ||
            !hdom.readoutDxBtn ||
            !hdom.readoutDzBtn
        ) {
            return;
        }
        hdom.root.hidden = false;
        hdom.root.removeAttribute('hidden');
        hdom.root.setAttribute('aria-hidden', 'false');
        hdom.root.classList.add('desing2-stl-floor-dim-overlay--line-tool-preview');
        hdom.readoutBtn.hidden = false;
        hdom.readoutBtn.removeAttribute('hidden');
        hdom.readoutBtn.setAttribute('aria-hidden', 'false');
        hdom.readoutBtn.textContent = maStlUserFloorLineDimensionLabelMm(dimUd);
        maStlLineToolUpdateAngleArcHud(ud);
        maStlApplyFloorDimHudLengthOnlyMode(hdom, true);
        maStlPlaceAllFloorDimHudReadouts(true);
        maStlApplyFloorDimHudReadoutBrightClass(null);
        maStlApplyUserFloorDimDomHudTheme(hdom.readoutBtn);
    }

    /** Reposiciona cotas preview al orbitar/zoom sin recalcular geometría CAD. */
    function maStlLineToolSyncPreviewDimHudScreenOnly() {
        if (!maStlLineToolPreviewDimActive || maStlLineToolState !== 'picking2') return;
        if (!maStlUserFloorDimProjectHudReadoutScreens()) return;
        const hdom = maStlEnsureUserFloorDimDomHud();
        if (!hdom || !hdom.root) return;
        maStlPlaceAllFloorDimHudReadouts(true);
    }

    /** Activa polilínea Desing_2 → `picking1`; cada clic posterior encadena un segmento independiente. */
    function maStlStartPolylineToolModesToolbar() {
        if (maStlIsPolylineToolPlacementActive()) return;
        maStlDesing2ClearAtk60Visuals();
        maStlWall2dToolResumeState = null;
        if (maStlIsWall2dToolActive()) maStlStopWall2dToolModesToolbar(false);
        if (maStlIsLineToolPlacementActive()) maStlStopLineToolModesToolbar(false);
        if (maStlIsOffsetToolActive()) maStlStopOffsetToolModesToolbar(false);
        if (maStlIsDeleteToolActive()) maStlStopDeleteToolModesToolbar(false);
        if (maStlIsDupMoveToolActive()) maStlStopCopyToolModesToolbar(false);
        if (maStlIsWall3dToolActive()) maStlStopWall3dToolModesToolbar(false);
        if (maStlIsImageSketchToolActive()) maStlStopImageSketchToolModesToolbar(false);
        if (maStlIsInsertCornerToolActive()) maStlStopInsertCornerToolModesToolbar(false);
        if (maStlIsInsertEnclosureToolActive()) maStlStopInsertEnclosureToolModesToolbar(false);
        if (maStlIsImageSketchToolActive()) maStlStopImageSketchToolModesToolbar(false);
        maStlStopWallDimToolModesToolbar();
        maStlPolylineToolActiveGroupId = maStlUserFloorLineNextPolylineGroupId++;
        maStlDesing2SetLastToolbarCommandId('ma-stl-tool-polyline');
        maStlLineToolKind = 'polyline';
        maStlStopRulerAnchorPickModesToolbar();
        maStlTeardownPickHighlightsOnly();
        maStlResetLineToolPickingBaselineState();
        maStlLineToolState = 'picking1';
        maStlLockOrbitForRulerAnchorPick();
        maStlEnsureGridIntersectionPickHighlightMeshes();
        maStlSyncLineToolToggleBtnUi();
        maStlLineToolPickCursorSync();
        maStlSyncLineToolHud();
        if (maStlPolylineToolToggleBtn && document.activeElement === maStlPolylineToolToggleBtn) {
            maStlPolylineToolToggleBtn.blur();
        }
    }

    /** Activa muro 2D Desing_2 → polilínea con eje + caras (±espesor/2) y esquinas a inglete. */
    function maStlStartWall2dToolModesToolbar(options) {
        if (maStlIsWall2dToolPlacementActive()) return;
        maStlDesing2ClearAtk60Visuals();
        if (maStlIsPolylineToolPlacementActive()) maStlStopLineToolModesToolbar(false);
        if (maStlIsOffsetToolActive()) maStlStopOffsetToolModesToolbar(false);
        if (maStlIsDeleteToolActive()) maStlStopDeleteToolModesToolbar(false);
        if (maStlIsDupMoveToolActive()) maStlStopCopyToolModesToolbar(false);
        if (maStlIsWall3dToolActive()) maStlStopWall3dToolModesToolbar(false);
        if (maStlIsImageSketchToolActive()) maStlStopImageSketchToolModesToolbar(false);
        if (maStlIsInsertCornerToolActive()) maStlStopInsertCornerToolModesToolbar(false);
        if (maStlIsInsertEnclosureToolActive()) maStlStopInsertEnclosureToolModesToolbar(false);
        maStlStopWallDimToolModesToolbar();
        applyDesing2ConfigWallWidthsFromInputs();
        const wantResume =
            options && options.resume && maStlWall2dToolResumeState && maStlWall2dToolResumeState.pointMm;
        if (wantResume) {
            maStlWall2dToolActiveGroupId = maStlWall2dToolResumeState.wallGroupId;
        } else {
            maStlWall2dToolActiveGroupId = maStlUserFloorLineNextWallGroupId++;
        }
        maStlEnsureUserFloorWallAxisLineMat();
        if (renderer && renderer.domElement) {
            maStlSyncAllUserFloorLineMaterialResolutions(
                renderer.domElement.clientWidth,
                renderer.domElement.clientHeight
            );
        }
        maStlLineToolEnsureRubberBandMaterialIsolated();
        maStlDesing2SetLastToolbarCommandId('ma-stl-tool-wall-2d');
        maStlLineToolKind = 'wall2d';
        maStlStopRulerAnchorPickModesToolbar();
        maStlTeardownPickHighlightsOnly();
        maStlResetLineToolPickingBaselineState();
        if (wantResume) {
            const p = maStlWall2dToolResumeState.pointMm;
            maStlLineToolPoint1Mm.set(p.x, p.y, p.z);
            maStlLineToolState = 'picking2';
            maStlResetLineToolDistanceTypingState();
            maStlLineToolRefreshPicking2RubberBand();
        } else {
            maStlLineToolState = 'picking1';
        }
        maStlLockOrbitForRulerAnchorPick();
        maStlEnsureGridIntersectionPickHighlightMeshes();
        maStlSyncLineToolToggleBtnUi();
        maStlLineToolPickCursorSync();
        maStlSyncLineToolHud();
        if (maStlWall2dToolToggleBtn && document.activeElement === maStlWall2dToolToggleBtn) {
            maStlWall2dToolToggleBtn.blur();
        }
    }

    function maStlWall2dToolGroupHasAxisSegments(wallGroupId) {
        if (wallGroupId == null) return false;
        const group = maStlUserFloorPlanLinesInWallGroup(wallGroupId);
        for (let gi = 0; gi < group.length; gi++) {
            const ud = group[gi].userData && group[gi].userData.maStlUserPlanLine;
            if (ud && ud.wallRole === 'axis') return true;
        }
        return false;
    }

    /** Último vértice de la cadena de ejes (segmento con mayor `id` → `p2`). */
    function maStlWall2dToolFindGroupChainEndMm(wallGroupId) {
        if (wallGroupId == null) return null;
        const group = maStlUserFloorPlanLinesInWallGroup(wallGroupId);
        let bestUd = null;
        let maxId = -1;
        for (let gi = 0; gi < group.length; gi++) {
            const ud = group[gi].userData && group[gi].userData.maStlUserPlanLine;
            if (!ud || ud.wallRole !== 'axis' || ud.id == null || !ud.p2Mm) continue;
            if (ud.id > maxId) {
                maxId = ud.id;
                bestUd = ud;
            }
        }
        return bestUd ? maStlDesing2ClonePlanPointMm(bestUd.p2Mm) : null;
    }

    function maStlWall2dToolAxisSegmentsInGroup(wallGroupId) {
        const axes = [];
        if (wallGroupId == null) return axes;
        const group = maStlUserFloorPlanLinesInWallGroup(wallGroupId);
        for (let gi = 0; gi < group.length; gi++) {
            const ud = group[gi].userData && group[gi].userData.maStlUserPlanLine;
            if (ud && ud.wallRole === 'axis' && ud.id != null && ud.p1Mm && ud.p2Mm) {
                axes.push({ line: group[gi], ud: ud });
            }
        }
        axes.sort(function (a, b) {
            return a.ud.id - b.ud.id;
        });
        return axes;
    }

    function maStlWall2dToolFindGroupChainStartMm(wallGroupId) {
        const axes = maStlWall2dToolAxisSegmentsInGroup(wallGroupId);
        return axes.length ? maStlDesing2ClonePlanPointMm(axes[0].ud.p1Mm) : null;
    }

    function maStlWall2dToolCanCloseActiveGroup() {
        if (!maStlIsWall2dToolPlacementActive() || maStlLineToolState !== 'picking2') return false;
        const axes = maStlWall2dToolAxisSegmentsInGroup(maStlWall2dToolActiveGroupId);
        return axes.length >= 2;
    }

    function maStlWall2dToolTryCloseActiveGroupFromCommand() {
        if (!maStlWall2dToolCanCloseActiveGroup()) return true;
        const first = maStlWall2dToolFindGroupChainStartMm(maStlWall2dToolActiveGroupId);
        if (!first) return true;
        maStlWall2dToolCommitWallSegmentMm(maStlLineToolPoint1Mm, first);
        maStlStopLineToolModesToolbar(false);
        maStlWall2dToolResumeState = null;
        return true;
    }

    function maStlWall2dToolCaptureResumeState() {
        const gid = maStlWall2dToolActiveGroupId;
        if (gid == null || !maStlWall2dToolGroupHasAxisSegments(gid)) return;
        let pointMm = maStlWall2dToolFindGroupChainEndMm(gid);
        if (!pointMm) {
            pointMm = {
                x: maStlLineToolPoint1Mm.x,
                y: maStlLineToolPoint1Mm.y,
                z: maStlLineToolPoint1Mm.z,
            };
        }
        maStlWall2dToolResumeState = {
            wallGroupId: gid,
            pointMm: maStlDesing2ClonePlanPointMm(pointMm),
        };
    }

    /** Tras undo/redo: recalcula punto de reanudación del último muro en escena. */
    function maStlWall2dToolRefreshResumeStateFromScene() {
        if (maStlDesing2LastToolbarCommandId !== 'ma-stl-tool-wall-2d' || !maStlUserLinesGroup) {
            return;
        }
        let maxGid = 0;
        let hasAxis = false;
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const ud = ch[i].userData && ch[i].userData.maStlUserPlanLine;
            if (!ud || ud.wallRole !== 'axis' || ud.wallGroupId == null) continue;
            hasAxis = true;
            if (ud.wallGroupId > maxGid) maxGid = ud.wallGroupId;
        }
        if (!hasAxis) {
            maStlWall2dToolResumeState = null;
            return;
        }
        const endMm = maStlWall2dToolFindGroupChainEndMm(maxGid);
        if (!endMm) {
            maStlWall2dToolResumeState = null;
            return;
        }
        maStlWall2dToolResumeState = {
            wallGroupId: maxGid,
            pointMm: endMm,
        };
    }

    /** Redo con muro 2D: reanuda dibujo desde el último vértice restaurado. */
    function maStlWall2dToolMaybeAutoResumeAfterRedo() {
        if (maStlDesing2LastToolbarCommandId !== 'ma-stl-tool-wall-2d') return;
        if (maStlIsDesing2FloorDrawToolActive()) return;
        maStlWall2dToolRefreshResumeStateFromScene();
        if (!maStlWall2dToolResumeState) return;
        maStlStartWall2dToolModesToolbar({ resume: true });
    }

    function maStlStopWall2dToolModesToolbar(deferOrbitUnlock) {
        void deferOrbitUnlock;
        if (!maStlIsWall2dToolActive()) return;
        maStlStopLineToolModesToolbar(false);
        maStlWall2dToolHideFaceRubberBands();
        maStlSyncLineToolToggleBtnUi();
        maStlLineToolPickCursorSync();
    }

    /** Mitad del espesor total del muro (mm escena) desde Configuración X/Y. */
    function maStlWall2dToolThicknessHalfMm() {
        applyDesing2ConfigWallWidthsFromInputs();
        const totalMm = (desing2EnvWallWidthXMm + desing2EnvWallWidthYMm) * 0.5;
        return Math.max(totalMm * 0.5, maStlUserFloorSegmentMinMm() * 0.05);
    }

    /** @returns {THREE.Line2[]} */
    function maStlUserFloorPlanLinesInWallGroup(wallGroupId) {
        const out = [];
        if (wallGroupId == null || !maStlUserLinesGroup) return out;
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const ln = ch[i];
            if (!maStlIsUserFloorPlanLineObject(ln)) continue;
            const ud = ln.userData && ln.userData.maStlUserPlanLine;
            if (ud && ud.wallGroupId === wallGroupId) out.push(ln);
        }
        return out;
    }

    /** Todas las líneas del mismo muro 2D; si no hay grupo, solo `line`. */
    function maStlResolveWallGroupLinesForLine(line) {
        if (!line || !maStlIsUserFloorPlanLineObject(line)) return [];
        const ud = line.userData && line.userData.maStlUserPlanLine;
        if (!ud || ud.wallGroupId == null) return [line];
        const group = maStlUserFloorPlanLinesInWallGroup(ud.wallGroupId);
        return group.length > 0 ? group : [line];
    }

    /**
     * Paquete indivisible de un tramo de muro 2D: eje + sus dos caras.
     * El eje no se selecciona directamente, pero una operación sobre cualquier cara
     * debe afectar a todo el tramo asociado.
     */
    function maStlResolveWallSegmentLinesForLine(line) {
        if (!line || !maStlIsUserFloorPlanLineObject(line)) return [];
        const ud = line.userData && line.userData.maStlUserPlanLine;
        if (!ud || ud.wallGroupId == null || !ud.wallRole) return [line];
        let axisLine = null;
        if (ud.wallRole === 'axis') {
            axisLine = line;
        } else if (ud.wallRole === 'face' && ud.linkOffsetFromLineId != null) {
            axisLine = maStlWall2dToolFindLineByPlanId(ud.linkOffsetFromLineId);
        }
        if (!axisLine) return [line];
        const axisUd = axisLine.userData && axisLine.userData.maStlUserPlanLine;
        if (!axisUd || axisUd.id == null) return [line];
        const out = [axisLine];
        const faces = maStlWall2dToolFindFaceLinesForCenterId(axisUd.id);
        for (let fi = 0; fi < faces.length; fi++) {
            if (faces[fi] && out.indexOf(faces[fi]) < 0) out.push(faces[fi]);
        }
        return out.length > 0 ? out : [line];
    }

    /** @param {number} lineId */
    function maStlWall2dToolFindLineByPlanId(lineId) {
        if (lineId == null || !maStlUserLinesGroup) return null;
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const ln = ch[i];
            if (!maStlIsUserFloorPlanLineObject(ln)) continue;
            const ud = ln.userData && ln.userData.maStlUserPlanLine;
            if (ud && ud.id === lineId) return ln;
        }
        return null;
    }

    /** @param {number} centerLineId */
    function maStlWall2dToolFindFaceLinesForCenterId(centerLineId) {
        const out = [];
        if (centerLineId == null || !maStlUserLinesGroup) return out;
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const ln = ch[i];
            if (!maStlIsUserFloorPlanLineObject(ln)) continue;
            const ud = ln.userData && ln.userData.maStlUserPlanLine;
            if (ud && ud.wallRole === 'face' && ud.linkOffsetFromLineId === centerLineId) {
                out.push(ln);
            }
        }
        return out;
    }

    /**
     * Tramo de eje anterior del mismo muro que comparte vértice con `ptMm` (cambio de sentido).
     * @returns {THREE.Line2|null}
     */
    function maStlWall2dToolFindCenterNeighborAtPointMm(ptMm, wallGroupId) {
        if (!ptMm || wallGroupId == null || !maStlUserLinesGroup) return null;
        const eps = maStlUserFloorLineMergeEndpointEpsMm();
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const ln = ch[i];
            if (!maStlIsUserFloorPlanLineObject(ln)) continue;
            const ud = ln.userData && ln.userData.maStlUserPlanLine;
            if (!ud || ud.wallRole !== 'axis' || ud.wallGroupId !== wallGroupId) continue;
            if (!ud.p1Mm || !ud.p2Mm) continue;
            if (
                maStlUserFloorPlanPointNearXzMm(ud.p1Mm, ptMm, eps) ||
                maStlUserFloorPlanPointNearXzMm(ud.p2Mm, ptMm, eps)
            ) {
                return ln;
            }
        }
        return null;
    }

    /** @param {number} centerLineId @param {number} sideSign */
    function maStlWall2dToolFindFaceForCenterAndSide(centerLineId, sideSign) {
        const faces = maStlWall2dToolFindFaceLinesForCenterId(centerLineId);
        const want = sideSign === -1 ? -1 : 1;
        for (let fi = 0; fi < faces.length; fi++) {
            const fUd = faces[fi].userData && faces[fi].userData.maStlUserPlanLine;
            if (!fUd) continue;
            const got = fUd.numberWallFaceSideSign === -1 ? -1 : 1;
            if (got === want) return faces[fi];
        }
        return null;
    }

    function maStlWall2dToolCollectAllAxisLines() {
        const out = [];
        if (!maStlUserLinesGroup) return out;
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const ln = ch[i];
            if (!maStlIsUserFloorPlanLineObject(ln)) continue;
            const ud = ln.userData && ln.userData.maStlUserPlanLine;
            if (ud && ud.wallRole === 'axis') out.push(ln);
        }
        return out;
    }

    /** Punto offset de cara ± en un punto del eje (no necesariamente extremo). */
    function maStlWall2dToolFaceOffsetPointAtAxisPointMm(axisUd, ptOnAxis, halfT, sideSign) {
        if (!axisUd || !ptOnAxis || !(halfT > 0)) return null;
        const u = maStlUserFloorPlanLineDirUnitXz(axisUd);
        if (!u) return null;
        const n = maStlOffsetToolNormalFromDirSignMm(u.ux, u.uz, sideSign);
        return {
            x: ptOnAxis.x + n.nx * halfT,
            y: ptOnAxis.y,
            z: ptOnAxis.z + n.nz * halfT,
        };
    }

    /**
     * Tolerancia de agrupación en vértices de eje (uniones L/T).
     * Las caras están a ~espesor/2 del eje; sin este margen los ingletes no se aplican.
     */
    function maStlWall2dToolJunctionClusterEpsMm() {
        const halfT = maStlWall2dToolThicknessHalfMm();
        return Math.max(
            maStlUserFloorLineMergeEndpointEpsMm(),
            halfT * 1.2,
            MA_STL_WALL_DIM_LENGTH_VALUE_TOL_MM
        );
    }

    /**
     * Proyecta `p` sobre el cuerpo del eje más cercano (unión T) si está a ≤ tolerancia snap.
     * @returns {boolean}
     */
    function maStlWall2dToolSnapPlanPointToNearestAxisBodyMm(p) {
        if (!p || !maStlUserLinesGroup) return false;
        const eps = maStlUserFloorLineMergeEndpointEpsMm();
        const distTol = Math.max(
            MA_STL_USER_FLOOR_LINE_VERTEX_SNAP_MM,
            maStlWall2dToolJunctionClusterEpsMm()
        );
        const minSeg = maStlUserFloorSegmentMinMm();
        const axes = maStlWall2dToolCollectAllAxisLines();
        let bestDist = Infinity;
        let bestX = p.x;
        let bestY = p.y;
        let bestZ = p.z;
        for (let ai = 0; ai < axes.length; ai++) {
            const ud = axes[ai].userData && axes[ai].userData.maStlUserPlanLine;
            if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
            if (maStlUserFloorPlanPointNearXzMm(ud.p1Mm, p, eps)) continue;
            if (maStlUserFloorPlanPointNearXzMm(ud.p2Mm, p, eps)) continue;
            const proj = maStlProjectPointOntoUserFloorSegmentBodyXzMm(
                p,
                ud.p1Mm,
                ud.p2Mm,
                _maStlUserFloorSegmentBodyProj
            );
            if (!proj || proj.distXZ > distTol) continue;
            const span = Math.hypot(ud.p2Mm.x - ud.p1Mm.x, ud.p2Mm.z - ud.p1Mm.z);
            const minT = span > minSeg ? minSeg / span : 0.05;
            if (proj.t <= minT || proj.t >= 1 - minT) continue;
            if (proj.distXZ < bestDist) {
                bestDist = proj.distXZ;
                bestX = _maStlUserFloorSegmentBodyProj.x;
                bestY = _maStlUserFloorSegmentBodyProj.y;
                bestZ = _maStlUserFloorSegmentBodyProj.z;
            }
        }
        if (!Number.isFinite(bestDist) || bestDist === Infinity) return false;
        p.x = bestX;
        p.y = bestY;
        p.z = bestZ;
        return true;
    }

    /**
     * Intersección de dos segmentos en planta XZ (cuerpo interior de ambos).
     * @returns {{ x: number, y: number, z: number, tSeg: number, tAxis: number }|null}
     */
    function maStlWall2dToolIntersectSegmentPairInteriorMm(segA1, segA2, axisP1, axisP2, minAxisT, maxAxisT) {
        if (!segA1 || !segA2 || !axisP1 || !axisP2) return null;
        const dSegX = segA2.x - segA1.x;
        const dSegZ = segA2.z - segA1.z;
        const dAxisX = axisP2.x - axisP1.x;
        const dAxisZ = axisP2.z - axisP1.z;
        const hit = maStlPlanXzInfiniteLinesIntersectMm(
            segA1,
            dSegX,
            dSegZ,
            axisP1,
            dAxisX,
            dAxisZ
        );
        if (!hit) return null;
        const segLen2 = dSegX * dSegX + dSegZ * dSegZ;
        const axisLen2 = dAxisX * dAxisX + dAxisZ * dAxisZ;
        if (segLen2 < 1e-12 || axisLen2 < 1e-12) return null;
        const tSeg = ((hit.x - segA1.x) * dSegX + (hit.z - segA1.z) * dSegZ) / segLen2;
        const tAxis = ((hit.x - axisP1.x) * dAxisX + (hit.z - axisP1.z) * dAxisZ) / axisLen2;
        const slack = 1e-4;
        if (tSeg < -slack || tSeg > 1 + slack) return null;
        if (tAxis < minAxisT - slack || tAxis > maxAxisT + slack) return null;
        return {
            x: hit.x,
            y: segA1.y + (segA2.y - segA1.y) * THREE.MathUtils.clamp(tSeg, 0, 1),
            z: hit.z,
            tSeg: tSeg,
            tAxis: tAxis,
        };
    }

    /** @param {Array<{ x: number, y: number, z: number }>} outPts */
    function maStlWall2dToolCollectTJunctionSplitCandidatesMm(points, segA, segB, outPts) {
        if (!outPts) return;
        const clusterEps = maStlWall2dToolJunctionClusterEpsMm();
        const pushUnique = function (pt) {
            if (!pt || !Number.isFinite(pt.x) || !Number.isFinite(pt.z)) return;
            for (let i = 0; i < outPts.length; i++) {
                if (maStlUserFloorPlanPointNearXzMm(outPts[i], pt, clusterEps)) return;
            }
            outPts.push({ x: pt.x, y: pt.y, z: pt.z });
        };
        if (points) {
            for (let pi = 0; pi < points.length; pi++) {
                pushUnique(points[pi]);
            }
        }
        if (!segA || !segB) return;
        const minSeg = maStlUserFloorSegmentMinMm();
        const axes = maStlWall2dToolCollectAllAxisLines();
        for (let ai = 0; ai < axes.length; ai++) {
            const ud = axes[ai].userData && axes[ai].userData.maStlUserPlanLine;
            if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
            const span = Math.hypot(ud.p2Mm.x - ud.p1Mm.x, ud.p2Mm.z - ud.p1Mm.z);
            const minT = span > minSeg ? minSeg / span : 0.05;
            const hit = maStlWall2dToolIntersectSegmentPairInteriorMm(
                segA,
                segB,
                ud.p1Mm,
                ud.p2Mm,
                minT,
                1 - minT
            );
            if (hit) {
                pushUnique(hit);
            }
        }
    }

    /**
     * Parte un eje en un punto interior (unión en T): acorta el tramo y crea cola J→P2.
     * @returns {boolean}
     */
    function maStlWall2dToolSplitAxisAtInteriorPointMm(axisLine, splitPtMm) {
        const ud = axisLine.userData && axisLine.userData.maStlUserPlanLine;
        if (!ud || ud.wallRole !== 'axis' || !ud.p1Mm || !ud.p2Mm) return false;
        const halfT = maStlWall2dToolThicknessHalfMm();
        const wallGroupId = ud.wallGroupId;
        const oldP2 = maStlDesing2ClonePlanPointMm(ud.p2Mm);
        const J = maStlDesing2ClonePlanPointMm(splitPtMm);
        J.y = ud.p1Mm.y;

        ud.p2Mm.x = J.x;
        ud.p2Mm.y = J.y;
        ud.p2Mm.z = J.z;
        maStlWallLineEnsureAttrs(ud);
        maStlApplyUserFloorLineSegmentGeometryFromMm(axisLine);
        maStlUserFloorLineSyncAxisDashDistances(axisLine);

        const faces = maStlWall2dToolFindFaceLinesForCenterId(ud.id);
        for (let fi = 0; fi < faces.length; fi++) {
            const faceLine = faces[fi];
            const fUd = faceLine.userData && faceLine.userData.maStlUserPlanLine;
            if (!fUd) continue;
            const sideSign = fUd.numberWallFaceSideSign === -1 ? -1 : 1;
            const fj = maStlWall2dToolFaceOffsetPointAtAxisPointMm(ud, J, halfT, sideSign);
            if (!fj) continue;
            const key = maStlWall2dToolFaceEndpointKeyNearVertexMm(fUd, oldP2);
            maStlWall2dToolSetFaceEndpointMm(fUd, key, fj);
            maStlWallLineEnsureAttrs(fUd);
            maStlApplyUserFloorLineSegmentGeometryFromMm(faceLine);
        }

        const wallId = ud.wallId != null ? ud.wallId : wallGroupId;
        const wallExtras = {
            wallGroupId: wallGroupId,
            wallId: wallId,
            wallRole: 'axis',
            skipCollinearMerge: true,
        };
        const tailAxis = maStlWall2dToolAddSegmentMm(J, oldP2, wallExtras, true);
        if (!tailAxis) return true;
        const tailUd = tailAxis.userData && tailAxis.userData.maStlUserPlanLine;
        if (!tailUd || tailUd.id == null) return true;
        for (let si = 0; si < 2; si++) {
            const sideSign = si === 0 ? 1 : -1;
            const ends = maStlWall2dToolParallelFaceEndpointsWithMitersMm(tailAxis, halfT, sideSign);
            if (!ends) continue;
            maStlWall2dToolAddSegmentMm(
                ends.p1,
                ends.p2,
                {
                    wallGroupId: wallGroupId,
                    wallId: wallId,
                    wallRole: 'face',
                    linkOffsetFromLineId: tailUd.id,
                    numberOffsetMm: halfT,
                    numberWallFaceSideSign: sideSign,
                    skipCollinearMerge: true,
                },
                true
            );
        }
        maStlWall2dToolRefactorCenterFaceOffsets(axisLine, halfT, wallGroupId);
        return true;
    }

    /** Si un extremo cae sobre el cuerpo de otro eje, parte el muro atravesado (unión T). */
    function maStlWall2dToolSplitAxesAtInteriorHitsMm(points, segA, segB) {
        if (!maStlUserLinesGroup) return;
        const eps = maStlUserFloorLineMergeEndpointEpsMm();
        const interiorDistTol = Math.max(
            eps,
            maStlWall2dToolJunctionClusterEpsMm(),
            MA_STL_USER_FLOOR_LINE_VERTEX_SNAP_MM * 0.25
        );
        const minSeg = maStlUserFloorSegmentMinMm();
        const candidates = [];
        maStlWall2dToolCollectTJunctionSplitCandidatesMm(points, segA, segB, candidates);
        if (!candidates.length) return;
        let changed = true;
        while (changed) {
            changed = false;
            const axes = maStlWall2dToolCollectAllAxisLines();
            for (let pi = 0; pi < candidates.length; pi++) {
                const pt = candidates[pi];
                if (!pt) continue;
                for (let ai = 0; ai < axes.length; ai++) {
                    const axisLine = axes[ai];
                    const ud = axisLine.userData && axisLine.userData.maStlUserPlanLine;
                    if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
                    if (
                        maStlUserFloorPlanPointNearXzMm(ud.p1Mm, pt, eps) ||
                        maStlUserFloorPlanPointNearXzMm(ud.p2Mm, pt, eps)
                    ) {
                        continue;
                    }
                    const proj = maStlProjectPointOntoUserFloorSegmentBodyXzMm(
                        pt,
                        ud.p1Mm,
                        ud.p2Mm,
                        _maStlUserFloorSegmentBodyProj
                    );
                    if (!proj || proj.distXZ > interiorDistTol) continue;
                    const span = Math.hypot(ud.p2Mm.x - ud.p1Mm.x, ud.p2Mm.z - ud.p1Mm.z);
                    const minT = span > minSeg ? minSeg / span : 0.05;
                    if (proj.t <= minT || proj.t >= 1 - minT) continue;
                    if (
                        maStlWall2dToolSplitAxisAtInteriorPointMm(
                            axisLine,
                            _maStlUserFloorSegmentBodyProj
                        )
                    ) {
                        changed = true;
                        break;
                    }
                }
                if (changed) break;
            }
        }
    }

    /**
     * Parte todos los ejes que se cruzan por el cuerpo (caso +): ambos ejes deben
     * tener un extremo en el cruce para que el refactor pueda clasificar `Cross`.
     */
    function maStlWall2dToolSplitAllAxisInteriorCrossingsMm() {
        if (!maStlUserLinesGroup) return false;
        const endpointTol = Math.max(
            maStlUserFloorLineMergeEndpointEpsMm(),
            maStlWall2dToolJunctionClusterEpsMm()
        );
        const minSeg = maStlUserFloorSegmentMinMm();
        let changedAny = false;
        let changed = true;
        let guard = 0;
        while (changed && guard++ < 64) {
            changed = false;
            const axes = maStlWall2dToolCollectAllAxisLines();
            for (let i = 0; i < axes.length; i++) {
                const endpointAxis = axes[i];
                const endpointUd =
                    endpointAxis &&
                    endpointAxis.userData &&
                    endpointAxis.userData.maStlUserPlanLine;
                if (!endpointUd || !endpointUd.p1Mm || !endpointUd.p2Mm) continue;
                const endpointPts = [endpointUd.p1Mm, endpointUd.p2Mm];
                for (let pi = 0; pi < endpointPts.length; pi++) {
                    const pt = endpointPts[pi];
                    for (let j = 0; j < axes.length; j++) {
                        const bodyAxis = axes[j];
                        if (bodyAxis === endpointAxis) continue;
                        const bodyUd =
                            bodyAxis &&
                            bodyAxis.userData &&
                            bodyAxis.userData.maStlUserPlanLine;
                        if (!bodyUd || !bodyUd.p1Mm || !bodyUd.p2Mm) continue;
                        if (maStlUserFloorPlanLinesCollinearParallelXz(endpointUd, bodyUd)) continue;
                        if (
                            maStlUserFloorPlanPointNearXzMm(bodyUd.p1Mm, pt, endpointTol) ||
                            maStlUserFloorPlanPointNearXzMm(bodyUd.p2Mm, pt, endpointTol)
                        ) {
                            continue;
                        }
                        const proj = maStlProjectPointOntoUserFloorSegmentBodyXzMm(
                            pt,
                            bodyUd.p1Mm,
                            bodyUd.p2Mm,
                            _maStlUserFloorSegmentBodyProj
                        );
                        if (!proj || proj.distXZ > endpointTol) continue;
                        const span = Math.hypot(
                            bodyUd.p2Mm.x - bodyUd.p1Mm.x,
                            bodyUd.p2Mm.z - bodyUd.p1Mm.z
                        );
                        const minT = span > minSeg ? minSeg / span : 0.05;
                        if (proj.t <= minT || proj.t >= 1 - minT) continue;
                        const splitPt = { x: pt.x, y: bodyUd.p1Mm.y, z: pt.z };
                        if (maStlWall2dToolSplitAxisAtInteriorPointMm(bodyAxis, splitPt)) {
                            changed = true;
                            changedAny = true;
                            break;
                        }
                    }
                    if (changed) break;
                }
                if (changed) break;
            }
            if (changed) continue;
            for (let i = 0; i < axes.length; i++) {
                const axisA = axes[i];
                const udA = axisA && axisA.userData && axisA.userData.maStlUserPlanLine;
                if (!udA || !udA.p1Mm || !udA.p2Mm) continue;
                for (let j = i + 1; j < axes.length; j++) {
                    const axisB = axes[j];
                    const udB = axisB && axisB.userData && axisB.userData.maStlUserPlanLine;
                    if (!udB || !udB.p1Mm || !udB.p2Mm) continue;
                    if (maStlUserFloorPlanLinesCollinearParallelXz(udA, udB)) continue;
                    const spanA = Math.hypot(udA.p2Mm.x - udA.p1Mm.x, udA.p2Mm.z - udA.p1Mm.z);
                    const spanB = Math.hypot(udB.p2Mm.x - udB.p1Mm.x, udB.p2Mm.z - udB.p1Mm.z);
                    const minTA = spanA > minSeg ? minSeg / spanA : 0.05;
                    const minTB = spanB > minSeg ? minSeg / spanB : 0.05;
                    const hit = maStlWall2dToolIntersectSegmentPairInteriorMm(
                        udA.p1Mm,
                        udA.p2Mm,
                        udB.p1Mm,
                        udB.p2Mm,
                        minTB,
                        1 - minTB
                    );
                    if (!hit || hit.tSeg <= minTA || hit.tSeg >= 1 - minTA) continue;
                    const splitPtA = { x: hit.x, y: udA.p1Mm.y, z: hit.z };
                    const splitPtB = { x: hit.x, y: udB.p1Mm.y, z: hit.z };
                    const splitA = maStlWall2dToolSplitAxisAtInteriorPointMm(axisA, splitPtA);
                    const splitB =
                        axisB.parent === maStlUserLinesGroup &&
                        maStlWall2dToolSplitAxisAtInteriorPointMm(axisB, splitPtB);
                    if (splitA || splitB) {
                        changed = true;
                        changedAny = true;
                        break;
                    }
                }
                if (changed) break;
            }
        }
        return changedAny;
    }

    /**
     * Vecino de eje en vértice (cualquier muro; no colineal).
     * @returns {{ line: THREE.Line2, ud: *, onA: string, onB: string, uNeighFromV: { ux: number, uz: number } }|null}
     */
    function maStlWall2dToolFindAxisNeighborAtEndpoint(axisLine, endpointKind, wallGroupId) {
        void wallGroupId;
        const neigh = maStlOffsetToolFindNeighborAtEndpoint(axisLine, endpointKind);
        if (!neigh || !neigh.ud || neigh.ud.wallRole !== 'axis') return null;
        return neigh;
    }

    /** Punto de `faceLine` (p1/p2) más cercano a `vertexMm` en planta. */
    function maStlWall2dToolFaceEndpointKeyNearVertexMm(faceUd, vertexMm) {
        if (!faceUd || !faceUd.p1Mm || !faceUd.p2Mm || !vertexMm) return null;
        const junctionEps = maStlWall2dToolJunctionClusterEpsMm();
        const d1 = maStlUserFloorPlanPointDistSqXzMm(faceUd.p1Mm, vertexMm);
        const d2 = maStlUserFloorPlanPointDistSqXzMm(faceUd.p2Mm, vertexMm);
        const j2 = junctionEps * junctionEps;
        if (d1 <= j2 && d2 <= j2) {
            return d1 <= d2 ? 'p1' : 'p2';
        }
        if (d1 <= j2) return 'p1';
        if (d2 <= j2) return 'p2';
        return d1 <= d2 ? 'p1' : 'p2';
    }

    function maStlWall2dToolSetFaceEndpointMm(faceUd, endpointKey, pt) {
        if (!faceUd || !endpointKey || !pt) return;
        const ep = endpointKey === 'p2' ? faceUd.p2Mm : faceUd.p1Mm;
        ep.x = pt.x;
        ep.y = pt.y;
        ep.z = pt.z;
    }

    function maStlWall2dToolAxisEndpointKeyNearVertexMm(axisUd, vertexMm) {
        if (!axisUd || !axisUd.p1Mm || !axisUd.p2Mm || !vertexMm) return null;
        const eps = maStlWall2dToolJunctionClusterEpsMm();
        const d1 = maStlUserFloorPlanPointDistSqXzMm(axisUd.p1Mm, vertexMm);
        const d2 = maStlUserFloorPlanPointDistSqXzMm(axisUd.p2Mm, vertexMm);
        const e2 = eps * eps;
        if (d1 <= e2 && d2 <= e2) return d1 <= d2 ? 'p1' : 'p2';
        if (d1 <= e2) return 'p1';
        if (d2 <= e2) return 'p2';
        return d1 <= d2 ? 'p1' : 'p2';
    }

    /** Dirección desde el vértice de unión hacia el cuerpo real del eje. */
    function maStlWall2dToolDirFromVertexIntoAxisMm(axisUd, endpointKey) {
        const d = maStlUserFloorPlanLineDirUnitXz(axisUd);
        if (!d || !endpointKey) return null;
        if (endpointKey === 'p1') return { ux: d.ux, uz: d.uz };
        return { ux: -d.ux, uz: -d.uz };
    }

    function maStlWall2dToolApplyFaceEndpointMm(faceLine, vertexMm, pt) {
        const faceUd = faceLine && faceLine.userData && faceLine.userData.maStlUserPlanLine;
        if (!faceUd || !pt) return;
        const key = maStlWall2dToolFaceEndpointKeyNearVertexMm(faceUd, vertexMm);
        if (!key) return;
        maStlWall2dToolSetFaceEndpointMm(faceUd, key, pt);
        maStlApplyUserFloorLineSegmentGeometryFromMm(faceLine);
    }

    /**
     * Cierra una T real: dos ejes colineales atravesados + un eje entrante.
     * La cara del muro atravesado por donde entra la rama se abre solo en el ancho de la rama.
     */
    function maStlWall2dToolApplyTJunctionMm(throughA, throughB, branch, vertexMm) {
        if (!throughA || !throughB || !branch || !vertexMm) return false;
        const throughHalfA = maStlWall2dToolAxisHalfThicknessFromAxisUd(throughA);
        const throughHalfB = maStlWall2dToolAxisHalfThicknessFromAxisUd(throughB);
        const branchHalf = maStlWall2dToolAxisHalfThicknessFromAxisUd(branch);
        if (!(throughHalfA > 0) || !(branchHalf > 0)) return false;
        const branchEndKey = maStlWall2dToolAxisEndpointKeyNearVertexMm(branch, vertexMm);
        const throughAEndKey = maStlWall2dToolAxisEndpointKeyNearVertexMm(throughA, vertexMm);
        const throughBEndKey = maStlWall2dToolAxisEndpointKeyNearVertexMm(throughB, vertexMm);
        if (!branchEndKey || !throughAEndKey || !throughBEndKey) return false;
        const uBranchInto = maStlWall2dToolDirFromVertexIntoAxisMm(branch, branchEndKey);
        const uThroughAInto = maStlWall2dToolDirFromVertexIntoAxisMm(throughA, throughAEndKey);
        const uThroughBInto = maStlWall2dToolDirFromVertexIntoAxisMm(throughB, throughBEndKey);
        const uThroughA = maStlUserFloorPlanLineDirUnitXz(throughA);
        if (!uBranchInto || !uThroughAInto || !uThroughBInto || !uThroughA) return false;

        const nearSignA =
            maStlOffsetToolNormalFromDirSignMm(uThroughA.ux, uThroughA.uz, 1).nx * uBranchInto.ux +
                maStlOffsetToolNormalFromDirSignMm(uThroughA.ux, uThroughA.uz, 1).nz * uBranchInto.uz >=
            0
                ? 1
                : -1;
        const throughAFaces = {
            near: maStlWall2dToolFindFaceForCenterAndSide(throughA.id, nearSignA),
            far: maStlWall2dToolFindFaceForCenterAndSide(throughA.id, -nearSignA),
        };
        if (!throughAFaces.near || !throughAFaces.far) return false;

        const nearFaceUdA = throughAFaces.near.userData.maStlUserPlanLine;
        const uNearFaceA = maStlUserFloorPlanLineDirUnitXz(nearFaceUdA);
        const nearAnchorA = maStlWall2dToolFaceOffsetPointAtAxisPointMm(
            throughA,
            vertexMm,
            throughHalfA,
            nearSignA
        );
        if (!uNearFaceA || !nearAnchorA) return false;

        const nearBranchJoints = [];
        for (let si = 0; si < 2; si++) {
            const branchSideSign = si === 0 ? 1 : -1;
            const branchFace = maStlWall2dToolFindFaceForCenterAndSide(branch.id, branchSideSign);
            const branchFaceUd = branchFace && branchFace.userData && branchFace.userData.maStlUserPlanLine;
            const uBranchFace = maStlUserFloorPlanLineDirUnitXz(branchFaceUd);
            const branchAnchor = maStlWall2dToolFaceOffsetPointAtAxisPointMm(
                branch,
                vertexMm,
                branchHalf,
                branchSideSign
            );
            if (!branchFace || !branchFaceUd || !uBranchFace || !branchAnchor) continue;
            const hit = maStlPlanXzInfiniteLinesIntersectMm(
                branchAnchor,
                uBranchFace.ux,
                uBranchFace.uz,
                nearAnchorA,
                uNearFaceA.ux,
                uNearFaceA.uz
            );
            if (!hit) continue;
            maStlWall2dToolApplyFaceEndpointMm(
                branchFace,
                vertexMm,
                { x: hit.x, y: vertexMm.y, z: hit.z }
            );
            nearBranchJoints.push({ x: hit.x, y: vertexMm.y, z: hit.z });
        }
        if (nearBranchJoints.length !== 2) return false;

        const applyThrough = function (axisUd, outDir, axisHalfT) {
            const uAxis = maStlUserFloorPlanLineDirUnitXz(axisUd);
            if (!uAxis || !outDir) return;
            const nearSign =
                maStlOffsetToolNormalFromDirSignMm(uAxis.ux, uAxis.uz, 1).nx * uBranchInto.ux +
                    maStlOffsetToolNormalFromDirSignMm(uAxis.ux, uAxis.uz, 1).nz * uBranchInto.uz >=
                0
                    ? 1
                    : -1;
            let bestJoint = nearBranchJoints[0];
            let bestScore =
                (nearBranchJoints[0].x - vertexMm.x) * outDir.ux +
                (nearBranchJoints[0].z - vertexMm.z) * outDir.uz;
            for (let ji = 1; ji < nearBranchJoints.length; ji++) {
                const score =
                    (nearBranchJoints[ji].x - vertexMm.x) * outDir.ux +
                    (nearBranchJoints[ji].z - vertexMm.z) * outDir.uz;
                if (score > bestScore) {
                    bestScore = score;
                    bestJoint = nearBranchJoints[ji];
                }
            }
            for (let si = 0; si < 2; si++) {
                const sideSign = si === 0 ? 1 : -1;
                const face = maStlWall2dToolFindFaceForCenterAndSide(axisUd.id, sideSign);
                const pt =
                    sideSign === nearSign
                        ? bestJoint
                        : maStlWall2dToolFaceOffsetPointAtAxisPointMm(
                              axisUd,
                              vertexMm,
                              axisHalfT,
                              sideSign
                          );
                maStlWall2dToolApplyFaceEndpointMm(face, vertexMm, pt);
            }
        };

        void throughAEndKey;
        void throughBEndKey;
        applyThrough(throughA, uThroughAInto, throughHalfA);
        applyThrough(throughB, uThroughBInto, throughHalfB);
        return true;
    }

    function maStlWall2dToolWallFaceSideTowardDirMm(axisUd, dir) {
        const u = maStlUserFloorPlanLineDirUnitXz(axisUd);
        if (!u || !dir) return 1;
        const nPos = maStlOffsetToolNormalFromDirSignMm(u.ux, u.uz, 1);
        const nNeg = maStlOffsetToolNormalFromDirSignMm(u.ux, u.uz, -1);
        const dotPos = nPos.nx * dir.ux + nPos.nz * dir.uz;
        const dotNeg = nNeg.nx * dir.ux + nNeg.nz * dir.uz;
        return dotPos >= dotNeg ? 1 : -1;
    }

    function maStlWall2dToolCutAxisFacesAgainstBlockingWallMm(axisUd, endpointKey, blockingAxisUd, vertexMm) {
        if (!axisUd || !blockingAxisUd || !vertexMm || !endpointKey) return false;
        const axisHalfT = maStlWall2dToolAxisHalfThicknessFromAxisUd(axisUd);
        const blockingHalfT = maStlWall2dToolAxisHalfThicknessFromAxisUd(blockingAxisUd);
        if (!(axisHalfT > 0) || !(blockingHalfT > 0)) return false;
        const moveDir = maStlWall2dToolDirFromVertexIntoAxisMm(axisUd, endpointKey);
        const uBlocking = maStlUserFloorPlanLineDirUnitXz(blockingAxisUd);
        if (!moveDir || !uBlocking) return false;
        const blockingSideSign = maStlWall2dToolWallFaceSideTowardDirMm(blockingAxisUd, moveDir);
        const blockingAnchor = maStlWall2dToolFaceOffsetPointAtAxisPointMm(
            blockingAxisUd,
            vertexMm,
            blockingHalfT,
            blockingSideSign
        );
        if (!blockingAnchor) return false;
        let changed = false;
        for (let si = 0; si < 2; si++) {
            const faceSideSign = si === 0 ? 1 : -1;
            const faceLine = maStlWall2dToolFindFaceForCenterAndSide(axisUd.id, faceSideSign);
            const faceUd = faceLine && faceLine.userData && faceLine.userData.maStlUserPlanLine;
            const uFace = maStlUserFloorPlanLineDirUnitXz(faceUd);
            const faceAnchor = maStlWall2dToolFaceOffsetPointAtAxisPointMm(
                axisUd,
                vertexMm,
                axisHalfT,
                faceSideSign
            );
            if (!faceLine || !faceUd || !uFace || !faceAnchor) continue;
            const hit = maStlPlanXzInfiniteLinesIntersectMm(
                faceAnchor,
                uFace.ux,
                uFace.uz,
                blockingAnchor,
                uBlocking.ux,
                uBlocking.uz
            );
            if (!hit) continue;
            maStlWall2dToolApplyFaceEndpointMm(faceLine, vertexMm, {
                x: hit.x,
                y: vertexMm.y,
                z: hit.z,
            });
            changed = true;
        }
        return changed;
    }

    function maStlWall2dToolApplyCrossJunctionMm(axisA1, axisA2, axisB1, axisB2, vertexMm) {
        if (!axisA1 || !axisA2 || !axisB1 || !axisB2 || !vertexMm) return false;
        const pairs = [
            { axis: axisA1, blocker: axisB1 },
            { axis: axisA2, blocker: axisB1 },
            { axis: axisB1, blocker: axisA1 },
            { axis: axisB2, blocker: axisA1 },
        ];
        let changed = false;
        for (let i = 0; i < pairs.length; i++) {
            const endpointKey = maStlWall2dToolAxisEndpointKeyNearVertexMm(pairs[i].axis, vertexMm);
            if (!endpointKey) continue;
            if (
                maStlWall2dToolCutAxisFacesAgainstBlockingWallMm(
                    pairs[i].axis,
                    endpointKey,
                    pairs[i].blocker,
                    vertexMm
                )
            ) {
                changed = true;
            }
        }
        return changed;
    }

    function maStlWall2dToolTryApplyCrossJunctionMm(axes, vertexMm) {
        if (!axes || axes.length < 4 || !vertexMm) return false;
        for (let i = 0; i < axes.length; i++) {
            for (let j = i + 1; j < axes.length; j++) {
                const a1 = axes[i];
                const a2 = axes[j];
                if (!maStlUserFloorPlanLinesCollinearParallelXz(a1, a2)) continue;
                const a1End = maStlWall2dToolAxisEndpointKeyNearVertexMm(a1, vertexMm);
                const a2End = maStlWall2dToolAxisEndpointKeyNearVertexMm(a2, vertexMm);
                const a1Into = maStlWall2dToolDirFromVertexIntoAxisMm(a1, a1End);
                const a2Into = maStlWall2dToolDirFromVertexIntoAxisMm(a2, a2End);
                if (!a1Into || !a2Into || a1Into.ux * a2Into.ux + a1Into.uz * a2Into.uz > -0.85) continue;
                for (let k = 0; k < axes.length; k++) {
                    if (k === i || k === j) continue;
                    for (let l = k + 1; l < axes.length; l++) {
                        if (l === i || l === j) continue;
                        const b1 = axes[k];
                        const b2 = axes[l];
                        if (!maStlUserFloorPlanLinesCollinearParallelXz(b1, b2)) continue;
                        if (maStlUserFloorPlanLinesCollinearParallelXz(a1, b1)) continue;
                        const b1End = maStlWall2dToolAxisEndpointKeyNearVertexMm(b1, vertexMm);
                        const b2End = maStlWall2dToolAxisEndpointKeyNearVertexMm(b2, vertexMm);
                        const b1Into = maStlWall2dToolDirFromVertexIntoAxisMm(b1, b1End);
                        const b2Into = maStlWall2dToolDirFromVertexIntoAxisMm(b2, b2End);
                        if (!b1Into || !b2Into || b1Into.ux * b2Into.ux + b1Into.uz * b2Into.uz > -0.85) continue;
                        return maStlWall2dToolApplyCrossJunctionMm(a1, a2, b1, b2, vertexMm);
                    }
                }
            }
        }
        return false;
    }

    function maStlWall2dToolRefactorTJunctionsFromBucket(bucket) {
        if (!bucket) return;
        for (const bkey in bucket) {
            const junction = bucket[bkey];
            if (!junction || !junction.axes || junction.axes.length < 3) continue;
            const axes = junction.axes.map(function (entry) {
                return entry && entry.axisUd;
            }).filter(Boolean);
            if (maStlWall2dToolTryApplyCrossJunctionMm(axes, junction.vertexMm)) {
                continue;
            }
            for (let i = 0; i < axes.length; i++) {
                for (let j = i + 1; j < axes.length; j++) {
                    const a = axes[i];
                    const b = axes[j];
                    if (!maStlUserFloorPlanLinesCollinearParallelXz(a, b)) continue;
                    const aEnd = maStlWall2dToolAxisEndpointKeyNearVertexMm(a, junction.vertexMm);
                    const bEnd = maStlWall2dToolAxisEndpointKeyNearVertexMm(b, junction.vertexMm);
                    const aInto = maStlWall2dToolDirFromVertexIntoAxisMm(a, aEnd);
                    const bInto = maStlWall2dToolDirFromVertexIntoAxisMm(b, bEnd);
                    if (!aInto || !bInto || aInto.ux * bInto.ux + aInto.uz * bInto.uz > -0.85) continue;
                    for (let k = 0; k < axes.length; k++) {
                        if (k === i || k === j) continue;
                        const branch = axes[k];
                        if (maStlUserFloorPlanLinesCollinearParallelXz(branch, a)) continue;
                        maStlWall2dToolApplyTJunctionMm(a, b, branch, junction.vertexMm);
                    }
                }
            }
        }
    }

    /** Inglete cara± de dos ejes que se encuentran en `vertexMm`. */
    function maStlWall2dToolMiterFacePairAtVertexMm(axisUdA, axisUdB, vertexMm) {
        if (!axisUdA || !axisUdB || !vertexMm) return;
        if (maStlUserFloorPlanLinesCollinearParallelXz(axisUdA, axisUdB)) return;
        for (let si = 0; si < 2; si++) {
            const sideSign = si === 0 ? 1 : -1;
            const faceA = maStlWall2dToolFindFaceForCenterAndSide(axisUdA.id, sideSign);
            const faceB = maStlWall2dToolFindFaceForCenterAndSide(axisUdB.id, sideSign);
            if (!faceA || !faceB) continue;
            const fUdA = faceA.userData.maStlUserPlanLine;
            const fUdB = faceB.userData.maStlUserPlanLine;
            const uA = maStlUserFloorPlanLineDirUnitXz(fUdA);
            const uB = maStlUserFloorPlanLineDirUnitXz(fUdB);
            if (!uA || !uB) continue;
            const keyA = maStlWall2dToolFaceEndpointKeyNearVertexMm(fUdA, vertexMm);
            const keyB = maStlWall2dToolFaceEndpointKeyNearVertexMm(fUdB, vertexMm);
            if (!keyA || !keyB) continue;
            const pA = keyA === 'p2' ? fUdA.p2Mm : fUdA.p1Mm;
            const pB = keyB === 'p2' ? fUdB.p2Mm : fUdB.p1Mm;
            const hit = maStlPlanXzInfiniteLinesIntersectMm(
                pA,
                uA.ux,
                uA.uz,
                pB,
                uB.ux,
                uB.uz
            );
            if (!hit) continue;
            const joint = { x: hit.x, y: vertexMm.y, z: hit.z };
            maStlWall2dToolSetFaceEndpointMm(fUdA, keyA, joint);
            maStlWall2dToolSetFaceEndpointMm(fUdB, keyB, joint);
            maStlApplyUserFloorLineSegmentGeometryFromMm(faceA);
            maStlApplyUserFloorLineSegmentGeometryFromMm(faceB);
        }
    }

    /**
     * Cierra esquinas y uniones entre muros: ingletes en todos los vértices de eje compartidos
     * (incluye muros distintos y uniones en L/T tras partir el tramo atravesado).
     */
    function maStlWall2dToolRefactorAllWallJunctionsMm() {
        if (!maStlUserLinesGroup) return;
        const bucketEps = maStlWall2dToolJunctionClusterEpsMm();
        const axes = maStlWall2dToolCollectAllAxisLines();
        const bucket = Object.create(null);
        for (let ai = 0; ai < axes.length; ai++) {
            const axisLine = axes[ai];
            const axisUd = axisLine.userData && axisLine.userData.maStlUserPlanLine;
            if (!axisUd || !axisUd.p1Mm || !axisUd.p2Mm) continue;
            const ends = ['p1', 'p2'];
            for (let ei = 0; ei < ends.length; ei++) {
                const vertexMm = ends[ei] === 'p1' ? axisUd.p1Mm : axisUd.p2Mm;
                const key =
                    Math.round(vertexMm.x / bucketEps) +
                    '|' +
                    Math.round(vertexMm.z / bucketEps);
                if (!bucket[key]) {
                    bucket[key] = { vertexMm: vertexMm, axes: [] };
                }
                bucket[key].axes.push({ axisUd: axisUd });
            }
        }
        const processedPairs = Object.create(null);
        for (const bkey in bucket) {
            const junction = bucket[bkey];
            if (!junction || junction.axes.length < 2) continue;
            const vertexMm = junction.vertexMm;
            for (let i = 0; i < junction.axes.length; i++) {
                for (let j = i + 1; j < junction.axes.length; j++) {
                    const udA = junction.axes[i].axisUd;
                    const udB = junction.axes[j].axisUd;
                    if (!udA || !udB || udA.id == null || udB.id == null) continue;
                    const pairKey =
                        udA.id < udB.id
                            ? udA.id + '|' + udB.id + '|' + bkey
                            : udB.id + '|' + udA.id + '|' + bkey;
                    if (processedPairs[pairKey]) continue;
                    processedPairs[pairKey] = true;
                    maStlWall2dToolMiterFacePairAtVertexMm(udA, udB, vertexMm);
                }
            }
        }
        maStlWall2dToolRefactorTJunctionsFromBucket(bucket);
    }

    /**
     * Cierra caras interior/exterior en esquinas del grupo (delega en refactor global de uniones).
     */
    function maStlWall2dToolRefactorWallGroupCornersMm(wallGroupId) {
        void wallGroupId;
        maStlWall2dToolRefactorAllWallJunctionsMm();
    }

    /** Recalcula caras paralelas al eje; luego cierra esquinas del grupo. */
    function maStlWall2dToolRefactorCenterFaceOffsets(centerLine, halfT, wallGroupId) {
        if (!centerLine || !(halfT > 0)) return;
        const ud = centerLine.userData && centerLine.userData.maStlUserPlanLine;
        if (!ud || ud.wallRole !== 'axis' || ud.id == null) return;
        const faces = maStlWall2dToolFindFaceLinesForCenterId(ud.id);
        for (let fi = 0; fi < faces.length; fi++) {
            const faceLine = faces[fi];
            const fUd = faceLine.userData && faceLine.userData.maStlUserPlanLine;
            if (!fUd) continue;
            const sideSign = fUd.numberWallFaceSideSign === -1 ? -1 : 1;
            const ends = maStlWall2dToolParallelFaceEndpointsWithMitersMm(
                centerLine,
                halfT,
                sideSign
            );
            if (!ends) continue;
            fUd.p1Mm.x = ends.p1.x;
            fUd.p1Mm.y = ends.p1.y;
            fUd.p1Mm.z = ends.p1.z;
            fUd.p2Mm.x = ends.p2.x;
            fUd.p2Mm.y = ends.p2.y;
            fUd.p2Mm.z = ends.p2.z;
            maStlApplyUserFloorLineSegmentGeometryFromMm(faceLine);
        }
        if (wallGroupId != null) {
            maStlWall2dToolRefactorWallGroupCornersMm(wallGroupId);
        }
    }

    /**
     * Offset de cara de muro con inglete en vértices (interior **y** exterior; sin filtro inward).
     * @returns {{ p1: { x: number, y: number, z: number }, p2: { x: number, y: number, z: number } }|null}
     */
    function maStlWall2dToolParallelFaceEndpointsWithMitersMm(sourceLine, offsetMm, sideSign) {
        if (!sourceLine || !maStlIsUserFloorPlanLineObject(sourceLine)) return null;
        const ud = sourceLine.userData && sourceLine.userData.maStlUserPlanLine;
        if (!ud || !ud.p1Mm || !ud.p2Mm || ud.wallRole !== 'axis') return null;
        const uLineA = maStlUserFloorPlanLineDirUnitXz(ud);
        if (!uLineA) return null;
        const ends = maStlOffsetToolParallelEndpointsMm(ud.p1Mm, ud.p2Mm, offsetMm, sideSign);
        if (!ends) return null;
        const parallelP1 = { x: ends.p1.x, y: ends.p1.y, z: ends.p1.z };
        const parallelP2 = { x: ends.p2.x, y: ends.p2.y, z: ends.p2.z };
        const srcLenMm = uLineA.lenMm;
        const wallGroupId = ud.wallGroupId;
        const corners = [
            { endpointKind: 'p1', vertexMm: ud.p1Mm, outKey: 'p1', parallelAtCorner: parallelP1 },
            { endpointKind: 'p2', vertexMm: ud.p2Mm, outKey: 'p2', parallelAtCorner: parallelP2 },
        ];
        for (let ci = 0; ci < corners.length; ci++) {
            const corner = corners[ci];
            const neigh =
                wallGroupId != null
                    ? maStlWall2dToolFindAxisNeighborAtEndpoint(
                          sourceLine,
                          corner.endpointKind,
                          wallGroupId
                      )
                    : maStlOffsetToolFindNeighborAtEndpoint(sourceLine, corner.endpointKind);
            if (!neigh) continue;
            const uOutwardA = maStlUserFloorPlanLineOutwardDirUnitXz(ud, corner.endpointKind);
            const uLineB = maStlUserFloorPlanLineDirUnitXz(neigh.ud);
            if (!uOutwardA || !uLineB) continue;
            let committedUd = null;
            let committedULine = uLineB;
            if (wallGroupId != null && neigh.ud.id != null) {
                const committedFace = maStlWall2dToolFindFaceForCenterAndSide(neigh.ud.id, sideSign);
                if (committedFace) {
                    committedUd = committedFace.userData.maStlUserPlanLine;
                    const uCommitted = maStlUserFloorPlanLineDirUnitXz(committedUd);
                    if (uCommitted) committedULine = uCommitted;
                }
            } else {
                const committed = maStlOffsetToolFindCommittedOffsetOfNeighborMm(
                    sourceLine,
                    neigh.ud,
                    corner.vertexMm,
                    offsetMm
                );
                if (committed) {
                    committedUd = committed.ud;
                    committedULine = committed.uLine;
                }
            }
            const miter = maStlOffsetToolMiterPointAtCornerMm(
                corner.vertexMm,
                uLineA,
                committedULine,
                uOutwardA,
                neigh.uNeighFromV,
                offsetMm,
                sideSign,
                committedUd
            );
            if (!miter) continue;
            const otherKey = corner.outKey === 'p1' ? 'p2' : 'p1';
            if (
                !maStlOffsetToolAcceptMiterEndpointMm(
                    miter,
                    ends[otherKey],
                    corner.parallelAtCorner,
                    uLineA,
                    ud.p1Mm,
                    srcLenMm,
                    offsetMm,
                    corner.outKey
                )
            ) {
                continue;
            }
            ends[corner.outKey] = miter;
        }
        const minSpan = Math.max(maStlUserFloorSegmentMinMm() * 0.25, 1);
        const span = Math.hypot(ends.p2.x - ends.p1.x, ends.p2.z - ends.p1.z);
        if (!Number.isFinite(span) || span < minSpan) {
            return { p1: parallelP1, p2: parallelP2 };
        }
        return ends;
    }

    /**
     * @param {*} planExtras campos extra en `maStlUserPlanLine` (`wallGroupId`, `wallRole`, …).
     * @returns {THREE.Line2|null}
     */
    function maStlWall2dToolAddSegmentMm(a, b, planExtras, skipUndo) {
        const childCountBefore = maStlUserLinesGroup ? maStlUserLinesGroup.children.length : 0;
        maStlCommitUserPlanLineSegmentMm(a, b, skipUndo, null, planExtras);
        if (!maStlUserLinesGroup) return null;
        for (let ci = childCountBefore; ci < maStlUserLinesGroup.children.length; ci++) {
            const ln = maStlUserLinesGroup.children[ci];
            if (maStlIsUserFloorPlanLineObject(ln)) return ln;
        }
        return null;
    }

    /** Confirma un tramo de muro: eje + dos caras; refactoriza esquinas del tramo anterior. */
    function maStlWall2dToolCommitWallSegmentMm(a, b, skipUndo) {
        const halfT = maStlWall2dToolThicknessHalfMm();
        const wallGroupId = maStlWall2dToolActiveGroupId;
        if (wallGroupId == null) return false;
        const undoBefore =
            !skipUndo && maStlDesingV2Viewer ? maStlDesing2SerializeEditSnapshot() : null;
        const weldEps = Math.max(
            maStlUserFloorLineMergeEndpointEpsMm(),
            MA_STL_WALL_DIM_LENGTH_VALUE_TOL_MM
        );
        maStlQuantizeUserFloorPlanPointToGridMm(a);
        maStlQuantizeUserFloorPlanPointToGridMm(b);
        maStlWall2dToolSnapPlanPointToNearestAxisBodyMm(a);
        maStlWall2dToolSnapPlanPointToNearestAxisBodyMm(b);
        maStlWall2dToolSplitAxesAtInteriorHitsMm([a, b], a, b);
        maStlWeldUserFloorPlanPointToExistingEndpointsMm(a, weldEps);
        maStlWeldUserFloorPlanPointToExistingEndpointsMm(b, weldEps);
        maStlWall2dToolSnapPlanPointToNearestAxisBodyMm(a);
        maStlWall2dToolSnapPlanPointToNearestAxisBodyMm(b);
        const wallExtras = {
            wallGroupId: wallGroupId,
            wallId: wallGroupId,
            wallRole: 'axis',
            skipCollinearMerge: true,
        };
        const centerLine = maStlWall2dToolAddSegmentMm(a, b, wallExtras, true);
        if (!centerLine) return false;
        maStlUserFloorLineSyncAxisDashDistances(centerLine);
        const centerUd = centerLine.userData && centerLine.userData.maStlUserPlanLine;
        if (!centerUd || centerUd.id == null) return false;
        for (let si = 0; si < 2; si++) {
            const sideSign = si === 0 ? 1 : -1;
            const ends = maStlWall2dToolParallelFaceEndpointsWithMitersMm(centerLine, halfT, sideSign);
            if (!ends) continue;
            maStlWall2dToolAddSegmentMm(
                ends.p1,
                ends.p2,
                {
                    wallGroupId: wallGroupId,
                    wallId: wallGroupId,
                    wallRole: 'face',
                    linkOffsetFromLineId: centerUd.id,
                    numberOffsetMm: halfT,
                    numberWallFaceSideSign: sideSign,
                    skipCollinearMerge: true,
                },
                true
            );
        }
        maStlWall2dToolRefactorAllWallJunctionsMm();
        maStlWall2dToolSplitAllAxisInteriorCrossingsMm();
        maStlWall2dToolRefactorAllWallJunctionsMm();
        maStlWeldAllUserFloorLineEndpointsMm();
        maStlWall2dToolRefactorAllWallJunctionsMm();
        maStlWall2dToolResumeState = {
            wallGroupId: wallGroupId,
            pointMm: maStlDesing2ClonePlanPointMm(b),
        };
        maStlReapplyAllUserFloorWallAxisLineStyles();
        if (undoBefore) {
            maStlDesing2PushEditSnapshotUndo(
                'createUserFloorLine',
                undoBefore,
                maStlDesing2SerializeEditSnapshot()
            );
        }
        return true;
    }

    /** Polilínea-muro: tras confirmar un tramo, encadenar desde el nuevo vértice. */
    function maStlWall2dToolAdvanceAfterSegmentMm(end) {
        maStlQuantizeUserFloorPlanPointToGridMm(end);
        maStlLineToolPoint1Mm.set(end.x, end.y, end.z);
        maStlLineToolState = 'picking2';
        maStlResetLineToolDistanceTypingState();
        maStlLineToolRefreshPicking2RubberBand();
        maStlSyncLineToolHud();
        queueMicrotask(function () {
            if (maStlLineToolState !== 'picking2' || !maStlLineToolHudDistanceInput) return;
            try {
                maStlLineToolHudDistanceInput.focus({ preventScroll: true });
            } catch (_e) {
                maStlLineToolHudDistanceInput.focus();
            }
        });
    }

    function maStlWall2dToolEnsureFaceRubberBandLine(which) {
        const isPlus = which === 'plus';
        let line = isPlus ? maStlWall2dToolRubberBandFacePlus : maStlWall2dToolRubberBandFaceMinus;
        if (line) return line;
        const geo = new LineGeometry();
        geo.setPositions(new Float32Array(6));
        const mat = maStlEnsureUserFloorLineMat();
        const previewMat = mat.clone ? mat.clone() : mat;
        if (previewMat.color) previewMat.color.setHex(MA_STL_OFFSET_TOOL_PREVIEW_COLOR_HEX);
        if (previewMat.opacity != null) {
            previewMat.transparent = true;
            previewMat.opacity = MA_STL_OFFSET_TOOL_PREVIEW_OPACITY * 0.85;
        }
        line = new Line2(geo, previewMat);
        line.renderOrder = 168;
        line.visible = false;
        maStlApplyUserFloorLineMaterialResolutionIfRenderer(previewMat);
        maStlDisableRaycastOnOverlay(line);
        scene.add(line);
        if (isPlus) maStlWall2dToolRubberBandFacePlus = line;
        else maStlWall2dToolRubberBandFaceMinus = line;
        return line;
    }

    function maStlWall2dToolHideFaceRubberBands() {
        if (maStlWall2dToolRubberBandFacePlus) maStlWall2dToolRubberBandFacePlus.visible = false;
        if (maStlWall2dToolRubberBandFaceMinus) maStlWall2dToolRubberBandFaceMinus.visible = false;
    }

    /** Vista previa de las dos caras (±espesor/2) durante `picking2`. */
    function maStlWall2dToolRefreshFaceRubberBands(endMm) {
        if (maStlLineToolState !== 'picking2' || !endMm) {
            maStlWall2dToolHideFaceRubberBands();
            return;
        }
        const halfT = maStlWall2dToolThicknessHalfMm();
        const p1 = {
            x: maStlLineToolPoint1Mm.x,
            y: maStlLineToolPoint1Mm.y,
            z: maStlLineToolPoint1Mm.z,
        };
        const p2 = { x: endMm.x, y: endMm.y, z: endMm.z };
        const segLen = Math.hypot(p2.x - p1.x, p2.z - p1.z);
        if (segLen < maStlUserFloorSegmentMinMm()) {
            maStlWall2dToolHideFaceRubberBands();
            return;
        }
        const bands = [
            { which: 'plus', sign: 1, line: maStlWall2dToolEnsureFaceRubberBandLine('plus') },
            { which: 'minus', sign: -1, line: maStlWall2dToolEnsureFaceRubberBandLine('minus') },
        ];
        for (let bi = 0; bi < bands.length; bi++) {
            const ends = maStlOffsetToolParallelEndpointsMm(p1, p2, halfT, bands[bi].sign);
            if (!ends) {
                bands[bi].line.visible = false;
                continue;
            }
            maStlSetUserFloorLineGeometryMm(bands[bi].line, ends.p1, ends.p2);
            bands[bi].line.visible = true;
        }
    }

    /** Expande líneas de muro 2D al tramo completo (eje + caras) para borrado. */
    function maStlDesing2ExpandLinesWithWallGroups(lines) {
        const out = [];
        const seen = new Set();
        for (let li = 0; li < lines.length; li++) {
            const ln = lines[li];
            if (!ln) continue;
            const ud = ln.userData && ln.userData.maStlUserPlanLine;
            if (ud && ud.wallGroupId != null) {
                const segment = maStlResolveWallSegmentLinesForLine(ln);
                for (let gi = 0; gi < segment.length; gi++) {
                    const gl = segment[gi];
                    if (!seen.has(gl.uuid)) {
                        seen.add(gl.uuid);
                        out.push(gl);
                    }
                }
            } else if (!seen.has(ln.uuid)) {
                seen.add(ln.uuid);
                out.push(ln);
            }
        }
        return out;
    }

    /** Clic en muro 2D: seleccionar la cara (el eje no es interactivo). */
    function maStlWall2dToolResolveSelectionLine(line) {
        if (!line || !maStlIsUserFloorPlanLineSelectable(line)) return null;
        return line;
    }

    function maStlIsUserFloorWallFacePlanLine(line) {
        const ud = line && line.userData && line.userData.maStlUserPlanLine;
        return !!(ud && ud.wallRole === 'face' && ud.linkOffsetFromLineId != null);
    }

    function maStlWall2dToolEditableAxisLineForDimension(line) {
        if (!line || !maStlIsUserFloorPlanLineObject(line)) return null;
        const ud = line.userData && line.userData.maStlUserPlanLine;
        if (!ud) return null;
        if (ud.wallRole === 'axis') return line;
        if (ud.wallRole === 'face' && ud.linkOffsetFromLineId != null) {
            return maStlWall2dToolFindLineByPlanId(ud.linkOffsetFromLineId);
        }
        return line;
    }

    function maStlWall2dToolRefreshFacesAfterEditableAxisChange(line) {
        const axisLine = maStlWall2dToolEditableAxisLineForDimension(line);
        const axisUd = axisLine && axisLine.userData && axisLine.userData.maStlUserPlanLine;
        if (!axisLine || !axisUd || axisUd.wallRole !== 'axis') return;
        const faces = maStlWall2dToolFindFaceLinesForCenterId(axisUd.id);
        let halfT = maStlWall2dToolThicknessHalfMm();
        for (let fi = 0; fi < faces.length; fi++) {
            const fUd = faces[fi].userData && faces[fi].userData.maStlUserPlanLine;
            if (fUd && fUd.numberOffsetMm != null && Number.isFinite(fUd.numberOffsetMm)) {
                halfT = Math.abs(fUd.numberOffsetMm);
                break;
            }
        }
        maStlWall2dToolRefactorCenterFaceOffsets(axisLine, halfT, axisUd.wallGroupId);
        maStlWall2dToolSplitAllAxisInteriorCrossingsMm();
        maStlWall2dToolRefactorAllWallJunctionsMm();
        maStlWeldAllUserFloorLineEndpointsMm();
        maStlWall2dToolRefactorAllWallJunctionsMm();
        maStlReapplyAllUserFloorWallAxisLineStyles();
    }

    function maStlWall2dToolAxisFaceHalfThicknessMm(axisLine) {
        const axisUd = axisLine && axisLine.userData && axisLine.userData.maStlUserPlanLine;
        if (!axisUd || axisUd.id == null) return maStlWall2dToolThicknessHalfMm();
        const faces = maStlWall2dToolFindFaceLinesForCenterId(axisUd.id);
        for (let fi = 0; fi < faces.length; fi++) {
            const fUd = faces[fi].userData && faces[fi].userData.maStlUserPlanLine;
            if (fUd && fUd.numberOffsetMm != null && Number.isFinite(fUd.numberOffsetMm)) {
                return Math.abs(fUd.numberOffsetMm);
            }
        }
        return maStlWall2dToolThicknessHalfMm();
    }

    function maStlWall2dToolAxisTotalThicknessMm(axisLine) {
        return maStlWall2dToolAxisFaceHalfThicknessMm(axisLine) * 2;
    }

    /** Mitad de espesor a partir del userData del eje (uniones T / cortes). */
    function maStlWall2dToolAxisHalfThicknessFromAxisUd(axisUd) {
        if (!axisUd || axisUd.id == null) return maStlWall2dToolThicknessHalfMm();
        const axisLine = maStlWall2dToolFindLineByPlanId(axisUd.id);
        if (!axisLine) return maStlWall2dToolThicknessHalfMm();
        return maStlWall2dToolAxisFaceHalfThicknessMm(axisLine);
    }

    /**
     * Recoloca ambas caras paralelas al eje (±mitad) sin ingletes; prepara el refactor de uniones.
     */
    function maStlWall2dToolApplyParallelFaceOffsetsOnlyMm(centerLine, halfT) {
        if (!centerLine || !(halfT > 0)) return;
        const ud = centerLine.userData && centerLine.userData.maStlUserPlanLine;
        if (!ud || ud.wallRole !== 'axis' || ud.id == null || !ud.p1Mm || !ud.p2Mm) return;
        const faces = maStlWall2dToolFindFaceLinesForCenterId(ud.id);
        for (let fi = 0; fi < faces.length; fi++) {
            const faceLine = faces[fi];
            const fUd = faceLine.userData && faceLine.userData.maStlUserPlanLine;
            if (!fUd) continue;
            const sideSign = fUd.numberWallFaceSideSign === -1 ? -1 : 1;
            const ends = maStlOffsetToolParallelEndpointsMm(ud.p1Mm, ud.p2Mm, halfT, sideSign);
            if (!ends) continue;
            fUd.numberOffsetMm = halfT;
            fUd.p1Mm.x = ends.p1.x;
            fUd.p1Mm.y = ends.p1.y;
            fUd.p1Mm.z = ends.p1.z;
            fUd.p2Mm.x = ends.p2.x;
            fUd.p2Mm.y = ends.p2.y;
            fUd.p2Mm.z = ends.p2.z;
            maStlApplyUserFloorLineSegmentGeometryFromMm(faceLine);
        }
    }

    /** Muros cuyo eje comparte vértice o unión T con `seedAxisLine` (red conectada en planta). */
    function maStlWall2dToolCollectTopologyConnectedAxisLinesMm(seedAxisLine) {
        if (!seedAxisLine || !maStlUserLinesGroup) return [];
        const eps = maStlWall2dToolJunctionClusterEpsMm();
        const allAxes = [];
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const ln = ch[i];
            if (!maStlIsUserFloorPlanLineObject(ln)) continue;
            const ud = ln.userData && ln.userData.maStlUserPlanLine;
            if (!ud || ud.wallRole !== 'axis' || !ud.p1Mm || !ud.p2Mm) continue;
            allAxes.push(ln);
        }
        if (!allAxes.length) return [];

        function axisSharesJunctionWith(axisUd, otherUd) {
            const endsA = [axisUd.p1Mm, axisUd.p2Mm];
            const endsB = [otherUd.p1Mm, otherUd.p2Mm];
            for (let ai = 0; ai < endsA.length; ai++) {
                for (let bi = 0; bi < endsB.length; bi++) {
                    if (maStlUserFloorPlanPointNearXzMm(endsA[ai], endsB[bi], eps)) return true;
                }
            }
            for (let ai = 0; ai < endsA.length; ai++) {
                if (
                    maStlUserFloorPlanPointDistanceToSegmentAxisXzMm(
                        endsA[ai],
                        otherUd.p1Mm,
                        otherUd.p2Mm
                    ) <= eps
                ) {
                    return true;
                }
            }
            for (let bi = 0; bi < endsB.length; bi++) {
                if (
                    maStlUserFloorPlanPointDistanceToSegmentAxisXzMm(
                        endsB[bi],
                        axisUd.p1Mm,
                        axisUd.p2Mm
                    ) <= eps
                ) {
                    return true;
                }
            }
            return false;
        }

        const visited = new Set();
        const result = [];
        const queue = [seedAxisLine];
        while (queue.length) {
            const cur = queue.shift();
            if (!cur || visited.has(cur.uuid)) continue;
            visited.add(cur.uuid);
            result.push(cur);
            const curUd = cur.userData && cur.userData.maStlUserPlanLine;
            if (!curUd) continue;
            for (let i = 0; i < allAxes.length; i++) {
                const other = allAxes[i];
                if (visited.has(other.uuid)) continue;
                const otherUd = other.userData && other.userData.maStlUserPlanLine;
                if (!otherUd) continue;
                if (axisSharesJunctionWith(curUd, otherUd)) queue.push(other);
            }
        }
        return result;
    }

    /**
     * Espesor total simétrico (±mitad) solo en el eje seleccionado.
     * Ambas caras se recolocan en paralelo; luego las uniones L/T en ambos extremos se adaptan.
     * Los muros conectados conservan su espesor pero recalculan ingletes.
     * @param {number} totalThicknessMm espesor total mm escena
     */
    function maStlWall2dToolApplyConnectedWallsThicknessMm(seedAxisLine, totalThicknessMm) {
        if (!seedAxisLine || !Number.isFinite(totalThicknessMm)) return false;
        const axisUd = seedAxisLine.userData && seedAxisLine.userData.maStlUserPlanLine;
        if (!axisUd || axisUd.wallRole !== 'axis' || axisUd.id == null) return false;
        const thicknessMm = THREE.MathUtils.clamp(
            totalThicknessMm,
            MA_STL_WALL_DIM_MIN_THICKNESS_MM,
            MA_STL_WALL_DIM_MAX_THICKNESS_MM
        );
        const halfT = thicknessMm * 0.5;
        const affected = maStlWall2dToolCollectTopologyConnectedAxisLinesMm(seedAxisLine);
        if (!affected.length) affected.push(seedAxisLine);

        for (let ai = 0; ai < affected.length; ai++) {
            const axisLine = affected[ai];
            if (!axisLine) continue;
            const axisHalf =
                axisLine === seedAxisLine
                    ? halfT
                    : maStlWall2dToolAxisFaceHalfThicknessMm(axisLine);
            maStlWall2dToolApplyParallelFaceOffsetsOnlyMm(axisLine, axisHalf);
        }
        maStlWall2dToolSplitAllAxisInteriorCrossingsMm();
        maStlWall2dToolRefactorAllWallJunctionsMm();
        maStlWeldAllUserFloorLineEndpointsMm();
        maStlWall2dToolRefactorAllWallJunctionsMm();
        maStlReapplyAllUserFloorWallAxisLineStyles();
        maStlSaveWallConnectionsNow('wall-thickness-edit');
        return true;
    }

    function maStlWall2dToolRefreshAxisFaceOffsetsNoJunction(axisLine) {
        const axisUd = axisLine && axisLine.userData && axisLine.userData.maStlUserPlanLine;
        if (!axisLine || !axisUd || axisUd.wallRole !== 'axis') return;
        maStlWall2dToolRefactorCenterFaceOffsets(
            axisLine,
            maStlWall2dToolAxisFaceHalfThicknessMm(axisLine),
            null
        );
    }

    /** Post-procesado único de muros tras estirar / editar eje (evita duplicados). */
    let _maStlWallEditFinalize = null;
    function maStlWallEditFinalize() {
        if (!_maStlWallEditFinalize) {
            _maStlWallEditFinalize = new MaStlWallEditFinalize({
                refreshAxisFaceOffsetsNoJunction: maStlWall2dToolRefreshAxisFaceOffsetsNoJunction,
                refactorAllWallJunctionsMm: maStlWall2dToolRefactorAllWallJunctionsMm,
                splitAllAxisInteriorCrossingsMm: maStlWall2dToolSplitAllAxisInteriorCrossingsMm,
                weldAllUserFloorLineEndpointsMm: maStlWeldAllUserFloorLineEndpointsMm,
                reapplyAllUserFloorWallAxisLineStyles: maStlReapplyAllUserFloorWallAxisLineStyles,
                saveWallConnections: maStlSaveWallConnectionsNow,
                editableAxisLineForDimension: maStlWall2dToolEditableAxisLineForDimension,
            });
        }
        return _maStlWallEditFinalize;
    }

    function maStlWall2dToolCaptureAxisEditPropagationState(line) {
        const axisLine = maStlWall2dToolEditableAxisLineForDimension(line);
        const axisUd = axisLine && axisLine.userData && axisLine.userData.maStlUserPlanLine;
        if (!axisLine || !axisUd || axisUd.wallRole !== 'axis' || axisUd.id == null) return null;
        if (!maStlUserLinesGroup) return null;
        const axes = [];
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const ln = ch[i];
            if (!maStlIsUserFloorPlanLineObject(ln)) continue;
            const ud = ln.userData && ln.userData.maStlUserPlanLine;
            if (!ud || ud.wallRole !== 'axis' || ud.id == null || !ud.p1Mm || !ud.p2Mm) continue;
            axes.push({
                line: ln,
                id: ud.id,
                p1Mm: maStlDesing2ClonePlanPointMm(ud.p1Mm),
                p2Mm: maStlDesing2ClonePlanPointMm(ud.p2Mm),
            });
        }
        return axes.length
            ? {
                  editedAxisId: axisUd.id,
                  axes: axes,
              }
            : null;
    }

    function maStlWall2dToolOldAxisStateById(snapshot, axisId) {
        if (!snapshot || axisId == null) return null;
        for (let i = 0; i < snapshot.axes.length; i++) {
            if (snapshot.axes[i].id === axisId) return snapshot.axes[i];
        }
        return null;
    }

    function maStlWall2dToolPropagationFindNode(nodes, pt, eps) {
        for (let i = 0; i < nodes.length; i++) {
            if (maStlUserFloorPlanPointNearXzMm(nodes[i].pt, pt, eps)) return i;
        }
        nodes.push({ pt: maStlDesing2ClonePlanPointMm(pt), edges: [] });
        return nodes.length - 1;
    }

    function maStlWall2dToolPropagationDeltaNear(a, b) {
        if (!a || !b) return false;
        return Math.abs(a.dx - b.dx) <= 1e-6 && Math.abs(a.dz - b.dz) <= 1e-6;
    }

    function maStlWall2dToolPropagationEdgeAlignedWithDelta(edge, delta) {
        if (!edge || !edge.rec || !delta) return false;
        const ex = edge.rec.p2Mm.x - edge.rec.p1Mm.x;
        const ez = edge.rec.p2Mm.z - edge.rec.p1Mm.z;
        const el = Math.hypot(ex, ez);
        const dl = Math.hypot(delta.dx, delta.dz);
        if (!(el > 1e-9) || !(dl > 1e-9)) return false;
        const crossNorm = Math.abs((ex * delta.dz - ez * delta.dx) / (el * dl));
        return crossNorm <= 0.08;
    }

    function maStlWall2dToolAssignPropagationDelta(nodeDeltas, nodeIdx, delta, queue, fixedNodes) {
        if (nodeIdx == null || nodeIdx < 0 || !delta) return;
        if (fixedNodes[nodeIdx]) return;
        const existing = nodeDeltas[nodeIdx];
        if (existing) return;
        nodeDeltas[nodeIdx] = delta;
        queue.push(nodeIdx);
    }

    function maStlWall2dToolApplyAxisEditPropagation(line, snapshot) {
        const axisLine = maStlWall2dToolEditableAxisLineForDimension(line);
        const axisUd = axisLine && axisLine.userData && axisLine.userData.maStlUserPlanLine;
        if (!axisLine || !axisUd || axisUd.wallRole !== 'axis' || axisUd.id == null || !snapshot) return false;
        const oldEdited = maStlWall2dToolOldAxisStateById(snapshot, axisUd.id);
        if (!oldEdited || !axisUd.p1Mm || !axisUd.p2Mm) return false;

        const eps = Math.max(
            maStlUserFloorLineMergeEndpointEpsMm(),
            MA_STL_WALL_DIM_LENGTH_VALUE_TOL_MM,
            maStlWall2dToolJunctionClusterEpsMm(),
            maStlWall2dToolThicknessHalfMm() * 2.5
        );
        const changed = [];
        const fixedOldPts = [];
        const dP1 = {
            dx: axisUd.p1Mm.x - oldEdited.p1Mm.x,
            dz: axisUd.p1Mm.z - oldEdited.p1Mm.z,
        };
        const dP2 = {
            dx: axisUd.p2Mm.x - oldEdited.p2Mm.x,
            dz: axisUd.p2Mm.z - oldEdited.p2Mm.z,
        };
        if (Math.hypot(dP1.dx, dP1.dz) > eps * 0.05) changed.push({ pt: oldEdited.p1Mm, delta: dP1 });
        else fixedOldPts.push(oldEdited.p1Mm);
        if (Math.hypot(dP2.dx, dP2.dz) > eps * 0.05) changed.push({ pt: oldEdited.p2Mm, delta: dP2 });
        else fixedOldPts.push(oldEdited.p2Mm);
        if (!changed.length) return false;

        const nodes = [];
        const edgeRefs = [];
        for (let ai = 0; ai < snapshot.axes.length; ai++) {
            const rec = snapshot.axes[ai];
            const n1 = maStlWall2dToolPropagationFindNode(nodes, rec.p1Mm, eps);
            const n2 = maStlWall2dToolPropagationFindNode(nodes, rec.p2Mm, eps);
            const edge = { rec: rec, n1: n1, n2: n2 };
            edgeRefs.push(edge);
            nodes[n1].edges.push(edge);
            nodes[n2].edges.push(edge);
        }

        const fixedNodes = {};
        for (let fi = 0; fi < fixedOldPts.length; fi++) {
            const fn = maStlWall2dToolPropagationFindNode(nodes, fixedOldPts[fi], eps);
            fixedNodes[fn] = true;
        }

        const nodeDeltas = {};
        const queue = [];
        for (let ci = 0; ci < changed.length; ci++) {
            const cn = maStlWall2dToolPropagationFindNode(nodes, changed[ci].pt, eps);
            maStlWall2dToolAssignPropagationDelta(nodeDeltas, cn, changed[ci].delta, queue, fixedNodes);
        }

        for (let qi = 0; qi < queue.length; qi++) {
            const nodeIdx = queue[qi];
            const delta = nodeDeltas[nodeIdx];
            if (!delta) continue;
            const edges = nodes[nodeIdx].edges;
            for (let ei = 0; ei < edges.length; ei++) {
                const edge = edges[ei];
                if (edge.rec.id === axisUd.id) continue;
                const otherIdx = edge.n1 === nodeIdx ? edge.n2 : edge.n1;
                if (maStlWall2dToolPropagationEdgeAlignedWithDelta(edge, delta)) {
                    continue;
                }
                maStlWall2dToolAssignPropagationDelta(nodeDeltas, otherIdx, delta, queue, fixedNodes);
            }
        }

        const movedAxes = [];
        for (let ri = 0; ri < edgeRefs.length; ri++) {
            const edge = edgeRefs[ri];
            const rec = edge.rec;
            if (rec.id === axisUd.id) {
                movedAxes.push(axisLine);
                continue;
            }
            const ud = rec.line && rec.line.userData && rec.line.userData.maStlUserPlanLine;
            if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
            const d1 = nodeDeltas[edge.n1];
            const d2 = nodeDeltas[edge.n2];
            let changedLine = false;
            if (d1 && !fixedNodes[edge.n1]) {
                ud.p1Mm.x = rec.p1Mm.x + d1.dx;
                ud.p1Mm.z = rec.p1Mm.z + d1.dz;
                changedLine = true;
            }
            if (d2 && !fixedNodes[edge.n2]) {
                ud.p2Mm.x = rec.p2Mm.x + d2.dx;
                ud.p2Mm.z = rec.p2Mm.z + d2.dz;
                changedLine = true;
            }
            if (changedLine) {
                if (d1 && d2 && !maStlWall2dToolPropagationDeltaNear(d1, d2)) {
                    maStlQuantizeUserFloorPlanPointToGridMm(ud.p1Mm);
                    maStlQuantizeUserFloorPlanPointToGridMm(ud.p2Mm);
                }
                maStlApplyUserFloorLineSegmentGeometryFromMm(rec.line);
                movedAxes.push(rec.line);
            }
        }

        for (let mi = 0; mi < movedAxes.length; mi++) {
            maStlWall2dToolRefreshAxisFaceOffsetsNoJunction(movedAxes[mi]);
        }
        maStlWall2dToolSplitAllAxisInteriorCrossingsMm();
        maStlWall2dToolRefactorAllWallJunctionsMm();
        maStlWeldAllUserFloorLineEndpointsMm();
        maStlWall2dToolRefactorAllWallJunctionsMm();
        maStlReapplyAllUserFloorWallAxisLineStyles();
        return true;
    }

    function maStlWall2dToolReapplyAxisLengthWithPropagation(axisLine, targetLenMm) {
        const axisUd = axisLine && axisLine.userData && axisLine.userData.maStlUserPlanLine;
        if (!axisLine || !axisUd || axisUd.wallRole !== 'axis' || !(targetLenMm > 0)) return false;
        const currentLen = maStlUserFloorLineLengthMm(axisUd);
        if (Math.abs(currentLen - targetLenMm) <= MA_STL_WALL_DIM_LENGTH_VALUE_TOL_MM) return false;
        const snapshot = maStlWall2dToolCaptureAxisEditPropagationState(axisLine);
        maStlResizeUserFloorLineToLengthMm(axisLine, targetLenMm);
        if (!maStlWall2dToolApplyAxisEditPropagation(axisLine, snapshot)) {
            maStlWall2dToolRefreshFacesAfterEditableAxisChange(axisLine);
        }
        return true;
    }

    /**
     * @param {boolean} deferOrbitUnlock reservado; salida completa siempre rehabilita órbita al instante.
     */
    function maStlStopLineToolModesToolbar(deferOrbitUnlock) {
        if (!maStlLineToolState) return;
        const wasWall2d = maStlLineToolKind === 'wall2d';
        if (wasWall2d && maStlWall2dToolActiveGroupId != null) {
            maStlWall2dToolCaptureResumeState();
        }
        maStlRefactorUserFloorLinesMergeCollinear();
        if (wasWall2d) {
            maStlWall2dToolSplitAllAxisInteriorCrossingsMm();
        }
        maStlWall2dToolRefactorAllWallJunctionsMm();
        maStlPolylineToolActiveGroupId = null;
        maStlWall2dToolActiveGroupId = null;
        maStlWall2dToolHideFaceRubberBands();
        maStlLineToolHidePreviewDimHud();
        maStlLineToolState = null;
        maStlLineToolKind = null;
        maStlResetLineToolPickingBaselineState();
        if (maStlLineToolRubberBandLine) {
            maStlLineToolRubberBandLine.visible = false;
        }
        maStlClearGridIntersectionPickHighlight();
        maStlClearLineToolVertexSnapHighlight();
        maStlSyncLineToolHud();
        maStlSyncLineToolToggleBtnUi();
        maStlLineToolPickCursorSync();
        syncMaStlRulerAnchorPickCursor();
        if (wasWall2d) {
            maStlReapplyAllUserFloorWallAxisLineStyles();
        }
        /* Línea no mueve anclaje de reglas → nunca preserveView→ruler en unlock (misma filosofía que defer tras pan). */
        maStlUnlockOrbitForRulerAnchorPick(true);
        maStlSaveWallConnectionsNow({
            force: wasWall2d,
            reason: wasWall2d ? 'wall2d-stop-escape-or-toolbar' : 'line-tool-stop',
        });
    }

    function maStlOffsetToolClearTransientOverlays() {
        maStlClearGridIntersectionPickHighlight();
        maStlClearLineToolVertexSnapHighlight();
    }

    /**
     * Punto más cercano en el segmento P1–P2 (t ∈ [0,1]) al cursor en planta.
     * @param {{ x: number, y: number, z: number }} p1Mm
     * @param {{ x: number, y: number, z: number }} p2Mm
     * @param {{ x: number, z: number }} floorPt
     * @param {{ x: number, y: number, z: number }} out
     */
    function maStlOffsetToolClosestPointOnSegmentMm(p1Mm, p2Mm, floorPt, out) {
        if (!p1Mm || !p2Mm || !floorPt || !out) return null;
        const abx = p2Mm.x - p1Mm.x;
        const abz = p2Mm.z - p1Mm.z;
        const len2 = abx * abx + abz * abz;
        if (len2 < 1e-12) {
            out.x = p1Mm.x;
            out.y = p1Mm.y;
            out.z = p1Mm.z;
            return out;
        }
        const apx = floorPt.x - p1Mm.x;
        const apz = floorPt.z - p1Mm.z;
        const t = THREE.MathUtils.clamp((apx * abx + apz * abz) / len2, 0, 1);
        out.x = p1Mm.x + abx * t;
        out.y = p1Mm.y + (p2Mm.y - p1Mm.y) * t;
        out.z = p1Mm.z + abz * t;
        return out;
    }

    /** Hover pickLine: resalta línea bajo cursor + círculo snap en proyección sobre el tramo. */
    function maStlOffsetToolSyncPickLineHoverFeedback(clientX, clientY) {
        maStlClearGridIntersectionPickHighlight();
        const ln = maStlPickUserFloorLineNearScreenMm(
            clientX,
            clientY,
            MA_STL_USER_FLOOR_LINE_SCREEN_PICK_PX
        );
        maStlOffsetToolSetHoverLine(ln);
        if (!ln) {
            maStlClearLineToolVertexSnapHighlight();
            return;
        }
        const floorPt = maStlResolveLineToolFloorPointMm(clientX, clientY);
        if (!floorPt) {
            maStlClearLineToolVertexSnapHighlight();
            return;
        }
        const ud = ln.userData && ln.userData.maStlUserPlanLine;
        if (!ud || !ud.p1Mm || !ud.p2Mm) {
            maStlClearLineToolVertexSnapHighlight();
            return;
        }
        maStlOffsetToolClosestPointOnSegmentMm(
            ud.p1Mm,
            ud.p2Mm,
            floorPt,
            _maStlOffsetToolSegmentProjMm
        );
        const onMajor = maStlIsOnDisplayedMajorGridLineAtMm(
            _maStlOffsetToolSegmentProjMm.x,
            _maStlOffsetToolSegmentProjMm.z
        );
        maStlSetLineToolVertexSnapHighlight(_maStlOffsetToolSegmentProjMm, true, onMajor);
    }

    function maStlOffsetToolResetSessionState() {
        maStlOffsetToolClearSourceGroupHighlight();
        maStlOffsetToolSourceLine = null;
        maStlOffsetToolSideSign = 1;
        maStlOffsetToolDistanceMm = maStlClampDesing2OffsetDefaultMm(desing2EnvOffsetDefaultMm);
        maStlOffsetToolDistanceRowForced = false;
        maStlOffsetToolClearHoverLine();
    }

    function maStlOffsetToolClearHoverLine() {
        maStlOffsetToolClearHoverGroupHighlight();
    }

    function maStlOffsetToolSetHoverLine(line) {
        if (!line) {
            maStlOffsetToolClearHoverLine();
            return;
        }
        const group = maStlResolvePolylineGroupLinesForLine(line);
        const groupKey = group.map(function (g) {
            return g.uuid;
        }).join('|');
        const hoverKey = maStlOffsetToolHoverGroupLines.map(function (g) {
            return g.uuid;
        }).join('|');
        if (groupKey === hoverKey) return;
        maStlOffsetToolClearHoverGroupHighlight();
        maStlOffsetToolHoverLine = line;
        maStlOffsetToolHoverGroupLines = group.slice();
        for (let i = 0; i < maStlOffsetToolHoverGroupLines.length; i++) {
            const ln = maStlOffsetToolHoverGroupLines[i];
            if (!ln || !ln.material || maStlOffsetToolLineInSourceGroup(ln)) continue;
            maStlApplyUserFloorLineOffsetSourceMaterial(ln.material);
        }
    }

    function maStlOffsetToolHighlightSourceLine(line) {
        maStlOffsetToolClearHoverLine();
        maStlOffsetToolClearSourceGroupHighlight();
        maStlOffsetToolSourceLine = line;
        maStlOffsetToolSourceGroupLines = maStlResolvePolylineGroupLinesForLine(line);
        for (let i = 0; i < maStlOffsetToolSourceGroupLines.length; i++) {
            const ln = maStlOffsetToolSourceGroupLines[i];
            if (ln && ln.material) {
                maStlApplyUserFloorLineOffsetSourceMaterial(ln.material);
            }
        }
    }

    function maStlOffsetToolHidePreviewLine() {
        for (let i = 0; i < maStlOffsetToolPreviewLines.length; i++) {
            if (maStlOffsetToolPreviewLines[i]) {
                maStlOffsetToolPreviewLines[i].visible = false;
            }
        }
        if (maStlOffsetToolPreviewLine) {
            maStlOffsetToolPreviewLine.visible = false;
        }
    }

    function maStlOffsetToolAnyPreviewVisible() {
        if (maStlOffsetToolPreviewLine && maStlOffsetToolPreviewLine.visible === true) return true;
        for (let i = 0; i < maStlOffsetToolPreviewLines.length; i++) {
            if (maStlOffsetToolPreviewLines[i] && maStlOffsetToolPreviewLines[i].visible === true) {
                return true;
            }
        }
        return false;
    }

    function maStlOffsetToolEnsurePreviewLineAtIndex(idx) {
        while (maStlOffsetToolPreviewLines.length <= idx) {
            const geo = new LineGeometry();
            geo.setPositions(new Float32Array(6));
            const mat = maStlMakeUserFloorLineMaterial();
            mat.dashed = true;
            mat.dashSize = 12;
            mat.gapSize = 8;
            mat.linewidth = MA_STL_OFFSET_TOOL_PREVIEW_LINEWIDTH_PX;
            mat.color.setHex(MA_STL_OFFSET_TOOL_PREVIEW_COLOR_HEX);
            mat.opacity = MA_STL_OFFSET_TOOL_PREVIEW_OPACITY;
            mat.transparent = true;
            if (renderer && renderer.domElement) {
                maStlApplyUserFloorLineMaterialResolution(
                    mat,
                    renderer.domElement.clientWidth,
                    renderer.domElement.clientHeight
                );
            }
            const pl = new Line2(geo, mat);
            pl.renderOrder = 169;
            pl.visible = false;
            maStlDisableRaycastOnOverlay(pl);
            scene.add(pl);
            maStlOffsetToolPreviewLines.push(pl);
            if (!maStlOffsetToolPreviewLine) maStlOffsetToolPreviewLine = pl;
        }
        return maStlOffsetToolPreviewLines[idx];
    }

    /** @returns {THREE.Line2[]} */
    function maStlUserFloorPlanLinesInPolylineGroup(groupId) {
        const out = [];
        if (groupId == null || !maStlUserLinesGroup) return out;
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const ln = ch[i];
            if (!maStlIsUserFloorPlanLineObject(ln)) continue;
            const ud = ln.userData && ln.userData.maStlUserPlanLine;
            if (ud && ud.polylineGroupId === groupId) out.push(ln);
        }
        return out;
    }

    /** Polilínea completa si comparten `polylineGroupId`; si no, solo `line`. */
    function maStlResolvePolylineGroupLinesForLine(line) {
        if (!line || !maStlIsUserFloorPlanLineObject(line)) return [];
        const ud = line.userData && line.userData.maStlUserPlanLine;
        if (!ud || ud.polylineGroupId == null) return [line];
        const group = maStlUserFloorPlanLinesInPolylineGroup(ud.polylineGroupId);
        return group.length > 0 ? group : [line];
    }

    function maStlOffsetToolLineInSourceGroup(line) {
        if (!line || !maStlOffsetToolSourceGroupLines.length) return false;
        return maStlOffsetToolSourceGroupLines.indexOf(line) >= 0;
    }

    function maStlOffsetToolClearSourceGroupHighlight() {
        for (let i = 0; i < maStlOffsetToolSourceGroupLines.length; i++) {
            const ln = maStlOffsetToolSourceGroupLines[i];
            if (ln && ln.material) maStlApplyUserFloorLineBaseMaterialForLine(ln);
        }
        maStlOffsetToolSourceGroupLines = [];
    }

    function maStlOffsetToolClearHoverGroupHighlight() {
        for (let i = 0; i < maStlOffsetToolHoverGroupLines.length; i++) {
            const ln = maStlOffsetToolHoverGroupLines[i];
            if (
                ln &&
                ln.material &&
                !maStlOffsetToolLineInSourceGroup(ln) &&
                ln !== maStlOffsetToolSourceLine
            ) {
                maStlApplyUserFloorLineBaseMaterialForLine(ln);
            }
        }
        maStlOffsetToolHoverGroupLines = [];
        maStlOffsetToolHoverLine = null;
    }

    function maStlEnsureOffsetToolPreviewLine() {
        maStlOffsetToolEnsurePreviewLineAtIndex(0);
    }

    /** @returns {boolean} geometría válida (longitud mínima) lista para mostrar. */
    function maStlOffsetToolSyncPreviewLineGeometryMm(previewLine, p1, p2) {
        if (!previewLine) return false;
        const segLen = Math.hypot(p2.x - p1.x, p2.z - p1.z);
        if (segLen < maStlUserFloorSegmentMinMm()) {
            return false;
        }
        maStlSetUserFloorLineGeometryMm(previewLine, p1, p2);
        if (typeof previewLine.computeLineDistances === 'function') {
            previewLine.computeLineDistances();
        }
        return true;
    }

    /** `true` si el punto en planta cae sobre el segmento origen (≤ ε perpendicular). */
    function maStlOffsetToolFloorPointOnSourceLineMm(floorPt, p1Mm, p2Mm, epsMm) {
        if (!floorPt || !p1Mm || !p2Mm || !(epsMm > 0)) return false;
        const abx = p2Mm.x - p1Mm.x;
        const abz = p2Mm.z - p1Mm.z;
        const len = Math.hypot(abx, abz);
        if (len < 1e-9) return true;
        const apx = floorPt.x - p1Mm.x;
        const apz = floorPt.z - p1Mm.z;
        const t = THREE.MathUtils.clamp((apx * abx + apz * abz) / (len * len), 0, 1);
        const refX = p1Mm.x + abx * t;
        const refZ = p1Mm.z + abz * t;
        return Math.hypot(floorPt.x - refX, floorPt.z - refZ) <= epsMm;
    }

    /**
     * Signo lateral ±1: perpendicular izquierda de P1→P2 (`n = (-u.z, u.x)`) hacia `floorPt`.
     * @param {{ x: number, y: number, z: number }} p1Mm
     * @param {{ x: number, y: number, z: number }} p2Mm
     * @param {{ x: number, z: number }} floorPt
     */
    function maStlOffsetToolSideSignFromFloorPointMm(p1Mm, p2Mm, floorPt) {
        const abx = p2Mm.x - p1Mm.x;
        const abz = p2Mm.z - p1Mm.z;
        const len = Math.hypot(abx, abz);
        if (len < 1e-9) return 1;
        const nx = -abz / len;
        const nz = abx / len;
        const apx = floorPt.x - p1Mm.x;
        const apz = floorPt.z - p1Mm.z;
        const t = THREE.MathUtils.clamp((apx * abx + apz * abz) / (len * len), 0, 1);
        const refX = p1Mm.x + abx * t;
        const refZ = p1Mm.z + abz * t;
        const vx = floorPt.x - refX;
        const vz = floorPt.z - refZ;
        const dot = vx * nx + vz * nz;
        return dot >= 0 ? 1 : -1;
    }

    /**
     * Extremos paralelos desplazados perpendicularmente en XZ.
     * @returns {{ p1: { x: number, y: number, z: number }, p2: { x: number, y: number, z: number } }|null}
     */
    function maStlOffsetToolParallelEndpointsMm(p1Mm, p2Mm, offsetMm, sideSign) {
        const abx = p2Mm.x - p1Mm.x;
        const abz = p2Mm.z - p1Mm.z;
        const len = Math.hypot(abx, abz);
        if (len < maStlUserFloorSegmentMinMm() || !(offsetMm > 0)) return null;
        const ux = abx / len;
        const uz = abz / len;
        const sign = sideSign >= 0 ? 1 : -1;
        const nx = -uz * sign;
        const nz = ux * sign;
        return {
            p1: {
                x: p1Mm.x + nx * offsetMm,
                y: p1Mm.y,
                z: p1Mm.z + nz * offsetMm,
            },
            p2: {
                x: p2Mm.x + nx * offsetMm,
                y: p2Mm.y,
                z: p2Mm.z + nz * offsetMm,
            },
        };
    }

    /**
     * Intersección de dos rectas infinitas en planta XZ: P1 + t·D1 con P2 + s·D2.
     * @returns {{ x: number, z: number }|null}
     */
    function maStlPlanXzInfiniteLinesIntersectMm(p1, d1x, d1z, p2, d2x, d2z) {
        const cross = d1x * d2z - d1z * d2x;
        if (Math.abs(cross) < 1e-12) return null;
        const rx = p2.x - p1.x;
        const rz = p2.z - p1.z;
        const t = (rx * d2z - rz * d2x) / cross;
        return { x: p1.x + d1x * t, z: p1.z + d1z * t };
    }

    /** Normal perpendicular izquierda de `u` en XZ, con signo lateral ±1. */
    function maStlOffsetToolNormalFromDirSignMm(ux, uz, sideSign) {
        const sign = sideSign >= 0 ? 1 : -1;
        return { nx: -uz * sign, nz: ux * sign };
    }

    /**
     * Bisectriz unitaria del ángulo **interior** (cuña cóncava) en vértice compartido.
     * `uOutwardA`/`uOutwardB` salen del vértice a lo largo de cada tramo (dirs salientes).
     * @returns {{ ux: number, uz: number }|null}
     */
    function maStlOffsetToolInteriorBisectorUnitXzMm(uOutwardA, uOutwardB) {
        const bx = -uOutwardA.ux - uOutwardB.ux;
        const bz = -uOutwardA.uz - uOutwardB.uz;
        const blen = Math.hypot(bx, bz);
        if (blen < 1e-9) return null;
        return { ux: bx / blen, uz: bz / blen };
    }

    /** `true` si `sideSign` desplaza la línea (dir `p1→p2`) hacia el interior del ángulo con el vecino. */
    function maStlOffsetToolIsInwardOffsetAtCornerMm(uLine, uOutwardA, uOutwardB, sideSign) {
        const bis = maStlOffsetToolInteriorBisectorUnitXzMm(uOutwardA, uOutwardB);
        if (!bis || !uLine) return false;
        const n = maStlOffsetToolNormalFromDirSignMm(uLine.ux, uLine.uz, sideSign);
        return n.nx * bis.ux + n.nz * bis.uz > 1e-6;
    }

    /**
     * Signo lateral (respecto a `uLine` `p1→p2`) que desplaza el vecino hacia el mismo interior
     * que la fuente con `sideSignA`.
     */
    function maStlOffsetToolNeighborSideSignForMiterMm(uLineA, uLineB, sideSignA, uOutwardA, uOutwardB) {
        const bis = maStlOffsetToolInteriorBisectorUnitXzMm(uOutwardA, uOutwardB);
        if (!bis || !uLineA || !uLineB) return null;
        const nA = maStlOffsetToolNormalFromDirSignMm(uLineA.ux, uLineA.uz, sideSignA);
        const targetDot = nA.nx * bis.ux + nA.nz * bis.uz;
        const nBPos = maStlOffsetToolNormalFromDirSignMm(uLineB.ux, uLineB.uz, 1);
        const nBNeg = maStlOffsetToolNormalFromDirSignMm(uLineB.ux, uLineB.uz, -1);
        const dotPos = nBPos.nx * bis.ux + nBPos.nz * bis.uz;
        const dotNeg = nBNeg.nx * bis.ux + nBNeg.nz * bis.uz;
        if (targetDot >= 0) {
            if (dotPos >= dotNeg) return dotPos >= 0 ? 1 : -1;
            return dotNeg >= 0 ? -1 : 1;
        }
        if (dotPos <= dotNeg) return dotPos <= 0 ? 1 : -1;
        return dotNeg <= 0 ? -1 : 1;
    }

    /** Copia paralela sigue alineada con el tramo fuente (`p1→p2`, mismo sentido). */
    function maStlOffsetToolSegmentParallelToSourceMm(outP1, outP2, srcP1, srcP2) {
        if (!outP1 || !outP2 || !srcP1 || !srcP2) return false;
        const sdx = srcP2.x - srcP1.x;
        const sdz = srcP2.z - srcP1.z;
        const odx = outP2.x - outP1.x;
        const odz = outP2.z - outP1.z;
        const slen = Math.hypot(sdx, sdz);
        const olen = Math.hypot(odx, odz);
        if (slen < 1e-9 || olen < 1e-9) return false;
        const cross = sdx * odz - sdz * odx;
        const dot = sdx * odx + sdz * odz;
        const tol = 1e-6 * slen * olen;
        return Math.abs(cross) <= tol && dot > 0;
    }

    /** `point` sobre la paralela offset que pasa por `parallelAnchor` con dir `uLine`. */
    function maStlOffsetToolPointOnOffsetParallelLineMm(point, parallelAnchor, uLine, offsetMm) {
        if (!point || !parallelAnchor || !uLine) return false;
        const dx = point.x - parallelAnchor.x;
        const dz = point.z - parallelAnchor.z;
        const cross = uLine.ux * dz - uLine.uz * dx;
        const tol = Math.max(1e-6, Math.abs(offsetMm) * 1e-6);
        return Math.abs(cross) <= tol;
    }

    /** Distancia perpendicular en XZ de `point` a la recta infinita `p1 + t·uLine`. */
    function maStlOffsetToolPointPerpDistanceFromSourceLineMm(point, p1Mm, uLine) {
        if (!point || !p1Mm || !uLine) return NaN;
        const apx = point.x - p1Mm.x;
        const apz = point.z - p1Mm.z;
        return Math.abs(uLine.ux * apz - uLine.uz * apx);
    }

    /** Parámetro escalar `t` de `point` sobre `p1Mm + t·uLine`. */
    function maStlOffsetToolScalarAlongLineMm(point, p1Mm, uLine) {
        if (!point || !p1Mm || !uLine) return NaN;
        const apx = point.x - p1Mm.x;
        const apz = point.z - p1Mm.z;
        return apx * uLine.ux + apz * uLine.uz;
    }

    /**
     * Copia offset ya confirmada, paralela a `sourceNeighborUd` a ~`offsetMm` y con extremo
     * razonablemente cerca del vértice ancla (cadena cerrada / rectángulo).
     * @returns {{ line: THREE.Line2, ud: *, uLine: { ux: number, uz: number, lenMm: number } }|null}
     */
    function maStlOffsetToolFindCommittedOffsetOfNeighborMm(
        sourceLine,
        sourceNeighborUd,
        anchorVertexMm,
        offsetMm
    ) {
        if (!sourceNeighborUd || !anchorVertexMm || !(offsetMm > 0) || !maStlUserLinesGroup) return null;
        const uNeigh = maStlUserFloorPlanLineDirUnitXz(sourceNeighborUd);
        if (!uNeigh) return null;
        const eps = maStlUserFloorLineMergeEndpointEpsMm();
        const offsetTol = Math.max(eps * 2, offsetMm * 0.12);
        const parallelCrossTol = MA_STL_USER_FLOOR_LINE_MERGE_COLLINEAR_CROSS_MAX;
        const cornerReachMm = Math.max(eps * 4, offsetMm * 2.5);
        let best = null;
        let bestScore = Infinity;
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const line = ch[i];
            if (line === sourceLine || !maStlIsUserFloorPlanLineObject(line)) continue;
            const udB = line.userData && line.userData.maStlUserPlanLine;
            if (!udB || !udB.p1Mm || !udB.p2Mm) continue;
            if (udB === sourceNeighborUd) continue;
            const uB = maStlUserFloorPlanLineDirUnitXz(udB);
            if (!uB) continue;
            const cross = uNeigh.ux * uB.uz - uNeigh.uz * uB.ux;
            if (Math.abs(cross) > parallelCrossTol) continue;
            const perp = maStlOffsetToolPointPerpDistanceFromSourceLineMm(
                udB.p1Mm,
                sourceNeighborUd.p1Mm,
                uNeigh
            );
            if (!Number.isFinite(perp) || Math.abs(perp - offsetMm) > offsetTol) continue;
            const d1 = maStlUserFloorPlanPointNearXzMm(udB.p1Mm, anchorVertexMm, cornerReachMm)
                ? 0
                : Math.hypot(udB.p1Mm.x - anchorVertexMm.x, udB.p1Mm.z - anchorVertexMm.z);
            const d2 = maStlUserFloorPlanPointNearXzMm(udB.p2Mm, anchorVertexMm, cornerReachMm)
                ? 0
                : Math.hypot(udB.p2Mm.x - anchorVertexMm.x, udB.p2Mm.z - anchorVertexMm.z);
            const score = Math.min(d1, d2);
            if (score > cornerReachMm) continue;
            if (score < bestScore) {
                bestScore = score;
                best = { line: line, ud: udB, uLine: uB };
            }
        }
        return best;
    }

    /**
     * Valida y acepta un extremo recortado por miter: debe caer sobre la paralela offset del tramo
     * y no invertir el sentido respecto al otro extremo (paralelo o ya recortado).
     */
    function maStlOffsetToolAcceptMiterEndpointMm(
        miter,
        otherEnd,
        parallelAtCorner,
        uLine,
        srcP1Mm,
        srcLenMm,
        offsetMm,
        cornerOutKey
    ) {
        if (
            !miter ||
            !otherEnd ||
            !parallelAtCorner ||
            !uLine ||
            !srcP1Mm ||
            !(srcLenMm > 0) ||
            !(offsetMm > 0)
        ) {
            return false;
        }
        if (!maStlOffsetToolPointOnOffsetParallelLineMm(miter, parallelAtCorner, uLine, offsetMm)) {
            return false;
        }
        const perp = maStlOffsetToolPointPerpDistanceFromSourceLineMm(miter, srcP1Mm, uLine);
        const perpTol = Math.max(1e-3, offsetMm * 0.08);
        if (!Number.isFinite(perp) || Math.abs(perp - offsetMm) > perpTol) return false;
        const tMiter = maStlOffsetToolScalarAlongLineMm(miter, srcP1Mm, uLine);
        const tOther = maStlOffsetToolScalarAlongLineMm(otherEnd, srcP1Mm, uLine);
        const slack = Math.max(1e-3, srcLenMm * 1e-6);
        if (cornerOutKey === 'p1') {
            return tMiter >= -slack && tMiter <= tOther + slack;
        }
        return tMiter <= srcLenMm + slack && tMiter >= tOther - slack;
    }

    /**
     * Vecino conectado en P1 o P2 de `sourceLine` (≤ ε merge), excluyendo colineales en la junta.
     * @returns {{ line: THREE.Line2, ud: *, onA: string, onB: string, uNeighFromV: { ux: number, uz: number } }|null}
     */
    function maStlOffsetToolFindNeighborAtEndpoint(sourceLine, endpointKind) {
        if (!sourceLine || !maStlUserLinesGroup) return null;
        const ud = sourceLine.userData && sourceLine.userData.maStlUserPlanLine;
        if (!ud || !ud.p1Mm || !ud.p2Mm) return null;
        let eps = maStlUserFloorLineMergeEndpointEpsMm();
        if (ud.wallRole === 'axis') {
            eps = Math.max(eps, maStlWall2dToolJunctionClusterEpsMm());
        }
        const ch = maStlUserLinesGroup.children;
        for (let i = 0; i < ch.length; i++) {
            const line = ch[i];
            if (line === sourceLine || !maStlIsUserFloorPlanLineObject(line)) continue;
            const udB = line.userData && line.userData.maStlUserPlanLine;
            if (!udB || !udB.p1Mm || !udB.p2Mm) continue;
            if (udB.wallRole === 'face') continue;
            const shareEps =
                udB.wallRole === 'axis' ? Math.max(eps, maStlWall2dToolJunctionClusterEpsMm()) : eps;
            const share = maStlUserFloorPlanLinesShareEndpointMm(ud, udB, shareEps);
            if (!share || share.onA !== endpointKind) continue;
            if (
                maStlUserFloorPlanLinesCollinearSameSenseXzAtShare(
                    ud,
                    udB,
                    share.onA,
                    share.onB
                )
            ) {
                continue;
            }
            const uNeighFromV = maStlUserFloorPlanLineOutwardDirUnitXz(udB, share.onB);
            if (!uNeighFromV) continue;
            return { line, ud: udB, onA: share.onA, onB: share.onB, uNeighFromV };
        }
        return null;
    }

    /**
     * Punto de miter: intersección de la recta offset del tramo A con la del tramo B en el vértice V.
     * Si `committedNeighborUd` existe (copia offset ya confirmada del vecino), usa su geometría real.
     * @returns {{ x: number, y: number, z: number }|null}
     */
    function maStlOffsetToolMiterPointAtCornerMm(
        vertexMm,
        uLineA,
        uLineB,
        uOutwardA,
        uOutwardB,
        offsetMm,
        sideSignA,
        committedNeighborUd
    ) {
        if (!vertexMm || !(offsetMm > 0) || !uLineA) return null;
        const nA = maStlOffsetToolNormalFromDirSignMm(uLineA.ux, uLineA.uz, sideSignA);
        const pA = { x: vertexMm.x + nA.nx * offsetMm, z: vertexMm.z + nA.nz * offsetMm };
        let pB;
        let dBx;
        let dBz;
        if (committedNeighborUd && committedNeighborUd.p1Mm && committedNeighborUd.p2Mm) {
            pB = committedNeighborUd.p1Mm;
            dBx = uLineB.ux;
            dBz = uLineB.uz;
        } else {
            if (!uLineB) return null;
            const sideSignB = maStlOffsetToolNeighborSideSignForMiterMm(
                uLineA,
                uLineB,
                sideSignA,
                uOutwardA,
                uOutwardB
            );
            if (sideSignB == null) return null;
            const nB = maStlOffsetToolNormalFromDirSignMm(uLineB.ux, uLineB.uz, sideSignB);
            pB = { x: vertexMm.x + nB.nx * offsetMm, z: vertexMm.z + nB.nz * offsetMm };
            dBx = uLineB.ux;
            dBz = uLineB.uz;
        }
        const hit = maStlPlanXzInfiniteLinesIntersectMm(
            pA,
            uLineA.ux,
            uLineA.uz,
            pB,
            dBx,
            dBz
        );
        if (!hit) return null;
        return { x: hit.x, y: vertexMm.y, z: hit.z };
    }

    /**
     * Copia paralela con esquinas a inglete en vértices compartidos (offset interior hacia la junta).
     * Recorta **cada** extremo con vecino no colineal por separado; usa copias offset ya confirmadas
     * del vecino cuando existen (rectángulo / cadena cerrada).
     */
    function maStlOffsetToolParallelEndpointsWithMitersMm(sourceLine, offsetMm, sideSign) {
        if (!sourceLine || !maStlIsUserFloorPlanLineObject(sourceLine)) return null;
        const ud = sourceLine.userData && sourceLine.userData.maStlUserPlanLine;
        if (!ud || !ud.p1Mm || !ud.p2Mm) return null;
        const uLineA = maStlUserFloorPlanLineDirUnitXz(ud);
        if (!uLineA) return null;
        const ends = maStlOffsetToolParallelEndpointsMm(ud.p1Mm, ud.p2Mm, offsetMm, sideSign);
        if (!ends) return null;
        const parallelP1 = { x: ends.p1.x, y: ends.p1.y, z: ends.p1.z };
        const parallelP2 = { x: ends.p2.x, y: ends.p2.y, z: ends.p2.z };
        const srcLenMm = uLineA.lenMm;

        const corners = [
            {
                endpointKind: 'p1',
                vertexMm: ud.p1Mm,
                outKey: 'p1',
                parallelAtCorner: parallelP1,
            },
            {
                endpointKind: 'p2',
                vertexMm: ud.p2Mm,
                outKey: 'p2',
                parallelAtCorner: parallelP2,
            },
        ];
        for (let ci = 0; ci < corners.length; ci++) {
            const corner = corners[ci];
            const neigh = maStlOffsetToolFindNeighborAtEndpoint(sourceLine, corner.endpointKind);
            if (!neigh) continue;
            const uOutwardA = maStlUserFloorPlanLineOutwardDirUnitXz(ud, corner.endpointKind);
            const uLineB = maStlUserFloorPlanLineDirUnitXz(neigh.ud);
            if (!uOutwardA || !uLineB) continue;
            if (
                !maStlOffsetToolIsInwardOffsetAtCornerMm(
                    uLineA,
                    uOutwardA,
                    neigh.uNeighFromV,
                    sideSign
                )
            ) {
                continue;
            }
            const committed = maStlOffsetToolFindCommittedOffsetOfNeighborMm(
                sourceLine,
                neigh.ud,
                corner.vertexMm,
                offsetMm
            );
            const miter = maStlOffsetToolMiterPointAtCornerMm(
                corner.vertexMm,
                uLineA,
                committed ? committed.uLine : uLineB,
                uOutwardA,
                neigh.uNeighFromV,
                offsetMm,
                sideSign,
                committed ? committed.ud : null
            );
            if (!miter) continue;
            const otherKey = corner.outKey === 'p1' ? 'p2' : 'p1';
            if (
                !maStlOffsetToolAcceptMiterEndpointMm(
                    miter,
                    ends[otherKey],
                    corner.parallelAtCorner,
                    uLineA,
                    ud.p1Mm,
                    srcLenMm,
                    offsetMm,
                    corner.outKey
                )
            ) {
                continue;
            }
            ends[corner.outKey] = miter;
        }

        const t1 = maStlOffsetToolScalarAlongLineMm(ends.p1, ud.p1Mm, uLineA);
        const t2 = maStlOffsetToolScalarAlongLineMm(ends.p2, ud.p1Mm, uLineA);
        if (Number.isFinite(t1) && Number.isFinite(t2) && t1 > t2) {
            const tmp = ends.p1;
            ends.p1 = ends.p2;
            ends.p2 = tmp;
        }

        const minSpan = Math.max(maStlUserFloorSegmentMinMm() * 0.25, 1);
        const span = Math.hypot(ends.p2.x - ends.p1.x, ends.p2.z - ends.p1.z);
        if (!Number.isFinite(span) || span < minSpan) {
            return { p1: parallelP1, p2: parallelP2 };
        }
        if (!maStlOffsetToolSegmentParallelToSourceMm(ends.p1, ends.p2, ud.p1Mm, ud.p2Mm)) {
            return { p1: parallelP1, p2: parallelP2 };
        }
        return ends;
    }

    function maStlOffsetToolRefreshPreviewFromFloorPointMm(floorPt) {
        if (
            maStlOffsetToolState !== 'pickDirection' ||
            !maStlOffsetToolSourceLine ||
            !floorPt
        ) {
            maStlOffsetToolHidePreviewLine();
            return;
        }
        const primaryUd =
            maStlOffsetToolSourceLine.userData &&
            maStlOffsetToolSourceLine.userData.maStlUserPlanLine;
        if (!primaryUd || !primaryUd.p1Mm || !primaryUd.p2Mm) {
            maStlOffsetToolHidePreviewLine();
            return;
        }
        maStlOffsetToolSideSign = maStlOffsetToolSideSignFromFloorPointMm(
            primaryUd.p1Mm,
            primaryUd.p2Mm,
            floorPt
        );
        const sourceLines =
            maStlOffsetToolSourceGroupLines.length > 0
                ? maStlOffsetToolSourceGroupLines
                : [maStlOffsetToolSourceLine];
        let visibleCount = 0;
        for (let si = 0; si < sourceLines.length; si++) {
            const srcLine = sourceLines[si];
            const ends = maStlOffsetToolParallelEndpointsWithMitersMm(
                srcLine,
                maStlOffsetToolDistanceMm,
                maStlOffsetToolSideSign
            );
            const previewLine = maStlOffsetToolEnsurePreviewLineAtIndex(si);
            if (!ends || !maStlOffsetToolSyncPreviewLineGeometryMm(previewLine, ends.p1, ends.p2)) {
                previewLine.visible = false;
                continue;
            }
            previewLine.visible = true;
            visibleCount++;
        }
        for (let hi = sourceLines.length; hi < maStlOffsetToolPreviewLines.length; hi++) {
            maStlOffsetToolPreviewLines[hi].visible = false;
        }
        if (visibleCount === 0) {
            maStlOffsetToolHidePreviewLine();
        }
    }

    /**
     * Vista previa discontinua solo en `pickDirection` con cursor fuera de la línea origen
     * (screen-pick y proyección en planta).
     */
    function maStlOffsetToolShouldShowPreviewAtPointer(clientX, clientY, floorPt) {
        if (maStlOffsetToolState !== 'pickDirection' || !maStlOffsetToolSourceLine || !floorPt) {
            return false;
        }
        const lnOn = maStlPickUserFloorLineNearScreenMm(
            clientX,
            clientY,
            MA_STL_USER_FLOOR_LINE_SCREEN_PICK_PX
        );
        const sourceLines =
            maStlOffsetToolSourceGroupLines.length > 0
                ? maStlOffsetToolSourceGroupLines
                : [maStlOffsetToolSourceLine];
        for (let gi = 0; gi < sourceLines.length; gi++) {
            if (lnOn === sourceLines[gi]) return false;
        }
        const epsMm = Math.max(maStlUserFloorSegmentMinMm() * 0.35, 8);
        for (let si = 0; si < sourceLines.length; si++) {
            const ud =
                sourceLines[si].userData && sourceLines[si].userData.maStlUserPlanLine;
            if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
            if (maStlOffsetToolFloorPointOnSourceLineMm(floorPt, ud.p1Mm, ud.p2Mm, epsMm)) {
                return false;
            }
        }
        return true;
    }

    function maStlOffsetToolSyncPreviewAtPointer(clientX, clientY) {
        const p = maStlResolveLineToolFloorPointMm(clientX, clientY);
        if (!p || !maStlOffsetToolShouldShowPreviewAtPointer(clientX, clientY, p)) {
            maStlOffsetToolHidePreviewLine();
            return;
        }
        maStlOffsetToolRefreshPreviewFromFloorPointMm(p);
    }

    function maStlOffsetToolSyncDistanceInputFromMm(mm) {
        if (!(maStlOffsetToolHudDistanceInput instanceof HTMLInputElement)) return;
        maStlOffsetToolHudDistanceInput.value = maStlDesing2DimEditableMetersDisplayFromMm(
            maStlClampDesing2OffsetDefaultMm(mm)
        );
    }

    function maStlOffsetToolRawDistanceTrimmed() {
        return maStlOffsetToolHudDistanceInput
            ? String(maStlOffsetToolHudDistanceInput.value || '').trim()
            : '';
    }

    function maStlOffsetToolTryApplyDistanceFromInput(showToastOnInvalid) {
        const parsed = maStlParseLengthInputValueToMm(maStlOffsetToolRawDistanceTrimmed());
        if (parsed == null || !Number.isFinite(parsed) || parsed <= 0) {
            if (showToastOnInvalid) {
                const toastTpl =
                    maStlOffsetToolHud &&
                    maStlOffsetToolHud.getAttribute('data-ma-stl-offset-tool-distance-invalid-toast');
                if (toastTpl) maStlDesing2ShowSaveViewToast(toastTpl);
            }
            maStlOffsetToolSyncDistanceInputFromMm(maStlOffsetToolDistanceMm);
            return false;
        }
        maStlOffsetToolDistanceMm = maStlClampDesing2OffsetDefaultMm(parsed);
        maStlOffsetToolSyncDistanceInputFromMm(maStlOffsetToolDistanceMm);
        if (maStlOffsetToolState === 'pickDirection' && renderer) {
            const cx = maStlLineToolLastPointerClientXY.x;
            const cy = maStlLineToolLastPointerClientXY.y;
            if (Number.isFinite(cx) && Number.isFinite(cy)) {
                maStlOffsetToolSyncPreviewAtPointer(cx, cy);
            }
        }
        return true;
    }

    function maStlSyncOffsetToolHud() {
        if (!maStlOffsetToolHud || !maStlDesingV2Viewer) return;
        if (!maStlIsOffsetToolActive()) {
            maStlOffsetToolHud.classList.add('d-none');
            if (maStlOffsetToolHudInstruction) maStlOffsetToolHudInstruction.textContent = '';
            if (maStlOffsetToolHudDistanceRow) maStlOffsetToolHudDistanceRow.classList.add('d-none');
            return;
        }
        if (maStlOffsetToolState === 'pickLine') {
            maStlOffsetToolHud.classList.add('d-none');
            if (maStlOffsetToolHudInstruction) maStlOffsetToolHudInstruction.textContent = '';
            if (maStlOffsetToolHudDistanceRow) maStlOffsetToolHudDistanceRow.classList.add('d-none');
            return;
        }
        const insPickDir =
            (maStlOffsetToolHud &&
                maStlOffsetToolHud.getAttribute('data-ma-stl-offset-tool-instruction-pick-direction')) ||
            '';
        if (maStlOffsetToolHudInstruction) {
            maStlOffsetToolHudInstruction.textContent = insPickDir;
        }
        const showDistanceRow =
            maStlOffsetToolDistanceRowForced || maStlOffsetToolState === 'pickDirection';
        if (maStlOffsetToolHudDistanceRow) {
            maStlOffsetToolHudDistanceRow.classList.toggle('d-none', !showDistanceRow);
        }
        if (showDistanceRow) {
            maStlOffsetToolSyncDistanceInputFromMm(maStlOffsetToolDistanceMm);
        }
        maStlOffsetToolHud.classList.remove('d-none');
    }

    function maStlOffsetToolSelectSourceLine(line) {
        if (!line || !maStlIsUserFloorPlanLineObject(line)) return;
        maStlOffsetToolHidePreviewLine();
        maStlOffsetToolHighlightSourceLine(line);
        maStlOffsetToolState = 'pickDirection';
        maStlOffsetToolDistanceRowForced = false;
        maStlOffsetToolClearTransientOverlays();
        maStlSyncOffsetToolHud();
    }

    function maStlOffsetToolCommitOneParallelCopyMm(
        sourceLine,
        offsetMm,
        sideSign,
        skipUndo,
        polylineGroupIdForNew
    ) {
        if (!sourceLine || !maStlIsUserFloorPlanLineObject(sourceLine)) return false;
        const ud = sourceLine.userData && sourceLine.userData.maStlUserPlanLine;
        if (!ud || !ud.p1Mm || !ud.p2Mm) return false;
        const ends = maStlOffsetToolParallelEndpointsWithMitersMm(sourceLine, offsetMm, sideSign);
        if (!ends) return false;
        const childCountBefore = maStlUserLinesGroup ? maStlUserLinesGroup.children.length : 0;
        maStlCommitUserPlanLineSegmentMm(ends.p1, ends.p2, skipUndo, polylineGroupIdForNew);
        if (maStlUserLinesGroup && ud.id != null) {
            for (let ci = childCountBefore; ci < maStlUserLinesGroup.children.length; ci++) {
                const newLine = maStlUserLinesGroup.children[ci];
                const newUd =
                    newLine && newLine.userData && newLine.userData.maStlUserPlanLine;
                if (!newUd) continue;
                newUd.linkOffsetFromLineId = ud.id;
                newUd.numberOffsetMm = offsetMm;
            }
        }
        return true;
    }

    function maStlOffsetToolCommitParallelCopyMm(sourceLine, offsetMm, sideSign) {
        const groupLines =
            maStlOffsetToolSourceGroupLines.length > 0
                ? maStlOffsetToolSourceGroupLines.slice()
                : maStlResolvePolylineGroupLinesForLine(sourceLine);
        if (groupLines.length <= 1) {
            return maStlOffsetToolCommitOneParallelCopyMm(
                sourceLine,
                offsetMm,
                sideSign,
                false,
                maStlUserFloorLineNextPolylineGroupId++
            );
        }
        const undoBefore = maStlDesingV2Viewer ? maStlDesing2SerializeEditSnapshot() : null;
        const offsetGroupId = maStlUserFloorLineNextPolylineGroupId++;
        let ok = false;
        for (let gi = 0; gi < groupLines.length; gi++) {
            if (
                maStlOffsetToolCommitOneParallelCopyMm(
                    groupLines[gi],
                    offsetMm,
                    sideSign,
                    true,
                    offsetGroupId
                )
            ) {
                ok = true;
            }
        }
        if (ok && undoBefore) {
            maStlDesing2PushEditSnapshotUndo(
                'createUserFloorLine',
                undoBefore,
                maStlDesing2SerializeEditSnapshot()
            );
        }
        return ok;
    }

    /** Activa offset Desing_2 → `pickLine`; clic línea → `pickDirection` → clic dirección confirma copia. */
    function maStlStartOffsetToolModesToolbar() {
        if (maStlIsOffsetToolActive()) return;
        maStlWall2dToolResumeState = null;
        if (maStlIsWall2dToolActive()) maStlStopWall2dToolModesToolbar(false);
        if (maStlIsLineToolPlacementActive()) maStlStopLineToolModesToolbar(false);
        if (maStlIsDeleteToolActive()) maStlStopDeleteToolModesToolbar(false);
        if (maStlIsDupMoveToolActive()) maStlStopCopyToolModesToolbar(false);
        if (maStlIsWall3dToolActive()) maStlStopWall3dToolModesToolbar(false);
        if (maStlIsImageSketchToolActive()) maStlStopImageSketchToolModesToolbar(false);
        if (maStlIsInsertCornerToolActive()) maStlStopInsertCornerToolModesToolbar(false);
        if (maStlIsInsertEnclosureToolActive()) maStlStopInsertEnclosureToolModesToolbar(false);
        if (maStlIsImageSketchToolActive()) maStlStopImageSketchToolModesToolbar(false);
        maStlStopWallDimToolModesToolbar();
        maStlDesing2SetLastToolbarCommandId('ma-stl-tool-offset');
        maStlStopRulerAnchorPickModesToolbar();
        maStlTeardownPickHighlightsOnly();
        maStlClearUserFloorLineSelection();
        maStlHideUserFloorLineDimHud(true);
        maStlClearUserFloorEndpointDragSnapPreview();
        maStlOffsetToolResetSessionState();
        maStlOffsetToolState = 'pickLine';
        maStlLockOrbitForRulerAnchorPick();
        maStlSyncLineToolToggleBtnUi();
        maStlLineToolPickCursorSync();
        maStlSyncOffsetToolHud();
        if (maStlOffsetToolToggleBtn && document.activeElement === maStlOffsetToolToggleBtn) {
            maStlOffsetToolToggleBtn.blur();
        }
    }

    /** @param {boolean} deferOrbitUnlock reservado; salida completa rehabilita órbita al instante. */
    function maStlStopOffsetToolModesToolbar(deferOrbitUnlock) {
        void deferOrbitUnlock;
        if (!maStlOffsetToolState) return;
        maStlOffsetToolState = null;
        maStlOffsetToolResetSessionState();
        maStlOffsetToolHidePreviewLine();
        maStlOffsetToolClearTransientOverlays();
        maStlSyncOffsetToolHud();
        maStlSyncLineToolToggleBtnUi();
        maStlLineToolPickCursorSync();
        syncMaStlRulerAnchorPickCursor();
        maStlUnlockOrbitForRulerAnchorPick(true);
    }

    function maStlIsDeletableStlMesh(mesh) {
        return !!(mesh && mesh.isMesh && clipStlMeshes.indexOf(mesh) >= 0);
    }

    function maStlDeleteToolEnsureStlMeshMaterialSnapshot(mesh) {
        if (!mesh || !mesh.material || maStlDeleteToolStlMeshMaterialSnapshots.has(mesh)) return;
        maStlDeleteToolStlMeshMaterialSnapshots.set(mesh, {
            opacity: mesh.material.opacity,
            transparent: mesh.material.transparent,
            color: mesh.material.color.clone(),
            emissive: mesh.material.emissive
                ? mesh.material.emissive.clone()
                : new THREE.Color(0x000000),
            emissiveIntensity:
                mesh.material.emissiveIntensity != null ? mesh.material.emissiveIntensity : 0,
        });
    }

    function maStlDeleteToolRestoreStlMeshMaterial(mesh) {
        const snap = maStlDeleteToolStlMeshMaterialSnapshots.get(mesh);
        if (!mesh || !mesh.material || !snap) return;
        mesh.material.opacity = snap.opacity;
        mesh.material.transparent = snap.transparent;
        mesh.material.color.copy(snap.color);
        if (mesh.material.emissive) {
            mesh.material.emissive.copy(snap.emissive);
        }
        mesh.material.emissiveIntensity = snap.emissiveIntensity;
        mesh.material.needsUpdate = true;
        maStlDeleteToolStlMeshMaterialSnapshots.delete(mesh);
    }

    /** Herramienta borrar: malla STL seleccionada a 50 % opacity. */
    function maStlDeleteToolApplyStlMeshDeletePickMaterial(mesh) {
        if (!mesh || !mesh.material) return;
        maStlDeleteToolEnsureStlMeshMaterialSnapshot(mesh);
        mesh.material.opacity = MA_STL_DELETE_TOOL_PICK_OPACITY;
        mesh.material.transparent = true;
        mesh.material.needsUpdate = true;
    }

    /** Hover borrar sobre malla no seleccionada (emissive azul, mismo criterio que pick objeto). */
    function maStlDeleteToolApplyStlMeshHoverMaterial(mesh) {
        if (!mesh || !mesh.material) return;
        maStlDeleteToolEnsureStlMeshMaterialSnapshot(mesh);
        mesh.material.emissive.setHex(MA_STL_PICK_HOVER_EMISSIVE_HEX);
        mesh.material.emissiveIntensity = MA_STL_PICK_HOVER_EMISSIVE_INTENSITY;
        mesh.material.color.lerp(_maStlPickHoverColor, MA_STL_PICK_HOVER_COLOR_LERP);
        mesh.material.needsUpdate = true;
    }

    function maStlDetachStlMeshToGraveyard(mesh) {
        if (!mesh) return;
        maStlDeleteToolRestoreStlMeshMaterial(mesh);
        const idx = clipStlMeshes.indexOf(mesh);
        if (idx >= 0) clipStlMeshes.splice(idx, 1);
        if (mesh.parent) mesh.parent.remove(mesh);
        maStlStlMeshGraveyard.set(mesh.uuid, mesh);
    }

    function maStlRestoreStlMeshFromGraveyard(uuid) {
        const mesh = maStlStlMeshGraveyard.get(uuid);
        if (!mesh) return null;
        maStlStlMeshGraveyard.delete(uuid);
        if (currentRoot) currentRoot.add(mesh);
        if (clipStlMeshes.indexOf(mesh) < 0) clipStlMeshes.push(mesh);
        return mesh;
    }

    /** Restaura presencia de mallas STL según lista de uuids (undo/redo). */
    function maStlDesing2ApplyStlMeshSnapshotFromUuids(uuids) {
        const want = new Set(uuids || []);
        const toRemove = [];
        for (let i = 0; i < clipStlMeshes.length; i++) {
            const sm = clipStlMeshes[i];
            if (!want.has(sm.uuid)) toRemove.push(sm);
        }
        for (let ri = 0; ri < toRemove.length; ri++) {
            maStlDetachStlMeshToGraveyard(toRemove[ri]);
        }
        want.forEach(function (uuid) {
            let present = false;
            for (let pi = 0; pi < clipStlMeshes.length; pi++) {
                if (clipStlMeshes[pi].uuid === uuid) {
                    present = true;
                    break;
                }
            }
            if (!present) maStlRestoreStlMeshFromGraveyard(uuid);
        });
        updateClipPlanes();
        syncGroundShadowToggleUi();
        if (currentRoot && clipStlMeshes.length > 0) {
            refitCamerasToObject(currentRoot);
        }
    }

    function maStlDeleteToolLineIsSelected(line) {
        return !!(line && maStlDeleteToolSelectedLines.has(line));
    }

    function maStlDeleteToolClearHoverLine() {
        if (
            maStlDeleteToolHoverLine &&
            !maStlDeleteToolLineIsSelected(maStlDeleteToolHoverLine) &&
            maStlDeleteToolHoverLine.material
        ) {
            maStlApplyUserFloorLineBaseMaterialForLine(maStlDeleteToolHoverLine);
        }
        maStlDeleteToolHoverLine = null;
    }

    function maStlDeleteToolClearHoverMesh() {
        if (
            maStlDeleteToolHoverMesh &&
            !maStlDeleteToolMeshIsSelected(maStlDeleteToolHoverMesh)
        ) {
            maStlDeleteToolRestoreStlMeshMaterial(maStlDeleteToolHoverMesh);
        }
        maStlDeleteToolHoverMesh = null;
    }

    function maStlDeleteToolMeshIsSelected(mesh) {
        return !!(mesh && maStlDeleteToolSelectedMeshes.has(mesh));
    }

    function maStlRectPxFromDrag(x0, y0, x1, y1) {
        return {
            left: Math.min(x0, x1),
            right: Math.max(x0, x1),
            top: Math.min(y0, y1),
            bottom: Math.max(y0, y1),
            crossing: x1 < x0,
        };
    }

    function maStlPointInRectPx(px, py, rect) {
        return px >= rect.left && px <= rect.right && py >= rect.top && py <= rect.bottom;
    }

    function maStlOrient2dPx(ax, ay, bx, by, cx, cy) {
        const v = (by - ay) * (cx - bx) - (bx - ax) * (cy - by);
        if (Math.abs(v) < 1e-9) return 0;
        return v > 0 ? 1 : 2;
    }

    function maStlPointOnSegment2dPx(px, py, ax, ay, bx, by) {
        return (
            Math.min(ax, bx) - 1e-9 <= px &&
            px <= Math.max(ax, bx) + 1e-9 &&
            Math.min(ay, by) - 1e-9 <= py &&
            py <= Math.max(ay, by) + 1e-9
        );
    }

    function maStlSegmentsIntersect2dPx(ax, ay, bx, by, cx, cy, dx, dy) {
        const o1 = maStlOrient2dPx(ax, ay, bx, by, cx, cy);
        const o2 = maStlOrient2dPx(ax, ay, bx, by, dx, dy);
        const o3 = maStlOrient2dPx(cx, cy, dx, dy, ax, ay);
        const o4 = maStlOrient2dPx(cx, cy, dx, dy, bx, by);
        if (o1 !== o2 && o3 !== o4) return true;
        if (o1 === 0 && maStlPointOnSegment2dPx(cx, cy, ax, ay, bx, by)) return true;
        if (o2 === 0 && maStlPointOnSegment2dPx(dx, dy, ax, ay, bx, by)) return true;
        if (o3 === 0 && maStlPointOnSegment2dPx(ax, ay, cx, cy, dx, dy)) return true;
        if (o4 === 0 && maStlPointOnSegment2dPx(bx, by, cx, cy, dx, dy)) return true;
        return false;
    }

    function maStlSegmentIntersectsRectPx(ax, ay, bx, by, rect) {
        if (maStlPointInRectPx(ax, ay, rect) || maStlPointInRectPx(bx, by, rect)) return true;
        const edges = [
            [rect.left, rect.top, rect.right, rect.top],
            [rect.right, rect.top, rect.right, rect.bottom],
            [rect.right, rect.bottom, rect.left, rect.bottom],
            [rect.left, rect.bottom, rect.left, rect.top],
        ];
        for (let ei = 0; ei < edges.length; ei++) {
            const e = edges[ei];
            if (maStlSegmentsIntersect2dPx(ax, ay, bx, by, e[0], e[1], e[2], e[3])) return true;
        }
        return false;
    }

    function maStlRectsOverlapPx(a, b) {
        return !(a.right < b.left || a.left > b.right || a.bottom < b.top || a.top > b.bottom);
    }

    function maStlRectFullyContainsRectPx(outer, inner) {
        return (
            inner.left >= outer.left &&
            inner.right <= outer.right &&
            inner.top >= outer.top &&
            inner.bottom <= outer.bottom
        );
    }

    const _maStlWindowSelectionMeshBox = new THREE.Box3();
    const _maStlWindowSelectionMeshCorner = new THREE.Vector3();

    /** Proyecta AABB mundo de malla a rect pantalla (client px). @returns {boolean} */
    function maStlDesing2MeshScreenBoundsPx(mesh, outMin, outMax) {
        if (!mesh || !renderer || !activeCamera()) return false;
        mesh.updateMatrixWorld(true);
        _maStlWindowSelectionMeshBox.setFromObject(mesh);
        if (_maStlWindowSelectionMeshBox.isEmpty()) return false;
        const min = _maStlWindowSelectionMeshBox.min;
        const max = _maStlWindowSelectionMeshBox.max;
        let any = false;
        let minX = Infinity;
        let minY = Infinity;
        let maxX = -Infinity;
        let maxY = -Infinity;
        for (let xi = 0; xi < 2; xi++) {
            for (let yi = 0; yi < 2; yi++) {
                for (let zi = 0; zi < 2; zi++) {
                    _maStlWindowSelectionMeshCorner.set(
                        xi ? max.x : min.x,
                        yi ? max.y : min.y,
                        zi ? max.z : min.z
                    );
                    const scr = {};
                    if (!maStlWorldMmToScreenPx(
                        _maStlWindowSelectionMeshCorner.x,
                        _maStlWindowSelectionMeshCorner.y,
                        _maStlWindowSelectionMeshCorner.z,
                        scr
                    )) {
                        continue;
                    }
                    any = true;
                    if (scr.x < minX) minX = scr.x;
                    if (scr.y < minY) minY = scr.y;
                    if (scr.x > maxX) maxX = scr.x;
                    if (scr.y > maxY) maxY = scr.y;
                }
            }
        }
        if (!any) return false;
        outMin.x = minX;
        outMin.y = minY;
        outMax.x = maxX;
        outMax.y = maxY;
        return true;
    }

    /**
     * Calcula líneas usuario y mallas STL dentro del rect marquee (ventana o cruce).
     * @param {{ left: number, right: number, top: number, bottom: number, crossing: boolean }} rect
     * @param {{ filterLine?: (line: THREE.Line2) => boolean, filterMesh?: (mesh: THREE.Mesh) => boolean }=} pickOptions
     * @returns {{ lines: THREE.Line2[], meshes: THREE.Mesh[], mode: 'window'|'crossing' }}
     */
    function maStlDesing2ComputeWindowSelectionHits(rect, pickOptions) {
        const opts = pickOptions || {};
        const filterLine =
            typeof opts.filterLine === 'function'
                ? opts.filterLine
                : maStlIsUserFloorPlanLineObject;
        const filterMesh = typeof opts.filterMesh === 'function' ? opts.filterMesh : function () {
            return true;
        };
        const crossing = !!(rect && rect.crossing);
        const mode = crossing ? 'crossing' : 'window';
        const lines = [];
        const meshes = [];
        const meshScrMin = { x: 0, y: 0 };
        const meshScrMax = { x: 0, y: 0 };
        if (maStlUserLinesGroup) {
            const ch = maStlUserLinesGroup.children;
            for (let li = 0; li < ch.length; li++) {
                const line = ch[li];
                const ud = line.userData && line.userData.maStlUserPlanLine;
                if (!filterLine(line) || !ud || !ud.p1Mm || !ud.p2Mm) continue;
                const sp1 = {};
                const sp2 = {};
                if (!maStlWorldMmToScreenPx(ud.p1Mm.x, ud.p1Mm.y, ud.p1Mm.z, sp1)) continue;
                if (!maStlWorldMmToScreenPx(ud.p2Mm.x, ud.p2Mm.y, ud.p2Mm.z, sp2)) continue;
                let hit = false;
                if (crossing) {
                    hit = maStlSegmentIntersectsRectPx(sp1.x, sp1.y, sp2.x, sp2.y, rect);
                } else {
                    hit =
                        maStlPointInRectPx(sp1.x, sp1.y, rect) &&
                        maStlPointInRectPx(sp2.x, sp2.y, rect);
                }
                if (hit) lines.push(line);
            }
        }
        for (let mi = 0; mi < clipStlMeshes.length; mi++) {
            const mesh = clipStlMeshes[mi];
            if (!filterMesh(mesh)) continue;
            if (!maStlDesing2MeshScreenBoundsPx(mesh, meshScrMin, meshScrMax)) continue;
            const meshRect = {
                left: meshScrMin.x,
                top: meshScrMin.y,
                right: meshScrMax.x,
                bottom: meshScrMax.y,
            };
            let hit = false;
            if (crossing) {
                hit = maStlRectsOverlapPx(rect, meshRect);
            } else {
                hit = maStlRectFullyContainsRectPx(rect, meshRect);
            }
            if (hit) meshes.push(mesh);
        }
        return { lines: lines, meshes: meshes, mode: mode };
    }

    function maStlDesing2IsWindowSelectionActive() {
        return maStlWindowSelectionSession != null;
    }

    function maStlDesing2IsWindowSelectionBusy() {
        const s = maStlWindowSelectionSession;
        return !!(s && (s.pending || s.active));
    }

    function maStlDesing2EnsureWindowSelectionMarqueeEl() {
        if (maStlWindowSelectionMarqueeEl) return maStlWindowSelectionMarqueeEl;
        const el = document.createElement('div');
        el.id = 'ma-stl-window-selection-marquee';
        el.className = 'desing2-stl-window-selection-marquee d-none';
        el.setAttribute('aria-hidden', 'true');
        document.body.appendChild(el);
        maStlWindowSelectionMarqueeEl = el;
        return el;
    }

    function maStlDesing2HideWindowSelectionMarqueeEl() {
        const el = maStlWindowSelectionMarqueeEl;
        if (!el) return;
        el.classList.add('d-none');
        el.classList.remove('desing2-stl-window-selection-marquee--crossing');
        el.setAttribute('aria-hidden', 'true');
        el.style.left = '';
        el.style.top = '';
        el.style.width = '';
        el.style.height = '';
    }

    function maStlDesing2UnwireWindowSelectionWindowListeners() {
        if (maStlWindowSelectionWindowMoveHandler) {
            window.removeEventListener('pointermove', maStlWindowSelectionWindowMoveHandler, true);
            maStlWindowSelectionWindowMoveHandler = null;
        }
        if (maStlWindowSelectionWindowUpHandler) {
            window.removeEventListener('pointerup', maStlWindowSelectionWindowUpHandler, true);
            window.removeEventListener('pointercancel', maStlWindowSelectionWindowUpHandler, true);
            maStlWindowSelectionWindowUpHandler = null;
        }
    }

    function maStlDesing2CancelWindowSelectionDrag(releaseCapture) {
        const s = maStlWindowSelectionSession;
        const capturePid =
            (s && s.active && s.active.pointerId) || (s && s.pending && s.pending.pointerId);
        if (s) {
            s.pending = null;
            s.active = null;
        }
        maStlDesing2HideWindowSelectionMarqueeEl();
        maStlDesing2UnwireWindowSelectionWindowListeners();
        if (releaseCapture && renderer && renderer.domElement && capturePid != null) {
            try {
                renderer.domElement.releasePointerCapture(capturePid);
            } catch (_e) {
                /* sin captura activa */
            }
        }
    }

    function maStlDesing2UpdateWindowSelectionMarqueeVisual(x0, y0, x1, y1) {
        const rect = maStlRectPxFromDrag(x0, y0, x1, y1);
        const el = maStlDesing2EnsureWindowSelectionMarqueeEl();
        el.classList.remove('d-none');
        el.setAttribute('aria-hidden', 'false');
        el.classList.toggle('desing2-stl-window-selection-marquee--crossing', rect.crossing);
        el.style.left = rect.left + 'px';
        el.style.top = rect.top + 'px';
        el.style.width = Math.max(rect.right - rect.left, 1) + 'px';
        el.style.height = Math.max(rect.bottom - rect.top, 1) + 'px';
        return rect;
    }

    function maStlDesing2FinishWindowSelectionDrag(clientX, clientY, pointerId) {
        const s = maStlWindowSelectionSession;
        if (!s) return;
        const active = s.active;
        const pending = s.pending;
        const pid = pointerId != null ? pointerId : active ? active.pointerId : pending ? pending.pointerId : -1;
        if (active && (pid < 0 || active.pointerId === pid)) {
            const rect = maStlDesing2UpdateWindowSelectionMarqueeVisual(active.x0, active.y0, clientX, clientY);
            const hits = maStlDesing2ComputeWindowSelectionHits(rect, {
                filterLine: s.options.filterLine,
                filterMesh: s.options.filterMesh,
            });
            if (typeof s.options.onSelectionComplete === 'function') {
                s.options.onSelectionComplete(hits.lines, hits.meshes, hits.mode);
            }
            /* Evitar clic fantasma tras marquee; no bloquear clic si el rect quedó degenerado. */
            const rectW = Math.max(rect.right - rect.left, 0);
            const rectH = Math.max(rect.bottom - rect.top, 0);
            s.suppressClick = rectW >= 1 && rectH >= 1;
        }
        maStlDesing2CancelWindowSelectionDrag(true);
    }

    function maStlDesing2WireWindowSelectionWindowListeners() {
        if (maStlWindowSelectionWindowMoveHandler) return;
        maStlWindowSelectionWindowMoveHandler = function (ev) {
            const s = maStlWindowSelectionSession;
            if (!s || (typeof s.options.enabled === 'function' && !s.options.enabled())) {
                maStlDesing2CancelWindowSelectionDrag(false);
                return;
            }
            const pending = s.pending;
            const active = s.active;
            if (!pending && !active) return;
            const pid = pending ? pending.pointerId : active.pointerId;
            if (ev.pointerId !== pid) return;
            ev.preventDefault();
            if (pending && !active) {
                const dx = ev.clientX - pending.x0;
                const dy = ev.clientY - pending.y0;
                if (
                    dx * dx + dy * dy <
                    MA_STL_WINDOW_SELECTION_DRAG_THRESHOLD_PX * MA_STL_WINDOW_SELECTION_DRAG_THRESHOLD_PX
                ) {
                    return;
                }
                s.active = {
                    x0: pending.x0,
                    y0: pending.y0,
                    x1: ev.clientX,
                    y1: ev.clientY,
                    pointerId: pending.pointerId,
                    crossing: ev.clientX < pending.x0,
                };
                s.pending = null;
                if (typeof s.options.onMarqueeDragStart === 'function') {
                    s.options.onMarqueeDragStart();
                }
                try {
                    renderer.domElement.setPointerCapture(pending.pointerId);
                } catch (_e) {
                    /* ignore */
                }
            }
            if (s.active) {
                s.active.x1 = ev.clientX;
                s.active.y1 = ev.clientY;
                s.active.crossing = ev.clientX < s.active.x0;
                maStlDesing2UpdateWindowSelectionMarqueeVisual(
                    s.active.x0,
                    s.active.y0,
                    ev.clientX,
                    ev.clientY
                );
            }
        };
        maStlWindowSelectionWindowUpHandler = function (ev) {
            const s = maStlWindowSelectionSession;
            if (!s) return;
            const pending = s.pending;
            const active = s.active;
            if (!pending && !active) return;
            const pid = pending ? pending.pointerId : active.pointerId;
            if (ev.pointerId !== pid) return;
            maStlDesing2FinishWindowSelectionDrag(ev.clientX, ev.clientY, ev.pointerId);
        };
        window.addEventListener('pointermove', maStlWindowSelectionWindowMoveHandler, true);
        window.addEventListener('pointerup', maStlWindowSelectionWindowUpHandler, true);
        window.addEventListener('pointercancel', maStlWindowSelectionWindowUpHandler, true);
    }

    /**
     * Activa sesión reutilizable de selección por ventana/cruce (marquee).
     * @param {{
     *   enabled?: () => boolean,
     *   additive?: boolean,
     *   blocksMarqueeAt?: (clientX: number, clientY: number) => boolean,
     *   filterLine?: (line: THREE.Line2) => boolean,
     *   filterMesh?: (mesh: THREE.Mesh) => boolean,
     *   onMarqueeDragStart?: () => void,
     *   onSelectionComplete?: (selectedLines: THREE.Line2[], selectedMeshes: THREE.Mesh[], mode: 'window'|'crossing') => void
     * }} options
     */
    function maStlDesing2BeginWindowSelection(options) {
        maStlDesing2EndWindowSelection();
        maStlWindowSelectionSession = {
            options: options || {},
            pending: null,
            active: null,
            suppressClick: false,
        };
    }

    /** Cierra sesión marquee y cancela arrastre pendiente. */
    function maStlDesing2EndWindowSelection() {
        maStlDesing2CancelWindowSelectionDrag(true);
        maStlWindowSelectionSession = null;
    }

    function maStlDesing2WindowSelectionShouldSuppressClick() {
        return !!(maStlWindowSelectionSession && maStlWindowSelectionSession.suppressClick);
    }

    function maStlDesing2WindowSelectionClearClickSuppression() {
        if (maStlWindowSelectionSession) {
            maStlWindowSelectionSession.suppressClick = false;
        }
    }

    /** Pointerdown en canvas vacío — inicia marquee si hay sesión activa y `enabled()`. */
    function maStlDesing2WindowSelectionPointerDown(ev) {
        const s = maStlWindowSelectionSession;
        if (!s || !maStlDesingV2Viewer) return false;
        if (typeof s.options.enabled === 'function' && !s.options.enabled()) return false;
        if (ev.button !== 0) return false;
        const canvas = renderer && renderer.domElement;
        if (!canvas || ev.currentTarget !== canvas) return false;
        const rawTarget = ev.target;
        if (rawTarget && typeof rawTarget.closest === 'function') {
            if (rawTarget.closest('button, input, select, textarea, [role="button"], label')) return false;
        }
        const blocks =
            typeof s.options.blocksMarqueeAt === 'function' &&
            s.options.blocksMarqueeAt(ev.clientX, ev.clientY);
        s.suppressClick = false;
        if (!blocks) {
            s.pending = {
                x0: ev.clientX,
                y0: ev.clientY,
                pointerId: ev.pointerId,
            };
            ev.preventDefault();
            maStlDesing2WireWindowSelectionWindowListeners();
        }
        return true;
    }

    function maStlDeleteToolPickTargetAtPointer(clientX, clientY) {
        const ln = maStlPickUserFloorLineForCanvasInteraction(clientX, clientY, 4);
        if (ln) return { kind: 'line', target: ln };
        const mesh = maStlRaycastClipStlMeshFirst(clientX, clientY);
        if (mesh && maStlIsDeletableStlMesh(mesh)) return { kind: 'mesh', target: mesh };
        return null;
    }

    function maStlDeleteToolPointerDownBlocksMarquee(clientX, clientY) {
        return maStlDeleteToolPickTargetAtPointer(clientX, clientY) != null;
    }

    function maStlDeleteToolWireWindowSelection() {
        maStlDesing2BeginWindowSelection({
            enabled: maStlIsDeleteToolActive,
            additive: true,
            blocksMarqueeAt: maStlDeleteToolPointerDownBlocksMarquee,
            filterLine: function (line) {
                return maStlIsUserFloorPlanLineSelectable(line);
            },
            filterMesh: maStlIsDeletableStlMesh,
            onMarqueeDragStart: function () {
                maStlDeleteToolClearHoverLine();
                maStlDeleteToolClearHoverMesh();
            },
            onSelectionComplete: function (selectedLines, selectedMeshes, mode) {
                void mode;
                for (let i = 0; i < selectedLines.length; i++) {
                    maStlDeleteToolAddLineSelection(selectedLines[i]);
                }
                for (let j = 0; j < selectedMeshes.length; j++) {
                    maStlDeleteToolAddMeshSelection(selectedMeshes[j]);
                }
            },
        });
    }

    function maStlDeleteToolUnwireWindowSelection() {
        maStlDesing2EndWindowSelection();
    }

    function maStlDeleteToolAddSingleLineSelection(line) {
        if (!line || !maStlIsUserFloorPlanLineObject(line) || maStlDeleteToolSelectedLines.has(line)) return;
        maStlDeleteToolSelectedLines.add(line);
        if (line.material && maStlIsUserFloorPlanLineSelectable(line)) {
            maStlApplyUserFloorLineDeletePickMaterial(
                line.material,
                maStlPlanUdForLineMaterial(line)
            );
        }
    }

    function maStlDeleteToolAddLineSelection(line) {
        if (!line || !maStlIsUserFloorPlanLineObject(line)) return;
        const ud = line.userData && line.userData.maStlUserPlanLine;
        const targets =
            ud && ud.wallGroupId != null
                ? maStlResolveWallSegmentLinesForLine(line)
                : [line];
        for (let ti = 0; ti < targets.length; ti++) {
            maStlDeleteToolAddSingleLineSelection(targets[ti]);
        }
    }

    function maStlDeleteToolAddMeshSelection(mesh) {
        if (!maStlIsDeletableStlMesh(mesh) || maStlDeleteToolSelectedMeshes.has(mesh)) return;
        maStlDeleteToolSelectedMeshes.add(mesh);
        maStlDeleteToolApplyStlMeshDeletePickMaterial(mesh);
    }

    function maStlDeleteToolSetHoverMesh(mesh) {
        if (mesh === maStlDeleteToolHoverMesh) return;
        maStlDeleteToolClearHoverMesh();
        maStlDeleteToolHoverMesh = mesh;
        if (
            maStlDeleteToolHoverMesh &&
            !maStlDeleteToolMeshIsSelected(maStlDeleteToolHoverMesh)
        ) {
            maStlDeleteToolApplyStlMeshHoverMaterial(maStlDeleteToolHoverMesh);
        }
    }

    function maStlDeleteToolSetHoverLine(line) {
        if (!maStlIsUserFloorPlanLineSelectable(line)) return;
        if (line === maStlDeleteToolHoverLine) return;
        maStlDeleteToolClearHoverLine();
        maStlDeleteToolHoverLine = line;
        if (
            maStlDeleteToolHoverLine &&
            !maStlDeleteToolLineIsSelected(maStlDeleteToolHoverLine) &&
            maStlDeleteToolHoverLine.material
        ) {
            maStlApplyUserFloorLineHoverBrightMaterialForLine(maStlDeleteToolHoverLine);
        }
    }

    function maStlDeleteToolClearSelection() {
        maStlDeleteToolSelectedLines.forEach(function (line) {
            if (line && line.material) {
                maStlApplyUserFloorLineBaseMaterialForLine(line);
            }
        });
        maStlDeleteToolSelectedLines.clear();
        maStlDeleteToolSelectedMeshes.forEach(function (mesh) {
            maStlDeleteToolRestoreStlMeshMaterial(mesh);
        });
        maStlDeleteToolSelectedMeshes.clear();
    }

    function maStlDeleteToolToggleLineSelection(line) {
        if (!line || !maStlIsUserFloorPlanLineSelectable(line)) return;
        const ud = line.userData && line.userData.maStlUserPlanLine;
        const targets =
            ud && ud.wallGroupId != null
                ? maStlResolveWallSegmentLinesForLine(line)
                : [line];
        const anySelected = targets.some(function (ln) {
            return maStlDeleteToolSelectedLines.has(ln);
        });
        if (anySelected) {
            for (let ti = 0; ti < targets.length; ti++) {
                const ln = targets[ti];
                maStlDeleteToolSelectedLines.delete(ln);
                if (ln.material) {
                    if (ln === maStlDeleteToolHoverLine) {
                        maStlApplyUserFloorLineHoverBrightMaterialForLine(ln);
                    } else {
                        maStlApplyUserFloorLineBaseMaterialForLine(ln);
                    }
                }
            }
            return;
        }
        for (let aj = 0; aj < targets.length; aj++) {
            const ln = targets[aj];
            maStlDeleteToolSelectedLines.add(ln);
            if (ln.material && maStlIsUserFloorPlanLineSelectable(ln)) {
                maStlApplyUserFloorLineDeletePickMaterial(
                    ln.material,
                    maStlPlanUdForLineMaterial(ln)
                );
            }
        }
    }

    function maStlSyncDeleteToolHud() {
        if (!maStlDeleteToolHud || !maStlDesingV2Viewer) return;
        if (!maStlIsDeleteToolActive()) {
            maStlDeleteToolHud.classList.add('d-none');
            if (maStlDeleteToolHudInstruction) maStlDeleteToolHudInstruction.textContent = '';
            return;
        }
        const insTpl =
            (maStlDeleteToolHud &&
                maStlDeleteToolHud.getAttribute('data-ma-stl-delete-tool-instruction')) ||
            '';
        if (maStlDeleteToolHudInstruction) {
            maStlDeleteToolHudInstruction.textContent = insTpl;
        }
        maStlDeleteToolHud.classList.remove('d-none');
    }

    function maStlDeleteToolToggleMeshSelection(mesh) {
        if (!maStlIsDeletableStlMesh(mesh)) return;
        if (maStlDeleteToolSelectedMeshes.has(mesh)) {
            maStlDeleteToolSelectedMeshes.delete(mesh);
            if (mesh === maStlDeleteToolHoverMesh) {
                maStlDeleteToolApplyStlMeshHoverMaterial(mesh);
            } else {
                maStlDeleteToolRestoreStlMeshMaterial(mesh);
            }
            return;
        }
        maStlDeleteToolSelectedMeshes.add(mesh);
        maStlDeleteToolApplyStlMeshDeletePickMaterial(mesh);
    }

    function maStlCommitUserFloorLinesAndStlMeshesDelete(linesToRemove, meshesToRemove) {
        const lineList = [];
        const meshList = [];
        for (let li = 0; li < linesToRemove.length; li++) {
            const ln = linesToRemove[li];
            const expanded = maStlDesing2ExpandLinesWithWallGroups([ln]);
            for (let ei = 0; ei < expanded.length; ei++) {
                const exLine = expanded[ei];
                if (exLine && exLine.parent === maStlUserLinesGroup && lineList.indexOf(exLine) < 0) {
                    lineList.push(exLine);
                }
            }
        }
        for (let mi = 0; mi < meshesToRemove.length; mi++) {
            const mesh = meshesToRemove[mi];
            if (mesh && meshList.indexOf(mesh) < 0) {
                meshList.push(mesh);
            }
        }
        if (lineList.length === 0 && meshList.length === 0) return false;

        const undoBefore = maStlDesing2SerializeEditSnapshot();
        for (let di = 0; di < lineList.length; di++) {
            const ln = lineList[di];
            maStlDeleteToolSelectedLines.delete(ln);
            maStlWall3dToolSelectedLines.delete(ln);
            if (ln === maStlDeleteToolHoverLine) maStlDeleteToolHoverLine = null;
            if (ln === maStlWall3dToolHoverLine) maStlWall3dToolHoverLine = null;
            maStlDisposeUserFloorPlanLineObject(ln);
        }
        for (let mj = 0; mj < meshList.length; mj++) {
            const mesh = meshList[mj];
            maStlDeleteToolSelectedMeshes.delete(mesh);
            if (mesh === maStlDeleteToolHoverMesh) maStlDeleteToolHoverMesh = null;
            maStlDetachStlMeshToGraveyard(mesh);
        }
        updateClipPlanes();
        syncGroundShadowToggleUi();
        if (currentRoot && clipStlMeshes.length > 0) {
            refitCamerasToObject(currentRoot);
        }
        maStlDesing2PushEditSnapshotUndo(
            'deleteUserFloorLinesAndStlMeshes',
            undoBefore,
            maStlDesing2SerializeEditSnapshot()
        );
        return true;
    }

    function maStlDesing2CollectDeleteKeyTargets() {
        const lines = [];
        const meshes = [];
        if (maStlIsDeleteToolActive()) {
            maStlDeleteToolSelectedLines.forEach(function (ln) {
                lines.push(ln);
            });
            maStlDeleteToolSelectedMeshes.forEach(function (mesh) {
                meshes.push(mesh);
            });
            return { lines: lines, meshes: meshes };
        }
        if (maStlIsWall3dToolActive() && maStlWall3dToolSelectedLines.size > 0) {
            maStlWall3dToolSelectedLines.forEach(function (ln) {
                lines.push(ln);
            });
            return { lines: lines, meshes: meshes };
        }
        if (maStlUserFloorLineSelected) {
            lines.push(
                ...maStlDesing2ExpandLinesWithWallGroups([maStlUserFloorLineSelected])
            );
        }
        return { lines: lines, meshes: meshes };
    }

    function maStlDeleteToolCommitSelection() {
        if (
            !maStlIsDeleteToolActive() ||
            (maStlDeleteToolSelectedLines.size === 0 && maStlDeleteToolSelectedMeshes.size === 0)
        ) {
            return false;
        }
        const linesToRemove = Array.from(maStlDeleteToolSelectedLines);
        const meshesToRemove = Array.from(maStlDeleteToolSelectedMeshes);
        maStlDeleteToolSelectedLines.clear();
        maStlDeleteToolSelectedMeshes.clear();
        maStlDeleteToolHoverLine = null;
        maStlDeleteToolHoverMesh = null;
        const ok = maStlCommitUserFloorLinesAndStlMeshesDelete(linesToRemove, meshesToRemove);
        if (ok) maStlStopDeleteToolModesToolbar(false);
        return ok;
    }

    /** @deprecated alias — usar {@link maStlDeleteToolCommitSelection}. */
    function maStlDeleteToolCommitSelectedLines() {
        return maStlDeleteToolCommitSelection();
    }

    /** Enter/Espacio con herramienta borrar activa confirma eliminación (no repite último comando). */
    function maStlDeleteToolApplyWindowKeydownConfirm(ev) {
        if (!maStlIsDeleteToolActive() || !maStlDesingV2Viewer) return false;
        if (!maStlIsDesing2ViewerShellVisibleForKeyboardShortcuts()) return false;
        if (ev.defaultPrevented) return false;
        const isEnter = ev.key === 'Enter' || ev.code === 'Enter' || ev.key === 'NumpadEnter';
        const isSpace = ev.key === ' ' || ev.code === 'Space';
        if (!isEnter && !isSpace) return false;
        if (ev.shiftKey || ev.ctrlKey || ev.metaKey || ev.altKey) return false;
        const ae = document.activeElement;
        if (maStlIsUserFloorLineDimEditOverlayActive()) return false;
        if (maStlDesingV2AvoidKeyboardShortcutSteal(ae)) return false;
        if (
            maStlDeleteToolSelectedLines.size === 0 &&
            maStlDeleteToolSelectedMeshes.size === 0
        ) {
            return false;
        }
        ev.preventDefault();
        return maStlDeleteToolCommitSelection();
    }

    /**
     * Supr (Delete): borra la selección actual sin exigir modo borrar activo.
     * Con modo borrar activo confirma el conjunto pendiente; si no, línea de planta seleccionada
     * o líneas del modo muro 3D.
     * @returns {boolean}
     */
    function maStlApplyWindowKeydownDeleteKey(ev) {
        if (ev.key !== 'Delete' && ev.code !== 'Delete') return false;
        if (!maStlDesingV2Viewer) return false;
        if (!maStlIsDesing2ViewerShellVisibleForKeyboardShortcuts()) return false;
        if (ev.defaultPrevented) return false;
        if (ev.shiftKey || ev.ctrlKey || ev.metaKey || ev.altKey) return false;
        const ae = document.activeElement;
        if (maStlIsUserFloorLineDimEditOverlayActive()) return false;
        if (maStlDesingV2AvoidKeyboardShortcutSteal(ae)) return false;

        if (maStlIsDupMoveToolActive()) return false;

        if (maStlIsDeleteToolActive()) {
            if (
                maStlDeleteToolSelectedLines.size === 0 &&
                maStlDeleteToolSelectedMeshes.size === 0
            ) {
                return false;
            }
            ev.preventDefault();
            return maStlDeleteToolCommitSelection();
        }

        if (
            maStlIsLineToolPlacementActive() ||
            maStlIsOffsetToolActive() ||
            maStlIsRulerAnchorPickModeActive() ||
            maStlIsInsertCornerToolPlacementActive() ||
            maStlIsInsertEnclosureToolPlacementActive() ||
            maStlIsImageSketchToolPlacementActive()
        ) {
            return false;
        }

        const targets = maStlDesing2CollectDeleteKeyTargets();
        if (targets.lines.length === 0 && targets.meshes.length === 0) return false;

        ev.preventDefault();
        if (maStlIsWall3dToolActive()) {
            maStlWall3dToolClearHoverLine();
            maStlWall3dToolSelectedLines.clear();
        }
        return maStlCommitUserFloorLinesAndStlMeshesDelete(targets.lines, targets.meshes);
    }

    /** Activa borrar Desing_2 → pick multi-selección; Enter/Espacio/Supr confirma, Escape cancela. */
    function maStlStartDeleteToolModesToolbar() {
        if (maStlIsDeleteToolActive()) return;
        maStlWall2dToolResumeState = null;
        if (maStlIsWall2dToolActive()) maStlStopWall2dToolModesToolbar(false);
        if (maStlIsLineToolPlacementActive()) maStlStopLineToolModesToolbar(false);
        if (maStlIsOffsetToolActive()) maStlStopOffsetToolModesToolbar(false);
        if (maStlIsDupMoveToolActive()) maStlStopCopyToolModesToolbar(false);
        if (maStlIsInsertCornerToolActive()) maStlStopInsertCornerToolModesToolbar(false);
        if (maStlIsInsertEnclosureToolActive()) maStlStopInsertEnclosureToolModesToolbar(false);
        if (maStlIsWall3dToolActive()) maStlStopWall3dToolModesToolbar(false);
        maStlStopWallDimToolModesToolbar();
        maStlDesing2SetLastToolbarCommandId('ma-stl-tool-delete');
        maStlStopRulerAnchorPickModesToolbar();
        maStlTeardownPickHighlightsOnly();
        maStlDisposeUserFloorLineDimEdit(false);
        maStlClearUserFloorLineSelection();
        maStlHideUserFloorLineDimHud(true);
        maStlDeleteToolClearSelection();
        maStlDeleteToolClearHoverLine();
        maStlDeleteToolClearHoverMesh();
        maStlDeleteToolActive = true;
        maStlLockOrbitFullyForToolSelection();
        maStlSyncLineToolToggleBtnUi();
        maStlLineToolPickCursorSync();
        maStlSyncDeleteToolHud();
        maStlDeleteToolWireWindowSelection();
        if (maStlDeleteToolToggleBtn && document.activeElement === maStlDeleteToolToggleBtn) {
            maStlDeleteToolToggleBtn.blur();
        }
    }

    /** @param {boolean} deferOrbitUnlock reservado; salida completa rehabilita órbita al instante. */
    function maStlStopDeleteToolModesToolbar(deferOrbitUnlock) {
        void deferOrbitUnlock;
        if (!maStlIsDeleteToolActive()) return;
        maStlDeleteToolActive = false;
        maStlDeleteToolUnwireWindowSelection();
        maStlDesing2WindowSelectionClearClickSuppression();
        maStlDeleteToolClearSelection();
        maStlDeleteToolClearHoverLine();
        maStlDeleteToolClearHoverMesh();
        maStlSyncDeleteToolHud();
        maStlSyncLineToolToggleBtnUi();
        maStlLineToolPickCursorSync();
        syncMaStlRulerAnchorPickCursor();
        maStlUnlockOrbitForRulerAnchorPick(true);
    }

    function maStlCopyToolEnsureStlMeshMaterialSnapshot(mesh) {
        if (!mesh || !mesh.material || maStlCopyToolStlMeshMaterialSnapshots.has(mesh)) return;
        maStlCopyToolStlMeshMaterialSnapshots.set(mesh, {
            opacity: mesh.material.opacity,
            transparent: mesh.material.transparent,
            emissive: mesh.material.emissive ? mesh.material.emissive.clone() : null,
            emissiveIntensity: mesh.material.emissiveIntensity,
            color: mesh.material.color ? mesh.material.color.clone() : null,
        });
    }

    function maStlCopyToolRestoreStlMeshMaterial(mesh) {
        const snap = maStlCopyToolStlMeshMaterialSnapshots.get(mesh);
        if (!mesh || !mesh.material || !snap) return;
        mesh.material.opacity = snap.opacity;
        mesh.material.transparent = snap.transparent;
        if (snap.emissive && mesh.material.emissive) mesh.material.emissive.copy(snap.emissive);
        if (snap.color && mesh.material.color) mesh.material.color.copy(snap.color);
        mesh.material.emissiveIntensity = snap.emissiveIntensity;
        mesh.material.needsUpdate = true;
        maStlCopyToolStlMeshMaterialSnapshots.delete(mesh);
    }

    function maStlCopyToolApplyStlMeshPickMaterial(mesh) {
        if (!mesh || !mesh.material) return;
        maStlCopyToolEnsureStlMeshMaterialSnapshot(mesh);
        mesh.material.opacity = MA_STL_DELETE_TOOL_PICK_OPACITY;
        mesh.material.transparent = true;
        mesh.material.needsUpdate = true;
    }

    function maStlCopyToolApplyStlMeshHoverMaterial(mesh) {
        if (!mesh || !mesh.material) return;
        maStlCopyToolEnsureStlMeshMaterialSnapshot(mesh);
        mesh.material.emissive.setHex(MA_STL_PICK_HOVER_EMISSIVE_HEX);
        mesh.material.emissiveIntensity = MA_STL_PICK_HOVER_EMISSIVE_INTENSITY;
        mesh.material.color.lerp(_maStlPickHoverColor, MA_STL_PICK_HOVER_COLOR_LERP);
        mesh.material.needsUpdate = true;
    }

    function maStlCopyToolLineIsSelected(line) {
        return !!(line && maStlCopyToolSelectedLines.has(line));
    }

    function maStlCopyToolMeshIsSelected(mesh) {
        return !!(mesh && maStlCopyToolSelectedMeshes.has(mesh));
    }

    function maStlCopyToolClearHoverLine() {
        if (
            maStlCopyToolHoverLine &&
            !maStlCopyToolLineIsSelected(maStlCopyToolHoverLine) &&
            maStlCopyToolHoverLine.material
        ) {
            maStlApplyUserFloorLineBaseMaterialForLine(maStlCopyToolHoverLine);
        }
        maStlCopyToolHoverLine = null;
    }

    function maStlCopyToolClearHoverMesh() {
        if (maStlCopyToolHoverMesh && !maStlCopyToolMeshIsSelected(maStlCopyToolHoverMesh)) {
            maStlCopyToolRestoreStlMeshMaterial(maStlCopyToolHoverMesh);
        }
        maStlCopyToolHoverMesh = null;
    }

    function maStlCopyToolSetHoverLine(line) {
        if (!maStlIsUserFloorPlanLineSelectable(line)) return;
        if (line === maStlCopyToolHoverLine) return;
        maStlCopyToolClearHoverLine();
        maStlCopyToolHoverLine = line;
        if (
            maStlCopyToolHoverLine &&
            !maStlCopyToolLineIsSelected(maStlCopyToolHoverLine) &&
            maStlCopyToolHoverLine.material
        ) {
            maStlApplyUserFloorLineHoverBrightMaterialForLine(maStlCopyToolHoverLine);
        }
    }

    function maStlCopyToolSetHoverMesh(mesh) {
        if (mesh === maStlCopyToolHoverMesh) return;
        maStlCopyToolClearHoverMesh();
        maStlCopyToolHoverMesh = mesh;
        if (maStlCopyToolHoverMesh && !maStlCopyToolMeshIsSelected(maStlCopyToolHoverMesh)) {
            maStlCopyToolApplyStlMeshHoverMaterial(maStlCopyToolHoverMesh);
        }
    }

    function maStlCopyToolClearSelection() {
        maStlCopyToolSelectedLines.forEach(function (line) {
            if (line && line.material) maStlApplyUserFloorLineBaseMaterialForLine(line);
        });
        maStlCopyToolSelectedLines.clear();
        maStlCopyToolSelectedMeshes.forEach(function (mesh) {
            maStlCopyToolRestoreStlMeshMaterial(mesh);
        });
        maStlCopyToolSelectedMeshes.clear();
    }

    function maStlCopyToolAddSingleLineSelection(line) {
        if (!line || !maStlIsUserFloorPlanLineObject(line) || maStlCopyToolSelectedLines.has(line)) return;
        maStlCopyToolSelectedLines.add(line);
        if (line.material && maStlIsUserFloorPlanLineSelectable(line)) {
            maStlApplyUserFloorLineDeletePickMaterial(line.material, maStlPlanUdForLineMaterial(line));
        }
    }

    function maStlCopyToolAddLineSelection(line) {
        if (!line || !maStlIsUserFloorPlanLineObject(line)) return;
        const ud = line.userData && line.userData.maStlUserPlanLine;
        const targets =
            ud && ud.wallGroupId != null ? maStlResolveWallSegmentLinesForLine(line) : [line];
        for (let ti = 0; ti < targets.length; ti++) {
            maStlCopyToolAddSingleLineSelection(targets[ti]);
        }
    }

    function maStlCopyToolAddMeshSelection(mesh) {
        if (!maStlIsDeletableStlMesh(mesh) || maStlCopyToolSelectedMeshes.has(mesh)) return;
        maStlCopyToolSelectedMeshes.add(mesh);
        maStlCopyToolApplyStlMeshPickMaterial(mesh);
    }

    function maStlCopyToolToggleLineSelection(line) {
        if (!line || !maStlIsUserFloorPlanLineSelectable(line)) return;
        const ud = line.userData && line.userData.maStlUserPlanLine;
        const targets =
            ud && ud.wallGroupId != null ? maStlResolveWallSegmentLinesForLine(line) : [line];
        const anySelected = targets.some(function (ln) {
            return maStlCopyToolSelectedLines.has(ln);
        });
        if (anySelected) {
            for (let ti = 0; ti < targets.length; ti++) {
                const ln = targets[ti];
                maStlCopyToolSelectedLines.delete(ln);
                if (ln.material) {
                    if (ln === maStlCopyToolHoverLine) {
                        maStlApplyUserFloorLineHoverBrightMaterialForLine(ln);
                    } else {
                        maStlApplyUserFloorLineBaseMaterialForLine(ln);
                    }
                }
            }
            return;
        }
        for (let aj = 0; aj < targets.length; aj++) {
            maStlCopyToolAddSingleLineSelection(targets[aj]);
        }
    }

    function maStlCopyToolToggleMeshSelection(mesh) {
        if (!maStlIsDeletableStlMesh(mesh)) return;
        if (maStlCopyToolSelectedMeshes.has(mesh)) {
            maStlCopyToolSelectedMeshes.delete(mesh);
            if (mesh === maStlCopyToolHoverMesh) {
                maStlCopyToolApplyStlMeshHoverMaterial(mesh);
            } else {
                maStlCopyToolRestoreStlMeshMaterial(mesh);
            }
            return;
        }
        maStlCopyToolAddMeshSelection(mesh);
    }

    function maStlCopyToolPickTargetAtPointer(clientX, clientY) {
        const ln = maStlPickUserFloorLineForCanvasInteraction(clientX, clientY, 4);
        if (ln) return { kind: 'line', target: ln };
        const mesh = maStlRaycastClipStlMeshFirst(clientX, clientY);
        if (mesh && maStlIsDeletableStlMesh(mesh)) return { kind: 'mesh', target: mesh };
        return null;
    }

    function maStlCopyToolPointerDownBlocksMarquee(clientX, clientY) {
        return maStlCopyToolPickTargetAtPointer(clientX, clientY) != null;
    }

    function maStlCopyToolWireWindowSelection() {
        maStlDesing2BeginWindowSelection({
            enabled: function () {
                return maStlIsDupMoveToolActive() && maStlCopyToolState === 'selecting';
            },
            additive: true,
            blocksMarqueeAt: maStlCopyToolPointerDownBlocksMarquee,
            filterLine: function (line) {
                return maStlIsUserFloorPlanLineSelectable(line);
            },
            filterMesh: maStlIsDeletableStlMesh,
            onMarqueeDragStart: function () {
                maStlCopyToolClearHoverLine();
                maStlCopyToolClearHoverMesh();
            },
            onSelectionComplete: function (selectedLines, selectedMeshes) {
                for (let i = 0; i < selectedLines.length; i++) {
                    maStlCopyToolAddLineSelection(selectedLines[i]);
                }
                for (let j = 0; j < selectedMeshes.length; j++) {
                    maStlCopyToolAddMeshSelection(selectedMeshes[j]);
                }
            },
        });
    }

    function maStlCopyToolUnwireWindowSelection() {
        maStlDesing2EndWindowSelection();
    }

    function maStlCopyToolResetTypingState() {
        maStlCopyToolDistanceTypeBuffer = '';
        maStlCopyToolAngleTypeBuffer = '';
        const distInput = maStlDupMoveToolHudDistanceInput();
        const angleInput = maStlDupMoveToolHudAngleInput();
        const distPreview = maStlDupMoveToolHudDistancePreview();
        if (distInput) distInput.value = '';
        if (angleInput) angleInput.value = '';
        if (distPreview) distPreview.textContent = '';
    }

    function maStlCopyToolRawTypingTrimmed() {
        const distInput = maStlDupMoveToolHudDistanceInput();
        const vi = distInput ? String(distInput.value || '').trim() : '';
        const vb = String(maStlCopyToolDistanceTypeBuffer || '').trim();
        return vi || vb;
    }

    function maStlCopyToolRawAngleTypingTrimmed() {
        const angleInput = maStlDupMoveToolHudAngleInput();
        const vi = angleInput ? String(angleInput.value || '').trim() : '';
        const vb = String(maStlCopyToolAngleTypeBuffer || '').trim();
        return vi || vb;
    }

    function maStlCopyToolParsedAngleDeg() {
        const rawAngle = maStlCopyToolRawAngleTypingTrimmed();
        if (rawAngle) {
            const deg = maStlParseAngleInputValueDeg(rawAngle);
            return deg == null || !Number.isFinite(deg) ? null : maStlNormalizeAzimuthDeg(deg);
        }
        const polar = maStlLineToolParsePolarDistanceAngleMm(maStlCopyToolRawTypingTrimmed());
        return polar ? polar.angleDeg : null;
    }

    function maStlCopyToolComputeFloorDirUnitXz() {
        const angleDeg = maStlCopyToolParsedAngleDeg();
        if (angleDeg != null && Number.isFinite(angleDeg)) {
            const rad = THREE.MathUtils.degToRad(angleDeg);
            return { x: Math.cos(rad), z: -Math.sin(rad) };
        }
        const polar = maStlLineToolParsePolarDistanceAngleMm(maStlCopyToolRawTypingTrimmed());
        if (polar) return { x: polar.ux, z: polar.uz };
        if (
            Number.isFinite(maStlCopyToolLastHoverDirUnitXz.x) &&
            Number.isFinite(maStlCopyToolLastHoverDirUnitXz.y)
        ) {
            return { x: maStlCopyToolLastHoverDirUnitXz.x, z: maStlCopyToolLastHoverDirUnitXz.y };
        }
        return { x: 1, z: 0 };
    }

    /**
     * Dirección y longitud de desplazamiento en planta. Con orto activo: solo ejes 90° (0°/90°/180°/270°).
     * @returns {{ x: number, z: number, len: number } | null}
     */
    function maStlCopyToolFloorDirLenFromDeltaMm(dxMm, dzMm) {
        const h = Math.hypot(dxMm, dzMm);
        if (h < MA_STL_LINE_TOOL_DIR_EPS_MM) return null;
        if (!maStlLineToolOrtho15Enabled) {
            return { x: dxMm / h, z: dzMm / h, len: h };
        }
        const ang = Math.atan2(dzMm, dxMm);
        const snapped =
            Math.round(ang / MA_STL_COPY_TOOL_ORTHO_STEP_RAD) * MA_STL_COPY_TOOL_ORTHO_STEP_RAD;
        const ux = Math.cos(snapped);
        const uz = Math.sin(snapped);
        const t = dxMm * ux + dzMm * uz;
        if (t < MA_STL_LINE_TOOL_DIR_EPS_MM) return null;
        return { x: ux, z: uz, len: t };
    }

    /** @param {{ x: number, y: number, z: number }} p @param {{ x: number, y: number, z: number }} out */
    function maStlCopyToolSnapDisplacementFloorPointMm(p, out) {
        const dx = p.x - maStlCopyToolBasePointMm.x;
        const dz = p.z - maStlCopyToolBasePointMm.z;
        const r = maStlCopyToolFloorDirLenFromDeltaMm(dx, dz);
        if (!r) return null;
        out.x = maStlCopyToolBasePointMm.x + r.x * r.len;
        out.y = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM;
        out.z = maStlCopyToolBasePointMm.z + r.z * r.len;
        return out;
    }

    function maStlCopyToolMaybeUpdateHoverDirFromCandidate(p) {
        if (!p) return;
        const dx = p.x - maStlCopyToolBasePointMm.x;
        const dz = p.z - maStlCopyToolBasePointMm.z;
        const r = maStlCopyToolFloorDirLenFromDeltaMm(dx, dz);
        if (r) {
            maStlCopyToolLastHoverDirUnitXz.set(r.x, r.z);
        }
    }

    function maStlCopyToolStretchPrimaryAxisDeltaMm(dx, dz) {
        const axisLine = maStlCopyToolPrimaryStretchAxisLine();
        if (!axisLine) return Math.hypot(dx, dz);
        const ud = axisLine.userData && axisLine.userData.maStlUserPlanLine;
        if (!ud || !ud.p1Mm || !ud.p2Mm) return Math.hypot(dx, dz);
        const plan = MaStlWallStretchMath.planFromDisplacementMm(ud.p1Mm, ud.p2Mm, dx, dz);
        return plan ? plan.axisDeltaMm : 0;
    }

    function maStlCopyToolFormatStretchAxisDeltaHudMm(deltaMm) {
        if (!Number.isFinite(deltaMm) || Math.abs(deltaMm) < 1e-6) return '';
        const sign = deltaMm >= 0 ? '+' : '\u2212';
        const d = maStlDesing2DimEditableMetersDisplayFromMm(
            maStlDesing2LengthMmRoundedEditableFromMm(Math.abs(deltaMm))
        );
        return sign + '\u00A0' + d + '\u00A0m';
    }

    function maStlStretchSnapSearchOptions(axisUd) {
        return {
            excludeWallGroupId:
                axisUd && axisUd.wallGroupId != null ? axisUd.wallGroupId : null,
        };
    }

    function maStlStretchJunctionSnapLabelWorldScaleMm() {
        const step = desing2EnvGridSnapMm > 0 ? desing2EnvGridSnapMm : MA_STL_DESING2_GRID_MINOR_MM;
        return Math.max(step * 1.15, MA_STL_DESING2_GRID_MINOR_MM * 0.9);
    }

    function maStlClearStretchJunctionSnapHighlight() {
        maStlStretchJunctionSnapHighlightGroup.visible = false;
        _maStlStretchJunctionSnapKind = null;
    }

    function maStlEnsureStretchJunctionSnapSprite(letter) {
        if (maStlStretchJunctionSnapSprite && _maStlStretchJunctionSnapKind === letter) {
            return maStlStretchJunctionSnapSprite;
        }
        if (maStlStretchJunctionSnapSprite) {
            maStlStretchJunctionSnapHighlightGroup.remove(maStlStretchJunctionSnapSprite);
            if (maStlStretchJunctionSnapSprite.material) {
                if (maStlStretchJunctionSnapSprite.material.map) {
                    maStlStretchJunctionSnapSprite.material.map.dispose();
                }
                maStlStretchJunctionSnapSprite.material.dispose();
            }
            maStlStretchJunctionSnapSprite = null;
        }
        const scale = maStlStretchJunctionSnapLabelWorldScaleMm();
        const stroke = letter === 'T' ? '#ff6600' : '#2563eb';
        maStlStretchJunctionSnapSprite = maStlMakeTextSprite(letter, scale, {
            thinFillOnly: true,
            fontPx: 22,
            fontWeight: 800,
            fillColor: '#111111',
            thinPillFill: 'rgba(255,255,255,0.96)',
            thinPillStroke: stroke,
            thinPillLineWidth: 3,
        });
        if (maStlStretchJunctionSnapSprite) {
            maStlStretchJunctionSnapSprite.position.y = MA_STL_DESING2_GRID_MINOR_MM * 0.08;
            maStlDisableRaycastOnOverlay(maStlStretchJunctionSnapSprite);
            maStlStretchJunctionSnapHighlightGroup.add(maStlStretchJunctionSnapSprite);
            _maStlStretchJunctionSnapKind = letter;
        }
        return maStlStretchJunctionSnapSprite;
    }

    /**
     * @param {{ x: number, y: number, z: number }} pt
     * @param {'T'|'L'} junctionKind
     */
    function maStlSetStretchJunctionSnapHighlight(pt, junctionKind) {
        if (!pt || (junctionKind !== 'T' && junctionKind !== 'L')) {
            maStlClearStretchJunctionSnapHighlight();
            return;
        }
        maStlEnsureStretchJunctionSnapSprite(junctionKind);
        maStlStretchJunctionSnapHighlightGroup.position.set(pt.x, pt.y, pt.z);
        maStlStretchJunctionSnapHighlightGroup.visible = true;
    }

    /**
     * L vs T a ~90°: T si el cruce cae en el interior del eje atravesado; L si cae en un extremo.
     * @param {'p1'|'p2'} movedEndpoint
     * @param {{ x: number, z: number }} [stretchedTipMm] extremo tras desplazamiento (preview estirar)
     * @returns {'L'|'T'|'plain'}
     */
    function maStlStretchNeighborJunctionKindFromBranchMm(fixedPt, branchTipPt, targetUd) {
        if (!fixedPt || !branchTipPt || !targetUd || !targetUd.p1Mm || !targetUd.p2Mm) {
            return 'plain';
        }
        const dBx = branchTipPt.x - fixedPt.x;
        const dBz = branchTipPt.z - fixedPt.z;
        const branchLen = Math.hypot(dBx, dBz);
        if (branchLen < 1e-9) return 'plain';
        const bUx = dBx / branchLen;
        const bUz = dBz / branchLen;
        const targetDir = maStlUserFloorPlanLineDirUnitXz(targetUd);
        if (!targetDir) return 'plain';
        const parallel = Math.abs(bUx * targetDir.ux + bUz * targetDir.uz);
        if (parallel > 0.15) return 'plain';

        const dTx = targetUd.p2Mm.x - targetUd.p1Mm.x;
        const dTz = targetUd.p2Mm.z - targetUd.p1Mm.z;
        const hit = maStlPlanXzInfiniteLinesIntersectMm(fixedPt, dBx, dBz, targetUd.p1Mm, dTx, dTz);
        if (!hit) return 'L';

        const span = Math.hypot(dTx, dTz);
        if (span < 1e-9) return 'plain';
        const minSeg = maStlUserFloorSegmentMinMm();
        const minT = span > minSeg ? minSeg / span : 0.05;
        const t = ((hit.x - targetUd.p1Mm.x) * dTx + (hit.z - targetUd.p1Mm.z) * dTz) / (span * span);
        if (t > minT && t < 1 - minT) return 'T';
        return 'L';
    }

    function maStlStretchNeighborJunctionKindMm(axisUd, movedEndpoint, targetUd, stretchedTipMm) {
        if (!axisUd || !targetUd || !axisUd.p1Mm || !axisUd.p2Mm || !targetUd.p1Mm || !targetUd.p2Mm) {
            return 'plain';
        }
        if (maStlUserFloorPlanLinesCollinearParallelXz(axisUd, targetUd)) return 'plain';
        const fixedPt = movedEndpoint === 'p1' ? axisUd.p2Mm : axisUd.p1Mm;
        const branchTipPt =
            stretchedTipMm || (movedEndpoint === 'p1' ? axisUd.p1Mm : axisUd.p2Mm);
        return maStlStretchNeighborJunctionKindFromBranchMm(fixedPt, branchTipPt, targetUd);
    }

    /**
     * Punto de conexión del eje que se estira: intersección de ejes (T/L), no vértice de cara suelto.
     * @param {'p1'|'p2'} movedEndpoint
     * @param {{ x: number, y?: number, z: number }} [stretchedTipMm]
     */
    function maStlStretchResolveAxisEndpointFromNeighborSnapMm(
        axisLine,
        movedEndpoint,
        snap,
        stretchedTipMm
    ) {
        const yFloor = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM;
        if (!axisLine || !snap) {
            return null;
        }
        const ud = axisLine.userData && axisLine.userData.maStlUserPlanLine;
        if (!ud || !ud.p1Mm || !ud.p2Mm) return null;

        const targetAxis = maStlLineToolResolveWallAxisLineFromSnapLine(snap.segLine);
        const targetUd = targetAxis && targetAxis.userData && targetAxis.userData.maStlUserPlanLine;
        if (!targetUd || targetAxis === axisLine || targetUd.wallRole !== 'axis') {
            return { x: snap.x, y: snap.y != null ? snap.y : yFloor, z: snap.z };
        }

        const fixedPt = movedEndpoint === 'p1' ? ud.p2Mm : ud.p1Mm;
        const dirAnchorPt =
            stretchedTipMm || (movedEndpoint === 'p1' ? ud.p1Mm : ud.p2Mm);
        const tipPt = movedEndpoint === 'p1' ? ud.p1Mm : ud.p2Mm;
        const dBx = dirAnchorPt.x - fixedPt.x;
        const dBz = dirAnchorPt.z - fixedPt.z;
        const dTx = targetUd.p2Mm.x - targetUd.p1Mm.x;
        const dTz = targetUd.p2Mm.z - targetUd.p1Mm.z;
        const hit = maStlPlanXzInfiniteLinesIntersectMm(fixedPt, dBx, dBz, targetUd.p1Mm, dTx, dTz);
        const minLen = maStlUserFloorSegmentMinMm();
        const resolved = { x: 0, y: yFloor, z: 0 };
        if (hit && maStlProjectPointOntoSegmentAxisMm(hit, fixedPt, dirAnchorPt, minLen, resolved)) {
            resolved.y = tipPt.y != null ? tipPt.y : yFloor;
            return resolved;
        }
        return { x: snap.x, y: snap.y != null ? snap.y : yFloor, z: snap.z };
    }

    /**
     * Extremo móvil tras estirar + cuantizar rejilla (misma posición que al confirmar).
     * @returns {'p1'|'p2'|null}
     */
    function maStlCopyToolComputeStretchQuantizedAxisProbeMm(axisUd, dx, dz, outProbePt) {
        if (!axisUd || !axisUd.p1Mm || !axisUd.p2Mm || !outProbePt) return null;
        const p1 = { x: axisUd.p1Mm.x, y: axisUd.p1Mm.y, z: axisUd.p1Mm.z };
        const p2 = { x: axisUd.p2Mm.x, y: axisUd.p2Mm.y, z: axisUd.p2Mm.z };
        const outP1 = { x: 0, y: 0, z: 0 };
        const outP2 = { x: 0, y: 0, z: 0 };
        if (!maStlCopyToolStretchSegmentEndpointsByDisplacementMm(p1, p2, dx, dz, outP1, outP2)) {
            return null;
        }
        maStlQuantizeUserFloorPlanPointToGridMm(outP1);
        maStlQuantizeUserFloorPlanPointToGridMm(outP2);
        const plan = maStlCopyToolStretchPlanFromDisplacementMm(p1, p2, dx, dz);
        if (!plan) return null;
        const ep = plan.movedEndpoint === 'p1' ? outP1 : outP2;
        outProbePt.x = ep.x;
        outProbePt.y = ep.y;
        outProbePt.z = ep.z;
        return plan.movedEndpoint;
    }

    /**
     * Misma prueba de snap que al confirmar estirar (sin mutar geometría).
     * @param {boolean} [forPreview] tolerancia ampliada (cuerpo del muro / snap crudo) solo en arrastre
     * @returns {{ snap: object, resolved: object, targetUd: object|null, distXZ: number }|null}
     */
    function maStlCopyToolProbeStretchWallAxisEndpointSnapMm(
        axisLine,
        axisUd,
        movedEndpoint,
        queryPtMm,
        forPreview
    ) {
        if (!axisLine || !axisUd || !queryPtMm) return null;
        const threshMm = MA_STL_USER_FLOOR_ENDPOINT_STRETCH_SNAP_MM;
        const snap = maStlCopyToolFindStretchNeighborSnapMm(
            axisLine,
            axisUd,
            movedEndpoint,
            queryPtMm,
            queryPtMm
        );
        if (!snap) return null;
        const resolved = maStlStretchResolveAxisEndpointFromNeighborSnapMm(
            axisLine,
            movedEndpoint,
            snap,
            queryPtMm
        );
        if (!resolved) return null;
        const targetAxis = maStlLineToolResolveWallAxisLineFromSnapLine(snap.segLine);
        const targetUd = targetAxis && targetAxis.userData && targetAxis.userData.maStlUserPlanLine;
        let distXZ = Math.hypot(queryPtMm.x - resolved.x, queryPtMm.z - resolved.z);
        if (forPreview) {
            distXZ = Math.min(distXZ, Math.hypot(queryPtMm.x - snap.x, queryPtMm.z - snap.z));
            if (targetUd && targetUd.p1Mm && targetUd.p2Mm) {
                distXZ = Math.min(
                    distXZ,
                    maStlUserFloorPlanPointDistanceToSegmentAxisXzMm(
                        queryPtMm,
                        targetUd.p1Mm,
                        targetUd.p2Mm
                    )
                );
            }
        }
        if (distXZ > threshMm) return null;
        return { snap: snap, resolved: resolved, targetUd: targetUd, distXZ: distXZ };
    }

    function maStlClearStretchConnectionJunctionPreview() {
        maStlClearStretchJunctionSnapHighlight();
        maStlClearLineToolVertexSnapHighlight();
    }

    /** Luz (esfera) + etiqueta T/L en el punto de conexión previsto. */
    function maStlApplyStretchConnectionJunctionPreviewMm(hit) {
        if (!hit || !hit.resolved || !hit.snap) {
            maStlClearStretchConnectionJunctionPreview();
            return false;
        }
        const junctionKind = maStlStretchPreviewJunctionLabelKindMm(
            hit.targetUd,
            hit.resolved,
            hit.snap
        );
        const yFloor = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM;
        const display = {
            x: hit.resolved.x,
            y: hit.resolved.y != null ? hit.resolved.y : yFloor,
            z: hit.resolved.z,
            kind: hit.snap.kind || 'segment',
        };
        maStlSetStretchJunctionSnapHighlight(display, junctionKind);
        const onMajor = maStlIsOnDisplayedMajorGridLineAtMm(display.x, display.z);
        maStlSetLineToolVertexSnapHighlight(display, true, onMajor);
        return true;
    }

    /** Etiqueta T/L para preview: T si el punto de unión no es un extremo del muro atravesado. */
    function maStlStretchPreviewJunctionLabelKindMm(targetUd, resolved, snap) {
        if (snap && snap.kind === 'segment') return 'T';
        if (!targetUd || !resolved || !targetUd.p1Mm || !targetUd.p2Mm) {
            return snap && (snap.kind === 'p1' || snap.kind === 'p2') ? 'L' : 'T';
        }
        const eps = Math.max(
            maStlUserFloorLineMergeEndpointEpsMm(),
            MA_STL_WALL_DIM_LENGTH_VALUE_TOL_MM
        );
        if (
            maStlUserFloorPlanPointNearXzMm(resolved, targetUd.p1Mm, eps) ||
            maStlUserFloorPlanPointNearXzMm(resolved, targetUd.p2Mm, eps)
        ) {
            return 'L';
        }
        return 'T';
    }

    /** Candidato vecino para estirar (línea más cercana; excluye el propio muro). */
    function maStlCopyToolFindStretchNeighborSnapMm(
        axisLine,
        axisUd,
        movedEndpoint,
        queryPtMm,
        stretchedTipMm
    ) {
        if (!queryPtMm) return null;
        const threshMm = MA_STL_USER_FLOOR_ENDPOINT_STRETCH_SNAP_MM;
        const searchOpts = maStlStretchSnapSearchOptions(axisUd);
        let best = null;
        let bestScore = Infinity;

        function considerSnap(snap) {
            if (!snap) return;
            const distXZ = Math.hypot(queryPtMm.x - snap.x, queryPtMm.z - snap.z);
            if (distXZ > threshMm) return;
            const targetAxis = maStlLineToolResolveWallAxisLineFromSnapLine(snap.segLine);
            const targetUd =
                targetAxis && targetAxis.userData && targetAxis.userData.maStlUserPlanLine;
            let score = distXZ;
            if (targetUd && targetAxis !== axisLine) {
                const junction = maStlStretchNeighborJunctionKindMm(
                    axisUd,
                    movedEndpoint,
                    targetUd,
                    stretchedTipMm
                );
                if (junction === 'T' && (snap.kind === 'p1' || snap.kind === 'p2')) {
                    score += threshMm * 0.75;
                } else if (junction === 'T' && snap.kind === 'segment') {
                    score -= threshMm * 0.25;
                } else if (junction === 'L' && (snap.kind === 'p1' || snap.kind === 'p2')) {
                    score -= threshMm * 0.15;
                }
            }
            if (score < bestScore) {
                bestScore = score;
                best = snap;
            }
        }

        considerSnap(
            maStlFindNearestUserFloorLineSegmentSnapMm(queryPtMm, axisLine, threshMm, searchOpts)
        );

        if (renderer && Number.isFinite(maStlCopyToolLastPointerClientXY.x)) {
            const canvas = renderer.domElement;
            const cam = activeCamera();
            if (
                maStlClientRayToWorkspaceFloor(
                    maStlCopyToolLastPointerClientXY.x,
                    maStlCopyToolLastPointerClientXY.y,
                    canvas,
                    cam,
                    orbitPivotNdc,
                    orbitPivotRaycaster,
                    _maStlUserFloorLineP1DragFloorPt
                )
            ) {
                considerSnap(
                    maStlFindNearestUserFloorLineSegmentSnapMm(
                        {
                            x: _maStlUserFloorLineP1DragFloorPt.x,
                            y: _maStlUserFloorLineP1DragFloorPt.y,
                            z: _maStlUserFloorLineP1DragFloorPt.z,
                        },
                        axisLine,
                        threshMm,
                        searchOpts
                    )
                );
            }
        }

        return best;
    }

    /**
     * Vista previa T/L + luz: misma prueba que al confirmar (extremo cuantizado a rejilla).
     * @param {number} dx
     * @param {number} dz
     */
    function maStlCopyToolSyncStretchSnapPreview(dx, dz) {
        if (!maStlIsStretchToolActive() || maStlCopyToolState !== 'displacement') {
            maStlClearStretchConnectionJunctionPreview();
            return;
        }
        const expanded = maStlDesing2ExpandLinesWithWallGroups(Array.from(maStlCopyToolSelectedLines));
        const parts = maStlCopyToolPartitionLinesForDuplicate(expanded);
        const probePt = { x: 0, y: 0, z: 0 };
        let bestHit = null;
        let bestDistXZ = Infinity;

        for (let wi = 0; wi < parts.wallAxisLines.length; wi++) {
            const axisLine = parts.wallAxisLines[wi];
            const axisUd = axisLine.userData && axisLine.userData.maStlUserPlanLine;
            if (!axisUd || !axisUd.p1Mm || !axisUd.p2Mm) continue;
            const movedEndpoint = maStlCopyToolComputeStretchQuantizedAxisProbeMm(
                axisUd,
                dx,
                dz,
                probePt
            );
            if (!movedEndpoint) continue;
            const hit = maStlCopyToolProbeStretchWallAxisEndpointSnapMm(
                axisLine,
                axisUd,
                movedEndpoint,
                probePt,
                true
            );
            if (!hit || hit.distXZ >= bestDistXZ) continue;
            bestDistXZ = hit.distXZ;
            bestHit = hit;
        }

        maStlApplyStretchConnectionJunctionPreviewMm(bestHit);
    }

    function maStlCopyToolSyncStretchDeltaHud() {
        const hudCoords = maStlDupMoveToolHudCoords();
        if (!hudCoords || !maStlIsStretchToolActive()) return;
        if (maStlCopyToolState !== 'displacement') {
            hudCoords.textContent = '';
            return;
        }
        const end = { x: 0, y: 0, z: 0 };
        if (!maStlCopyToolComputeDisplacementEndMm(end)) {
            hudCoords.textContent = '';
            return;
        }
        const dx = end.x - maStlCopyToolBasePointMm.x;
        const dz = end.z - maStlCopyToolBasePointMm.z;
        hudCoords.textContent = maStlCopyToolFormatStretchAxisDeltaHudMm(
            maStlCopyToolStretchPrimaryAxisDeltaMm(dx, dz)
        );
    }

    function maStlCopyToolSyncTypingPreviewUi() {
        const distPreview = maStlDupMoveToolHudDistancePreview();
        if (maStlIsStretchToolActive()) {
            if (distPreview) distPreview.textContent = '';
            return;
        }
        if (!distPreview || maStlCopyToolState !== 'displacement') {
            if (distPreview) distPreview.textContent = '';
            return;
        }
        const raw = maStlCopyToolRawTypingTrimmed();
        const polar = maStlLineToolParsePolarDistanceAngleMm(raw);
        const lenParsed = polar ? polar.lenMm : maStlParseLengthInputValueToMm(raw);
        if (lenParsed != null && lenParsed > 0) {
            const d = maStlDesing2DimEditableMetersDisplayFromMm(
                maStlDesing2LengthMmRoundedEditableFromMm(lenParsed)
            );
            const hud = maStlDupMoveToolHud();
            const pfx =
                (hud && hud.getAttribute('data-ma-stl-line-tool-distance-preview-prefix')) || '\u2248';
            const angleDeg = maStlCopyToolParsedAngleDeg();
            distPreview.textContent =
                String(pfx) +
                '\u00A0' +
                d +
                '\u00A0m' +
                (angleDeg != null ? '\u00A0<\u00A0' + maStlFormatFloorPlanAngleDegDisplay(angleDeg) : '');
        } else {
            distPreview.textContent = '';
        }
    }

    function maStlCopyToolSyncHud() {
        const activeHud = maStlDupMoveToolHud();
        if (!activeHud || !maStlDesingV2Viewer) return;
        if (!maStlIsDupMoveToolActive()) {
            maStlXformToolHideAllHuds();
            return;
        }
        maStlXformToolHideInactiveHuds();
        let insTpl = '';
        if (maStlCopyToolState === 'selecting') {
            insTpl = activeHud.getAttribute(maStlDupMoveToolInstructionDataAttr('selecting')) || '';
        } else if (maStlCopyToolState === 'basePoint') {
            insTpl = activeHud.getAttribute(maStlDupMoveToolInstructionDataAttr('base')) || '';
        } else if (maStlCopyToolState === 'displacement') {
            insTpl = activeHud.getAttribute(maStlDupMoveToolInstructionDataAttr('displacement')) || '';
        }
        const hudInstruction = maStlDupMoveToolHudInstruction();
        if (hudInstruction) hudInstruction.textContent = insTpl;
        const hudCoords = maStlDupMoveToolHudCoords();
        if (maStlIsStretchToolActive()) {
            maStlCopyToolSyncStretchDeltaHud();
        } else if (hudCoords) {
        const tpl =
            (hudCoords && hudCoords.getAttribute('data-ma-stl-line-tool-coords-template')) || '';
        const typedRaw = maStlCopyToolRawTypingTrimmed();
        const typedPt =
            maStlCopyToolState === 'basePoint'
                ? typedRaw
                    ? maStlLineToolTryParseAbsoluteFloorCoordsMm(typedRaw, 'picking1')
                    : null
                : maStlCopyToolState === 'displacement'
                  ? typedRaw
                      ? maStlLineToolTryParseAbsoluteFloorCoordsMm(typedRaw, 'picking2') ||
                        (function () {
                            const end = { x: 0, y: 0, z: 0 };
                            return maStlCopyToolComputeDisplacementEndMm(end) ? end : null;
                        })()
                      : null
                  : null;
        if (hudCoords) {
            if (typedPt && tpl) {
                hudCoords.textContent = maStlFormatRulerAnchorGridIntersectionToast(
                    tpl,
                    typedPt.x,
                    typedPt.z
                );
            } else if (
                maStlCopyToolState !== 'selecting' &&
                (maStlGridIntersectionPickHighlightGroup.visible ||
                    maStlLineToolVertexSnapHighlightGroup.visible)
            ) {
                const snapX = maStlLineToolVertexSnapHighlightGroup.visible
                    ? _maStlLineToolVertexSnapMm.x
                    : _maStlGridIntersectionSnapMm.x;
                const snapZ = maStlLineToolVertexSnapHighlightGroup.visible
                    ? _maStlLineToolVertexSnapMm.z
                    : _maStlGridIntersectionSnapMm.z;
                hudCoords.textContent = maStlFormatRulerAnchorGridIntersectionToast(
                    tpl,
                    snapX,
                    snapZ
                );
            } else {
                hudCoords.textContent = '';
            }
        }
        }
        const hudDistanceRow = maStlDupMoveToolHudDistanceRow();
        if (hudDistanceRow) {
            hudDistanceRow.classList.toggle(
                'd-none',
                maStlCopyToolState !== 'basePoint' && maStlCopyToolState !== 'displacement'
            );
        }
        maStlCopyToolSyncTypingPreviewUi();
        activeHud.classList.remove('d-none');
    }

    function maStlCopyToolApplyPreviewLineMaterialStyle(mat, wallRole) {
        if (!mat || !mat.isLineMaterial) return;
        if (wallRole === 'axis') {
            maStlApplyUserFloorWallAxisLineStyleToMaterial(mat);
            mat.opacity = MA_STL_COPY_TOOL_PREVIEW_OPACITY;
            mat.transparent = true;
        } else {
            mat.dashed = true;
            mat.dashSize = 12;
            mat.gapSize = 8;
            mat.linewidth = MA_STL_COPY_TOOL_PREVIEW_LINEWIDTH_PX;
            mat.color.setHex(maStlCopyToolPreviewColorHex());
            mat.opacity = MA_STL_COPY_TOOL_PREVIEW_OPACITY;
            mat.transparent = true;
        }
        mat.needsUpdate = true;
    }

    function maStlCopyToolEnsurePreviewLineAtIndex(idx) {
        while (maStlCopyToolPreviewLines.length <= idx) {
            const geo = new LineGeometry();
            geo.setPositions(new Float32Array(6));
            const mat = maStlMakeUserFloorLineMaterial();
            maStlCopyToolApplyPreviewLineMaterialStyle(mat, null);
            if (renderer && renderer.domElement) {
                maStlApplyUserFloorLineMaterialResolution(
                    mat,
                    renderer.domElement.clientWidth,
                    renderer.domElement.clientHeight
                );
            }
            const pl = new Line2(geo, mat);
            pl.renderOrder = 168;
            pl.visible = false;
            maStlDisableRaycastOnOverlay(pl);
            scene.add(pl);
            maStlCopyToolPreviewLines.push(pl);
        }
        return maStlCopyToolPreviewLines[idx];
    }

    function maStlCopyToolHidePreview() {
        for (let i = 0; i < maStlCopyToolPreviewLines.length; i++) {
            if (maStlCopyToolPreviewLines[i]) maStlCopyToolPreviewLines[i].visible = false;
        }
        for (let mi = 0; mi < maStlCopyToolPreviewMeshSlots.length; mi++) {
            if (maStlCopyToolPreviewMeshSlots[mi].mesh) {
                maStlCopyToolPreviewMeshSlots[mi].mesh.visible = false;
            }
        }
    }

    function maStlCopyToolDisposePreviewMeshes() {
        for (let mi = 0; mi < maStlCopyToolPreviewMeshSlots.length; mi++) {
            const slot = maStlCopyToolPreviewMeshSlots[mi];
            const m = slot && slot.mesh;
            if (!m) continue;
            if (m.parent) m.parent.remove(m);
            const mats = Array.isArray(m.material) ? m.material : m.material ? [m.material] : [];
            for (let mati = 0; mati < mats.length; mati++) {
                if (mats[mati]) mats[mati].dispose();
            }
        }
        maStlCopyToolPreviewMeshSlots.length = 0;
    }

    function maStlCopyToolDisposePreview() {
        maStlCopyToolHidePreview();
        for (let i = 0; i < maStlCopyToolPreviewLines.length; i++) {
            const pl = maStlCopyToolPreviewLines[i];
            if (!pl) continue;
            if (pl.parent) pl.parent.remove(pl);
            if (pl.geometry) pl.geometry.dispose();
            if (pl.material) pl.material.dispose();
        }
        maStlCopyToolPreviewLines.length = 0;
        maStlCopyToolDisposePreviewMeshes();
        maStlCopyToolPreviewSegments = null;
    }

    function maStlCopyToolClonePreviewMeshMaterial(srcMat) {
        if (!srcMat) return srcMat;
        const clone = srcMat.clone();
        clone.transparent = true;
        clone.opacity = MA_STL_COPY_TOOL_PREVIEW_MESH_OPACITY;
        clone.depthWrite = false;
        clone.needsUpdate = true;
        return clone;
    }

    function maStlCopyToolBuildPreviewSnapshot() {
        maStlCopyToolDisposePreviewMeshes();
        const expanded = maStlDesing2ExpandLinesWithWallGroups(Array.from(maStlCopyToolSelectedLines));
        const seen = new Set();
        const segments = [];
        for (let ei = 0; ei < expanded.length; ei++) {
            const ln = expanded[ei];
            if (!ln || seen.has(ln.uuid)) continue;
            seen.add(ln.uuid);
            const ud = ln.userData && ln.userData.maStlUserPlanLine;
            if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
            if (ud.wallGroupId != null && ud.wallRole !== 'axis') continue;
            segments.push({
                p1: { x: ud.p1Mm.x, y: ud.p1Mm.y, z: ud.p1Mm.z },
                p2: { x: ud.p2Mm.x, y: ud.p2Mm.y, z: ud.p2Mm.z },
                wallRole: ud.wallRole || null,
            });
        }
        maStlCopyToolPreviewSegments = segments;

        const scale = stlVertexToSceneScale || 1;
        const meshes = Array.from(maStlCopyToolSelectedMeshes);
        for (let mi = 0; mi < meshes.length; mi++) {
            const src = meshes[mi];
            if (!src) continue;
            const clone = src.clone();
            clone.geometry = src.geometry;
            clone.position.copy(src.position);
            if (Array.isArray(clone.material)) {
                clone.material = clone.material.map(maStlCopyToolClonePreviewMeshMaterial);
            } else if (clone.material) {
                clone.material = maStlCopyToolClonePreviewMeshMaterial(clone.material);
            }
            clone.renderOrder = 167;
            maStlDisableRaycastOnOverlay(clone);
            const parent = src.parent || currentRoot || scene;
            parent.add(clone);
            maStlCopyToolPreviewMeshSlots.push({
                mesh: clone,
                baseX: src.position.x,
                baseZ: src.position.z,
                scale: scale,
            });
        }
    }

    function maStlCopyToolStretchPlanFromDisplacementMm(p1Mm, p2Mm, dx, dz) {
        return MaStlWallStretchMath.planFromDisplacementMm(p1Mm, p2Mm, dx, dz);
    }

    /** @returns {boolean} */
    function maStlCopyToolStretchSegmentEndpointsByDisplacementMm(p1Mm, p2Mm, dx, dz, outP1, outP2) {
        return MaStlWallStretchMath.segmentEndpointsByDisplacementMm(
            p1Mm,
            p2Mm,
            dx,
            dz,
            outP1,
            outP2,
            maStlUserFloorSegmentMinMm()
        );
    }

    function maStlCopyToolSyncPreviewAtStretchDisplacement(dx, dy, dz) {
        if (!maStlCopyToolPreviewSegments || maStlCopyToolPreviewSegments.length === 0) {
            maStlCopyToolHidePreview();
            return;
        }
        const minLen = maStlUserFloorSegmentMinMm();
        const show = Math.hypot(dx, dz) >= 1e-6;
        const stretchedP1 = { x: 0, y: 0, z: 0 };
        const stretchedP2 = { x: 0, y: 0, z: 0 };
        let visibleCount = 0;
        for (let si = 0; si < maStlCopyToolPreviewSegments.length; si++) {
            const seg = maStlCopyToolPreviewSegments[si];
            const pl = maStlCopyToolEnsurePreviewLineAtIndex(si);
            if (
                !show ||
                !maStlCopyToolStretchSegmentEndpointsByDisplacementMm(
                    seg.p1,
                    seg.p2,
                    dx,
                    dz,
                    stretchedP1,
                    stretchedP2
                ) ||
                Math.hypot(stretchedP2.x - stretchedP1.x, stretchedP2.z - stretchedP1.z) < minLen
            ) {
                pl.visible = false;
                continue;
            }
            maStlCopyToolApplyPreviewLineMaterialStyle(pl.material, seg.wallRole);
            maStlSetUserFloorLineGeometryMm(pl, stretchedP1, stretchedP2);
            if (typeof pl.computeLineDistances === 'function') {
                pl.computeLineDistances();
            }
            pl.visible = true;
            visibleCount++;
        }
        for (let hi = maStlCopyToolPreviewSegments.length; hi < maStlCopyToolPreviewLines.length; hi++) {
            maStlCopyToolPreviewLines[hi].visible = false;
        }
        for (let mi = 0; mi < maStlCopyToolPreviewMeshSlots.length; mi++) {
            if (maStlCopyToolPreviewMeshSlots[mi].mesh) {
                maStlCopyToolPreviewMeshSlots[mi].mesh.visible = false;
            }
        }
        if (visibleCount === 0) maStlCopyToolHidePreview();
    }

    function maStlCopyToolSyncPreviewAtDisplacement(dx, dy, dz) {
        if (!maStlCopyToolPreviewSegments || maStlCopyToolPreviewSegments.length === 0) {
            maStlCopyToolHidePreview();
            return;
        }
        const minLen = maStlUserFloorSegmentMinMm();
        const show = Math.hypot(dx, dz) >= 1e-6;
        let visibleCount = 0;
        for (let si = 0; si < maStlCopyToolPreviewSegments.length; si++) {
            const seg = maStlCopyToolPreviewSegments[si];
            const p1 = { x: seg.p1.x + dx, y: seg.p1.y + dy, z: seg.p1.z + dz };
            const p2 = { x: seg.p2.x + dx, y: seg.p2.y + dy, z: seg.p2.z + dz };
            const pl = maStlCopyToolEnsurePreviewLineAtIndex(si);
            if (!show || Math.hypot(p2.x - p1.x, p2.z - p1.z) < minLen) {
                pl.visible = false;
                continue;
            }
            maStlCopyToolApplyPreviewLineMaterialStyle(pl.material, seg.wallRole);
            maStlSetUserFloorLineGeometryMm(pl, p1, p2);
            if (typeof pl.computeLineDistances === 'function') {
                pl.computeLineDistances();
            }
            pl.visible = true;
            visibleCount++;
        }
        for (let hi = maStlCopyToolPreviewSegments.length; hi < maStlCopyToolPreviewLines.length; hi++) {
            maStlCopyToolPreviewLines[hi].visible = false;
        }
        for (let mi = 0; mi < maStlCopyToolPreviewMeshSlots.length; mi++) {
            const slot = maStlCopyToolPreviewMeshSlots[mi];
            if (!slot.mesh) continue;
            slot.mesh.position.x = slot.baseX + dx / slot.scale;
            slot.mesh.position.z = slot.baseZ + dz / slot.scale;
            slot.mesh.visible = show;
        }
        if (visibleCount === 0) maStlCopyToolHidePreview();
    }

    function maStlCopyToolHideRubberBand() {
        if (maStlLineToolRubberBandLine) maStlLineToolRubberBandLine.visible = false;
    }

    /** @param {{ x: number, y: number, z: number }} out */
    function maStlCopyToolComputeDisplacementEndMm(out) {
        if (maStlCopyToolState !== 'displacement') return null;
        const raw = maStlCopyToolRawTypingTrimmed();
        const absPt = raw ? maStlLineToolTryParseAbsoluteFloorCoordsMm(raw, 'picking2') : null;
        if (absPt) {
            out.x = absPt.x;
            out.y = absPt.y;
            out.z = absPt.z;
            return out;
        }
        const polar = maStlLineToolParsePolarDistanceAngleMm(raw);
        const lenMmRaw = polar ? polar.lenMm : maStlParseLengthInputValueToMm(raw);
        if (lenMmRaw != null && Number.isFinite(lenMmRaw) && lenMmRaw > 0) {
            const u = polar
                ? { x: polar.ux, z: polar.uz }
                : maStlCopyToolComputeFloorDirUnitXz();
            const lenMm = maStlDesing2LengthMmRoundedEditableFromMm(lenMmRaw);
            out.x = maStlCopyToolBasePointMm.x + u.x * lenMm;
            out.y = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM;
            out.z = maStlCopyToolBasePointMm.z + u.z * lenMm;
            return out;
        }
        if (!Number.isFinite(maStlCopyToolLastPointerClientXY.x) || !renderer) return null;
        const p = maStlResolveLineToolFloorPointMm(
            maStlCopyToolLastPointerClientXY.x,
            maStlCopyToolLastPointerClientXY.y
        );
        if (!p) return null;
        return maStlCopyToolSnapDisplacementFloorPointMm(p, out);
    }

    function maStlCopyToolAdvanceToNextDisplacementAfterCommit() {
        if (maStlCopyToolState !== 'displacement') return;
        maStlCopyToolResetTypingState();
        maStlCopyToolLastHoverDirUnitXz.set(1, 0);
        maStlCopyToolLastPointerClientXY.set(Number.NaN, Number.NaN);
        maStlCopyToolBuildPreviewSnapshot();
        maStlCopyToolHideRubberBand();
        maStlCopyToolHidePreview();
        maStlCopyToolSyncHud();
        queueMicrotask(function () {
            if (maStlCopyToolState !== 'displacement' || !maStlDupMoveToolHudDistanceInput()) return;
            const distInput = maStlDupMoveToolHudDistanceInput();
            try {
                distInput.focus({ preventScroll: true });
            } catch (_e) {
                distInput.focus();
            }
        });
    }

    function maStlCopyToolRefreshDisplacementRubberBand() {
        if (maStlCopyToolState !== 'displacement') {
            maStlCopyToolHideRubberBand();
            maStlCopyToolHidePreview();
            return;
        }
        const end = maStlCopyToolComputeDisplacementEndMm({ x: 0, y: 0, z: 0 });
        if (!end) {
            maStlCopyToolHideRubberBand();
            maStlCopyToolHidePreview();
            return;
        }
        maStlEnsureLineToolRubberBand();
        if (!maStlLineToolRubberBandLine) return;
        const y = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM;
        const positions = [
            maStlCopyToolBasePointMm.x,
            y,
            maStlCopyToolBasePointMm.z,
            end.x,
            y,
            end.z,
        ];
        maStlLineToolRubberBandLine.geometry.setPositions(positions);
        maStlLineToolRubberBandLine.visible = true;
        const dx = end.x - maStlCopyToolBasePointMm.x;
        const dy = end.y - maStlCopyToolBasePointMm.y;
        const dz = end.z - maStlCopyToolBasePointMm.z;
        if (Math.hypot(dx, dz) >= 1e-6) {
            if (maStlIsStretchToolActive()) {
                maStlCopyToolSyncPreviewAtStretchDisplacement(dx, dy, dz);
                maStlCopyToolSyncStretchSnapPreview(dx, dz);
            } else {
                maStlCopyToolSyncPreviewAtDisplacement(dx, dy, dz);
            }
        } else {
            maStlCopyToolHidePreview();
            if (maStlIsStretchToolActive()) {
                maStlClearStretchConnectionJunctionPreview();
            }
        }
    }

    function maStlCopyToolAdvanceToBasePointPhase() {
        maStlCopyToolUnwireWindowSelection();
        maStlCopyToolState = 'basePoint';
        maStlReenableOrbitForDupMovePlacementAfterSelection();
        maStlCopyToolResetTypingState();
        maStlCopyToolClearHoverLine();
        maStlCopyToolClearHoverMesh();
        maStlCopyToolSyncHud();
        queueMicrotask(function () {
            if (maStlCopyToolState !== 'basePoint' || !maStlDupMoveToolHudDistanceInput()) return;
            const distInput = maStlDupMoveToolHudDistanceInput();
            try {
                distInput.focus({ preventScroll: true });
            } catch (_e) {
                distInput.focus();
            }
        });
    }

    function maStlCopyToolAdvanceToDisplacementPhase(pBase) {
        maStlQuantizeUserFloorPlanPointToGridMm(pBase);
        maStlCopyToolBasePointMm.set(pBase.x, pBase.y, pBase.z);
        maStlCopyToolState = 'displacement';
        maStlCopyToolResetTypingState();
        maStlCopyToolLastHoverDirUnitXz.set(1, 0);
        maStlCopyToolBuildPreviewSnapshot();
        maStlCopyToolSyncHud();
        maStlCopyToolRefreshDisplacementRubberBand();
        queueMicrotask(function () {
            if (maStlCopyToolState !== 'displacement' || !maStlDupMoveToolHudDistanceInput()) return;
            const distInput = maStlDupMoveToolHudDistanceInput();
            try {
                distInput.focus({ preventScroll: true });
            } catch (_e) {
                distInput.focus();
            }
        });
    }

    function maStlCopyToolTryCommitBasePointFromTyping() {
        const raw = maStlCopyToolRawTypingTrimmed();
        maStlCopyToolDistanceTypeBuffer = raw;
        const pt = maStlLineToolTryParseAbsoluteFloorCoordsMm(raw, 'picking1');
        if (!pt) return false;
        maStlCopyToolAdvanceToDisplacementPhase(pt);
        return true;
    }

    function maStlCopyToolPartitionLinesForDuplicate(sourceLines) {
        const plainLines = [];
        const axisSeen = new Set();
        const wallAxisLines = [];
        for (let i = 0; i < sourceLines.length; i++) {
            const ln = sourceLines[i];
            const ud = ln.userData && ln.userData.maStlUserPlanLine;
            if (!ud) continue;
            if (ud.wallGroupId != null) {
                if (ud.wallRole === 'axis' && ud.id != null && !axisSeen.has(ud.id)) {
                    axisSeen.add(ud.id);
                    wallAxisLines.push(ln);
                }
                continue;
            }
            plainLines.push(ln);
        }
        return { plainLines: plainLines, wallAxisLines: wallAxisLines };
    }

    function maStlCopyToolOffsetPlanPointMm(src, dx, dy, dz) {
        return {
            x: src.x + dx,
            y: src.y + dy,
            z: src.z + dz,
        };
    }

    function maStlCopyToolCommitDuplicateMm(dx, dy, dz) {
        const expanded = maStlDesing2ExpandLinesWithWallGroups(Array.from(maStlCopyToolSelectedLines));
        const meshes = Array.from(maStlCopyToolSelectedMeshes);
        const parts = maStlCopyToolPartitionLinesForDuplicate(expanded);
        if (parts.plainLines.length === 0 && parts.wallAxisLines.length === 0 && meshes.length === 0) {
            return false;
        }
        const undoBefore = maStlDesing2SerializeEditSnapshot();
        const wallGroupMap = new Map();
        const polylineGroupMap = new Map();
        const weldEps = Math.max(
            maStlUserFloorLineMergeEndpointEpsMm(),
            MA_STL_WALL_DIM_LENGTH_VALUE_TOL_MM
        );
        let hadWall = false;

        for (let pi = 0; pi < parts.plainLines.length; pi++) {
            const ud = parts.plainLines[pi].userData && parts.plainLines[pi].userData.maStlUserPlanLine;
            if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
            const a = maStlCopyToolOffsetPlanPointMm(ud.p1Mm, dx, dy, dz);
            const b = maStlCopyToolOffsetPlanPointMm(ud.p2Mm, dx, dy, dz);
            let polyId = ud.polylineGroupId;
            if (polyId != null) {
                if (!polylineGroupMap.has(polyId)) {
                    polylineGroupMap.set(polyId, maStlUserFloorLineNextPolylineGroupId++);
                }
                polyId = polylineGroupMap.get(polyId);
            }
            maStlCommitUserPlanLineSegmentMm(a, b, true, polyId, null);
        }

        for (let wi = 0; wi < parts.wallAxisLines.length; wi++) {
            const src = parts.wallAxisLines[wi];
            const ud = src.userData && src.userData.maStlUserPlanLine;
            if (!ud || !ud.p1Mm || !ud.p2Mm || ud.wallGroupId == null) continue;
            hadWall = true;
            if (!wallGroupMap.has(ud.wallGroupId)) {
                wallGroupMap.set(ud.wallGroupId, maStlUserFloorLineNextWallGroupId++);
            }
            const wallGroupId = wallGroupMap.get(ud.wallGroupId);
            const halfT = maStlWall2dToolAxisFaceHalfThicknessMm(src);
            const a = maStlCopyToolOffsetPlanPointMm(ud.p1Mm, dx, dy, dz);
            const b = maStlCopyToolOffsetPlanPointMm(ud.p2Mm, dx, dy, dz);
            maStlQuantizeUserFloorPlanPointToGridMm(a);
            maStlQuantizeUserFloorPlanPointToGridMm(b);
            maStlWall2dToolSnapPlanPointToNearestAxisBodyMm(a);
            maStlWall2dToolSnapPlanPointToNearestAxisBodyMm(b);
            maStlWall2dToolSplitAxesAtInteriorHitsMm([a, b], a, b);
            maStlWeldUserFloorPlanPointToExistingEndpointsMm(a, weldEps);
            maStlWeldUserFloorPlanPointToExistingEndpointsMm(b, weldEps);
            maStlWall2dToolSnapPlanPointToNearestAxisBodyMm(a);
            maStlWall2dToolSnapPlanPointToNearestAxisBodyMm(b);
            const centerLine = maStlWall2dToolAddSegmentMm(
                a,
                b,
                { wallGroupId: wallGroupId, wallRole: 'axis', skipCollinearMerge: true },
                true
            );
            if (!centerLine) continue;
            maStlUserFloorLineSyncAxisDashDistances(centerLine);
            const centerUd = centerLine.userData && centerLine.userData.maStlUserPlanLine;
            if (!centerUd || centerUd.id == null) continue;
            for (let si = 0; si < 2; si++) {
                const sideSign = si === 0 ? 1 : -1;
                const ends = maStlWall2dToolParallelFaceEndpointsWithMitersMm(centerLine, halfT, sideSign);
                if (!ends) continue;
                maStlWall2dToolAddSegmentMm(
                    ends.p1,
                    ends.p2,
                    {
                        wallGroupId: wallGroupId,
                        wallRole: 'face',
                        linkOffsetFromLineId: centerUd.id,
                        numberOffsetMm: halfT,
                        numberWallFaceSideSign: sideSign,
                        skipCollinearMerge: true,
                    },
                    true
                );
            }
        }

        if (hadWall) {
            maStlWall2dToolRefactorAllWallJunctionsMm();
            maStlWall2dToolSplitAllAxisInteriorCrossingsMm();
            maStlWall2dToolRefactorAllWallJunctionsMm();
            maStlWeldAllUserFloorLineEndpointsMm();
            maStlWall2dToolRefactorAllWallJunctionsMm();
            maStlReapplyAllUserFloorWallAxisLineStyles();
            maStlSaveWallConnectionsNow({
                force: true,
                reason: 'copy-tool-displacement-commit',
            });
        } else {
            maStlWeldAllUserFloorLineEndpointsMm();
        }

        const scale = stlVertexToSceneScale || 1;
        for (let mi = 0; mi < meshes.length; mi++) {
            const mesh = meshes[mi];
            if (!mesh) continue;
            const clone = mesh.clone();
            clone.position.copy(mesh.position);
            clone.position.x += dx / scale;
            clone.position.z += dz / scale;
            const parent = mesh.parent || currentRoot;
            if (parent) parent.add(clone);
            if (clipStlMeshes.indexOf(clone) < 0) clipStlMeshes.push(clone);
        }
        updateClipPlanes();
        syncGroundShadowToggleUi();
        maStlDesing2PushEditSnapshotUndo(
            'copyUserFloorLinesAndStlMeshes',
            undoBefore,
            maStlDesing2SerializeEditSnapshot()
        );
        return true;
    }

    function maStlCopyToolCommitMoveMm(dx, dy, dz, undoLabel, saveReason) {
        const expanded = maStlDesing2ExpandLinesWithWallGroups(Array.from(maStlCopyToolSelectedLines));
        const meshes = Array.from(maStlCopyToolSelectedMeshes);
        const parts = maStlCopyToolPartitionLinesForDuplicate(expanded);
        if (parts.plainLines.length === 0 && parts.wallAxisLines.length === 0 && meshes.length === 0) {
            return false;
        }
        const undoBefore = maStlDesing2SerializeEditSnapshot();
        let hadWall = false;
        const undoKey = undoLabel || 'moveUserFloorLinesAndStlMeshes';
        const saveKey = saveReason || 'move-tool-displacement-commit';

        for (let pi = 0; pi < parts.plainLines.length; pi++) {
            const line = parts.plainLines[pi];
            if (!maStlTranslateUserFloorLineSegmentPlanMm(line, dx, dz)) continue;
            const ud = line.userData && line.userData.maStlUserPlanLine;
            if (ud && ud.p1Mm && ud.p2Mm) {
                maStlQuantizeUserFloorPlanPointToGridMm(ud.p1Mm);
                maStlQuantizeUserFloorPlanPointToGridMm(ud.p2Mm);
                maStlApplyUserFloorLineSegmentGeometryFromMm(line);
            }
        }

        for (let wi = 0; wi < parts.wallAxisLines.length; wi++) {
            const axisLine = parts.wallAxisLines[wi];
            hadWall = true;
            if (!maStlTranslateUserFloorLineSegmentPlanMm(axisLine, dx, dz)) continue;
            const ud = axisLine.userData && axisLine.userData.maStlUserPlanLine;
            if (ud && ud.p1Mm && ud.p2Mm) {
                maStlQuantizeUserFloorPlanPointToGridMm(ud.p1Mm);
                maStlQuantizeUserFloorPlanPointToGridMm(ud.p2Mm);
                maStlApplyUserFloorLineSegmentGeometryFromMm(axisLine);
            }
        }

        if (hadWall) {
            for (let wj = 0; wj < parts.wallAxisLines.length; wj++) {
                maStlWall2dToolRefreshAxisFaceOffsetsNoJunction(parts.wallAxisLines[wj]);
            }
            maStlWall2dToolRefactorAllWallJunctionsMm();
            maStlWall2dToolSplitAllAxisInteriorCrossingsMm();
            maStlWall2dToolRefactorAllWallJunctionsMm();
            maStlWeldAllUserFloorLineEndpointsMm();
            maStlWall2dToolRefactorAllWallJunctionsMm();
            maStlReapplyAllUserFloorWallAxisLineStyles();
            maStlSaveWallConnectionsNow({
                force: true,
                reason: saveKey,
            });
        } else {
            maStlWeldAllUserFloorLineEndpointsMm();
        }

        const scale = stlVertexToSceneScale || 1;
        for (let mi = 0; mi < meshes.length; mi++) {
            const mesh = meshes[mi];
            if (!mesh) continue;
            mesh.position.x += dx / scale;
            mesh.position.z += dz / scale;
        }
        updateClipPlanes();
        syncGroundShadowToggleUi();
        maStlDesing2PushEditSnapshotUndo(
            undoKey,
            undoBefore,
            maStlDesing2SerializeEditSnapshot()
        );
        return true;
    }

    /**
     * Tras estirar: conectar sólo si el extremo móvil (no el cursor) está a ≤ ε de un vecino.
     * @returns {boolean} true si se aplicó snap/conexión
     */
    function maStlCopyToolStretchWallAxisEndpointSnapConnect(axisLine, movedEndpoint) {
        const ud = axisLine && axisLine.userData && axisLine.userData.maStlUserPlanLine;
        if (!ud || !ud.p1Mm || !ud.p2Mm) return false;
        const axisPt = movedEndpoint === 'p1' ? ud.p1Mm : ud.p2Mm;
        const hit = maStlCopyToolProbeStretchWallAxisEndpointSnapMm(
            axisLine,
            ud,
            movedEndpoint,
            axisPt
        );
        if (!hit) return false;
        if (movedEndpoint === 'p1') {
            maStlSetUserFloorLineP1PlanMm(axisLine, hit.resolved.x, hit.resolved.y, hit.resolved.z);
        } else {
            maStlSetUserFloorLineP2PlanMm(axisLine, hit.resolved.x, hit.resolved.y, hit.resolved.z);
        }
        return true;
    }

    /** @param {number} dx @param {number} dy @param {number} dz @param {number} [clientX] @param {number} [clientY] */
    function maStlCopyToolCommitStretchByDisplacementMm(dx, dy, dz, clientX, clientY) {
        const expanded = maStlDesing2ExpandLinesWithWallGroups(Array.from(maStlCopyToolSelectedLines));
        const meshes = Array.from(maStlCopyToolSelectedMeshes);
        const parts = maStlCopyToolPartitionLinesForDuplicate(expanded);
        if (parts.plainLines.length === 0 && parts.wallAxisLines.length === 0 && meshes.length === 0) {
            return false;
        }
        const undoBefore = maStlDesing2SerializeEditSnapshot();
        let hadWall = false;
        let anyLineChanged = false;
        const outP1 = { x: 0, y: 0, z: 0 };
        const outP2 = { x: 0, y: 0, z: 0 };
        const movedTarget = { x: 0, y: 0, z: 0 };
        /** @type {Array<{ axisLine: THREE.Line2, movedEndpoint: 'p1'|'p2' }>} */
        const stretchedWallAxes = [];
        let anySnapConnect = false;

        for (let pi = 0; pi < parts.plainLines.length; pi++) {
            const line = parts.plainLines[pi];
            const ud = line.userData && line.userData.maStlUserPlanLine;
            if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
            if (
                !maStlCopyToolStretchSegmentEndpointsByDisplacementMm(
                    ud.p1Mm,
                    ud.p2Mm,
                    dx,
                    dz,
                    outP1,
                    outP2
                )
            ) {
                continue;
            }
            ud.p1Mm.x = outP1.x;
            ud.p1Mm.y = outP1.y;
            ud.p1Mm.z = outP1.z;
            ud.p2Mm.x = outP2.x;
            ud.p2Mm.y = outP2.y;
            ud.p2Mm.z = outP2.z;
            maStlQuantizeUserFloorPlanPointToGridMm(ud.p1Mm);
            maStlQuantizeUserFloorPlanPointToGridMm(ud.p2Mm);
            maStlApplyUserFloorLineSegmentGeometryFromMm(line);
            anyLineChanged = true;
        }

        for (let wi = 0; wi < parts.wallAxisLines.length; wi++) {
            const axisLine = parts.wallAxisLines[wi];
            const axisUd = axisLine.userData && axisLine.userData.maStlUserPlanLine;
            if (!axisUd || !axisUd.p1Mm || !axisUd.p2Mm) continue;
            const plan = maStlCopyToolStretchPlanFromDisplacementMm(axisUd.p1Mm, axisUd.p2Mm, dx, dz);
            if (!plan) continue;
            const ax = axisUd.p2Mm.x - axisUd.p1Mm.x;
            const az = axisUd.p2Mm.z - axisUd.p1Mm.z;
            const axisLen = Math.hypot(ax, az);
            const ux = ax / axisLen;
            const uz = az / axisLen;
            const newLen =
                plan.movedEndpoint === 'p2' ? axisLen + plan.axisDeltaMm : axisLen - plan.axisDeltaMm;
            if (newLen < maStlUserFloorSegmentMinMm() - 1e-6) continue;
            if (plan.movedEndpoint === 'p2') {
                movedTarget.x = axisUd.p1Mm.x + ux * newLen;
                movedTarget.y = axisUd.p2Mm.y;
                movedTarget.z = axisUd.p1Mm.z + uz * newLen;
            } else {
                movedTarget.x = axisUd.p2Mm.x - ux * newLen;
                movedTarget.y = axisUd.p1Mm.y;
                movedTarget.z = axisUd.p2Mm.z - uz * newLen;
            }
            let applied = false;
            if (plan.movedEndpoint === 'p1') {
                applied = maStlSetUserFloorLineP1PlanMm(
                    axisLine,
                    movedTarget.x,
                    movedTarget.y,
                    movedTarget.z
                );
            } else {
                applied = maStlSetUserFloorLineP2PlanMm(
                    axisLine,
                    movedTarget.x,
                    movedTarget.y,
                    movedTarget.z
                );
            }
            if (!applied) continue;
            maStlQuantizeUserFloorPlanPointToGridMm(axisUd.p1Mm);
            maStlQuantizeUserFloorPlanPointToGridMm(axisUd.p2Mm);
            maStlApplyUserFloorLineSegmentGeometryFromMm(axisLine);
            hadWall = true;
            stretchedWallAxes.push({
                axisLine: axisLine,
                movedEndpoint: plan.movedEndpoint,
            });
            anyLineChanged = true;
        }

        if (!anyLineChanged && meshes.length === 0) return false;

        if (hadWall) {
            for (let sc = 0; sc < stretchedWallAxes.length; sc++) {
                const item = stretchedWallAxes[sc];
                if (
                    maStlCopyToolStretchWallAxisEndpointSnapConnect(
                        item.axisLine,
                        item.movedEndpoint
                    )
                ) {
                    anySnapConnect = true;
                }
            }
            maStlWallEditFinalize().finalizeWallAxes(parts.wallAxisLines, {
                allowWeld: anySnapConnect,
                allowSplit: true,
                saveReason: 'stretch-tool-displacement-commit',
            });
        } else if (anyLineChanged) {
            maStlWeldAllUserFloorLineEndpointsMm();
        }

        const scale = stlVertexToSceneScale || 1;
        for (let mi = 0; mi < meshes.length; mi++) {
            const mesh = meshes[mi];
            if (!mesh) continue;
            mesh.position.x += dx / scale;
            mesh.position.z += dz / scale;
        }
        updateClipPlanes();
        syncGroundShadowToggleUi();
        maStlDesing2PushEditSnapshotUndo(
            'stretchUserFloorLinesAndStlMeshes',
            undoBefore,
            maStlDesing2SerializeEditSnapshot()
        );
        return true;
    }

    /** @param {number} dx @param {number} dy @param {number} dz @param {number} [clientX] @param {number} [clientY] */
    function maStlCopyToolCommitStretchMm(dx, dy, dz, clientX, clientY) {
        return maStlCopyToolCommitStretchByDisplacementMm(dx, dy, dz, clientX, clientY);
    }

    function maStlCopyToolBlurDupMoveHudInputs() {
        const distInput = maStlDupMoveToolHudDistanceInput();
        const angleInput = maStlDupMoveToolHudAngleInput();
        if (distInput && document.activeElement === distInput) distInput.blur();
        if (angleInput && document.activeElement === angleInput) angleInput.blur();
    }

    function maStlCopyToolResetPlacementTapGesture() {
        maStlCopyToolPlacementPointerId = -1;
        maStlCopyToolPlacementPointerDownXY.set(Number.NaN, Number.NaN);
    }

    /** @param {PointerEvent} ev */
    function maStlCopyToolPlacementWasTap(ev) {
        if (!Number.isFinite(maStlCopyToolPlacementPointerDownXY.x)) return false;
        if (ev.pointerId !== maStlCopyToolPlacementPointerId) return false;
        const dx = ev.clientX - maStlCopyToolPlacementPointerDownXY.x;
        const dy = ev.clientY - maStlCopyToolPlacementPointerDownXY.y;
        return Math.hypot(dx, dy) <= MA_STL_COPY_TOOL_PLACEMENT_TAP_MAX_PX;
    }

    function maStlCopyToolPrimaryStretchAxisLine() {
        const expanded = maStlDesing2ExpandLinesWithWallGroups(Array.from(maStlCopyToolSelectedLines));
        const parts = maStlCopyToolPartitionLinesForDuplicate(expanded);
        if (parts.wallAxisLines.length > 0) return parts.wallAxisLines[0];
        if (parts.plainLines.length > 0) return parts.plainLines[0];
        return null;
    }

    /**
     * Estirar AutoCAD: ¿el vector base→segundo punto cambia algún segmento?
     * @param {number} dx
     * @param {number} dz
     * @returns {boolean}
     */
    function maStlCopyToolStretchWouldChangeByDisplacementMm(dx, dz) {
        if (Math.hypot(dx, dz) < 1e-6) return false;
        const expanded = maStlDesing2ExpandLinesWithWallGroups(Array.from(maStlCopyToolSelectedLines));
        const parts = maStlCopyToolPartitionLinesForDuplicate(expanded);
        const outP1 = { x: 0, y: 0, z: 0 };
        const outP2 = { x: 0, y: 0, z: 0 };
        for (let wi = 0; wi < parts.wallAxisLines.length; wi++) {
            const axisUd =
                parts.wallAxisLines[wi].userData && parts.wallAxisLines[wi].userData.maStlUserPlanLine;
            if (!axisUd || !axisUd.p1Mm || !axisUd.p2Mm) continue;
            const plan = maStlCopyToolStretchPlanFromDisplacementMm(axisUd.p1Mm, axisUd.p2Mm, dx, dz);
            if (!plan) continue;
            const axisLen = Math.hypot(
                axisUd.p2Mm.x - axisUd.p1Mm.x,
                axisUd.p2Mm.z - axisUd.p1Mm.z
            );
            const newLen =
                plan.movedEndpoint === 'p2' ? axisLen + plan.axisDeltaMm : axisLen - plan.axisDeltaMm;
            if (newLen >= maStlUserFloorSegmentMinMm() - 1e-6 && Math.abs(plan.axisDeltaMm) >= 1e-6) {
                return true;
            }
        }
        for (let pi = 0; pi < parts.plainLines.length; pi++) {
            const ud = parts.plainLines[pi].userData && parts.plainLines[pi].userData.maStlUserPlanLine;
            if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
            if (
                maStlCopyToolStretchSegmentEndpointsByDisplacementMm(
                    ud.p1Mm,
                    ud.p2Mm,
                    dx,
                    dz,
                    outP1,
                    outP2
                )
            ) {
                if (
                    Math.hypot(outP1.x - ud.p1Mm.x, outP1.z - ud.p1Mm.z) >= 1e-6 ||
                    Math.hypot(outP2.x - ud.p2Mm.x, outP2.z - ud.p2Mm.z) >= 1e-6
                ) {
                    return true;
                }
            }
        }
        return maStlCopyToolSelectedMeshes.size > 0;
    }

    /**
     * Punto base o confirmación de desplazamiento (tap corto). Compartido por click y pointerup:
     * en este visor el segundo clic a veces no llega tras preventDefault en pointerdown.
     * @param {number} clientX @param {number} clientY @returns {boolean}
     */
    function maStlCopyToolHandlePlacementTap(clientX, clientY) {
        if (!maStlIsDupMoveToolPlacementPhaseActive()) return false;
        const now = performance.now();
        if (now - maStlCopyToolPlacementTapHandledAt < 80) return false;
        const p = maStlResolveLineToolFloorPointMm(clientX, clientY);
        if (!p) return false;
        const pSnap = maStlApplyLineToolVertexSnapOnClickMm(clientX, clientY, p);
        const placementPt = maStlIsStretchToolActive() ? p : pSnap;
        if (maStlCopyToolState === 'basePoint') {
            maStlCopyToolLastPointerClientXY.set(clientX, clientY);
            maStlCopyToolAdvanceToDisplacementPhase(placementPt);
            maStlCopyToolPlacementTapHandledAt = now;
            return true;
        }
        if (maStlCopyToolState === 'displacement') {
            maStlCopyToolBlurDupMoveHudInputs();
            maStlCopyToolLastPointerClientXY.set(clientX, clientY);
            maStlCopyToolMaybeUpdateHoverDirFromCandidate(placementPt);
            const end = { x: 0, y: 0, z: 0 };
            let hasEnd = !!maStlCopyToolSnapDisplacementFloorPointMm(placementPt, end);
            if (!hasEnd) {
                hasEnd = !!maStlCopyToolComputeDisplacementEndMm(end);
            }
            if (!hasEnd) {
                maStlCopyToolShowDisplacementInvalidToast();
                return false;
            }
            const ok = maStlCopyToolTryCommitDisplacementAtEndMm(end, clientX, clientY);
            if (!ok) maStlCopyToolShowDisplacementInvalidToast();
            if (ok) maStlCopyToolPlacementTapHandledAt = now;
            return ok;
        }
        return false;
    }

    function maStlCopyToolShowDisplacementInvalidToast() {
        const hud = maStlDupMoveToolHud();
        const toastTpl = hud && hud.getAttribute(maStlDupMoveToolDistanceInvalidToastAttr());
        if (toastTpl) maStlDesing2ShowSaveViewToast(toastTpl);
    }

    /** @param {{ x: number, y: number, z: number }} end @param {number} [clientX] @param {number} [clientY] */
    function maStlCopyToolTryCommitDisplacementAtEndMm(end, clientX, clientY) {
        if (!end || maStlCopyToolState !== 'displacement') return false;
        maStlQuantizeUserFloorPlanPointToGridMm(end);
        const dx = end.x - maStlCopyToolBasePointMm.x;
        const dy = end.y - maStlCopyToolBasePointMm.y;
        const dz = end.z - maStlCopyToolBasePointMm.z;
        if (maStlCopyToolKind === 'stretch') {
            if (!maStlCopyToolStretchWouldChangeByDisplacementMm(dx, dz)) {
                maStlCopyToolShowDisplacementInvalidToast();
                return false;
            }
        } else if (Math.hypot(dx, dz) < 1e-6) {
            maStlCopyToolShowDisplacementInvalidToast();
            return false;
        }
        const ok =
            maStlCopyToolKind === 'copy'
                ? maStlCopyToolCommitDuplicateMm(dx, dy, dz)
                : maStlCopyToolKind === 'stretch'
                  ? maStlCopyToolCommitStretchByDisplacementMm(dx, dy, dz, clientX, clientY)
                  : maStlCopyToolCommitMoveMm(dx, dy, dz);
        if (ok) {
            if (maStlCopyToolKind === 'stretch') {
                maStlStopCopyToolModesToolbar();
            } else {
                maStlCopyToolAdvanceToNextDisplacementAfterCommit();
            }
        }
        return ok;
    }

    function maStlCopyToolTryCommitDisplacement() {
        const end = { x: 0, y: 0, z: 0 };
        const cx = Number.isFinite(maStlCopyToolLastPointerClientXY.x)
            ? maStlCopyToolLastPointerClientXY.x
            : Number.NaN;
        const cy = Number.isFinite(maStlCopyToolLastPointerClientXY.y)
            ? maStlCopyToolLastPointerClientXY.y
            : Number.NaN;
        const hasEnd = !!maStlCopyToolComputeDisplacementEndMm(end);
        if (!hasEnd) {
            maStlCopyToolShowDisplacementInvalidToast();
            return false;
        }
        return maStlCopyToolTryCommitDisplacementAtEndMm(end, cx, cy);
    }

    function maStlCopyToolHasSelection() {
        return maStlCopyToolSelectedLines.size > 0 || maStlCopyToolSelectedMeshes.size > 0;
    }

    function maStlCopyToolApplyWindowKeydownConfirm(ev) {
        if (!maStlIsDupMoveToolActive() || !maStlDesingV2Viewer) return false;
        if (!maStlIsDesing2ViewerShellVisibleForKeyboardShortcuts()) return false;
        if (ev.defaultPrevented) return false;
        const isEnter = ev.key === 'Enter' || ev.code === 'Enter' || ev.key === 'NumpadEnter';
        if (!isEnter || ev.shiftKey || ev.ctrlKey || ev.metaKey || ev.altKey) return false;
        const ae = document.activeElement;
        if (maStlIsUserFloorLineDimEditOverlayActive()) return false;
        if (maStlCopyToolState === 'selecting') {
            if (!maStlCopyToolHasSelection()) return false;
            if (maStlDesingV2AvoidKeyboardShortcutSteal(ae)) return false;
            ev.preventDefault();
            maStlCopyToolAdvanceToBasePointPhase();
            return true;
        }
        const distInput = maStlDupMoveToolHudDistanceInput();
        const angleInput = maStlDupMoveToolHudAngleInput();
        if (
            ae !== distInput &&
            ae !== angleInput &&
            maStlDesingV2AvoidKeyboardShortcutSteal(ae)
        ) {
            return false;
        }
        if (maStlCopyToolState === 'basePoint') {
            if (maStlCopyToolTryCommitBasePointFromTyping()) {
                ev.preventDefault();
                return true;
            }
            return false;
        }
        if (maStlCopyToolState === 'displacement') {
            const ok = maStlCopyToolTryCommitDisplacement();
            if (ok) ev.preventDefault();
            return ok;
        }
        return false;
    }

    /** Escape cancela copiar/mover en cualquier fase (selección, base, desplazamiento). */
    function maStlCopyToolApplyWindowKeydownEscape(ev) {
        if (ev.key !== 'Escape' && ev.code !== 'Escape') return false;
        if (!maStlIsDupMoveToolActive() || !maStlDesingV2Viewer) return false;
        if (!maStlIsDesing2ViewerShellVisibleForKeyboardShortcuts()) return false;
        if (ev.defaultPrevented) return false;
        ev.preventDefault();
        ev.stopPropagation();
        maStlStopCopyToolModesToolbar(false);
        return true;
    }

    function maStlCopyToolApplyWindowKeydownToInputBuffer(ev) {
        if (!maStlIsDupMoveToolPlacementPhaseActive() || !maStlDesingV2Viewer) return false;
        if (!maStlIsDesing2ViewerShellVisibleForKeyboardShortcuts()) return false;
        if (ev.defaultPrevented) return false;
        if (ev.ctrlKey || ev.metaKey || ev.altKey) return false;
        if (ev.key === 'Escape' || ev.code === 'Escape') return false;
        if (ev.key === 'Enter' || ev.code === 'Enter' || ev.key === 'NumpadEnter') {
            if (maStlCopyToolState === 'basePoint') {
                const ok = maStlCopyToolTryCommitBasePointFromTyping();
                if (ok) ev.preventDefault();
                return ok;
            }
            if (maStlCopyToolState === 'displacement') {
                const ok = maStlCopyToolTryCommitDisplacement();
                if (ok) ev.preventDefault();
                return ok;
            }
            return false;
        }
        const ae = document.activeElement;
        const distInput = maStlDupMoveToolHudDistanceInput();
        const angleInput = maStlDupMoveToolHudAngleInput();
        if (distInput && ae === distInput) return false;
        if (angleInput && ae === angleInput) return false;
        if (maStlIsUserFloorLineDimEditOverlayActive()) return false;
        if (maStlDesingV2AvoidKeyboardShortcutSteal(ae)) return false;
        if (
            (maStlCopyToolToggleBtn && ae === maStlCopyToolToggleBtn) ||
            (maStlMoveToolToggleBtn && ae === maStlMoveToolToggleBtn)
        ) {
            return true;
        }
        if (ae && ae.closest && ae.closest('button, a[href], [role="button"], label')) return false;
        let next = maStlCopyToolDistanceTypeBuffer;
        const k = ev.key;
        if (k === 'Backspace') {
            if (!next.length) return false;
            ev.preventDefault();
            next = next.slice(0, -1);
        } else if (k === 'Delete') {
            if (!next.length) return false;
            ev.preventDefault();
            next = '';
        } else if (k.length === 1 && /^[0-9.,;\sMm#@<>\-+°º]$/.test(k)) {
            ev.preventDefault();
            next += k;
        } else {
            return false;
        }
        maStlCopyToolDistanceTypeBuffer = next;
        if (distInput && ae !== distInput) {
            distInput.value = next;
        }
        maStlCopyToolSyncTypingPreviewUi();
        maStlCopyToolSyncHud();
        maStlCopyToolRefreshDisplacementRubberBand();
        return true;
    }

    function maStlStartCopyToolModesToolbar() {
        if (maStlIsCopyToolActive()) return;
        maStlWall2dToolResumeState = null;
        if (maStlIsWall2dToolActive()) maStlStopWall2dToolModesToolbar(false);
        if (maStlIsLineToolPlacementActive()) maStlStopLineToolModesToolbar(false);
        if (maStlIsOffsetToolActive()) maStlStopOffsetToolModesToolbar(false);
        if (maStlIsDeleteToolActive()) maStlStopDeleteToolModesToolbar(false);
        if (maStlIsDupMoveToolActive()) maStlStopCopyToolModesToolbar(false);
        if (maStlIsInsertCornerToolActive()) maStlStopInsertCornerToolModesToolbar(false);
        if (maStlIsInsertEnclosureToolActive()) maStlStopInsertEnclosureToolModesToolbar(false);
        if (maStlIsWall3dToolActive()) maStlStopWall3dToolModesToolbar(false);
        maStlStopWallDimToolModesToolbar();
        maStlDesing2SetLastToolbarCommandId('ma-stl-tool-copy');
        maStlStopRulerAnchorPickModesToolbar();
        maStlTeardownPickHighlightsOnly();
        maStlDisposeUserFloorLineDimEdit(false);
        maStlClearUserFloorLineSelection();
        maStlHideUserFloorLineDimHud(true);
        maStlCopyToolClearSelection();
        maStlCopyToolClearHoverLine();
        maStlCopyToolClearHoverMesh();
        maStlCopyToolResetTypingState();
        maStlCopyToolKind = 'copy';
        maStlCopyToolActive = true;
        maStlCopyToolState = 'selecting';
        maStlCopyToolLastPointerClientXY.set(Number.NaN, Number.NaN);
        maStlLockOrbitFullyForToolSelection();
        maStlSyncLineToolToggleBtnUi();
        maStlLineToolPickCursorSync();
        maStlCopyToolSyncHud();
        maStlCopyToolWireWindowSelection();
        if (maStlCopyToolToggleBtn && document.activeElement === maStlCopyToolToggleBtn) {
            maStlCopyToolToggleBtn.blur();
        }
    }

