    /**
     * Clic derecho corto en canvas (sin arrastre pan): refactor global de segmentos colineales.
     * Durante herramienta línea el RMB sigue siendo pan; sólo dispara si el gesto no movió órbita.
     */
    function onCanvasPointerDownUserFloorLineRefactorRmb(ev) {
        if (!maStlDesingV2Viewer || ev.button !== 2) return;
        if (maStlLineToolOpenPolarInputFromCurrentRubberBand(ev)) {
            _maStlUserFloorLineRefactorRmbGesture = null;
            return;
        }
        const canvas = renderer.domElement;
        if (ev.currentTarget !== canvas) return;
        const rawTarget = ev.target;
        if (rawTarget && typeof rawTarget.closest === 'function') {
            if (rawTarget.closest('button, input, select, textarea, [role="button"], label')) return;
        }
        if (maStlIsRulerAnchorPickModeActive()) return;
        if (maStlIsUserFloorLineDimEditOverlayActive()) return;
        _maStlUserFloorLineRefactorRmbGesture = {
            clientX: ev.clientX,
            clientY: ev.clientY,
        };
        if (controls) {
            _maStlUserFloorLineRefactorRmbOrbitBaseline.copy(controls.target);
        }
    }

    function onWindowPointerUpUserFloorLineRefactorRmb(ev) {
        if (ev.button !== 2 || !_maStlUserFloorLineRefactorRmbGesture) return;
        const track = _maStlUserFloorLineRefactorRmbGesture;
        _maStlUserFloorLineRefactorRmbGesture = null;
        if (!maStlDesingV2Viewer) return;
        const dx = ev.clientX - track.clientX;
        const dy = ev.clientY - track.clientY;
        const maxPx = MA_STL_USER_FLOOR_LINE_REFACTOR_RMB_CLICK_MAX_PX;
        if (dx * dx + dy * dy > maxPx * maxPx) return;
        if (controls) {
            const epsMm = MA_STL_DESING2_PICK_ORBIT_PAN_DETECTION_EPS_MM;
            if (
                controls.target.distanceToSquared(_maStlUserFloorLineRefactorRmbOrbitBaseline) >
                epsMm * epsMm
            ) {
                return;
            }
        }
        const undoBeforeRefactor = maStlDesing2SerializeEditSnapshot();
        maStlRefactorUserFloorLinesMergeCollinear();
        maStlDesing2PushEditSnapshotUndo(
            'refactorUserFloorLines',
            undoBeforeRefactor,
            maStlDesing2SerializeEditSnapshot()
        );
    }

    function onWindowPointerCancelUserFloorLineRefactorRmb(ev) {
        if (ev.button !== 2) return;
        _maStlUserFloorLineRefactorRmbGesture = null;
    }

    function maStlLineToolOpenPolarInputFromCurrentRubberBand(ev) {
        if (!maStlIsLineToolPlacementActive() || maStlLineToolState !== 'picking2' || !maStlDesingV2Viewer) {
            return false;
        }
        const end = maStlLineToolComputeRubberBandEndMm(_maStlLineToolRubberEndMm);
        if (!end || !maStlLineToolHudDistanceInput) return false;
        const dx = end.x - maStlLineToolPoint1Mm.x;
        const dz = end.z - maStlLineToolPoint1Mm.z;
        const lenMm = Math.hypot(dx, dz);
        if (!(lenMm >= maStlUserFloorSegmentMinMm())) return false;
        const lenText = maStlDesing2DimEditableMetersDisplayFromMm(
            maStlDesing2LengthMmRoundedEditableFromMm(lenMm)
        );
        const angleText = maStlFormatFloorPlanAngleDegDisplay(
            maStlFloorPlanCadAngleDegFromDeltaMm(dx, dz)
        ).replace('\u00B0', '');
        if (ev) {
            ev.preventDefault();
            ev.stopPropagation();
            if (typeof ev.stopImmediatePropagation === 'function') ev.stopImmediatePropagation();
        }
        maStlLineToolDistanceTypeBuffer = lenText;
        maStlLineToolAngleTypeBuffer = angleText;
        maStlLineToolHudDistanceInput.value = lenText;
        if (maStlLineToolHudAngleInput) {
            maStlLineToolHudAngleInput.value = angleText;
        }
        maStlLineToolSyncTypingPreviewUi();
        maStlLineToolRefreshPicking2RubberBand();
        maStlSyncLineToolHud();
        try {
            maStlLineToolHudDistanceInput.focus({ preventScroll: true });
            maStlLineToolHudDistanceInput.select();
        } catch (_eFocusPolar) {
            maStlLineToolHudDistanceInput.focus();
        }
        return true;
    }

    function onCanvasContextMenuLineToolPolarInput(ev) {
        if (maStlWall3dInspectInteractionEnabled()) {
            const rawTarget = ev.target;
            if (rawTarget && typeof rawTarget.closest === 'function') {
                if (rawTarget.closest('button, input, select, textarea, [role="button"], label')) return;
            }
            if (maStlWallInspectTryAlertAtPointer(ev.clientX, ev.clientY)) {
                ev.preventDefault();
                ev.stopPropagation();
                if (typeof ev.stopImmediatePropagation === 'function') ev.stopImmediatePropagation();
                return;
            }
        }
        if (maStlLineToolOpenPolarInputFromCurrentRubberBand(ev)) return;
        if (maStlLineToolState === 'picking2' || maStlIsUserFloorLineDimEditOverlayActive()) {
            ev.preventDefault();
            ev.stopPropagation();
            if (typeof ev.stopImmediatePropagation === 'function') ev.stopImmediatePropagation();
        }
    }

    /**
     * Dos clics simples: P1 y P2. Se usa `click` (no `pointerdown`) para no colocar si el usuario arrastró el botón
     * izquierdo; el {@link onCanvasPointerDownLineTool} en captura evita que OrbitControls inicie rotación en el down.
     */
    function onCanvasClickLineTool(ev) {
        if (!maStlIsLineToolPlacementActive() || !maStlDesingV2Viewer) return;
        if (ev.button !== 0) return;
        const canvas = renderer.domElement;
        if (ev.currentTarget !== canvas) return;
        const rawTarget = ev.target;
        if (rawTarget && typeof rawTarget.closest === 'function') {
            if (rawTarget.closest('button, input, select, textarea, [role="button"], label')) return;
        }
        ev.preventDefault();
        ev.stopPropagation();
        ev.stopImmediatePropagation();
        const p = maStlResolveLineToolFloorPointMm(ev.clientX, ev.clientY);
        if (!p) {
            if (maStlLineToolState === 'picking1') {
                maStlStopLineToolModesToolbar(false);
            }
            return;
        }
        const pSnap = maStlApplyLineToolVertexSnapOnClickMm(ev.clientX, ev.clientY, p);
        if (maStlLineToolState === 'picking1') {
            maStlLineToolLastPointerClientXY.set(ev.clientX, ev.clientY);
            maStlLineToolMaybeUpdateHoverDirFromP2Candidate(pSnap);
            maStlLineToolAdvancePicking1ToPicking2Mm(pSnap);
            return;
        }
        if (maStlLineToolState === 'picking2') {
            const end = maStlLineToolComputeSegmentEndMmFromFloorPointMm(pSnap);
            maStlQuantizeUserFloorPlanPointToGridMm(end);
            if (maStlIsWall2dToolPlacementActive()) {
                maStlWall2dToolCommitWallSegmentMm(maStlLineToolPoint1Mm, end);
                if (pSnap.maStlLineVertexSnap) {
                    maStlStopLineToolModesToolbar(false);
                } else {
                    maStlWall2dToolAdvanceAfterSegmentMm(end);
                }
            } else {
                maStlCommitUserPlanLineSegmentMm(maStlLineToolPoint1Mm, end);
                if (pSnap.maStlLineVertexSnap) {
                    maStlStopLineToolModesToolbar(false);
                } else {
                    maStlPolylineToolAdvanceAfterSegmentMm(end);
                }
            }
        }
    }

    /**
     * Hover rejilla (pointermove): highlight + HUD únicamente — sin cámara, target, controls ni reglas.
     * @returns {boolean} true si hay snap en planta (idle o connected)
     */
    function maStlUpdateGridIntersectionPickHover(clientX, clientY) {
        if (maStlRulerAnchorPickMode !== 'grid' || !maStlDesingV2Viewer || !renderer) {
            maStlClearGridIntersectionPickHighlight();
            maStlClearLineToolVertexSnapHighlight();
            return false;
        }
        const canvas = renderer.domElement;
        const cam = activeCamera();
        const floorHit = maStlClientRayToWorkspaceFloor(
            clientX,
            clientY,
            canvas,
            cam,
            orbitPivotNdc,
            orbitPivotRaycaster,
            _maStlInsertionFloorProbe
        );
        if (!floorHit) {
            maStlClearGridIntersectionPickHighlight();
            maStlClearLineToolVertexSnapHighlight();
            return false;
        }
        const lineSnap = maStlFindFloorLineVertexSnapAtPointer(
            clientX,
            clientY,
            MA_STL_LINE_TOOL_GRID_PICK_SCREEN_PX_BOOST
        );
        if (lineSnap) {
            const onMajor = maStlIsOnDisplayedMajorGridLineAtMm(lineSnap.x, lineSnap.z);
            maStlSetLineToolVertexSnapHighlight(lineSnap, true, onMajor);
            maStlClearGridIntersectionPickHighlight();
            return true;
        }
        maStlClearLineToolVertexSnapHighlight();
        const gridSnap = maStlSnapFloorToGridIntersection(
            { x: _maStlInsertionFloorProbe.x, z: _maStlInsertionFloorProbe.z },
            { clientX: clientX, clientY: clientY, camera: cam, canvas: canvas, maxDim: lastMaxDim },
            desing2EnvGridSnapMm
        );
        const onMajorGrid = maStlIsOnDisplayedMajorGridLineAtMm(gridSnap.x, gridSnap.z);
        maStlSetGridIntersectionPickHighlight(
            gridSnap.active ? 'connected' : 'idle',
            gridSnap,
            onMajorGrid
        );
        return true;
    }

    function onCanvasPointerMoveRulerAnchorPick(ev) {
        if (!maStlIsRulerAnchorPickModeActive()) return;
        if (maStlRulerAnchorPickMode === 'grid') {
            maStlUpdateGridIntersectionPickHover(ev.clientX, ev.clientY);
            return;
        }
        maStlUpdateObjectInsertionPickHover(ev.clientX, ev.clientY);
    }

    function onCanvasPointerMoveWall3dInspectGlobal(ev) {
        if (!maStlDesingV2Viewer) return;
        maStlWallInspectSyncHoverAtPointer(ev.clientX, ev.clientY);
    }

    function onHudContextMenuWallInspectGlobal(ev) {
        if (!maStlDesingV2Viewer || !maStlWall3dInspectInteractionEnabled()) return;
        const rawTarget = ev.target;
        if (rawTarget && typeof rawTarget.closest === 'function') {
            if (rawTarget.closest('button, input, select, textarea, [role="button"], label')) return;
        }
        if (maStlWallInspectTryAlertAtPointer(ev.clientX, ev.clientY)) {
            ev.preventDefault();
            ev.stopPropagation();
            if (typeof ev.stopImmediatePropagation === 'function') ev.stopImmediatePropagation();
        }
    }

    function onCanvasPointerLeaveInsertionPick() {
        onCanvasPointerLeaveUserFloorLineHover();
        maStlWallInspectClearHover();
        if (maStlIsLineToolPlacementActive()) {
            maStlClearGridIntersectionPickHighlight();
            maStlClearLineToolVertexSnapHighlight();
            maStlSyncLineToolHud();
            if (maStlLineToolState === 'picking2') {
                maStlLineToolRefreshPicking2RubberBand();
            }
        }
        if (maStlIsDupMoveToolPlacementPhaseActive()) {
            maStlClearGridIntersectionPickHighlight();
            maStlClearLineToolVertexSnapHighlight();
            maStlCopyToolSyncHud();
            if (maStlCopyToolState === 'displacement') {
                maStlCopyToolRefreshDisplacementRubberBand();
            }
        }
        if (maStlIsInsertCornerToolPlacementActive()) {
            maStlClearGridIntersectionPickHighlight();
            maStlClearLineToolVertexSnapHighlight();
            maStlSyncInsertCornerToolHud();
            if (maStlInsertCornerToolState === 'picking2') {
                maStlInsertCornerToolHidePreview();
            }
        }
        if (maStlIsInsertEnclosureToolPlacementActive()) {
            maStlClearGridIntersectionPickHighlight();
            maStlClearLineToolVertexSnapHighlight();
            maStlSyncInsertEnclosureToolHud();
            if (maStlInsertEnclosureToolState === 'picking2') {
                maStlInsertEnclosureToolHidePreview();
            }
        }
        if (maStlIsOffsetToolActive()) {
            maStlOffsetToolClearHoverLine();
            maStlOffsetToolHidePreviewLine();
            maStlOffsetToolClearTransientOverlays();
        }
        if (!maStlIsRulerAnchorPickModeActive()) return;
        maStlClearStlPickHoverHighlight();
        maStlClearInsertionPickHighlight();
        maStlClearGridIntersectionPickHighlight();
        maStlClearLineToolVertexSnapHighlight();
    }

    function maStlWall3dInspectClearHoverMesh() {
        if (!maStlWall3dInspectHoverMesh || !maStlWall3dInspectHoverState) {
            maStlWall3dInspectHoverMesh = null;
            maStlWall3dInspectHoverState = null;
            return;
        }
        const st = maStlWall3dInspectHoverState;
        const mat = st.material;
        if (mat && mat.color) {
            mat.color.setHex(st.colorHex);
        }
        if (mat && mat.emissive && st.emissiveHex != null) {
            mat.emissive.setHex(st.emissiveHex);
        }
        maStlWall3dInspectHoverMesh = null;
        maStlWall3dInspectHoverState = null;
    }

    function maStlWallInspectClearHoverLine() {
        if (!maStlWallInspectHoverLine) return;
        if (maStlWallInspectHoverLine.material) {
            maStlApplyUserFloorLineBaseMaterialForLine(maStlWallInspectHoverLine);
        }
        maStlWallInspectHoverLine = null;
    }

    function maStlWallInspectSetHoverLine(line) {
        if (line === maStlWallInspectHoverLine) return;
        maStlWallInspectClearHoverLine();
        if (!line || !line.material) return;
        maStlWallInspectHoverLine = line;
        const mat = line.material;
        if (mat.color) {
            mat.color.setHex(maStlWallInspectHoverHexForMode(maStlWallInspectActiveMode()));
            mat.needsUpdate = true;
        }
    }

    function maStlWallInspectClearHover() {
        maStlWall3dInspectClearHoverMesh();
        maStlWallInspectClearHoverLine();
    }

    function maStlWall3dInspectSetHoverMesh(mesh) {
        if (mesh === maStlWall3dInspectHoverMesh) return;
        maStlWall3dInspectClearHoverMesh();
        if (!mesh || !mesh.isMesh || !mesh.material) return;
        const mat = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material;
        if (!mat || !mat.color) return;
        maStlWall3dInspectHoverMesh = mesh;
        maStlWall3dInspectHoverState = {
            material: mat,
            colorHex: mat.color.getHex(),
            emissiveHex: mat.emissive ? mat.emissive.getHex() : null,
        };
        mat.color.setHex(maStlWallInspectHoverHexForMode(maStlWallInspectActiveMode()));
        if (mat.emissive) {
            mat.emissive.setHex(0x1a1200);
        }
    }

    function maStlWall3dInspectPickMeshHitAtPointer(clientX, clientY) {
        if (!renderer || !maStlWall3dMeshesGroup || !maStlWall3dMeshesGroup.visible) return null;
        const canvas = renderer.domElement;
        const rect = canvas.getBoundingClientRect();
        const rw = Math.max(rect.width, 1);
        const rh = Math.max(rect.height, 1);
        _maStlFloorPickNdc.set(
            ((clientX - rect.left) / rw) * 2 - 1,
            -((clientY - rect.top) / rh) * 2 + 1
        );
        const cam = activeCamera();
        if (!cam) return null;
        cam.updateMatrixWorld(true);
        orbitPivotRaycaster.setFromCamera(_maStlFloorPickNdc, cam);
        const hits = orbitPivotRaycaster.intersectObject(maStlWall3dMeshesGroup, true);
        for (let i = 0; i < hits.length; i++) {
            const obj = hits[i] && hits[i].object;
            if (!obj || !obj.isMesh || !obj.userData || !obj.userData.maStlWall3dGenerated) continue;
            if (obj.userData.maStlAtk60TFootprintGuide || obj.userData.maStlAtk60XFootprintGuide) continue;
            return hits[i];
        }
        return null;
    }

    function maStlWall2dInspectPickMeshHitAtPointer(clientX, clientY) {
        if (!renderer || !maStlWall2dModelMeshesGroup || !maStlWall2dModelMeshesGroup.visible) return null;
        const canvas = renderer.domElement;
        const rect = canvas.getBoundingClientRect();
        const rw = Math.max(rect.width, 1);
        const rh = Math.max(rect.height, 1);
        _maStlFloorPickNdc.set(
            ((clientX - rect.left) / rw) * 2 - 1,
            -((clientY - rect.top) / rh) * 2 + 1
        );
        const cam = activeCamera();
        if (!cam) return null;
        cam.updateMatrixWorld(true);
        orbitPivotRaycaster.setFromCamera(_maStlFloorPickNdc, cam);
        const hits = orbitPivotRaycaster.intersectObject(maStlWall2dModelMeshesGroup, true);
        for (let i = 0; i < hits.length; i++) {
            const obj = hits[i] && hits[i].object;
            if (!obj || !obj.isMesh || !obj.userData || !obj.userData.maStlWall2dModelGenerated) continue;
            return hits[i];
        }
        return null;
    }

    function maStlWall2dInspectResolveMeshFromLine(line) {
        if (!line || !line.userData || !line.userData.maStlUserPlanLine) return null;
        if (!maStlWall2dModelMeshesGroup || !maStlWall2dModelMeshesGroup.visible) return null;
        const ud = line.userData.maStlUserPlanLine;
        if (!ud.p1Mm || !ud.p2Mm) return null;
        const targetX = (ud.p1Mm.x + ud.p2Mm.x) * 0.5;
        const targetZ = (ud.p1Mm.z + ud.p2Mm.z) * 0.5;
        let best = null;
        let bestDistSq = Infinity;
        const center = new THREE.Vector3();
        maStlWall2dModelMeshesGroup.traverse(function (obj) {
            if (!obj || !obj.isMesh || !obj.geometry || !obj.userData) return;
            if (!obj.userData.maStlWall2dModelGenerated) return;
            if (obj.userData.maStlWall2dRectRefs || obj.userData.maStlAtk60TFootprintGuide || obj.userData.maStlAtk60XFootprintGuide) {
                return;
            }
            if (!obj.geometry.boundingSphere) obj.geometry.computeBoundingSphere();
            if (!obj.geometry.boundingSphere) return;
            center.copy(obj.geometry.boundingSphere.center).applyMatrix4(obj.matrixWorld);
            const dx = center.x - targetX;
            const dz = center.z - targetZ;
            const d2 = dx * dx + dz * dz;
            if (d2 < bestDistSq) {
                bestDistSq = d2;
                best = obj;
            }
        });
        return best;
    }

    function maStlWall3dInspectResolveAxisUdFromPoint(hitPoint) {
        if (!hitPoint) return null;
        const axes = maStlWall2dToolCollectAllAxisLines();
        if (!axes || !axes.length) return null;
        let bestUd = null;
        let bestDist = Infinity;
        for (let i = 0; i < axes.length; i++) {
            const axis = axes[i];
            const ud = axis && axis.userData && axis.userData.maStlUserPlanLine;
            if (!ud || !ud.p1Mm || !ud.p2Mm) continue;
            const proj = maStlProjectPointOntoUserFloorSegmentBodyXzMm(
                hitPoint,
                ud.p1Mm,
                ud.p2Mm,
                _maStlUserFloorSegmentBodyProj
            );
            if (!proj) continue;
            if (proj.distXZ < bestDist) {
                bestDist = proj.distXZ;
                bestUd = ud;
            }
        }
        return bestUd;
    }

    function maStlWallInspectToFiniteNumber(v) {
        const n = Number(v);
        return Number.isFinite(n) ? n : null;
    }

    function maStlWallInspectPointXmm(p) {
        if (!p || typeof p !== 'object') return null;
        return maStlWallInspectToFiniteNumber(p.xMm != null ? p.xMm : p.x);
    }

    function maStlWallInspectPointZmm(p) {
        if (!p || typeof p !== 'object') return null;
        return maStlWallInspectToFiniteNumber(p.zMm != null ? p.zMm : p.z);
    }

    function maStlWallInspectRoundCornerKeyMm(x, z) {
        return String(Math.round(x)) + '|' + String(Math.round(z));
    }

    function maStlWallInspectBuildTrimmedGeomMap() {
        const walls = maStlBuildStraightWallsFromWallModelSource();
        if (!Array.isArray(walls) || !walls.length) return null;

        const geoms = [];
        for (let i = 0; i < walls.length; i++) {
            const w = walls[i];
            if (!w || typeof w !== 'object') continue;
            const attrs = w.Attributes && typeof w.Attributes === 'object' ? w.Attributes : {};
            const p1 = w.P1 || attrs.p1;
            const p2 = w.P2 || attrs.p2;

            const startX = maStlWallInspectPointXmm(p1) != null
                ? maStlWallInspectPointXmm(p1)
                : maStlWallInspectToFiniteNumber(attrs.InicioX);
            const startZ = maStlWallInspectPointZmm(p1) != null
                ? maStlWallInspectPointZmm(p1)
                : maStlWallInspectToFiniteNumber(attrs.InicioY);
            const endX = maStlWallInspectPointXmm(p2) != null
                ? maStlWallInspectPointXmm(p2)
                : maStlWallInspectToFiniteNumber(attrs.FinX);
            const endZ = maStlWallInspectPointZmm(p2) != null
                ? maStlWallInspectPointZmm(p2)
                : maStlWallInspectToFiniteNumber(attrs.FinY);
            if (
                !Number.isFinite(startX) ||
                !Number.isFinite(startZ) ||
                !Number.isFinite(endX) ||
                !Number.isFinite(endZ)
            ) {
                continue;
            }

            geoms.push({
                id: w.Id != null ? String(w.Id) : null,
                lineId: w.LineId != null ? String(w.LineId) : null,
                wallId: w.WallId != null ? String(w.WallId) : null,
                startX: startX,
                startZ: startZ,
                endX: endX,
                endZ: endZ,
                attrs: attrs,
            });
        }

        if (!geoms.length) return null;

        const nodeDegree = Object.create(null);
        for (let i = 0; i < geoms.length; i++) {
            const g = geoms[i];
            const ks = maStlWallInspectRoundCornerKeyMm(g.startX, g.startZ);
            const ke = maStlWallInspectRoundCornerKeyMm(g.endX, g.endZ);
            nodeDegree[ks] = (nodeDegree[ks] || 0) + 1;
            nodeDegree[ke] = (nodeDegree[ke] || 0) + 1;
        }

        const byKey = Object.create(null);
        const CONNECTED_END_TRIM_MM = 450;
        for (let i = 0; i < geoms.length; i++) {
            const g = geoms[i];
            const dx = g.endX - g.startX;
            const dz = g.endZ - g.startZ;
            const len = Math.sqrt(dx * dx + dz * dz);
            if (!(len > 1e-6)) continue;

            const ks = maStlWallInspectRoundCornerKeyMm(g.startX, g.startZ);
            const ke = maStlWallInspectRoundCornerKeyMm(g.endX, g.endZ);
            const trimStart = (nodeDegree[ks] || 0) >= 2 ? CONNECTED_END_TRIM_MM : 0;
            const trimEnd = (nodeDegree[ke] || 0) >= 2 ? CONNECTED_END_TRIM_MM : 0;
            const trimmedLen = Math.max(0, len - trimStart - trimEnd);

            g.rawLengthMm = len;
            g.trimStartMm = trimStart;
            g.trimEndMm = trimEnd;
            g.trimmedLengthMm = trimmedLen;

            const keys = [
                g.id,
                g.lineId,
                g.wallId,
                g.attrs && g.attrs._idObject != null ? String(g.attrs._idObject) : null,
            ];
            for (let j = 0; j < keys.length; j++) {
                const key = keys[j];
                if (!key) continue;
                byKey[key] = g;
            }
        }

        return byKey;
    }

    function maStlWallInspectResolveEffectiveLengthMm(ud) {
        if (!ud || typeof ud !== 'object') return null;
        const byKey = maStlWallInspectBuildTrimmedGeomMap();
        if (!byKey) return null;

        const keys = [
            ud._idObject != null ? String(ud._idObject) : null,
            ud.Id != null ? String(ud.Id) : null,
            ud.LineId != null ? String(ud.LineId) : null,
            ud.WallId != null ? String(ud.WallId) : null,
        ];
        for (let i = 0; i < keys.length; i++) {
            const k = keys[i];
            if (!k) continue;
            const g = byKey[k];
            if (g && Number.isFinite(g.trimmedLengthMm)) return g.trimmedLengthMm;
        }

        const p1 = ud.p1Mm;
        const p2 = ud.p2Mm;
        const sx = p1 ? maStlWallInspectToFiniteNumber(p1.x) : null;
        const sz = p1 ? maStlWallInspectToFiniteNumber(p1.z) : null;
        const ex = p2 ? maStlWallInspectToFiniteNumber(p2.x) : null;
        const ez = p2 ? maStlWallInspectToFiniteNumber(p2.z) : null;
        if (Number.isFinite(sx) && Number.isFinite(sz) && Number.isFinite(ex) && Number.isFinite(ez)) {
            const cux = (sx + ex) * 0.5;
            const cuz = (sz + ez) * 0.5;
            let best = null;
            let bestScore = Infinity;
            const values = Object.keys(byKey);
            for (let i = 0; i < values.length; i++) {
                const g = byKey[values[i]];
                if (!g || !Number.isFinite(g.trimmedLengthMm)) continue;
                const cgx = (g.startX + g.endX) * 0.5;
                const cgz = (g.startZ + g.endZ) * 0.5;
                const ddx = cgx - cux;
                const ddz = cgz - cuz;
                const centerDist = Math.sqrt(ddx * ddx + ddz * ddz);
                const score = centerDist + Math.abs((g.rawLengthMm || 0) - Math.sqrt((ex - sx) * (ex - sx) + (ez - sz) * (ez - sz))) * 0.1;
                if (score < bestScore) {
                    bestScore = score;
                    best = g;
                }
            }
            if (best && Number.isFinite(best.trimmedLengthMm) && bestScore <= 300) {
                return best.trimmedLengthMm;
            }
        }
        return null;
    }

    function maStlWall3dInspectBuildAttrsAlertText(ud, mesh) {
        const lines = ['Atributos del muro'];
        if (ud) {
            const effectiveLengthMm = maStlWallInspectResolveEffectiveLengthMm(ud);
            const keys = [
                '_idObject',
                '_TypeMesh',
                '_Datalong',
                '_DataWith',
                '_DataHeight',
                '_XRotation',
                '_YrRtation',
                '_ZRotation',
                '_IsFormwork',
                '_IsUniversalPanel',
                '_XCoordinate',
                '_YCoordinate',
                '_ZCoordinate',
                '_Tape_1',
                '_Tape_2',
                '_Idconnection_1',
                '_Idconnection_2',
                '_CHeckBracketInside',
                '_CHeckBracketOutside',
                '_CHeckRijiInside',
                '_CHeckRijiOutside',
                '_CHeckPropInside',
                '_CHeckPropOutside',
                '_CHeckPropInsideInf',
                '_CHeckPropOutsideInf',
            ];
            for (let i = 0; i < keys.length; i++) {
                const k = keys[i];
                let v = ud[k];
                if (k === '_Datalong' && Number.isFinite(effectiveLengthMm)) {
                    v = maStlRoundMeters3(effectiveLengthMm / 1000);
                }
                lines.push(k + ': ' + (v == null ? 'null' : String(v)));
            }
            if (Number.isFinite(effectiveLengthMm)) {
                lines.push('__LengthSource: trimmed-3d');
                lines.push('__LengthMm: ' + String(Math.round(effectiveLengthMm)));
            }
        } else {
            lines.push('No se encontro maStlUserPlanLine asociado.');
            if (mesh && mesh.userData) {
                lines.push('kind: ' + String(mesh.userData.maStlWall3dKind || 'wall'));
                lines.push('atk60Kind: ' + String(mesh.userData.maStlWall3dAtk60Kind || 'n/a'));
            }
        }
        return lines.join('\n');
    }

    function maStlWall3dInspectSyncHoverAtPointer(clientX, clientY) {
        if (maStlWallInspectActiveMode() !== 'wall3d') {
            maStlWall3dInspectClearHoverMesh();
            return;
        }
        const hit = maStlWall3dInspectPickMeshHitAtPointer(clientX, clientY);
        maStlWall3dInspectSetHoverMesh(hit ? hit.object : null);
    }

    function maStlWall3dInspectTryAlertAtPointer(clientX, clientY) {
        if (maStlWallInspectActiveMode() !== 'wall3d') return false;
        const hit = maStlWall3dInspectPickMeshHitAtPointer(clientX, clientY);
        if (!hit || !hit.object) return false;
        const ud = maStlWall3dInspectResolveAxisUdFromPoint(hit.point || null);
        window.alert(maStlWall3dInspectBuildAttrsAlertText(ud, hit.object));
        return true;
    }

    function maStlWallInspectSyncHoverAtPointer(clientX, clientY) {
        const mode = maStlWallInspectActiveMode();
        if (mode === 'wall3d') {
            maStlWallInspectClearHoverLine();
            maStlWall3dInspectSyncHoverAtPointer(clientX, clientY);
            return;
        }
        if (mode === 'wall2d') {
            const hit = maStlWall2dInspectPickMeshHitAtPointer(clientX, clientY);
            if (hit && hit.object) {
                maStlWallInspectClearHoverLine();
                maStlWall3dInspectSetHoverMesh(hit.object);
            } else {
                const ln = maStlPickUserFloorLineForCanvasInteraction(clientX, clientY, 8);
                const meshFromLine = ln ? maStlWall2dInspectResolveMeshFromLine(ln) : null;
                if (meshFromLine) {
                    maStlWallInspectClearHoverLine();
                    maStlWall3dInspectSetHoverMesh(meshFromLine);
                } else {
                    maStlWall3dInspectClearHoverMesh();
                    maStlWallInspectSetHoverLine(ln || null);
                }
            }
            return;
        }
        maStlWallInspectClearHover();
    }

    function maStlWallInspectTryAlertAtPointer(clientX, clientY) {
        const mode = maStlWallInspectActiveMode();
        if (mode === 'wall3d') return maStlWall3dInspectTryAlertAtPointer(clientX, clientY);
        if (mode === 'wall2d') {
            const ln = maStlPickUserFloorLineForCanvasInteraction(clientX, clientY, 8);
            const udFromLine = ln && ln.userData ? ln.userData.maStlUserPlanLine || null : null;
            let hit = maStlWall2dInspectPickMeshHitAtPointer(clientX, clientY);
            if ((!hit || !hit.object) && maStlWall2dModelMeshesGroup) {
                const meshFromLine = ln ? maStlWall2dInspectResolveMeshFromLine(ln) : null;
                if (meshFromLine) {
                    hit = { object: meshFromLine, point: null };
                }
            }
            if (hit && hit.object) {
                const ud = udFromLine || maStlWall3dInspectResolveAxisUdFromPoint(hit.point || null);
                window.alert(maStlWall3dInspectBuildAttrsAlertText(ud || null, hit.object));
                return true;
            }
            if (!ln || !ln.userData) return false;
            const ud = udFromLine;
            window.alert(maStlWall3dInspectBuildAttrsAlertText(ud, null));
            return true;
        }
        return false;
    }

    /**
     * Reconstruye overlay según tamaño modelo; Desing_2: reglas hasta ~25 m físicos (unidades escena = mm).
     * @param {number} maxDimLocal mismo criterio que `refitCamerasToObject`.
     */
    function rebuildMaStlUcsOverlayDecor(maxDimLocal) {
        maStlStripOverlayMeshes(maStlUcsAxesGroup);
        maStlStripOverlayMeshes(maStlXyzAxesGroup);
        maStlStripOverlayMeshes(maStlRulersGroup);
        maStlOverlayLineMat = null;
        const axisLen = maStlWorldAxesLength(maxDimLocal, maStlRulersGate);
        const rulerExtent = maStlRulersGate
            ? maStlDesing2RulerExtentMm(
                  maxDimLocal,
                  desing2EnvRulerExtentCapMm,
                  desing2EnvGridMajorMm()
              )
            : maStlRulerExtentFromMaxDimMm(maxDimLocal);
        maStlOverlayLineMat =
            maStlRulersGate && maStlDesingV2Viewer
                ? maStlCreateDesing2RulerLineMaterial(darkBgVisible)
                : maStlMakeOverlayLineMat();
        if (maStlDesingV2Viewer) {
            maStlXyzAxesGroup.add(maStlBuildXyzAxesFromAxisLen(axisLen, MA_STL_XYZ_AXES_COLOR));
        } else {
            maStlUcsAxesGroup.add(maStlBuildUcsFromAxisLen(axisLen, maStlOverlayLineMat, false));
        }
        if (maStlRulersGate) {
            /** Geometría de reglas en **metros** (÷1000 vs mm escena); grupo escalado ×1000 → alineado con malla/rejilla. */
            const s = MA_STL_SCENE_MM_PER_PHYSICAL_METER;
            const rulerInner = maStlBuildPlanRulers(
                axisLen,
                rulerExtent / s,
                desing2EnvGridSnapMm / s,
                desing2EnvGridMajorMm() / s,
                maStlOverlayLineMat,
                maStlRulerLabelMetersFromWorldM,
                s,
                MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM,
                maStlRulerAnchorMm.x,
                maStlRulerAnchorMm.z
            );
            const rulerSceneWrap = new THREE.Group();
            rulerSceneWrap.scale.setScalar(s);
            rulerSceneWrap.add(rulerInner);
            maStlRulersSceneWrap = rulerSceneWrap;
            maStlRulersGroup.add(rulerSceneWrap);
        } else {
            maStlRulersSceneWrap = null;
        }
        maStlRebuildRulerAnchorMarker();
        syncMaStlUcsOverlayVisibility();
        maStlSyncDesing2RulerLabelSpritesToTheme();
        if (maStlRulersGate && maStlEdgeRulersManualOn) {
            maStlSyncEdgeRulersOverlay();
        }
        if (maStlDesingV2Viewer && maStlUserLinesGroup) {
            for (let uli = 0; uli < maStlUserLinesGroup.children.length; uli++) {
                const o = maStlUserLinesGroup.children[uli];
                if (!maStlIsUserFloorPlanLineObject(o)) continue;
                maStlEnsureUserFloorLineObjectMaterial(o);
                maStlApplyUserFloorLineBaseMaterialForLine(o);
                if (o === maStlHoveredUserFloorLine) {
                    maStlApplyUserFloorLineHoverBrightMaterialForLine(o);
                }
            }
            maStlReapplyAllUserFloorWallAxisLineStyles();
        }
        if (maStlDesingV2Viewer && maStlLineToolRubberBandLine) {
            maStlLineToolEnsureRubberBandMaterialIsolated();
            maStlLineToolSyncRubberBandWall2dStyle();
        }
    }

    function maStlSyncDesing2RulerLabelSpritesToTheme() {
        if (!maStlDesingV2Viewer) return;
        const fill = maStlDesing2RulerLabelFillForTheme(darkBgVisible);
        if (maStlRulersGate && maStlRulersSceneWrap) {
            maStlRulersSceneWrap.traverse(function (obj) {
                if (!obj.isSprite) return;
                const st = obj.userData && obj.userData.maStlThinTextSpriteState;
                if (!st) return;
                st.thinOpts.fillColor = obj.userData.maStlRulerLabelIsX5
                    ? MA_STL_DESING2_RULE_LABEL_X5_FILL
                    : fill;
                maStlRedrawThinTextSprite(obj);
            });
        }
        maStlApplyUserFloorDimGuideLineColors();
        if (maStlEnsureUserFloorDimDomHud()) {
            const hHud = maStlUserFloorDimDomHud;
            if (hHud && hHud.readoutBtn) maStlApplyUserFloorDimDomHudTheme(hHud.readoutBtn);
            if (hHud && hHud.inputEl) maStlApplyUserFloorDimDomHudTheme(hHud.inputEl);
        }
        if (maStlUserFloorLineHudTargetLine() && !maStlUserFloorDimDomHudEditing) {
            maStlUpdateUserFloorLineDimHud();
        }
        if (maStlRulersGate && maStlEdgeRulersManualOn) {
            maStlSyncEdgeRulersOverlay();
        }
    }

